// ===== ch01.js =====
// 第一章 初评级 —— 作者批次B（扩写版）
window.STORY.push({
  id: "ch01",
  title: "第一章 · 初评级",
  phase: "选秀",
  week: 1,
  nodes: [
    {t:"bg", v:"lobby"},
    {t:"n", x:"大巴驶过基地大门时，天边那点蟹壳青还没有被太阳收走。九月第一个周一，六点五十，七辆车在第二道铁闸前排成一列，发动机一台一台熄下去，声音层层往后退，退到最后只剩车顶空调的低鸣。你坐在倒数第二排靠窗的位置，额头贴着微凉的玻璃，看见外面那栋灰白色的楼：幕墙一格一格，把晨光切得很碎；楼顶架着节目组的红色灯牌，风一过就嗡嗡轻响。车厢里空调吹出淡淡的皮革味，压不住一百个人挤出来的暖。过道另一头有人在背歌词，节拍敲在座椅靠背上，敲得很轻，像怕惊动什么。"},
    {t:"n", x:"铁闸向两侧滑开，门里的冷气涌出来，比车厢里低好几度。一百个人拖着行李箱往里走，轮子碾过水泥坡道，轰隆声连成一片，像有什么笨重的东西被推过了门槛。新地板打过蜡，气味甜而涩，吸进去像含了一口没化开的糖。你的编号牌挂在胸前，塑料边硌着锁骨，走快一点就轻轻敲一下。有人把拉杆甩得太响，啪的一声，在大厅里滚了一圈才散。"},
    {t:"n", x:"苏景行走在你左前方半步。亚麻色头发被穿堂风掀起一层，T恤领口松松地塌着，整个人像刚从床上被拽起来，偏又把每一步踩得随性又好看。他回头找你，眼睛先弯了一下才开口。"},
    {t:"d", who:"苏景行", x:"小队长，一百个人里，我只看得见你后脑勺。紧张就回头，我在这儿。", fx:"smile"},
    {t:"n", x:"大厅比想象中深。磨石地面映着人影，冷气从顶上压下来，把说话声都削薄了。一百人按编号站成方阵，行李箱统一推到墙根，轮子朝外。角落里三台摄像机红灯亮着，镜头缓慢地扫，像在挑谁先扛不住。你左边那个人一直在清嗓子，清到第三遍才停；右边的把手插在兜里，指节贴着裤缝动了两下。你听见自己鞋底蹭在地砖上那一点涩响。"},
    {t:"sys", x:"【节目组】初评级即将开始。请按入场编号十人一组进入评审区，先唱后跳，伴奏自备。评级结果当场公布，等级决定宿舍、训练资源与首次舞台站位。"},
    {t:"n", x:"评审席摆在大厅最里侧，长桌铺黑布，桌上一排麦克风，线缠得像黑色的根。中间那人先一步落座：银白色头发，细框眼镜，灰色的眼睛在镜片后慢慢扫过入场口。他的肩线、手指交叠的角度，都像是被人用尺子量过——江慕白，节目唯一的评定制音人。顶灯落在他发梢，泛起一层冷而薄的光。他手边那张纸是空白的，笔搁在纸的正中，笔尖朝着自己。"},
    {t:"d", who:"江慕白", x:"安静。从你们踏进这扇门起，声音就属于舞台，不属于闲谈。", fx:"cool"},
    {t:"n", x:"一组一组地过。有人唱破了音，破了之后还硬着头皮往下走，走三步就被叫停；有人舞步踩空，落地时鞋底打了个滑，手在裤缝上扶了一下。评审席里只有笔尖划纸的沙沙声，偶尔一声杯盖合上的轻响。你们前一组那个人唱到一半忽然攥紧了话筒线，指节发白，退场时背绷得很直。冷气正贴着后颈往下走，你听见自己的心跳，一下一下，盖过了后面伴奏的前奏。"},
    {t:"d", who:"江慕白", x:"你。先唱，再跳。让我看看，一百个人里凭什么是你站在这儿。", fx:"neutral"},
    {t:"n", x:"你接过麦克风。塑料外壳被掌心焐热，金属网抵在唇上，还有一点没褪掉的凉。线从你脚边拖出去，像一根随时会绷紧的东西。音箱里漏出极轻的钢琴底噪，是远处有人在试音。你脚下的地砖比想象中凉，凉意顺着鞋底往上爬，爬到小腿。"},
    {t:"choice", prompt:"站稳这件事，原来比唱稳更难。你要把第一分钟交给什么？",
      options:[
        {x:"“先唱。我想让人先听见声音。”", heart:{江慕白:1, 林墨轩:1}, cb:"江慕白的笔尖停了半秒。后排有人抬了下头。"},
        {x:"“先跳。话少的人，身体先开口。”", heart:{苏景行:2, 陆清越:1}, cb:"苏景行吹了声口哨。角落里有人小声喊了句加油，很快被冷气吞掉。"},
        {x:"“两个一起。我不想被拆开看。”", heart:{江慕白:2, 顾知遥:1}, cb:"江慕白灰眸微动。有人哼笑了一声，又及时收住。"}
      ]},
    {t:"n", x:"声音出去的那一刻，大厅的回声撞在你背后，像有人轻轻推了一把。地板把节拍导上来，从脚心一路传到齿列，微微发麻。最后一个音落地时，汗正顺着鬓角往下爬，痒，但你没抬手去擦。麦克风线在你脚边弹了一下，又慢慢伏回去。评审席上有个人翻了一页纸，翻得很慢，像在等什么落定。"},
    {t:"d", who:"江慕白", x:"可以。声音干净，气场不慌。A级。", fx:"neutral"},
    {t:"n", x:"苏景行第二个上。他连伴奏都没准备全，随口哼了半段就起跳，收尾即兴加了个转音，把评审席边上的助理逗笑了。江慕白只写了一个字：A。那人接过等级牌，像接过一份外卖，冲镜头比了个无关紧要的耶，末了还朝你的方向挑了下下巴。"},
    {t:"n", x:"接着上台的是林墨轩。一身黑白灰，衬衫扣到最上面那颗，黑色短发压得很整，那双深眸里没什么情绪。上台前他把谱子对折了一次放进裤袋，没有多余动作，开口即入拍，转音干净得像刀刃划过纸。最后一句他没有加任何装饰，只把收尾留住。江慕白放下笔，看了他两秒，才落下一个A。他回身把麦克风放回架子，位置比原来正了半寸。"},
    {t:"n", x:"温以恒是另一种温。棕色头发被汗贴在额角，笑起来眼角很软，站姿松得像在自家客厅。他唱得不炫，气口收得干净，唱完把麦克风双手递回底座，指节轻得几乎没出声。江慕白的笔没有停，A。往回走的时候，他顺手替后面那位扶了一下晃动的谱架。"},
    {t:"n", x:"顾知遥的银灰色头发梳得一丝不苟，湛蓝眼眸在灯下像两块冰，鞋面亮得能照见地砖。上台前他先理了下袖口，把满厅的目光当成理所当然的东西。第一句音就压得很高，稳稳停住。被念到名字时他只挑了下眉，目光先扫过评审席，再扫过你，像在记位置。"},
    {t:"n", x:"沈时雨的深棕色头发垂在额前，身形薄而韧，脚上是双磨了边的练功鞋，鞋头补过一块，线脚一道一道很齐。他上台的脚步很轻，落地几乎没有声音，起跳时整个人像被一根线提起来。跳完他就低头看地板，听见A级时肩膀才松下来，像有人替他卸了担子。退回去的时候他贴着镜子根走，走了最短的一条路。"},
    {t:"n", x:"最后一个是陆清越。金色短发在顶灯下炸着一层绒，眼睛亮得像装了星。上台前他做了个深呼吸，呼得肩膀都抬起来了。跳到一半鞋带松了，也没停；收势后鞠躬太用力，额头差点撞上旁边那台摄像机的护罩，惹得全场笑了一片。江慕白抬手压了压：A。"},
    {t:"d", who:"陆清越", x:"诶？真的吗！真的——我、我刚才鞋带松了，那个，不算扣分吧？", fx:"laugh"},
    {t:"n", x:"七个A级席。方阵里响起一阵压着的吸气声，声音不大，却像有人往水里丢了七颗石子。你看见隔壁那排有人把号码牌翻过去扣在掌心，也看见有人低下头去看自己的鞋尖。空调出风口的风扫过一整个方阵，把几张翘起的节目单边角吹得直响。"},
    {t:"d", who:"江慕白", x:"一百人，A级七人。你们七块，是璞玉，也是靶子。现在，内部选一个临时队长。", fx:"neutral"},
    {t:"n", x:"大屏亮起，七个人的名字依次落下，你的名字后面空着一栏，光标一闪一闪，像在等人落印。七个名字排在同一行里，字的间距很匀，看起来像一句还没写完的话。空调换了一次风，把谁的号码牌吹得翻过来，塑料片啪地打在椅背上。你忽然想起车窗外那排被风掀着的红色灯牌，它们现在在你背后亮着。"},
    {t:"choice", prompt:"那行空位在等你。",
      options:[
        {x:"“我来。”", heart:{江慕白:2, 苏景行:2}, cb:"你往大屏走了半步。苏景行在队伍里笑出一个懒洋洋的弧度。"},
        {x:"“先听听大家的意思。”", heart:{温以恒:2, 林墨轩:1, 沈时雨:1}, cb:"温以恒朝你点了下头。沈时雨的视线从地板上抬起来一点点。"},
        {x:"“我推以恒哥。他比我稳。”", heart:{温以恒:3, 江慕白:-2}, cb:"温以恒愣了一下，随即笑着摆手。江慕白镜片后的目光，凉了一度。"}
      ]},
    {t:"n", x:"话音刚落，人群里有人笑了一声。银灰色头发的少年把双臂抱在胸前，湛蓝眼眸里写着明晃晃的不服，鞋跟在地砖上碾了半圈。他站的位置离评审席不远，像是特意挑的——站在那里，说什么都有人听得见。"},
    {t:"d", who:"顾知遥", x:"队长大人，你行不行啊？A级又不是冠军，凭什么你站中间？", fx:"angry"},
    {t:"n", x:"大厅安静了一瞬。摄像机红灯不动了。苏景行嗤地笑出来，双手插回裤袋；林墨轩抬眼，视线在你和顾知遥之间停了一秒；温以恒眉头微蹙，往顾知遥那边挪了半步，又停住；陆清越捂住了嘴，指缝里漏出一小声惊呼；沈时雨的头垂得更低，手指绞着那根松掉的鞋带。六道目光落过来——一道带刺，其余的在等你。摄像机的风扇声很轻，像有人在远处数拍子。窗外的车流声远远地，像另一个世界的事。"},
    {t:"choice", prompt:"顾知遥的刺还悬在半空。",
      options:[
        {x:"“行不行，舞台见。现在你也上去，让江老师看一遍。”", heart:{顾知遥:1, 苏景行:2}, cb:"顾知遥哼了一声，耳尖却动了下。苏景行笑得肩膀直抖。"},
        {x:"“队长不是王座，是先扛事的那个人。这活儿我先接。”", heart:{温以恒:2, 沈时雨:2, 江慕白:1}, cb:"沈时雨攥紧了那根松掉的鞋带。温以恒眼底浮起一点笑。"},
        {x:"“你有意见可以。先拿出让我服的东西。”", heart:{顾知遥:2, 林墨轩:1}, cb:"顾知遥挑眉，竟没反驳。林墨轩几不可察地点了下头。"}
      ]},
    {t:"d", who:"江慕白", x:"火气留着台上用。临时队长，从今天起，你负责把这七块璞玉，磨出声音来。", fx:"cool"},
    {t:"sys", x:"【节目组】初评级公示：A级七人——你、苏景行、林墨轩、温以恒、顾知遥、沈时雨、陆清越。临时队长由你担任，公示牌已更新于大厅东侧。"},
    {t:"n", x:"东侧那块电子公示牌亮起来，你的名字排在第一行，后面跟着六个人的番位，荧光在玻璃上留了一层薄薄的影。你伸手按上去，冰凉从指腹一直传到腕骨；屏幕下缘有一条很细的接缝，蹭过去有点毛。穿堂风掀起帘子一角，光斑在地砖上挪了半寸。身后有人小声把七个名字念了一遍，念到最后一个时停住，像是想起了别的什么。"},
    {t:"n", x:"散场的人流从你两侧分开，箱子轮子的声音一路滚出大门。陆清越跑过来问集合时间，问完自己先答了一遍；温以恒把散在地上的两张节目单捡起来叠好，放进回收筐；顾知遥从你旁边走过去，目不斜视，走出三步才丢下一句“明天别迟到”。苏景行落在最后，手插在兜里等你，没说别的。车窗外那栋楼，现在是你的背面了。"},
    {t:"end"}
  ]
});


// ===== ch02.js =====
// 第二章 A级宿舍夜谈 —— 作者批次B（扩写版）
window.STORY.push({
  id: "ch02",
  title: "第二章 · A级宿舍夜谈",
  phase: "选秀",
  week: 1,
  nodes: [
    {t:"bg", v:"dorm"},
    {t:"n", x:"公示牌那层荧光还印在眼底。电梯上行时轻微失重，耳膜鼓了一下，箱轮在轿厢地板上咯噔咯噔地跳。楼层数字一格一格往上翻，每跳一次，走廊那头的低音就远一层——是有人在练习室里放歌，低频穿过三道墙，到了这里只剩一点闷闷的震动。电梯门开的时候，声控灯一格一格亮起来，又在你身后一格一格灭掉，把影子拉长又收短。"},
    {t:"n", x:"门牌上贴着四个编号，边缘还没撕干净胶，摸上去有点黏。新宿舍有股油漆兑洗衣液的味道，床架是凉的，脚踩上去，地胶微微回弹，鞋跟在边缘蹭出一小声。窗外能看见基地的后院，一排晾着的练功服在风里慢慢转身，袖子鼓一下，又瘪回去，像些没睡的人。"},
    {t:"n", x:"分房表贴在门后：你、苏景行、林墨轩、顾知遥。四张床两两相对，中间一张长桌，桌角有块漆掉了一小片，露出底下浅黄的木；桌上摆着一把搪瓷壶，壶盖边缘结了一圈干了的水痕，四把椅子被谁朝同一个方向摆正过，椅背贴着桌沿，间距几乎一样。靠窗那面墙有一道很浅的水渍，从天花板斜着淌到底，颜色像旧茶。"},
    {t:"n", x:"苏景行已经瘫在靠窗那张床上，亚麻色头发铺在枕头上，像一匹晒懒的布，一只脚还挂在床沿外面晃，鞋也没脱干净。林墨轩正把行李按颜色排进柜子，黑白灰三色，从上到下分毫不差，连衣架的间距都像量过；他的行李箱里垫着一层灰绒布，把一只硬壳唱片盒裹在中间。顾知遥站在自己床边，银灰色头发在顶灯下泛冷光，正用一块叠得方正的手帕，擦一张根本没碰脏的桌面，擦完把手帕对着光看了一遍，又折起来。"},
    {t:"d", who:"苏景行", x:"小队长，以后这窗归我，月亮归你。半夜看见月亮，就当我在替你守夜。", fx:"smile"},
    {t:"n", x:"夜谈从一壶热水开始。搪瓷壶在底座上咕嘟了两声，白气从壶嘴顶出来，把顶灯晕开一小团。灯关了一半，四个人横在床上，天花板上有块水渍，形状像一团没散开的云。窗外的车灯偶尔扫过，给那团云镀一道浅金的边，又很快熄灭。被窝里留着白天晒过的余温，混着一点棉布气味，暖得让人想说实话。"},
    {t:"d", who:"林墨轩", x:"我来，是因为家里那间画廊太安静。弹了二十年琴，想听一次人潮。", fx:"neutral"},
    {t:"choice", prompt:"他说完就把话收了回去。",
      options:[
        {x:"“那这趟人潮，有你一个声部。”", heart:{林墨轩:2, 苏景行:1}, cb:"林墨轩的指尖在柜门上停了停，难得没反驳。苏景行在暗处笑了一声。"},
        {x:"“画廊不吵，这里补给你。”", heart:{林墨轩:1, 温以恒:1}, cb:"林墨轩几不可察地点了下头，把被角捋平。"},
        {x:"“弹了二十年，值得站上来听一次。”", heart:{林墨轩:2, 江慕白:1}, cb:"林墨轩抬眼看你，黑眸里没什么波澜，手却松了松领口。"}
      ]},
    {t:"n", x:"顾知遥哼了一声，把枕头拍得蓬松。他银灰色的头发在昏光里像覆了一层霜，湛蓝眼眸望着天花板那团云，不知在看云，还是在看别的什么。手帕被他折成更小的方块，压在枕头底下，压完还用指背按了两下。床板发出一声轻响，他把被子踢开，又默默拉了回来，拉得很齐。"},
    {t:"d", who:"顾知遥", x:"本少爷来，是要让人知道，这张脸底下还有东西。队长大人，你别拖后腿就行。", fx:"cool"},
    {t:"d", who:"苏景行", x:"这张脸我先替大家验收了。脸底下的东西，留给舞台去挖。", fx:"laugh"},
    {t:"n", x:"顾知遥抓起枕头砸过去。苏景行单手接住，笑得床垫都在颤，枕头被他抱在怀里又扔了回去，这回擦着顾知遥的耳朵飞过。枕头落地时扬起一点灰，在被窝的暖味里打了个转。林墨轩从柜门后抬起眼，看了两人一秒，又低头去对齐那只衣架的间距。"},
    {t:"d", who:"林墨轩", x:"别闹。明早六点半。", fx:"neutral"},
    {t:"n", x:"热水壶自己断开了一次，咕的一声，屋里静下来半分钟。苏景行把手枕在脑后，望着天花板那块水渍，忽然开了口，调子还是懒的，尾音却比平时收得早。"},
    {t:"d", who:"苏景行", x:"我啊，来陪我们队长。从小一起长大的人，总得有人看着你，别又一个人扛。", fx:"smile"},
    {t:"m", x:"他说得轻，像随口。可我听见枕头被他攥了一下，布面皱出一声很细的响。"},
    {t:"choice", prompt:"那句话落在被子上，没有收回去。",
      options:[
        {x:"“那你离我近点，别隔着两张床看。”", heart:{苏景行:3}, cb:"苏景行笑出声，把挂在床沿的那只脚收了回去，翻了个身面朝你。"},
        {x:"“从小看到大，你还没看够？”", heart:{苏景行:2, 陆清越:1}, cb:"他拖长声音应了句看不够，尾音懒洋洋地散在昏光里。"},
        {x:"“这次不一样。这次有六个人跟着我。”", heart:{苏景行:1, 温以恒:2, 林墨轩:1}, cb:"苏景行没接话，只伸过手来，在你床沿轻轻拍了两下。"}
      ]},
    {t:"n", x:"话题绕回你。三道目光在昏光里等你开口：苏景行侧过身来，一只手压在枕头下面；林墨轩的手指停在柜门上，柜门没关严，缝里露出一截灰绒布；顾知遥装作在看手机，屏幕其实已经暗了，映着他半张脸。你咳了一声，刚要说话，门外却传来很轻的两下——又停了。走廊的声控灯没有亮，像是有人特意把脚步压住了。"},
    {t:"n", x:"你掀开帘子。沈时雨站在走廊尽头的光里，深棕色头发垂着，身形薄而韧。他的手抬到半空，指节发白，像鼓了很久的勇气，又在门板前泄了气。脚上还是白天那双磨边的练功鞋，一根鞋带松着，垂下来晃。他站的姿势很小心，重心全压在脚尖上，仿佛随时准备转身。"},
    {t:"d", who:"沈时雨", x:"队长哥……我、我没事。你早些休息。", fx:"shy"},
    {t:"choice", prompt:"他的手还悬在半空。",
      options:[
        {x:"“进来坐。门没锁。”", heart:{沈时雨:3, 温以恒:1}, cb:"他耳尖红了，犹豫着挪进来半步，鞋尖还留在门外的那块光里。"},
        {x:"“想说什么就说，我听着。”", heart:{沈时雨:2, 林墨轩:1}, cb:"他嘴唇动了动，最后只点了头，肩膀松了一线。"},
        {x:"先让他回去，别逼。", heart:{沈时雨:1}, cb:"你轻轻带上门。他的脚步声在走廊停了一停，才慢慢走远。"}
      ]},
    {t:"d", who:"顾知遥", x:"门口那个胆小鬼，站了得有十分钟。玻璃都让他看出个洞了。", fx:"cool"},
    {t:"d", who:"林墨轩", x:"话别说那么快。他今天落地那一下，是全场最干净的。", fx:"neutral"},
    {t:"n", x:"顾知遥翻了个身，把脸埋进枕头，闷闷地说了句什么，谁都听不清。苏景行在暗处吹了声口哨，吹到一半又自己掐断。你回到床沿坐下，手机在枕头下震了一下，屏幕的光从指缝里漏出来，白得有点刺眼。窗外那轮被苏景行让给你的月亮，正好移到玻璃中央。远处饮水机咔地响了一声，是水烧好的提示音，隔着两道门传进来，闷闷的。"},
    {t:"phone", who:"温以恒", msgs:[
      {f:"them", x:"小队长，睡了吗？", time:"23:47"},
      {f:"me", x:"还没，刚聊完。"},
      {f:"them", x:"那就好。我煮了七份夜宵，一人一份，挂在你们门把手上啦。", time:"23:48"},
      {f:"them", x:"小清越那份少放了辣，小墨那盒没放葱。记得趁热。", time:"23:48"},
      {f:"them", x:"[图片] 七只保温盒排成一排", time:"23:49"}
    ]},
    {t:"n", x:"门把手上果然挂着一只棉布包，七只小保温盒并排躺着，热气透过布洇出一小片潮。你摸了下盒壁，还是烫的，像有人把体温留在了布的外面。拎起来时，盒底相碰，闷闷地响了一声。解开布包的绳结，指腹蹭到一层细绒，软得让人愣了一下；绳结打得很规矩，留出的两个耳朵一样长。"},
    {t:"n", x:"走廊尽头还站着个人。棕色头发，褐色眼眸，怀里抱着另一只布包，袖口卷到小臂，手腕上有一圈被热水烫红的印子；他怀里那只布包比你的小一号，说明前面已经送出去两趟了。他看见你，眼角先软下来——那是温以恒，A级里最不像来争什么的人。"},
    {t:"d", who:"温以恒", x:"小队长，趁热喝。两个妹妹的哥哥，别的不会，就会先把人喂饱。", fx:"smile"},
    {t:"choice", prompt:"布包还带着他的手温。",
      options:[
        {x:"回消息：“以恒哥，辛苦了。”", heart:{温以恒:2, 陆清越:1}, cb:"你打字慢了半拍。他很快回了个猫猫点头的表情。"},
        {x:"把七只盒子摆开，分给每个人。", heart:{温以恒:2, 沈时雨:1}, cb:"盒子摆在长桌上，热气把顶灯晕出一小圈白。顾知遥嘴上嫌麻烦，手却先伸了出去。"},
        {x:"问他：“那你自己的那份呢？”", heart:{温以恒:3}, cb:"温以恒愣了一下，把空着的那只手举了举：我回房再煮，水还热着。", flag:"yiheng_self"}
      ]},
    {t:"n", x:"四个人围着长桌坐开。汤是热的，姜味先冲上来，辣得人鼻尖冒汗。苏景行喝得咕咚响，末了冲你举了下空盒，像在敬什么；林墨轩把盒子转了个方向，让标签朝外，才慢慢喝；顾知遥只喝了两口就把盒子推远，说夜里喝汤第二天脸会肿，等你一转头，他那只盒子已经空了半盒，勺子在盒底刮出一声轻响。窗外那团云上的金边，又亮了一次。"},
    {t:"sys", x:"【节目组】23:30 熄灯。明日 6:30 全员集合于主练习室，第一次位置测评任务书将在现场发放。"},
    {t:"n", x:"灯灭了。四人的呼吸各成一拍，渐渐错开，又慢慢靠拢。苏景行翻了个身，床架吱一声；林墨轩那侧的被子几乎没动过，只有枕头被拍了两下；顾知遥把手机屏幕朝下扣在床头，光灭了。窗外的月亮移过顾知遥擦过的那块玻璃，落进你枕边一小块凉白。走廊尽头，不知道谁翻了个身，床架轻响了一声，像一句没说完的话。空盒子摞在桌角，盒底留着一点浅黄的汤渍，等你明天早上看见。"},
    {t:"end"}
  ]
});


// ===== ch03.js =====
// 第三章 位置测评 —— 作者批次B
window.STORY.push({
  id: "ch03",
  title: "第三章 · 位置测评",
  phase: "选秀",
  week: 1,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"九月第一个周一，六点二十。你出门时先看见桌角那摞保温盒：盒盖没扣严，盒底还留着一小块浅黄的汤渍，姜味在屋里散了一宿，凉了反而更冲。走廊的声控灯被你的脚步一格一格点亮，又在身后一格一格灭掉。主练习室在三楼东头，门牌是块亚克力板，边角裂了一道细纹。天刚翻出一点白，晨光斜着切进来，把地板照出一条亮带，亮带里有细小的灰在浮。"},
    {t:"n", x:"推门进去，整面镜墙先接住你。镜面被分成十六格，格缝里嵌着擦不掉的灰线；把杆是磨砂钢的，指尖按上去一层凉，握久了会留下一圈汗印。地胶新铺不久，气味甜而涩，脚踩上去微微回弹，鞋底在接缝处蹭出细响。天花板上四排灯只亮了最外面那一排，光落在空气里的浮尘上，照出一条条有形状的白。镜子对面那面墙贴着一排往届舞台的照片，边角被谁用胶带重新粘过，翘起来的地方反着光。窗缝漏进来的风是干的，吹得白板上几张纸的角一翘一翘。"},
    {t:"d", who:"江慕白", fx:"cool", x:"“位置不是你们想去的地方，是你们必须站住的地方。今天中午十二点前，把名字交上来。”"},
    {t:"n", x:"任务书钉在白板上，纸是新的，四角还翘着。上面分了三栏：Vocal、Rap、Dance，每栏底下留着空行，等名字落笔。其他等级的练习生沿着镜子根坐了一地，练功服有的还没干透，有人把外套叠成方块垫在膝盖下面。靠门那一侧坐着一个人，头发染成很扎眼的红，发梢用发胶压过，脖子上一条细链，手里的编号牌被翻来翻去，边角磨得发白——王腾。"},
    {t:"sys", x:"【节目组】位置测评任务书已下发：Vocal、Rap、Dance 三组，A级七人须各自择位，由临时队长主持分工，今日十二点前提交。各组按完成度独立评级，评级影响下一轮舞台站位。"},
    {t:"n", x:"七个人围到白板前。长桌被挪到屋子中间，桌面上留着上一批人写字时压出的笔痕，指甲划过去是一道浅沟。晨光移了半米，那条亮带从地板爬到了桌腿上。陆清越把外套叠好垫着坐下，温以恒拧开保温杯，一小股白气升起来，很快散在空调风里。谁都没有先开口，白板笔在顾知遥指间转了半圈，咔地弹了一下。"},
    {t:"d", who:"顾知遥", fx:"cool", x:"“Vocal。本少爷这张脸配这把嗓子，站哪儿不用讨论。”"},
    {t:"d", who:"林墨轩", fx:"neutral", x:"“我唱。Rap 我不碰。”"},
    {t:"d", who:"苏景行", fx:"smile", x:"“我随意。三个人里总得有个多背一段别人词的，那活儿归我。”"},
    {t:"d", who:"陆清越", fx:"laugh", x:"“我都行的！队长哥哥在哪一组，我就在哪一组！真的！”"},
    {t:"d", who:"温以恒", fx:"smile", x:"“先补空吧。哪个位置缺人，我去。中午要交表，别卡在这儿，好吗？”"},
    {t:"n", x:"沈时雨站在最外圈，背贴着白板的边。他今天换了鞋，鞋头洗得发白，线脚却一道一道整齐。手指在练功裤的缝上按了一下，又松开，按出来的那一小条褶很快自己弹回去。等所有人都说完了，他才把声音放进这片安静里。"},
    {t:"d", who:"沈时雨", fx:"shy", x:"“我……报 dance。行吗，队长哥。”"},
    {t:"choice", prompt:"白板上那三栏还空着，笔就搁在你手边。",
      options:[
        {x:"“先说清楚：谁站得住那个位置，谁就上。”", heart:{江慕白:2, 林墨轩:1, 温以恒:1},
         cb:"你拿过笔，一栏一栏往下填。写到 Vocal 那一笔的时候，林墨轩点了下头。"},
        {x:"“都先挑自己最想要的那一格。”", heart:{顾知遥:2, 陆清越:1, 沈时雨:1},
         cb:"顾知遥先落笔，笔尖戳得很重。陆清越凑过去看，被他一肩膀拐开，也没恼。"},
        {x:"“今天先补齐，缺的那块用两倍练习填。”", heart:{沈时雨:3, 温以恒:1, 苏景行:1}, flag:"extra_hour",
         cb:"沈时雨抬了下头，很快又低回去，笔在指间转了一圈才落下。"}
      ]},
    {t:"n", x:"表填完，白板上多了七行字。沈时雨写 dance 那一笔收得格外重，笔尖停了一下，纸上洇出一小点墨。你把表按在桌角压平的时候，指腹蹭到了那点没干的墨，黑了一小块，后来一整天都留在你食指侧面。"},
    {t:"n", x:"中午的饭是盒饭，米饭压得很实，配菜里有两块姜。没有人回房休息，都留在练习室等分组结果。日头爬到窗框上方，地板上的亮带收窄成一条线。镜子里映着一屋子人：压腿的，开腔的，拨弦的，声音叠在一起，像一锅没搅开的水。有人把喝完的矿泉水瓶捏扁，塑料壳咔啦响了一声，又被旁边的人按住。沈时雨在靠里那个角落，把脚踝架上把杆最下面一格，上身慢慢往下压，背脊绷成一条很薄的弧。"},
    {t:"d", who:"王腾", fx:"cool", x:"“芭蕾啊。我说呢，站那儿绷着个背——家里连双新鞋都换不起的人，学什么芭蕾？”"},
    {t:"d", who:"沈时雨", fx:"sad", x:"“我……没有。我就是想……跳好一点。”"},
    {t:"n", x:"镜子里一下静了。有人把压腿的腿悄悄放下来，有人低头去系根本没松的鞋带。空调出风口的声音突然显得很大，一阵一阵地吹，把白板上的纸角掀起来又压下去。温以恒拧杯盖的手停在半空，水汽从他指缝里逸出来。苏景行肩上那件外套滑下去一半，他没去扶。林墨轩把手里的谱子合上了。王腾站在光圈外面，笑得挺放松，链子晃了一下。"},
    {t:"choice", prompt:"那句话落在地上，没有人去捡。",
      options:[
        {x:"“这里是练功房，不比谁家里有钱。要评价别人，先跳一遍。”", heart:{沈时雨:4, 温以恒:2, 王腾:-3}, flag:"shield_shiyu",
         cb:"你把话截得很平。王腾的笑僵了半秒，链子在胸前停住不晃了。沈时雨握着把杆的手指，一节一节松开。"},
        {x:"“他跳得比你好。你不服，就拿舞台说话。”", heart:{沈时雨:3, 顾知遥:1, 苏景行:1},
         cb:"苏景行吹了声口哨，把外套重新搭回肩上。沈时雨的耳根红透了，这一次没有低头。"},
        {x:"“继续练。谁的时间空着，谁就多练一轮。”", heart:{沈时雨:1, 林墨轩:2, 江慕白:1},
         cb:"你按下播放键。音乐重新灌满屋子，把那句话冲散在节拍里——但你知道它还在。"}
      ]},
    {t:"n", x:"王腾把手插进裤袋，往回走了两步，又回头看了白板一眼。门在他身后晃了一下，弹簧拖着它慢慢合上，最后那一下是轻轻碰的。屋里的人重新动起来，只是压腿的角度都放低了些，有人把耳机塞回耳朵，音量明显调大了。沈时雨把架在把杆上的脚放下来，鞋跟着地，声音很轻。他弯腰去系鞋带，系了很久，最后打了一个很紧的结。"},
    {t:"n", x:"下午的楼层被声音切成三块。Vocal 那间一直开着钢琴，同一个和弦按到第九遍才对；Rap 那头的节拍器从八十调到九十二，快板敲在墙上，像有人敲门；Dance 的计数最短，一二三四，停，重来。走廊尽头的窗玻璃被三种声音一起撞着，嗡嗡地颤。你来回走，鞋底在地板上留下一点湿痕，很快被空调吹干。三点多的时候下过一阵雨，窗框上挂了半小时的水珠，太阳出来，一颗一颗地被晒没。"},
    {t:"phone", who:"苏景行", msgs:[
      {f:"them", x:"小队长，饭你没动。冷的那份我换了，在门口。", time:"20:11"},
      {f:"me", x:"马上。"},
      {f:"them", x:"[语音] 6″", time:"20:12"},
      {f:"them", x:"红头发那个，你别往心里去。他缺的不是钱，是胆子。", time:"20:12"},
      {f:"me", x:"我知道。"},
      {f:"them", x:"知道就吃。菜我挑过了，没有姜。", time:"20:13"}
    ]},
    {t:"n", x:"晚上十点，人散得差不多了。你从 Rap 那间出来，走廊的灯灭到只剩最后一盏。Dance 那间的门虚掩着，缝里漏出一条光。沈时雨还站在镜子前，谱子摊在把杆上，背面抄着白板上那三行字，被笔描过一遍，纸都起了毛。他跳一遍，停下来看自己两秒，再跳一遍。地板上七八个湿脚印叠在一起，分不出先后。"},
    {t:"n", x:"走廊那一盏灯被什么挡住了半格。江慕白站在门口，没有进来，细框眼镜后的灰眸在暗处没什么光，手里拿着你今天交上去的那张表。他翻过纸页看了一眼，又合上。"},
    {t:"d", who:"江慕白", fx:"cool", x:"“从明天起，他多留一小时。表我改过了。”"},
    {t:"n", x:"他把纸按回你手里，纸边是凉的。皮鞋跟敲在走廊上，一下，一下，没有回头，走到拐角时抬手按了下眼镜。你回宿舍的路上脚步放慢了半拍——那间练习室的灯还亮着，光从门缝底下透出来，在地板上切出一条极窄的亮线，亮线里有细小的一段晃动，是脚步来回收的时候挡了一下。走廊很静，饮水机咔地响了一声，是水又烧好了，保温灯转成红色那一颗。你在门外站了一会儿，没有推。里面传来脚掌落地的一声闷响，接着又是一声，一下一下，落在同一拍上。"},
    {t:"end"}
  ]
});


// ===== ch04.js =====
// 第四章 深夜练习室 —— 作者批次B
window.STORY.push({
  id: "ch04",
  title: "第四章 · 深夜练习室",
  phase: "选秀",
  week: 2,
  nodes: [
    {t:"bg", v:"night"},
    {t:"n", x:"一周之后的周二，二十三点四十。你从导师办公室出来，手里那份表格被红笔改过两处，纸角被攥得发软，边上起了毛。走廊只剩应急灯和尽头那一盏顶灯，光落在磨石地面上，冷得像铺了一层薄水。保洁刚拖过地，湿味混着消毒水的气味浮在半空，脚踩过去会有一声很短的粘响。饮水机在窗边嗡嗡地煲着，隔一会儿咔一下。"},
    {t:"n", x:"三楼东头的门缝里有一条亮线。整层楼早该熄了，只有那一条，薄薄地贴着地板，被门框切得很直。你走近，先听见鞋底与地胶摩擦的细响，接着是呼吸——很短，收得很急，每一口气都在同一个位置断掉，像被谁掐住了半拍。"},
    {t:"n", x:"你把脸贴近门上那块窄长的观察窗。里面只开了中间两排灯，靠墙半边的镜子沉在暗里，另一半照出一块很亮的地板。地板上有一道擦了又湿的印子，从把杆前一直拖到镜子根。沈时雨站在光的正中间，练功服后背洇深了一片，深棕色头发黏在额角，脚踝上缠着一圈旧护踝，边缘已经起球。"},
    {t:"n", x:"音响在重复同一段八拍。第四个转圈落地的时候，他的膝盖向内折了一下，撑住，又直起来。第二遍落地，小腿在抖，抖得能从镜子边沿的反光里看出来。他停下来，两手按住大腿，弯下腰，肩膀一起一伏，嘴里数到三，再直起身，去够音响的播放键。"},
    {t:"d", who:"沈时雨", fx:"sad", x:"“再来一遍……最后一遍。”"},
    {t:"n", x:"他对着镜子里的自己说，声音很轻，落在空屋子里的回声却很清楚。音响重新起头，第一个八拍就进得晚了。他抬手的时候，右肩先抖了一下，像里面有一根线绷断了半根。你没有动，掌心的汗把表格上那两行红笔字迹蹭花了一点。"},
    {t:"choice", prompt:"播放键又亮了起来。",
      options:[
        {x:"推门进去，先替他把把杆按住。", heart:{沈时雨:3, 温以恒:1},
         cb:"门轴响了一声。他整个人弹了一下，回头看见是你，脸上的血色先退后涨，手在裤缝上擦了擦。"},
        {x:"在门外，把剩下的八拍数完。", heart:{沈时雨:2, 苏景行:1, 林墨轩:1},
         cb:"你把手指按在门板上，跟着数下去。第八拍落地的时候，屋里的人正好也落了地——两个人隔着一扇门，踩在同一拍上。"},
        {x:"先看着他把这一遍跳完。", heart:{林墨轩:2, 沈时雨:1},
         cb:"你把表格卷成筒，靠在墙上。他把这一遍跳完了，才发现门上的观察窗里有一个人影。"}
      ]},
    {t:"n", x:"音乐被按停，屋子里突然静得有点响，冷却的灯管发出很细的嗡声。他站着没敢动，脚尖还朝外撇着，护踝上那圈毛边在灯下起了亮。地板上那团新汗印慢慢往外洇，把他赤着的脚底衬得像踩在一块深色的纸上。"},
    {t:"d", who:"沈时雨", fx:"shy", x:"“队长哥……你怎么还没走。我、我就再练一遍。真的。”"},
    {t:"n", x:"你还没答话，走廊那头传来很轻的两声。门口的墙边，不知什么时候放了一只保温壶：不锈钢壶身，壶盖边缘有一道磕出来的浅凹，外面套着洗得发白的布套，套子上缝着一只歪掉的标签。壶口还冒着气，一小股白烟贴着壶身往上爬，散在冷空气里。走廊那头站着个人，棕色头发被夜里的风压得有点塌，袖口卷到小臂，手腕上那一圈烫红的印子还在。"},
    {t:"d", who:"温以恒", fx:"smile", x:"“不要空腹练。壶里是姜枣水，喝完再跳，好吗？”"},
    {t:"choice", prompt:"壶口还在冒气，房间里静得能听见灯管的声音。",
      options:[
        {x:"“喝十分钟。十分钟以后我再陪你练。”", heart:{沈时雨:2, 温以恒:1},
         cb:"沈时雨把壶盖拧开，热气扑在他脸上，睫毛上凝了一层很薄的水汽。他小口小口地喝，像怕喝快了就没有了。"},
        {x:"倒一杯放在把杆上，谁都没说话。", heart:{沈时雨:1, 林墨轩:1},
         cb:"杯里的水凉到刚好能入口的时候，他自己端起来喝了。喝完把杯子放回原处，正对着壶。"},
        {x:"追出去问温以恒：你自己那份呢？", heart:{温以恒:3, 陆清越:1}, flag:"yiheng_cup",
         cb:"你追到走廊拐角。温以恒愣了一下，把手往袖子里收了半寸：我回房再煮，水还热着。"}
      ]},
    {t:"n", x:"那十分钟里，屋子安静下来。姜味顺着热气散开，把地胶那股甜涩味压下去一层。沈时雨坐在地板上，两条腿伸得很直，护踝被他解开一半，露出底下发红的一圈印子。他没说话，只把壶抱在膝盖上，指尖贴着壶壁，像在确认它还热不热。门被推开的时候几乎没有声音——林墨轩站在门口，黑色短发上还带着一点水汽，显然刚从楼上的琴房下来。他看了一眼地板上的壶，又看了一眼镜子前那摞谱子，什么都没问，径直走过去，把谱架往沈时雨手边挪了半尺。"},
    {t:"n", x:"然后他坐了下来，没说话，只把一张折过两道的谱子摊开在把杆上，用指节在谱架边沿敲了两下：一，二。沈时雨愣着没动，他又敲了两下，比刚才重一点。敲到第三遍的时候，沈时雨站了起来。节拍从他指节底下出来，不快，稳得像一根拉直的线。他不唱，也不出声数，只在谱子上该进的那一拍轻轻点一下。沈时雨跟着走，第一个转圈落地时腿还是抖的，第二个就压住了。镜子里三个人：一个坐着敲，一个跳，一个站在门边，谁都没有开口。"},
    {t:"heart", who:"林墨轩", delta:1},
    {t:"d", who:"林墨轩", fx:"neutral", x:"“重音在第二拍。你一直在等第四拍。”"},
    {t:"n", x:"沈时雨在原地站了两秒，重新抬手。这一遍进拍的时候，肩没有再抖。林墨轩看着镜子里的他，敲了最后三下，然后把手收回去，垂在膝盖上。"},
    {t:"d", who:"林墨轩", fx:"neutral", x:"“明早六点半。”"},
    {t:"n", x:"他把谱子折回原来的两道痕，塞进外套内袋，站起来时膝盖响了一声。走到门口，他停了半秒，像是还要说别的，最后什么也没说。门在他身后合上，走廊的声控灯亮了一格，又灭了。墙上的钟跳到二十三点五十五，秒针走过数字的时候有一声很轻的涩响。"},
    {t:"phone", who:"温以恒", msgs:[
      {f:"them", x:"小队长，壶我放在门口了。要是他喝完了，跟我说一声，好吗？", time:"23:58"},
      {f:"me", x:"喝完了。盖子他拧得很紧。"},
      {f:"them", x:"那就好。你也早点休息。", time:"23:59"}
    ]},
    {t:"n", x:"沈时雨跟着出去洗毛巾。门开着，走廊的光斜进来一块，把地板照出一道浅色的梯子。屋里只剩你，和落在谱架上那张纸。背包挂在椅背上，拉链没拉到底。你走过去放表格的时候，肘尖碰了一下那只背包，有什么东西从敞口滑了出来，落在地板上，啪的一声很闷——牛皮纸的封面，四个角都磨圆了，书脊上贴着一条发黄的透明胶，胶底下压着一小片贴纸，图案早已经看不清。本子摊开着，停在中间一页。"},
    {t:"diary", who:"沈时雨", date:"第2周 周二 夜里起风", x:"今天又跳到十一点。江老师让我每天多留一小时，说这句话的时候他没有看我，我也没有敢看他。今天有人站在门边看我跳，我跳完了才敢回头。温以恒哥的壶放在门口，壶盖有道凹痕，我喝完把盖子拧回去，拧到最紧，怕它凉。林墨轩哥一句话都没说，只敲拍子，敲到第三遍我才敢动；他敲的那两下比我数的要稳，我不太懂为什么。我还是不敢跟队长哥说谢谢。说出口的话会变轻，写下来就好。明天想把那个转圈跳到不晃。要是能跳到不用人替我数拍，我就去跟队长哥说一句话。"},
    {t:"n", x:"纸页上有两处被涂掉的字，涂得很用力，笔尖在纸背留下两道凸起的痕。这一页的右上角写着日期，字迹很工整，只有星期那两个字被描过第二遍。摊开的那一页边缘还沾着一点灰，是刚才落在地板上蹭的。"},
    {t:"choice", prompt:"门外传来脚步声，是拖鞋踩在湿地板上的那种响。",
      options:[
        {x:"原样塞回背包最里层，拉链留出同一道缝。", heart:{沈时雨:1},
         cb:"你把本子推进去，按回它离开时的位置。拉链停在半路，齿咬着一小块布。你退开两步，觉得这个角度正好。"},
        {x:"用他摊开的谱子盖住本子，只露出一个角。", heart:{沈时雨:2, 林墨轩:1},
         cb:"纸角盖住了本子的一半。你把谱子又挪了半寸，盖得再严一点，然后回到门边。"},
        {x:"摸出笔来，又收了回去。", heart:{沈时雨:1},
         cb:"笔帽在你指腹上抵了一会儿。你什么也没有写，把它插回口袋，布面被按出一小块温。"}
      ]},
    {t:"n", x:"沈时雨抱着毛巾回来，头发湿了一圈，看见你还在，脚步慢了半拍。他没问，走到椅边蹲下去，把本子拿起来，手在封皮上抹了一下，像要抹掉上面并不存在的灰。他看了看你，又低下头去，把毛巾搭在肩上，先去关了靠墙那半边的灯。"},
    {t:"n", x:"你把节拍器收进抽屉，发条回到零位的时候，里面轻轻咔了一声。身后，沈时雨正把日记本塞回背包最里层，拉链拉到一半，停住了。他的指腹在封皮上按了按，像按住一句还没说完的话。"},
    {t:"n", x:"灯一盏一盏灭下去。最后关掉的是镜子顶上那一排，光被收走的瞬间，整面镜子变成一块很暗的灰。门在你们身后轻轻合上，走廊的声控灯随着脚步依次亮起，又依次灭掉。你走在后面，隔着两步远，看见他把背包带子往肩上提了提，肩胛骨动了一下。你什么也没有问。"},
    {t:"end"}
  ]
});


// ===== ch05.js =====
// 第五章 首次PK赛（上） —— 作者批次B（扩写版）
window.STORY.push({
  id: "ch05",
  title: "第五章 · 首次PK赛（上）",
  phase: "选秀",
  week: 2,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"那一夜，练习室的灯是整层楼最后熄的。你把节拍器收进抽屉时，那个小东西还在轻轻打着拍，摆了三次才停住，摆锤的影子在墙上晃了三下。沈时雨正把日记本塞回背包最里层，拉链拉到一半又停住，指腹在封皮上按了按，像按住一句没说完的话。门合上之后，走廊的声控灯依次灭下去，像有人替你们把这一夜轻轻关好。"},
    {t:"n", x:"三天后，早晨六点四十。练习室的镜子还蒙着一层薄雾，是你带进来的室外空气遇热留下的，抬手一抹，指尖上留一道亮痕，过一会儿又慢慢糊回去。地板有股被反复擦过的微酸，把杆是凉的，指尖按上去会印出一个很快消失的白点。窗缝里漏进来的风带着九月的干，吹得谱架上的纸角一翘一翘，像有人在那里等着翻页。远处走廊传来推车的轮子声，滚过接缝时咯噔一下，一下接一下，把这层楼的清晨推了过来。"},
    {t:"sys", x:"【节目组】首次PK赛主题公开：绿洲。四十八小时后彩排，七十二小时后直播。请各队于今日十二点前提交曲目方案，逾期视为弃权。"},
    {t:"n", x:"十一点五十，你们挤在任务板前。那是一块白得发亮的磁贴板，边框上留着上一季没擦净的双面胶痕，指腹蹭过去有点黏。七张曲库卡片摊在长桌上，纸边被翻得起了毛，最上面那张的角上还留着谁的指印。空气里是速溶咖啡的焦苦，混着陆清越刚拆封的一盒润喉糖的薄荷味，一苦一凉，在空调风里搅在一起。"},
    {t:"d", who:"江慕白", fx:"cool", x:"“绿洲。不是舞台，是处境。沙漠里的人不会唱歌剧，他们只想活下去。”"},
    {t:"n", x:"他把细框眼镜往上推了推，转身走了，银白发尾在门框的逆光里扫过一道冷线。皮鞋跟敲在走廊上，走了六步就听不见了。板上剩下七张卡片，和七个各怀主意的人。空调在低处嗡了一声，把桌角的纸吹起来又落下，那声音像是在提醒，十二点快到了。"},
    {t:"n", x:"争论是顾知遥先起的头。他把最上面那张卡片抽出来，两根手指夹着，指甲修得很齐，卡片被他一转，正对着众人。"},
    {t:"d", who:"顾知遥", fx:"angry", x:"“本少爷说，选最炸的那首。PK赛比的是谁先被记住，不是谁更会讲故事。”"},
    {t:"d", who:"林墨轩", fx:"neutral", x:"“炸是结果，不是手段。那首的和声是空的。”"},
    {t:"d", who:"苏景行", fx:"smile", x:"“那就自己填。原曲的桥段留着，副歌前面砍两拍，加一段人声接龙——像沙漠里几个人轮流报数，谁先停下，谁先倒。”"},
    {t:"n", x:"顾知遥把卡片按回桌上，纸边被他按出一道折痕；林墨轩把那首歌的谱子摊开，指尖停在第二段和声上，停了两秒；温以恒把七只一次性杯子挨个摆开，倒水的时候没看任何人；沈时雨站在最外圈，手里的铅笔在指间转，转到第三次滑掉了，他蹲下去捡，捡起来的时候耳朵是红的；陆清越把润喉糖盒子推到桌子中间，谁也没去拿，他自己拿了一颗，含着没说话。"},
    {t:"choice", prompt:"七张卡片摊在桌上，谁也不肯先让步。",
      options:[
        {x:"“先听苏景行弹一遍。空谈不如试。”", heart:{苏景行:2, 林墨轩:1},
         cb:"苏景行笑开，把凳子让给你，自己一屁股坐到合成器前，先按出一个没成调的音试手感。"},
        {x:"“顾知遥要的炸也要。爆点留到副歌。”", heart:{顾知遥:2, 陆清越:1},
         cb:"顾知遥哼了一声，耳尖动了下，低头去理根本没乱的袖口。"},
        {x:"“先定要讲什么，再定用什么曲子。”", heart:{温以恒:2, 沈时雨:1},
         cb:"温以恒朝你点了下头。沈时雨把笔握紧了些，在纸上写了一行，又划掉。"}
      ]},
    {t:"n", x:"苏景行坐到合成器前。那是一台边角磨白的黑色键盘，中间那排键被弹得发亮，侧面贴着上一季谁留下的荧光贴纸，已经卷了边，边角上还粘着一根头发。他把袖子往上推了两下，没看谱，先按下一个低音，让它在空气里沉了三秒，才抬眼看你——从小到大的习惯，想让你先听见，再让你判断。"},
    {t:"d", who:"苏景行", fx:"smile", x:"“小队长，听这个。前两小节我不弹。”"},
    {t:"n", x:"留白。然后是三连音，像有人赤脚踩上滚烫的沙，一步一顿，顿里全是舍不得倒下。陆清越的呼吸跟着快了，含着的那颗糖被他咬碎，响了一声；顾知遥抱在胸前的手臂松了一寸；温以恒把倒好的水推到他手边，没出声；沈时雨蹲在合成器侧后方，仰着头看那排按键，像在看什么会发光的东西。林墨轩抬起了眼，把谱子往自己这边拉了半尺。旋律走到该进副歌的地方忽然停住半拍——那一拍空得像悬崖边，风从里面灌出来，灌了你一后背的凉。"},
    {t:"d", who:"林墨轩", fx:"neutral", x:"“半拍。留着。”"},
    {t:"d", who:"顾知遥", fx:"cool", x:"“……哼。勉强能听。本少爷的爆点放哪儿？”"},
    {t:"heart", who:"苏景行", delta:2},
    {t:"n", x:"曲目定下来是午后两点。之后四十个小时，你们几乎长在了这间屋子里。温以恒的早餐盒每天七点出现在门口，面包边烤得焦黄，鸡蛋剥了壳，用保鲜膜一只只分开摆好，盒盖上贴着一张便利贴，写着谁的那盒多了一块。地板上多了七道汗渍，镜子擦了又擦，指尖一碰还是凉的。夜里有人睡在把杆下面，压着一摞谱子，翻身时纸张哗啦一响，把半梦半醒的人全都惊得睁一下眼，又睡过去。"},
    {t:"d", who:"温以恒", fx:"smile", x:"“小队长，先吃了再练，好吗？凉了伤胃。”"},
    {t:"d", who:"陆清越", fx:"laugh", x:"“队长哥哥！我今天一个动作都没错！真的！”"},
    {t:"n", x:"第二天清晨五点五十，你推门进去，里面已经有人在练声。林墨轩背对着镜子，气从胸腔里一点点送出来，声音低得像地板在震，他每个音之间停一拍，停得很准。七点整，顾知遥进来，头发还是湿的，先对着镜子侧面看了三次，才把外套脱掉；他挑了一遍陆清越的走位，挑完自己拿笔在地上画了两个记号。沈时雨一直在最靠里的角落，音乐一停，他就把脚尖点在地上跟一遍，像怕别人看见。"},
    {t:"n", x:"夜里十点，卡在同一个八拍上的人是沈时雨。第三十二遍。他的练功鞋在地板上蹭出一声干响，深棕色头发被汗贴在额角，手撑着膝盖喘，肩膀一耸一耸。音乐停了，他没敢抬头，只把那半拍的谱子又看了一眼，好像那张纸会咬人。顾知遥在边上站了一会儿，把自己的水杯放在他脚边，转身去调镜子那边的灯；灯光一暗一亮，沈时雨的影子被拉长又收短，他还是没动。"},
    {t:"choice", prompt:"第三十二遍之后，屋子里只剩他的喘。",
      options:[
        {x:"“停。今天到这，明天再说。”", heart:{沈时雨:2, 温以恒:2},
         cb:"沈时雨抬起头，眼里有来不及收的感激，还有一丝不甘。温以恒把毛巾递了过去，没说话。"},
        {x:"“不是你的错。是我把走位排在换气上了。”", heart:{沈时雨:3, 林墨轩:1},
         cb:"沈时雨愣住，嘴唇动了动。林墨轩在镜子里看了你一眼，把谱架往你这边挪了半尺。"},
        {x:"关掉音响，陪他再走一遍。", heart:{沈时雨:2, 苏景行:1},
         cb:"你按下停止键，和他并排站进镜前。苏景行在角落打了个哈欠，没走。"}
      ]},
    {t:"n", x:"第二天下午，彩排。舞台的灯只开了三分之二，光落在地胶上像一层薄薄的水。耳返里全是电流的沙沙声，混着自己咽口水的动静。顾知遥在侧幕整理袖口，银灰色头发在暗处泛冷；陆清越把鞋带系了三遍，系完又蹲下去检查了两只鞋尖；温以恒挨个拍过每个人的后背，掌心是温的，拍完还停半秒，像是要确认底下那副骨架还撑得住；林墨轩站在暗处，嘴里含着气在过和声，嘴型几乎看不出来。空气里有新喷的地胶味，甜而涩，吸进鼻腔里发凉。有人在侧幕压腿，鞋底蹭出细碎的响。"},
    {t:"n", x:"音乐起。前八拍稳。第九拍，音响炸了一声——不是爆音，是彻底没了。耳返里只剩嗡嗡的白噪，全场静得能听见自己的心跳砸在肋骨上。灯光师的手悬在调音台上方不敢落下，舞台监督在台下喊了句什么，被吞进那片空白里，连回音都没有。"},
    {t:"choice", prompt:"伴奏死了。你的呼吸在耳返里被放大成海。",
      options:[
        {x:"摘掉耳返，开口就唱。", heart:{苏景行:3, 江慕白:3, 林墨轩:2}, flag:"oasis_acapella",
         cb:"你把耳返扯下来扔在地上。第一句清唱落出去的瞬间，苏景行在侧幕笑出了声。"},
        {x:"拍手定拍，示意六人跟着你走。", heart:{温以恒:2, 沈时雨:2, 陆清越:2}, flag:"oasis_clap",
         cb:"你拍响手心。节拍从一只手，变成三只、五只，最后七只，落在同一拍上。"},
        {x:"在白噪里找导播席那点冷光。", heart:{江慕白:1}, flag:"oasis_wait",
         cb:"你转过头。江慕白没有给指令，只是抬起下巴，像把决定权原样丢回来。"}
      ]},
    {t:"n", x:"没有伴奏的舞台只剩人声。你听见苏景行在左后方接上第二句，林墨轩的低音垫在下面，稳得像地面。陆清越的声线亮，顾知遥的尾音利，温以恒的和声像一只手托在底下。沈时雨最后一个进来，声音发颤，却没有断；进来之前他先吸了一口气，那口气在空气里留了很短的一下，像起跳前脚掌点地。七个声音在那半拍的悬崖边站成一排，谁也没掉下去。唱到最后一句时，你听见台下有人吸了下鼻子，很轻，混进那片还没修好的寂静里。"},
    {t:"m", x:"原来没有伴奏的时候，人才听得清彼此。"},
    {t:"d", who:"江慕白", fx:"cool", x:"“记住现在的声音。明天，它要有伴奏。”"},
    {t:"n", x:"灯一盏盏灭下来，舞台重新变回一块空地，地胶上留着七双脚的浅印。你弯腰捡起那只被你扔掉的耳返，塑料外壳还带着掌心的温度，线在脚边绕了一圈。走出侧幕时，走廊的公示屏正在刷新，明晚八点的直播场次排在第一行，光标一闪一闪，像有人在等你落笔。汗顺着后颈流进衣领，凉得你打了个颤。身后，妆发间的灯还亮着，把七个影子拉进走廊，长长地铺在你脚边。"},
    {t:"end"}
  ]
});


// ===== ch06.js =====
// 第六章 首次PK赛（下） —— 作者批次B（扩写版）
window.STORY.push({
  id: "ch06",
  title: "第六章 · 首次PK赛（下）",
  phase: "选秀",
  week: 2,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"彩排那晚的清唱，在你耳朵里留了整整一天。第二天下午你把那半拍又走了二十遍，直到镜子里的人不再抢拍，才肯停手；镜面上数出二十层薄薄的手印，你拿毛巾从上往下擦了一次，全没了。手机在裤兜里震过三次，家里问几点播，你回了个时间，没敢多打一个字。傍晚七点二十，距离直播还有四十分钟，你把鞋带重新系了一遍，系得很紧，打结的时候指腹被勒出一道白痕。"},
    {t:"bg", v:"greenroom"},
    {t:"n", x:"后台的温度比走廊高两度，灯是暖黄的，把每个人的影子都揉软了。化妆台上摊着七支编号的粉底液，海绵蛋压出一个个小坑，台面黏着一点没擦净的亮片，灯光一斜就闪。空气里是发胶的甜和定型喷雾的酒精味，混在一起有点呛。镜前那圈灯泡把你的脸圈住，热度顺着颧骨一点点往上爬。隔壁妆位有人说笑，笑声隔着布帘传过来，听着比实际远。"},
    {t:"d", who:"温以恒", fx:"smile", x:"“小队长，先吃半块巧克力再上，好吗？手别凉着。”"},
    {t:"d", who:"陆清越", fx:"laugh", x:"“队长哥哥！我腿在抖！但是是开心的抖！”"},
    {t:"n", x:"林墨轩坐在最靠里的妆位上，背对着镜子，把气一点点送出来试声，试了两遍就停；他把袖扣解开又扣上，扣了两次才扣正。顾知遥对着镜子侧面看了三回，把一根翘起来的头发按下去，按完又看了看灯光打过来的角度，才把外套搭在椅背上。沈时雨蹲在墙角检查耳返的线，绕了四圈，一圈也没敢多绕。"},
    {t:"sys", x:"【节目组】首次PK赛直播将于二十点整开始。本场开启实时弹幕通道，观众评论同步显示于后台及侧幕监视屏。请各队就位。"},
    {t:"n", x:"监视屏第一次亮起来的时候，弹幕像水一样漫上来，一行一行往上滚，快得看不清尾巴。那是一块挂在侧幕边的竖屏，边框贴着防滑胶带，屏幕的光是冷的，打在几个仰着头的脸上，像覆了层薄霜。陆清越踮脚去看，被顾知遥按住后脑勺按回椅子上，动作粗，手却没用力；苏景行凑过去扫了两眼，笑着念出一条，念到一半自己先没了兴趣。"},
    {t:"bg", v:"stage"},
    {t:"n", x:"进通道之前要排成一列。沈时雨站在最前面，因为他的位置离上场口最近，他把手贴在墙上，跟着返送里的鼓点数拍，嘴唇动着，没出声音；陆清越排在第二个，嘴里哼着副歌，一声比一声轻；林墨轩一言不发，把手腕转了两圈；顾知遥最后看了一眼门框上反光的自己，把领口往下压了半寸；苏景行在你身后半步，把一瓶水递过来，瓶壁上还留着他掌心的温度。前面那组的声音正从通道里撤出来，脚步杂，鞋底擦着地面，越走越近，然后从你们身边过去。"},
    {t:"choice", prompt:"上台前还有三十秒。六个人在你身后，看着你的后脑勺。",
      options:[
        {x:"“那半拍谁都别抢。我数到三。”", heart:{林墨轩:2, 沈时雨:2},
         cb:"黑暗里，林墨轩应了一声。沈时雨把呼吸一寸寸压下去，压到听不见。"},
        {x:"“赢了回去我请。想吃什么现在报。”", heart:{陆清越:3, 顾知遥:2, 苏景行:1},
         cb:"陆清越小声报了三样。顾知遥哼了一声，说本少爷不稀罕，报的却是最贵那家。"},
        {x:"转身，挨个拍过六个人的肩。", heart:{温以恒:3, 苏景行:2, 沈时雨:1},
         cb:"你从苏景行拍到沈时雨，最后那只手停在陆清越头顶，揉了一下。温以恒在最后面，朝你弯了弯眼睛。"}
      ]},
    {t:"n", x:"通道的地面是斜的，要先下两级台阶，墙面的颗粒粗，指腹蹭过去有点硌。前一组还没散的掌声隔着厚绒布传进来，闷得像水底。温以恒在通道口挨个数了一遍人头，数到第七个才让开；苏景行在你身后捏了下你的后颈，手一触即离。然后灯亮了——不是渐亮，是一下子全开，白得让人眼前发黑，视网膜上还留着最后那片黑的余印。地胶被上一组踩得发烫，热度透过鞋底一路传上来。前奏进来，你听见自己的声音从返送里回来，比记忆里稳。"},
    {t:"danmaku", items:[
      "星途野生制作人|来了来了 开场就这？",
      "苏苏的小甜饼🍪|这个走位也太齐了吧啊啊啊",
      "队长冲鸭🚀|七个人站一起气场好强 我腿软",
      "墨轩的黑胶唱片|和声稳得像铺了一层地板",
      "一只遥遥的猫|银灰头发那个眼神杀我",
      "时雨今天也要加油|左边那个弟弟是谁 跳得好狠",
      "清越的小太阳|金毛忙内好可爱 蹲一个名字"
    ]},
    {t:"n", x:"副歌前，那半拍。你抬手，六个人同时收声。整场两千人，加上屏幕那头数不清的人，一起掉进了那个洞里。半秒。然后七个声音一起落下来，像一堵墙平推过去。舞台的灯在这一拍里切成了冷蓝，打在汗上，每一滴都亮一下。"},
    {t:"danmaku", items:[
      "星途野生制作人|这半拍留得太狠了 谁编的",
      "队长冲鸭🚀|鸡皮疙瘩起来了 有没有人懂",
      "阿白的小学徒|彩排那个无伴奏是真的 我当场哭",
      "每天都要早睡|这个临时队长到底是谁啊 求名字",
      "遥遥领先本人|本少爷的爆点来了！看到了吗！",
      "时雨今天也要加油|他没断！他真的没断！",
      "苏苏的小甜饼🍪|七个声音像一条河 救命啊"
    ]},
    {t:"n", x:"最后一个音收干净。场上静了半秒，掌声才炸开，像迟到的浪。你鞠躬时听见自己的心跳，一下一下撞在耳膜上。汗从额角滑进眉毛，涩得眼睛发酸，你没敢抬手去擦。退到侧幕，六个人挤成一团，陆清越先叫出了声，声音劈了，他自己都没发觉；沈时雨扶着墙在喘，喘到一半忽然抬起头，去看侧幕外那片还在滚动的弹幕；林墨轩把外套从椅背上一把抓下来，谁也没给，自己攥在手里；顾知遥别着脸，肩膀抖得停不住；温以恒挨个数人头，数到第七个，才像终于把那口气喘上来。"},
    {t:"n", x:"主持人念分数的语速很慢，慢得像故意。前两组的数字报完，场上响起有礼貌的掌声。念到你们这一栏时，他停了一下，抬眼往你们这边看——那半秒比整场演出还长。空气里有股静电的味道，舌尖发麻。然后数字跳出来，第一。"},
    {t:"sys", x:"【节目组】首次PK赛最终结果：临时队长组总分第一。实时弹幕互动值计入本周热度榜，结果将于今晚同步至官方平台。"},
    {t:"weibo", items:[
      "#星途临时队长是谁# 2.3亿",
      "#绿洲舞台无伴奏半拍# 1.7亿",
      "#星途首次PK赛第一名# 1.5亿",
      "#苏景行改编封神# 0.9亿",
      "#银灰头发那个是谁# 0.6亿",
      "#星途七人组# 0.5亿"
    ]},
    {t:"n", x:"热搜第一那条，是你在后台的长椅上刷到的。手指停了两秒。你的名字还没被写进去，被一个称呼顶在最前面，像一个等人认领的空位。屏幕的冷光把你的脸照得发白，屋里其他人还在闹，声音隔着一层水传过来，一下近一下远。"},
    {t:"choice", prompt:"手机屏幕一直亮着，没熄。",
      options:[
        {x:"把手机递给苏景行看。", heart:{苏景行:3},
         cb:"他扫了一眼，嗤地笑出声，把手机塞回你手里：小队长，名字早晚要写上去的。"},
        {x:"收起手机，先去跟每个人碰拳。", heart:{顾知遥:2, 陆清越:2, 沈时雨:1},
         cb:"你把屏幕扣在腿上。陆清越扑过来撞了下你的肩，撞得你往后一晃，撞翻了半杯可乐。"},
        {x:"在群里发一句：是我们七个。", heart:{温以恒:2, 林墨轩:2, 沈时雨:2}, flag:"oasis_seven",
         cb:"群里先是静了三秒，接着七条消息几乎同时弹出来。最后一条是林墨轩的：嗯。"}
      ]},
    {t:"n", x:"庆功拖到凌晨一点。基地食堂留了一排灯，长桌上摆着节目组发的披萨，纸箱的油透过盒底洇出一圈深色，指尖碰上去是滑的。空气里是可乐开罐的甜，混着披萨边烤焦的糊味。七个人横七竖八地坐，椅子不够，有人坐到窗台上，脚在半空一晃一晃，把窗玻璃踢出闷响。沈时雨坐在长桌最靠墙那一边，先把自己那块披萨边整整齐齐地留在盘子里，一直没动。"},
    {t:"d", who:"顾知遥", fx:"cool", x:"“哼。第一而已。本少爷下次要压过你们所有人的票数。”"},
    {t:"d", who:"苏景行", fx:"smile", x:"“小队长，那半拍你今天数得比彩排准。”"},
    {t:"d", who:"林墨轩", fx:"neutral", x:"“前八拍里有一拍松了。回去听一遍录音。”"},
    {t:"n", x:"陆清越举着纸杯站起来，说要敬大家一杯，敬到一半发现杯子里只剩冰块，自己笑倒在温以恒肩上。温以恒把披萨盒往中间推了推，推到第七个人的手边，才想起来还差一个人。苏景行把空纸盒折成一只歪歪扭扭的船，推到桌子中央，谁也没碰它，它就在那儿搁着；顾知遥翻出一张拍糊了的合影，说拍得不好，手指却停在屏幕上没划走；林墨轩靠墙坐着，把手机举到耳边听了两遍录音，听完把耳机分了一只给沈时雨。闹到一半，你发现陆清越不见了。窗台空着，那头金色头发在暗处最显眼，如今人群里找不到那点亮。你端着纸杯沿走廊找，在消防通道的台阶上看见他——抱着膝盖，肩膀一抽一抽，哭得很小声，像怕被人听见。楼梯间那盏声控灯灭着，只有安全出口的绿光勾出他一边的轮廓。"},
    {t:"choice", prompt:"台阶很凉，他只穿了件薄外套。",
      options:[
        {x:"在他旁边坐下，把外套披过去。", heart:{陆清越:4, 温以恒:2}, flag:"qingyue_coat",
         cb:"你把外套搭上他的背。他往你这边挪了半寸，没抬头，肩膀却不再抖得那么厉害。"},
        {x:"“想家了？”", heart:{陆清越:3},
         cb:"他猛地点头，又拼命摇头，最后把脸埋进膝盖里，闷闷地嗯了一声。"},
        {x:"什么都不问，把纸杯塞进他手里。", heart:{陆清越:2, 沈时雨:1},
         cb:"他接过杯子，指尖碰到温热的杯壁，抖了一下，然后用两只手捧住了。"}
      ]},
    {t:"d", who:"陆清越", fx:"cry", x:"“队长哥哥……我不是难过。我就是、就是突然想起，我妈总把披萨边留给我。”"},
    {t:"n", x:"说完他又哭，这次没忍住，声音一下子冲出来，在消防通道里撞出回音，惊得声控灯亮了，亮了又灭。你伸手，一下一下拍他的背，隔着薄外套能摸到他脊椎的节，一节一节，硬硬的，还在长。他脚边放着一只盘子，盘里那块披萨边被撕成很小的一条一条，摆得像一排栏杆。"},
    {t:"d", who:"温以恒", fx:"smile", x:"“小队长，交给我，好吗？他小时候闹觉，要拍背才睡得着。”"},
    {t:"n", x:"温以恒蹲下来，把陆清越整个揽过去，掌心在他背上慢慢画圈，动作熟得像做过几百回。他自己的眼下也有乌青，被那盏声控灯照出来一瞬，又灭了。他没看你，只低声哄，哄到那点哭声一点点矮下去，矮成间隔越来越长的抽气。回宿舍的路上，基地的路灯把积水照成一块块碎银，你把外套留在了陆清越身上，袖子空着，夜风直接灌进领口。走到一半，沈时雨追上来，把手里的半瓶水塞给你，什么也没说，又退回温以恒那边。手机在裤兜里震了一下，是节目组群发：明早九点，全体练习生集合，主题曲任务发布。"},
    {t:"end"}
  ]
});


// ===== ch07.js =====
// 第七章 主题曲任务 —— 作者批次B
window.STORY.push({
  id: "ch07",
  title: "第七章 · 主题曲任务",
  phase: "选秀",
  week: 3,
  nodes: [
    {t:"bg", v:"dorm"},
    {t:"n", x:"闹钟响到第二遍，你才把自己从被子里拔出来。庆功闹到凌晨一点，宿舍里三个人的呼吸还压得很沉，窗帘缝里漏进一条灰白的天光，斜斜落在床尾那件外套上。外套被叠成了方块，四个角压得很齐——昨晚你把它留在消防通道，只有一种人会把它叠成这个样子。口袋里躺着一颗玻璃珠，透明的，芯里绕着一道彩色的螺旋，你用指尖一转，那道纹就跟着转。陆清越说过，这种珠子能把好运存起来。你把珠子塞回兜里，又在镜前把眼睛下面那块青色看了一遍，用冷水拍了三下脸。"},
    {t:"n", x:"八点五十，你推开大厅的门。空气里是消毒水混着新印节目单的油墨味，淡淡的，像放凉的凉白开。一百个人按班级列了队，地胶上贴着新换的站位标记，黄胶带的边角翘起一小截，被谁的鞋跟碾黑了。广播里的电流声先响了一下，落下去，然后PD的声音从四个方向的喇叭里同时压下来，压得脚底的地砖都在发麻。前排有人小声说了半句，立刻被旁边的人碰了碰胳膊。"},
    {t:"sys", x:"【节目组】主题曲任务发布：即日起全体练习生统一学习主题曲《Drift》。C位由现场互投产生，一人一票，不得代投，结果于本周内公布。"},
    {t:"n", x:"大屏亮起来的时候，扬声器先送出一小段钢琴，接着是低频。那低频从地胶底下钻上来，贴着脚底板一路撞到胸口，撞得肋骨发毛。副歌进来的那一下，你忽然觉得脚下有东西在漫——像站在一块刚离岸的木板上，四面八方都是黑的水。《Drift》，漂。歌名在屏幕上停了三秒，笔画很细，像被水冲过一次。你听见身后有人跟着哼了半句，哼到那个气口，断了。"},
    {t:"d", who:"苏景行", fx:"sleepy", x:"“小队长，这歌我昨晚在楼道里听了四十遍。副歌第二句，气口是空的，谁抢谁死。”"},
    {t:"d", who:"林墨轩", x:"“Dorian转小调。副歌前留半拍。”"},
    {t:"d", who:"顾知遥", fx:"cool", x:"“哼。半拍空着谁不会。难的是跳完别喘成风箱，镜头一怼，全完。”"},
    {t:"n", x:"教编舞的是个瘦高的男人，灰色工装裤的裤脚卷了两道，露出脚踝上一道旧疤，帽檐压得很低，只看得见下巴上一点没刮净的胡茬。他没自我介绍，抬手数完八拍，跳了一遍——动作干净得像刀口。跳到副歌，他停住，指了指场地正中央那块空着的位置。那里连记号都没贴。"},
    {t:"d", who:"陆清越", fx:"laugh", x:"“《Drift》！我在家就单曲循环过！我妈说我唱副歌像在喊救命！”"},
    {t:"n", x:"“中间这块，等人。”教编舞的人说完就去拧水瓶了。下午是自由练习，镜子里那块空地像一块没写字的匾，谁都不肯先站上去。你把八拍过了一遍，余光里六个人都在看你，看你怎么安置那块空出来的位置。头顶有一根灯管接触不良，隔几秒闪一下，闪的那一下，那块空地上的白比别处亮一点。"},
    {t:"choice", prompt:"镜子正中央那块地胶上，什么都没有。谁先站上去，谁就等于先要了。",
      options:[
        {x:"“先不管中间。八拍过齐，我数到三。”", heart:{林墨轩:2, 沈时雨:2},
         cb:"你把“三”咬得很短。镜子里七个人的脚尖同时点地，声音像一册书合上。林墨轩抬了下眼，什么也没说。"},
        {x:"走过去，把那八拍先自己走一遍。", heart:{苏景行:2, 顾知遥:1},
         cb:"你踩上那块没贴记号的地胶。苏景行在你身后懒洋洋地鼓了两下掌，顾知遥哼了一声，眼睛却没离开镜子。"},
        {x:"侧身让开半步，朝沈时雨抬了抬下巴。", heart:{沈时雨:4, 温以恒:2},
         cb:"沈时雨愣了两秒，才慢慢走上去。他的第一遍慢了半拍，落地却很轻，像怕踩坏什么。温以恒在边上把水杯放下了。"}
      ]},
    {t:"n", x:"下午的练习室里，空调出风口一直在响，风是干的，吹得喉咙发紧。沈时雨卡在副歌第三个八拍——转身那一下，他总要慢半拍，慢完自己也知道，耳根一直红到脖子。他没停，一遍一遍重来，数拍子的嘴唇动着，鞋带松了也没蹲下去系。汗从他后颈淌下来，在衣领上洇出一小条深色；手心的汗把裤缝蹭得发暗，他就把手在裤子上按两下，再抬手。"},
    {t:"d", who:"沈时雨", fx:"sad", x:"“……队长。我……我再来一遍。”"},
    {t:"n", x:"温以恒进来时端着那只旧保温壶，壶身上有一道磕痕，是他来的第一天就带着的。他挨个倒水，杯壁上很快浮起一层白雾。轮到你，他没倒水，先从兜里摸出一颗糖，剥了纸递过来，糖纸在他指间被折成很小的一方。门开合的间隙里，走廊上的消毒水味飘进来一缕，很快被练习室里的汗味压住了。他倒完最后一个人，把壶底在桌沿上磕了磕，把最后一滴水也倒干净。"},
    {t:"d", who:"温以恒", fx:"neutral", x:"“小队长，今天第三颗了。早饭吃了多少，嗯？”"},
    {t:"weibo", items:[
      "#星途主题曲Drift发布# 1.4亿",
      "#Drift副歌前那半拍# 0.8亿",
      "#主题曲C位你希望是谁# 0.7亿",
      "#苏景行改词还是改舞# 0.4亿",
      "#星途临时队长又出现了# 0.3亿",
      "#陆清越喊救命式唱法# 0.2亿"
    ]},
    {t:"n", x:"夜里十一点，你回练习室取落在琴凳边的东西。走廊的灯只开了一半，人一走过去，头顶的感应灯就一小段一小段地亮，亮完在你背后灭掉，像有人替你收尾。灯罩上积着灰，光里浮着细小的尘粒，慢慢地翻。走到消防通道门口，你停了一下——门虚掩着，留了一道掌宽的缝，缝里的声音先撞上你的耳朵：先是顾知遥的，尾音挑得很高；再是苏景行的，比他平时低一点，懒不下来。"},
    {t:"d", who:"顾知遥", fx:"angry", x:"“苏景行，你票差队长多少，你自己心里没数？中间那个位置，谁不想要？……你有毛病。”"},
    {t:"d", who:"苏景行", fx:"smile", x:"“有数。所以我把写好的那张划了。”他停了一下，“我不想要。”"},
    {t:"n", x:"你站在拐角，没有动。水杯攥得很紧，杯壁的凉一点点渗进掌纹，指节发僵。头顶那盏声控灯熄了，你没敢挪脚，怕它亮——亮了，缝里的人就会知道外面有人站着。楼道尽头有人拖着器材车走过，金属轮子碾出一串细响，一直响到拐角那头，才慢慢断掉。你听着自己的呼吸，把它压得比平时还轻。"},
    {t:"n", x:"缝里的人都走了。你等到脚步声上到三楼，才走过去。门边的地砖上躺着一张对折的卡片，不知从谁的口袋里滑出来。你捡起来，展开。卡片上印着一个窄格子，格子里本该写一个名字——那里原本写了三个字，被一道很重的一横划掉，划痕把纸背都顶起一点，翻过来能看见一道凸起的白线。格子外面，补着两个连笔的字：队长。穿堂风从门缝里挤过去，卡片在你手里抖了一下。"},
    {t:"m", x:"被划掉的那三个字，我认得。在他写歌的本子上，在他校服的领标上，我见过很多年。他划下去的时候，笔尖顿了一下。那个顿，我也认得。"},
    {t:"choice", prompt:"卡片在你手里，纸很薄，一用力就会折出新的痕。走廊那头没有人。",
      options:[
        {x:"第二天把卡片摊在镜前，当着所有人问他。", heart:{苏景行:-1, 顾知遥:2, 陆清越:1}, flag:"c_exposed",
         cb:"你把卡片按在化妆台上。苏景行看了一眼，笑还挂着，手指却在裤缝上收了半寸。“捡到了？”他说，“那不算我的。”旁边有人停下了手里的动作。"},
        {x:"等他一个人的时候，把卡片放回他手里。", heart:{苏景行:4, 林墨轩:1}, flag:"c_private_talk",
         cb:"练习室只剩他一个。他翻过卡片看了一眼，指腹在那道划痕上磨了两下，懒洋洋的调子低下去半度：“小队长，这张纸你留着。以后想看，随时看。”"},
        {x:"照原样折回去，放回门边，什么都不说。", heart:{苏景行:2, 温以恒:2}, flag:"c_silent",
         cb:"你把它折回原来的角度，塞进门缝底下。第二天苏景行看你的那一眼比平时长了半秒，你接住了，两个人都没提。"}
      ]},
    {t:"sys", x:"【节目组】主题曲C位互投结果已产生。请全体练习生今晚八点至大厅查看公示，得票最高者担任主题曲舞台中心位。"},
    {t:"n", x:"票是一条一条跳出来的。大厅的白光把屏幕照得发亮，跳到最后，两个名字之间只差两票。你的在上面，苏景行的在下面。有人在你背后抽了口气，也有人先鼓起掌，掌声稀稀拉拉地涨起来。王腾站在离你不远的地方，红发被灯压得发暗，他把手里的号码牌翻了个面，塞回口袋，转身走了，肩胛骨在衬衫底下顶出一条很硬的线。"},
    {t:"d", who:"苏景行", fx:"smile", x:"“小队长，中间那块地儿风大。站稳点。”"},
    {t:"n", x:"你踩上那块没贴记号的地胶。顶灯正对着你，热气从发顶一路落到肩胛，汗还没出，皮肤先绷紧了。镜子里，你站在正中，六个人的位置在你两侧排开，像一条铺好的河道。你抬起手的那一瞬，心里有个很轻的声音说：这块地不只属于你一个人。落地的那半拍，你数得比彩排还准，脚跟砸在地胶上，声音干净。"},
    {t:"n", x:"人都散了，练习室还亮着。你把中央那八拍又走了三十遍，走到手臂抬起来就发酸，才肯停。走廊尽头的钟指过十一点半，你想起今天只吃了一顿，胃里空得发凉，像一口没盖盖子的井。收拾东西的时候，那颗玻璃珠从兜里滚出来，在地上转了半圈才停住。你把它捡起来，塞回最里面那个兜，指腹在滚圆的那一面按了按。"},
    {t:"end"}
  ]
});


// ===== ch08.js =====
// 第八章 裂缝 —— 作者批次B
window.STORY.push({
  id: "ch08",
  title: "第八章 · 裂缝",
  phase: "选秀",
  week: 3,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"第3周，主题曲任务的第三天。六点半的闹钟把你从梦里拔出来时，天还是深灰的，窗玻璃上凝着一层薄雾，手背贴上去，凉。练习室那排顶灯只开了最左边一盏，光斜着铺过半场地胶，昨晚的脚印还没被拖干净。你把中央那八拍走了四遍，走完才想起来早饭这件事。胃是空的，凉的，像一口落了水的井。镜子里的人抬手、转身、收势，动作都对，脸色却比墙上那块白板还白。"},
    {t:"n", x:"食堂这个点只有两桌人。温以恒坐在靠窗那一桌，面前摆着七个碗，粥的热气把窗玻璃又熏白了一小块。他记得每个人的口味：林墨轩那碗不放糖，顾知遥那碗浮着两片火腿，沈时雨那份底下埋了一个蛋。轮到你，他把碗推过来，指节上有一小块新烫的红，红得发亮，他没遮。你看了眼墙上的钟，钟的秒针走得比平时响。"},
    {t:"choice", prompt:"粥的热气正往上走，时间也正往上走。",
      options:[
        {x:"拉开椅子坐下，把整碗喝到见底。", heart:{温以恒:3, 林墨轩:1}, flag:"breakfast_kept",
         cb:"粥烫，你喝得急，舌尖被烫麻了一小块。温以恒把空碗收走时，指节在你手背上碰了一下，像试试温度，又像确认什么。"},
        {x:"“我带着路上吃。”把鸡蛋和面包塞进包里。", heart:{温以恒:2},
         cb:"温以恒看着你把鸡蛋塞进侧袋，又补进去一盒牛奶，动作熟得像做过几百遍。“小队长，”他说，“别让我明天再数一遍少了几盒。”"},
        {x:"把蛋和火腿拨进旁边沈时雨的碗里。", heart:{沈时雨:3, 温以恒:-1},
         cb:"沈时雨的筷子停在半空。“队长……我吃不了这么多。”可他还是低头把蛋吃了，吃得很慢，像在吃一样很贵的东西。温以恒看了你一眼，把要说的话咽了回去。"}
      ]},
    {t:"n", x:"上午的练习是对着镜子抠主题曲。九点半，门被推开，江慕白走进来——今天他没打领带，衬衫袖口挽到小臂，细框眼镜后的灰眸先扫过镜面，再落到你身上。他手里夹着那本深灰色的评分册，边角磨得起了毛。他没有喊停，只站在侧幕的位置看，看了整整两段。练习室里没人说话，连头顶空调的风声都像被谁调小了一格。他把评分册夹在臂弯里，指节在封面上敲了两下，像在数拍子。"},
    {t:"d", who:"江慕白", fx:"cool", x:"“停。小队长，你在赶那半拍。半拍是空的，不是让你填满的。”"},
    {t:"n", x:"他合上评分册，走之前只留了一句：把你自己的呼吸放进去，别放别人的。门在他身后合拢，带起一小股风。你回到起点，重新数。第三遍的时候对了，膝盖压下去那一下，镜子里七个人的影子同时低了一寸。沈时雨的呼吸在你右后方，一板一眼，没有抢。林墨轩把拍子敲在琴键上，极轻，像给你垫了一块东西。傍晚散场，走廊那头的灯已经灭了一半，你留下把最后两个八拍补完——这一补，补到了天完全黑。"},
    {t:"weibo", items:[
      "#星途主题曲C位公布# 1.1亿",
      "#主题曲C位票差两票# 0.7亿",
      "#临时队长主题曲C位# 0.6亿",
      "#苏景行互投票数第二# 0.5亿",
      "#C位是不是内定# 0.3亿",
      "#星途练习室直播机位# 0.2亿"
    ]},
    {t:"bg", v:"corridor"},
    {t:"n", x:"从练习室回宿舍要穿过一条长走廊。晚上十点，走廊的灯只亮一半，白墙把冷光反上来，看久了眼睛发酸。你走到自动贩卖机旁边时，脚步开始不对——先是耳朵里嗡了一下，像有人把音量旋钮往左拧；接着地面轻轻往上一浮，膝盖先软了半寸。你伸手去扶墙，指尖从墙面上滑下去，指甲刮过漆面，留下一道白痕。手里的水瓶磕在踢脚线上，滚了出去，在走廊里响了很多下。你咽了口唾沫，喉咙干得发涩，像塞着一小团棉花。"},
    {t:"n", x:"“小队长。”声音是从背后来的，很轻，却比平时快。温以恒的手先落到你肩上——那只手是热的，很稳，掌心带着洗衣液淡淡的皂味，还有一点刚出炉的黄油甜。他半跪下来，把水瓶捡回你手边，又扶着你的脸转过来对着灯看，眉压得很低。走廊的感应灯在他头顶亮着，把他的影子整个盖在你身上。他的呼吸比平时重，落在你耳边，一下一下，很稳。"},
    {t:"d", who:"温以恒", fx:"shock", x:"“看着我。别闭眼。……早饭一颗糖，就这些，是不是？”"},
    {t:"n", x:"他把外套脱下来垫在你背后，把你往墙上扶正。地砖的凉隔着裤子也能咬到骨头。他从兜里摸出一颗糖，剥开，直接塞进你嘴里，糖纸捏在手心没丢。甜味从舌尖一路漫下去，你才发现自己在抖，膝盖在抖，握过水瓶的那只手也在抖。他把你的手腕翻过来，用两根手指按在上面，数了几秒，眉头松开半寸。那几秒比你今晚数过的所有拍子都长。"},
    {t:"d", who:"温以恒", fx:"sad", x:"“缓一缓。缓好了，我们再说话，好吗？”"},
    {t:"choice", prompt:"糖在你嘴里化开，他还捏着那张糖纸没扔。",
      options:[
        {x:"把口袋里攒的糖纸全掏出来，摊在他手心。", heart:{温以恒:4}, flag:"truth_candy",
         cb:"糖纸被汗浸过，皱成一团一团，全是他这几天给的。温以恒低头看了很久，最后把你那只手合起来握住了。“明天换个法子，”他说，“我看着你吃。”"},
        {x:"“别告诉他们。”", heart:{温以恒:2}, flag:"hide_weak",
         cb:"他看了你两秒，点了下头。“可以。”他把糖纸叠好塞回口袋，“但我有条件——从明天起，早饭我看着你吃完再走。”"},
        {x:"往墙边挪半尺，反问他昨晚睡了几个小时。", heart:{温以恒:3}, flag:"ask_yiheng_sleep",
         cb:"温以恒愣了一下。他坐下来之前先看了你一眼，像在确认这句问话不是顺口。“四个。”他说，“别跟清越讲。”"}
      ]},
    {t:"n", x:"你们在走廊里坐到十一点。声控灯灭过一次，又因为谁动了一下而亮起来。温以恒把保温壶里剩下的水倒给你半杯，温的，不烫。他话很少，只在你不注意的时候看了两次表。回宿舍的路上，那半杯水在你手里慢慢凉下去，掌心的虚汗退了一点。他没提医务室，也没提节目组，只在你上楼前把你外套的第二颗扣子系上了，指尖在扣沿上停了一秒才松开。楼梯间的灯坏了两盏，他数了一遍级数，说报修的事明天他去讲。"},
    {t:"diary", who:"温以恒", date:"第3周 周四 夜", x:"今天小队长在走廊里站不住的时候，我心跳漏了一下，很不体面。我是哥哥，是副队长，我该做的是把人扶起来、递糖、问清早饭，不是慌。可我慌了。糖纸我留着，塞在保温壶的布袋里，这几天给出去的都在，一张没丢，只是没吃饭。要不要告诉江老师？想了一路，最后什么都没说。小队长最怕的不是倒下，是被看见倒下。明天早饭我做两份。还有，我昨晚睡了四个小时，这件事不能让清越知道，那孩子会哭。"},
    {t:"phone", who:"苏景行", msgs:[
      {f:"them", x:"小队长，睡了吗？", time:"23:52"},
      {f:"me", x:"还没。"},
      {f:"them", x:"今天走廊里有人看见你扶墙。", time:"23:53"},
      {f:"me", x:"腿抽筋。"},
      {f:"them", x:"[语音] 6″", time:"23:54"},
      {f:"them", x:"行。信你一次。明天我盯你吃饭。", time:"23:54"}
    ]},
    {t:"n", x:"第二天晚上九点，江慕白把你留下了。他让其他人先走，门没有关，只留最里头那一排灯。练习室一下子空得发响，空调的风从头顶扫下来，汗湿的后颈立刻凉透。他站在镜子前，没有看你，先把评分册翻到那一页，压在台面上，纸页的边缘翘起来一点。镜子里，他的银白发尾垂在镜框旁边，跟你的影子隔着整整一面墙。他等你站定，才开口，声音不高，落在空练习室里，一句一句都很清楚。"},
    {t:"d", who:"江慕白", fx:"neutral", x:"“C位那段。从头，三遍。”"},
    {t:"n", x:"第一遍你数错了半拍，第二遍抢了。第三遍前半段还算干净，到转身那一下，你咬了一下舌尖，想把那股飘起来的虚劲按回去——按住了，嘴里先漫开一点铁锈味。镜子里你的脸白得反光，唇上那点血被你抿掉了。你没停，把八拍走完，脚跟落回地胶上，很响。汗从额角淌进眉毛，涩得眼睛一酸，你没抬手去擦。地胶被你踩得发滑，鞋底每次落下去都带一点黏音。"},
    {t:"d", who:"江慕白", fx:"cool", x:"“第一遍是动作散。第三遍，是你散。”"},
    {t:"n", x:"练习室里只有空调还在响。"},
    {t:"d", who:"江慕白", x:"“昨天走廊里的样子，我看见了。我本可以叫医务室。我没有——因为那条走廊上也装着摄影机。”"},
    {t:"d", who:"江慕白", x:"“明天早上七点那版通告，我已经改到八点。这不是照顾。是我不想在直播里看见你倒下去。”"},
    {t:"d", who:"江慕白", fx:"neutral", x:"“我对你最严格，因为你值得。这句话你记住也好，忘掉也好。C位不是奖赏，是靶子——站上去的人，先学会不晃。”"},
    {t:"n", x:"他说完，拿起台面上那本评分册，指腹在磨毛的边角上压了一下。你站在原地，没有动。镜面上凝着一层没干的水汽，把顶灯的光糊成一团，你的影子在里面，比你自己要模糊。走廊那头有风，把一扇没关严的门吹得轻轻磕了两下。他把那排灯留给了你，门缝里透进来的光落在你脚边，一条宽，一条窄。舌尖上那点铁锈味，还没散。"},
    {t:"sys", x:"【节目组】第一次顺位发布将于本周日晚八点直播进行。即日起票数每小时更新，顺位名单以当日实时票数为准。"},
    {t:"m", x:"三天。三天之后，一百个名字会被重新排一遍。我脚下这块地方是我自己站上来的，也可能是自己掉下去的。江慕白说，站上去的人先要学会不晃——那就先学会。名次挂在墙上，不在我手里。"},
    {t:"end"}
  ]
});


// ===== ch09.js =====
// 第九章 · 第一次顺位发布 —— 作者批次B
window.STORY.push({
  id: "ch09",
  title: "第九章 · 第一次顺位发布",
  phase: "选秀",
  week: 4,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"江慕白合上评分册。银白的发尾在顶灯下扫过一道冷光，细框眼镜后的灰眸没有再看你。门在他身后合拢，带起一小股风，把练习室的静翻了个面。镜子里只剩你和你的影子，镜面上还留着一圈没干的水汽，是你方才停下时呼出来的。你对着他站过的位置点了点头，舌尖抵着方才咬破的浅口，一点铁锈味沿着舌根漫开。窗外夜色压得很低，基地外的路灯把树影投在镜面上，晃成一片没形状的暗。"},
    {t:"n", x:"地胶上有一小圈被踩亮的地方，就是他刚才站的位置。你把脚尖挪进去，站了两秒，又挪出来。走廊那头有人在收器材，金属支架磕在一起的脆响一下一下传进来，像有人在替你数剩下的日子。空调出风口的纸带飘起来又落下，飘起来又落下。"},
    {t:"n", x:"三天后。周日。晚七点五十。你重新站回初评级那间大厅，白炽灯把一百个人的影子钉在地板上，空气凉得像刚消过毒。汗味混着发胶的甜，甜得发闷，前排有人咳了一声，又慌忙屏住。你扫了一眼左前方——苏景行靠墙站着，肩松着，亚麻色头发被灯打出一层绒边，像来的不是排名夜，是散场后的闲聊。他指尖夹着一瓶没开的矿泉水，转了两圈，始终没拧。"},
    {t:"sys", x:"【节目组】首次顺位发布将于今晚八点直播进行。请全部一百名练习生按班级就位，结果以实时票数为准，中途不得离场。"},
    {t:"n", x:"耳返里漏出主持人的声音：还有三十秒。四台机器同时对准方阵，红灯亮成一片，像许多只不肯眨的眼。十。九。八。每一声都踩在心口。有人把编号牌捏得嘎吱响。你咽了口唾沫，喉结动了一下。掌心那点潮，怎么擦也擦不干，只好把手背到身后，在裤缝上按了按。"},
    {t:"d", who:"苏景行", x:"小队长，手这么凉。", fx:"smile"},
    {t:"n", x:"他的指尖在你腕上一蹭就松开，像试水温。你没躲。大屏开始滚名字，蓝光落在前排人的后颈，浮起一层细密的疙瘩。空调的出风声很轻，压不住一百个人同时屏住的那口气。你听见自己数呼吸的声音，数到第三下就乱了。"},
    {t:"n", x:"方阵最右端，温以恒把臂弯里那件外套对折了两次，指腹沿着折痕一路抹平，抹完又把折角压了压。他没看大屏，先从方阵最左边一路看过来，像在清点人数。顾知遥站在他侧后方，银灰色刘海被发胶固定得很好，只有后颈那一小块皮肤出了汗，衬衫领口贴着不动。陆清越把两只手都缩进袖子里，只露出指尖，在袖口里偷偷活动着，像在给自己数拍子。"},
    {t:"weibo", items:[
      "#星途顺位直播进行中# 1.2亿",
      "#临时队长今晚第几# 0.8亿",
      "#苏景行断层第一预定# 0.6亿",
      "#王腾能否保住A级# 0.4亿",
      "#星途第一次排名# 0.3亿"
    ]},
    {t:"n", x:"第九十八。第九十。名字往上爬，像潮水退去后露出礁石。每跳一个，大厅就短促地抽一口气。有人低头看手心的号码。有人把指甲掐进掌心。你也一样，指节慢慢收紧，指腹发白，那块编号牌的边角被你攥得发软。前排有人小声念了一句名次，被旁边的人碰了碰胳膊，立刻噤了声。"},
    {t:"n", x:"第四十。第二十七。念到第二十七的时候，你右边那个人猛地吸了一口气，又慢慢吐出来，肩膀塌下去半寸，又自己撑了回来。你想起三天前那条走廊，想起嘴里化开的那颗糖，甜味早没了，糖纸还压在你口袋里，被手心的汗焐得发潮。"},
    {t:"d", who:"陆清越", x:"队长哥哥，我们一定都在前面的！", fx:"laugh"},
    {t:"n", x:"他站在你斜后方，金色短发支棱着，眼睛亮得不合时宜，两只手在身侧握成拳，像替你攥着劲。第二十。第十五。心跳开始敲太阳穴，一下重，一下轻。你看见王腾的红发在不远处晃，那撮红在冷光下像一小簇没熄的火。他盯着屏幕，眼神像要烧穿玻璃。A级的边缘，他站得太久了。"},
    {t:"n", x:"王腾旁边的陈默一直低着头，帽檐压得很低，只露出一小截下巴，手指在裤缝上来回摩挲同一个地方，把那块布蹭得起了细毛。两人之间隔着半步，谁也没跟谁说话。大屏的蓝光从他们头顶扫过去，一次，又一次。"},
    {t:"weibo", items:[
      "#星途顺位直播进行中# 1.5亿",
      "#前十要来了# 0.7亿",
      "#临时队长站得很直# 0.5亿",
      "#苏景行在转水瓶# 0.4亿",
      "#林浩宇的编号牌# 0.3亿"
    ]},
    {t:"m", x:"手心全是汗。他说我对你最严格，因为你值得。那这一刻，值得什么。我没念出答案，只把指甲又往掌心按了按，按出一个浅浅的月牙。"},
    {t:"n", x:"第十。第九。大屏停住。像有人按了暂停。整个大厅的呼吸被掐断半秒，只剩空调还在不识趣地嗡。那道横在第九名上的光迟迟不肯往下走，像在等人先眨眼。谁先眨眼，谁就先认。你把牙关咬紧，后槽牙抵出一声几乎听不见的响。"},
    {t:"d", who:"林浩宇", x:"队长……要是我掉下去了，你别难过。", fx:"sad"},
    {t:"n", x:"他站在你斜前方，短发被汗贴在额角，眼下两团乌青，是连着几晚没睡的颜色。手里那块编号牌的边角已经被汗浸软，弯了起来。第九名的名字亮起。不是他。他的肩膀塌下去半寸，又绷直，像一根快断的弦被人强行拨正，弦上还挂着颤。"},
    {t:"n", x:"他侧过头，冲你笑了一下。那个笑很短，嘴角只抬了一点点，眼睛却先红了。你看见他用拇指把那块软掉的牌角压了又压，压回原来的形状，像在替谁把一份体面重新叠好。"},
    {t:"d", who:"顾知遥", x:"队长大人，你行不行啊？手攥那么紧。", fx:"cool"},
    {t:"n", x:"他嘴上这么说，人却往你这边挪了半步，肩膀有意无意地挡在你和最近那台机器之间。银灰的发梢垂下来，遮住半只眼睛。你顺着他的方向看过去，才发现那台机器的镜头正对着你的侧脸。他哼了一声，没解释。"},
    {t:"choice", prompt:"大屏停在你名字前的那一帧。你要怎么接住这一刻？", options:[
      {x:"转头看他：“景行，第一是你的，我服。”", heart:{苏景行:2, 顾知遥:1}, flag:"rank_yield",
       cb:"你冲苏景行扬了扬下巴。他懒洋洋笑开，把食指抵在唇上，像替你藏住那点不甘。顾知遥哼了一声，说本少爷倒要看看你下轮怎么服，嘴上不饶人，脚尖却把那台机器又挡严了半寸。"},
      {x:"盯住榜首那行字：“第二也好。下一轮，那个位置是我的。”", heart:{林墨轩:2, 沈时雨:2}, flag:"rank_aim",
       cb:"林墨轩在人群后抬了下眼，看了你两秒，又把视线落回地面，指尖在袖口上轻敲了两下。沈时雨望着你，拳头悄悄握紧，像是替你攒着劲，指甲在掌心里掐出四个浅浅的印。"},
      {x:"不出声，把名次记进手心。", heart:{江慕白:2, 温以恒:1}, flag:"rank_quiet",
       cb:"你没说话。导播间的监控屏前，江慕白推了推眼镜，镜片后掠过一丝极淡的笑。温以恒隔着半个方阵看过来，把手里的外套又折了一次，折痕压得笔直。"}
    ]},
    {t:"n", x:"苏景行第一。你第二。两个名字并排打在巨幕上，光把中间那道缝照得发亮。他朝你比了个只有你认得的手势——小时候巷口约定谁先到家谁赢的那个，食指一勾，藏进袖口。你忽然就没那么紧了，像有人替你把勒了一晚的领口松了松。"},
    {t:"n", x:"你笑着收回手。第一是他，你信他配。第二是你，你还没服。两种情绪撞在一处，竟生出一点想往下跑的劲，像潮水退后，人总想追着浪再走两步。闪光灯在四周炸开，白得人眼前一花，你眨了两下眼才把瞳孔收回来。身后有人拍了拍你的背，力道轻得像怕碰坏什么。"},
    {t:"d", who:"温以恒", x:"站得稳。别晃，一会儿还有麦克风递过来。", fx:"smile"},
    {t:"n", x:"他把那件折了三次的外套搭到你肩上，动作快得像随手一放，衣料里还留着他掌心的温度。前排的闪光灯又炸了一轮。你听见主持人念出第十名的名字，念得很慢，像舍不得，念完还顿了一下才继续。"},
    {t:"n", x:"镜头缓缓扫过榜尾，慢得近乎不忍。林浩宇的名字停在淘汰区，被一道红圈锁住，刺眼。他低头，眼泪砸在地板上，没有声音，只有肩背微微耸动，把那点不肯出声的难过全压进脊椎。你想起他总笑着递来的那瓶水，瓶身上留着他的温度，冰凉，却总是及时。"},
    {t:"n", x:"灯光从他脚边扫过，地砖上落了一小片颜色更深的潮，他不擦。后排有人把帽檐往下压了压，也有人别过脸去。名次到这里已经不重要了，那道红圈替他把这一程圈在了末尾。"},
    {t:"choice", prompt:"红圈锁住了他的名字，他还站在原地。你要怎么送这一程？", options:[
      {x:"在他身边坐下，什么也不说。", heart:{温以恒:2, 林墨轩:1}, flag:"send_haoyu_sit",
       cb:"地板凉得透骨。温以恒远远看着，把手里的外套往你这边拢了拢，没有过来打扰。林墨轩在人群外站定，替你把那扇半开的侧门扶住，让走廊的光漏进来一线。"},
      {x:"“下一轮的位置，我替你占着。”", heart:{沈时雨:2, 陆清越:1}, flag:"send_haoyu_promise",
       cb:"沈时雨听见这句，眼圈一下红了。他别过脸，把那句话悄悄攥进手心，像攥住一枚硬币。陆清越在人群里把星星钥匙扣按了三下，红光在袖口里亮了一下就灭。"},
      {x:"把他扶起来，替他理平皱掉的衣领。", heart:{温以恒:1, 江慕白:1}, flag:"send_haoyu_up",
       cb:"你扶住他的胳膊，把衣领上的褶一下下抹平。林墨轩在人群后看了你一眼，极轻地点了下头。温以恒已经把那瓶没喝完的水拧开，放在他手边。"}
    ]},
    {t:"d", who:"温以恒", x:"小队长，先别看榜了。去送送他，好吗？", fx:"sad"},
    {t:"n", x:"你穿过人群走到林浩宇身边。他还攥着那块牌，指节白得发青，像抓着最后一点没被勾掉的东西。你说不出漂亮话，只把牌轻轻按回他胸口。他抬眼看你一下，又垂下，慢慢把那块软掉的牌角抚平，抚了很久，直到它重新变得方方正正。"},
    {t:"d", who:"林浩宇", x:"那瓶水，我以后不能再递了。你练完记得喝。", fx:"cry"},
    {t:"n", x:"他说完就转过身，抬手的动作很快，像怕慢一点就被人看见。你没追。人群在他身后合拢，把那件浅色的练功服一点点吞没。你站在原地，手心还留着刚才按过牌角的那点浅印。"},
    {t:"n", x:"人群另一头，王腾的红发消失在门后。他掉出了A级，连最后的边缘都没留住。你能看见的只有他后颈绷起的那道线，和他垂在身侧、慢慢攥成拳的手。那点恨意比灯光安静，却比灯光记得久。有人开始鼓掌，掌声盖过了抽气声。"},
    {t:"n", x:"他走过你身边时脚步慢了一瞬。他偏过头，视线在你脸上停了不到半秒，什么都没说，那半秒里连呼吸都是硬的。然后他走了，红发被走廊的暗一口吞掉。"},
    {t:"weibo", items:[
      "#星途首次顺位发布# 3.1亿",
      "#苏景行断层第一# 2.4亿",
      "#临时队长稳居第二# 1.8亿",
      "#林浩宇淘汰# 0.9亿",
      "#王腾掉出A级# 0.7亿",
      "#星途第一次有人哭# 0.5亿"
    ]},
    {t:"n", x:"散场后走廊的灯只亮了一半。夜风从大门缝里灌进来，凉得人一激灵，把皮肤上那层薄汗吹干。江慕白从导播间出来，银白发丝被风吹乱了一缕，他没去理，细框眼镜后的灰眸在你脸上停了一秒。"},
    {t:"d", who:"江慕白", x:"第二。小队长，你欠我一个第一。", fx:"neutral"},
    {t:"n", x:"他说完就走，皮鞋踩在地砖上的回声一下一下，比那句判词还清楚。风里还留着大厅的消毒水味，混着一点谁的发胶香。走廊尽头有人关了灯，只剩你背后那块不肯暗的榜，和一种还没来得及命名的、往上走的心气。远处有人在收拾器材，金属支架碰撞的声音清脆，一下，又一下。"},
    {t:"m", x:"第二不是终点。我把名次折好，塞进今晚的风里，等下一轮再展开，铺成一块更高的地方。榜单会暗，风不会停。"},
    {t:"end"}
  ]
});


// ===== ch10.js =====
// 第十章 · 风起 —— 作者批次B
window.STORY.push({
  id: "ch10",
  title: "第十章 · 风起",
  phase: "选秀",
  week: 5,
  nodes: [
    {t:"bg", v:"dorm"},
    {t:"n", x:"排名夜过去两天，走廊里那句你欠我一个第一还挂在耳边，像一根没拔干净的刺。第三天天没亮，手机先醒了。你眯着眼摸到屏幕，弹窗一层压一层，全是同一个名字被剪坏的样子——你的脸，和他的脸，拼成一句谁也没说过的话。窗外的灰光爬上被单，像一层没擦干净的旧事。宿舍里还有两道呼吸声，一道很稳，一道翻了个身又翻回来。"},
    {t:"n", x:"你划着那些评论，指尖越来越凉。陌生的人用最利的词，给一个他们从没见过的人判了刑，连证据都懒得要。有人把你蹲下去的那半分钟说成作秀，有人把沈时雨低头的那一帧做成表情包。你忽然懂了风为什么叫风：它从不挑人，只管把一句话吹成漫天的刺，扎在谁身上，它不看。"},
    {t:"n", x:"屏幕上方的亮度条还在往上滑，是隔壁床的手伸过来替你调的。苏景行没睁眼，声音哑得像刚从梦里捞出来：这个亮度，看久了眼睛废。说完他把手收回去，枕边的手机屏幕还亮着，同样一页评论区，只是他没让你看见。对面上铺，林墨轩已经坐了起来，床边的小台灯亮着一圈很窄的光，笔记本开着，光标在搜索框里等着。顾知遥背对着你，被子盖到耳朵，呼吸却一直没匀过，银灰的发梢露在外面，随着那点不匀轻轻动。"},
    {t:"weibo", items:[
      "#队长欺负沈时雨# 2.6亿",
      "#星途临时队长霸凌# 1.9亿",
      "#沈时雨被队长骂哭# 1.4亿",
      "#星途剪辑门# 0.8亿",
      "#守护沈时雨# 0.7亿",
      "#求节目组放完整版# 0.6亿"
    ]},
    {t:"n", x:"屏幕冷得刺眼。你点开那条黑热搜，视频只有九秒：你抬着下巴，沈时雨低着头。前面你蹲下去帮他压肩膀的那半分钟不见了，像被人用指甲掐掉，只剩一个看上去就很凶的截面，和一个被截断了来龙去脉的少年。评论区已经盖到几万楼，还在往上翻。你把进度条拖回去三次，每一次都停在同一个地方，像卡在喉咙里的一根刺。"},
    {t:"d", who:"沈时雨", x:"队长……那个视频……不是的。", fx:"sad"},
    {t:"n", x:"他站在门口，深棕色的头发乱了一缕，眼圈红着，像一夜没合眼。手指绞着衣角，绞得很紧。喉结动了动，他把后半句咽了回去，半张脸躲进走廊的阴影里，像怕连慌张都成了别人镜头里的罪证。门口的地砖上有一小片水痕，是他鞋底带进来的。他站着不敢往里走，脚尖只压着门槛那条线。"},
    {t:"d", who:"陆清越", x:"队长哥哥！他们为什么骂你！我去评论区解释！", fx:"angry"},
    {t:"n", x:"他掀开被子就往门口冲，拖鞋只穿上一只。温以恒不知什么时候已经站在走廊里，一手按住他的肩，一手把另一只拖鞋摆到他脚边。别去，你去只会让更多人骂他，温以恒说，声音很轻，按在他肩上的手却很稳。顾知遥从被子里坐起来，头发乱着，看一眼门口，又看一眼屏幕，什么都没说，抓起自己的手机走进了洗手间，门关得很轻，锁舌却响了两下。"},
    {t:"choice", prompt:"黑热搜压下来的第一分钟。你要怎么接？", options:[
      {x:"“先把完整录像调出来，我和你一起发。”", heart:{沈时雨:2, 林墨轩:1}, flag:"clarify_public",
       cb:"你打开剪辑软件，把进度条拖到第九秒。沈时雨看着你敲键盘的手指，呼吸慢慢平了下来。林墨轩从上铺下来，把笔记本转了个方向，屏幕上已经摊着那段原素材，时间码停在你蹲下去的前一帧。"},
      {x:"“不急着辩。让时雨自己说。”", heart:{沈时雨:3, 温以恒:1}, flag:"clarify_let",
       cb:"你按住他发抖的手腕。他抬眼看你，那一点光比任何声明都稳。温以恒在走廊里松开了按着陆清越的手，朝你这边点了一下头。"},
      {x:"“我去查是谁剪的。”", heart:{苏景行:1, 江慕白:1}, flag:"clarify_trace",
       cb:"你截下视频右下角的水印。走廊尽头，江慕白远远看了你一眼，像是赞许你先找源头。苏景行把那截截图接过去，放大到像素发毛，说这水印他见过。"}
    ]},
    {t:"n", x:"最后你做的，是把那台手机架稳，镜头调到他能坐直的高度，再把窗帘拉开一线，让晨光落进画面。澄清这种事，得由当事人的嘴说出来才作数。你把位置让开，退到画面外，把这片安静留给他一个人。陆清越被温以恒按着肩膀带出了门。"},
    {t:"d", who:"温以恒", x:"小队长，时雨一晚上没睡，他在等一个能说清楚的机会，好吗？", fx:"smile"},
    {t:"n", x:"温以恒把一杯温水放在桌角，杯壁上凝着一层细雾，是刚倒的。沈时雨的手搁在膝盖上，指节白着，像十根绷紧的弦。他没去碰那杯水，只盯着杯沿里自己的倒影，像在确认镜中那个人还值不值得被相信一次。窗外的天色正一点一点亮起来，楼下的送菜车碾过积水，哗啦一声，又远了。走廊那头传来平底锅碰灶台的轻响，应该是温以恒顺手把火关小了。"},
    {t:"n", x:"直播间的补光灯提前亮起，白得不太真实，把桌面的木纹都照平了。沈时雨坐到镜头前，脊背挺得很直，直得发僵。红灯亮起，像一颗替他跳的心脏。他开口时声音是哑的，一句一顿，每个字都先在水里过一遍才敢捞出来。"},
    {t:"d", who:"沈时雨", x:"那天……队长只是帮我压肩膀。我重心一直往左歪，他扶了一下。视频里……没有前面的事。", fx:"sad"},
    {t:"n", x:"他说完，把手机往下按了按，像怕自己再看一眼就会哭。屏幕那头安静了半秒，随后字一行一行涌上来，快得看不清。你站在画面外，看见他攥着衣角的手，指节一点点松开，最后垂在了膝盖边。他没看评论，只看着镜头，像看着一个他决定要当面交代的人。"},
    {t:"danmaku", items:[
      "时雨的水瓶💧|他声音在抖但还是说完了",
      "星蓝应援🌟|前面那半分钟呢 求完整版",
      "苏苏的小甜饼🍪|我们队长不是那种人",
      "路过的练习生|压肩膀那个动作我见过 很轻的",
      "墨轩的编曲神了|别骂了 看他手在抖",
      "清越今天也加油|时雨哥最棒！",
      "今天也要早睡|对不起 早上我骂错了"
    ]},
    {t:"n", x:"下播之后他坐着没动，过了很久才把椅子往后推了半寸，椅子腿在地板上刮出一声短音。他端起那杯温水，喝了一口，杯子放回去时磕在桌角，晃出两滴水。你没接话，把补光灯按灭。屋里忽然暗下来，只剩窗户那一片灰白的光，落在他背上，薄薄的一层。"},
    {t:"phone", who:"苏景行", msgs:[
      {f:"them", x:"小队长，猜谁在背后花钱压你那条黑热搜？", time:"10:12"},
      {f:"me", x:"谁？"},
      {f:"them", x:"那个嘴硬的少爷。匿名买的，被我翻到了后台记录。", time:"10:13"},
      {f:"them", x:"[语音] 2″", time:"10:13"}
    ]},
    {t:"n", x:"你推开休息室的门。顾知遥正对着手机皱眉，见你进来，拇指一划，界面瞬间干净。动作太急，耳尖却慢了一步，先红了。他靠在墙边，银灰色发丝垂下来遮住半边眼睛，那截发尾还在轻微地抖。镜子里映着他抿紧的嘴角。手机反扣在台面上，壳上贴着一张他自己撕了角又贴回去的贴纸。"},
    {t:"d", who:"顾知遥", x:"哼，才不是为你。过时的手段，本少爷顺手清了。", fx:"shy"},
    {t:"n", x:"他别过脸。你看见他搜索栏里还留着那串黑热搜的词条，没删干净，像一处没藏好的破绽。他指尖在屏幕边缘敲了两下，终于没再划走，任由你看着——这大概是他能给出的、最笨的坦白。窗台上那杯他没喝的咖啡已经凉了，杯壁内侧挂着一圈褐色的渍。他又补了一句：那帮人连图都P不干净，看着烦。"},
    {t:"choice", prompt:"把柄落在苏景行手里，这件事你要怎么收场？", options:[
      {x:"“谢了。下次直接告诉我。”", heart:{顾知遥:3, 沈时雨:1}, flag:"zhiyao_thanks",
       cb:"顾知遥哼了一声，嘴角却翘起来。沈时雨在门口低头，把这句谢悄悄记了进去。顾知遥顺手把那杯凉咖啡端起来喝了一口，皱了下眉，又放下了。"},
      {x:"“别让景行拿这个逗你，我替你压着。”", heart:{苏景行:2, 顾知遥:1}, flag:"zhiyao_cover",
       cb:"苏景行在群里发了个偷笑的表情。顾知遥的耳尖更红，却没再反驳，只丢下一句：本少爷没什么好压的。说完把手机壳上那张贴纸的角又按平了一次。"},
      {x:"“这份人情，我记着。”", heart:{顾知遥:2, 温以恒:1}, flag:"zhiyao_owe",
       cb:"你认真看了他一眼。他愣了半秒，把头转得更快，假装去理那根本不乱的袖口。温以恒在门外放下了一碟刚切好的苹果，没敲门。"}
    ]},
    {t:"d", who:"林墨轩", x:"水印能追到第一个上传的账号。要不要我让人查。", fx:"neutral"},
    {t:"n", x:"他把笔记本转过来一半，屏幕上摊着那九秒视频的逐帧截图，右下角那枚水印被放大到边缘发毛。旁边是一列时间码，第一帧到第九帧，中间缺了三帧，缺口干净得不像是网速造成的。他说完就收回手，指尖在触控板上敲了一下，停住。"},
    {t:"n", x:"午后，黑热搜掉头。沈时雨那段澄清被截成短片，配着原视频里你蹲下帮他压肩膀的九秒，一起冲上了榜。评论区有人删掉了早上的话，有人默默点了个赞。你刷到一个陌生头像下的句子：原来我骂错了，对不起时雨。你把手机放下，太阳穴还在突突地跳。"},
    {t:"weibo", items:[
      "#沈时雨澄清队长霸凌# 2.1亿",
      "#原来是被剪坏的瞬间# 1.5亿",
      "#守护沈时雨是真的# 1.1亿",
      "#星途剪辑门反转# 0.9亿",
      "#临时队长清白# 0.8亿"
    ]},
    {t:"n", x:"傍晚你路过练习室，听见里面有人把同一段舞走了一遍又一遍，脚步声砸在地板上，一下一下，像要把白天的不甘全踩进去。推门看，是沈时雨。他察觉到动静，脚步顿了顿，又继续。汗顺着下颌落进衣领，他没有停，仿佛只要还动着，重心就不会再歪，仿佛只要还跳着，那些骂过他的人就输了。镜子里他的影子被拉长，一直铺到你脚边。"},
    {t:"n", x:"你靠在门框上没进去。他的脚步比早上稳，也比早上轻。走廊的灯把你的影子拉得很长，一直铺到他脚边那块光里。你听见他数拍子的声音，压得很低，却一直没断，像一根线，把散掉的什么重新缝了回去。他把外套搭在把杆上，拉链拉到最上面，像给自己围了一道墙。"},
    {t:"d", who:"江慕白", x:"风波是筛子。筛掉的，本来就不该留下。小队长，你这次没白当。", fx:"neutral"},
    {t:"n", x:"他的声音从走廊那头的监控间飘出来，隔着玻璃，冷而清晰，像一句判词落了章。你没回头，只听见自己的鞋跟在地砖上敲了一声，算是应了。玻璃上映着你的脸，和练习室里那个还在数拍子的影子，一前一后。他补了半句：风明天还会起，别指望它停。"},
    {t:"m", x:"风是从暗处起的。但这一次，有人替我把门窗都关紧了。我把顾知遥那句才不是为你，和时雨那句不是的，一起收进今晚的枕头底下，像收好两枚还带着体温的扣子，等明天缝回原处。"},
    {t:"end"}
  ]
});


// ===== ch11.js =====
// 第十一章 · 雨夜 —— 作者批次B
window.STORY.push({
  id: "ch11",
  title: "第十一章 · 雨夜",
  phase: "选秀",
  week: 5,
  nodes: [
    {t:"bg", v:"dorm"},
    {t:"n", x:"黑热搜退潮的第二天下午，天开始阴。云低得像要压到楼顶，练习室的玻璃上蒙了一层水汽，擦掉一层又起一层。到了夜里，雨落下来，敲在窗沿上，一下一下，像有人在门外站着，敲了很久，也不肯走。走廊尽头的窗户没关严，风把纱帘吹得鼓起来，又垂下，一遍一遍。洗衣房的烘干机还在转，低低地嗡，把整层楼烘出一股湿热的水汽味。"},
    {t:"n", x:"你刚吹干头发，手机在枕边震了一下。屏幕亮起，是温以恒的消息，字句还是那样轻。你盯着那两行字，后脖颈的寒毛先竖了起来——以恒从不随便说谁脸色白，他说的白，是人在撑不住时才会漏出来的那种白。"},
    {t:"phone", who:"温以恒", msgs:[
      {f:"them", x:"小队长，时雨下午接了个家里的电话，脸色一下子白了。", time:"21:36"},
      {f:"them", x:"我给他留了伞，塞在你门后那件外套的口袋里。你去找他，好吗？", time:"21:36"},
      {f:"me", x:"他不在宿舍？"},
      {f:"them", x:"嗯，出去有一会儿了。雨大，别让他一个人。", time:"21:37"}
    ]},
    {t:"n", x:"门后那件外套果然挂着。口袋鼓着，掏出来是一把折叠伞，伞柄还留着一点体温，暖得有些烫手。你抓起它推门出去。雨点砸在脸上，凉得人清醒，也凉得人想快走，仿佛慢一步，那个人就被雨冲得更远。走廊的灯半明半灭，把你的影子切成一段一段，落在湿漉漉的地砖上。"},
    {t:"n", x:"楼梯口站着一个人。顾知遥穿着拖鞋，手里端着半杯水，银灰的头发被自己随手拨乱了一缕。他看见你怀里的伞，眉毛动了一下。这个点往外跑，他说，队长大人是打算在雨里站成雕像。他没拦你，往旁边让开一级台阶，脚边那盏声控灯灭了，他就抬手拍了一下墙，灯又亮起来。去吧，他又补了一句，背影很快转到楼梯下的暗里，水杯壁上的热气一路甩成一小串白点。"},
    {t:"bg", v:"rooftop"},
    {t:"n", x:"楼梯一道一道往上，雨声被水泥吞掉大半，又从头顶的天窗漏下来，滴在肩头。你推开天台的门，风裹着雨味扑面，像一盆冰水浇醒了剩下的困意。远处楼群的灯在雨里糊成一片晕黄，看不真切，像谁把这座城市揉皱了。排风扇的铁壳被雨打得噼啪响，缝隙里渗出一点旧机油的腥味，混在湿冷的空气里。"},
    {t:"n", x:"他在排风扇后面。深棕色的头发被雨汽洇湿，一缕一缕贴在前额，发梢滴着水，肩线薄得几乎撑不住那件湿透的T恤。肩膀一抽一抽的，声音却压得很低，像怕惊动楼下任何人，也怕一出声，那点力气就跟着散了。排风扇还在转，叶片把雨切成一片片飞散的雾，落在他肩上，很快就洇深了一块。他手里攥着手机，屏幕已经黑了，攥得很紧，像还捏着那通电话的尾巴。"},
    {t:"d", who:"沈时雨", x:"队长哥……我爸……在工地，摔了。", fx:"cry"},
    {t:"n", x:"雨打在栏杆上，溅起细白的水沫，风一斜，全扑到你裤脚。你站了两秒，才敢往他那边挪半步，怕惊飞一只淋透的鸟。你把手里那把还带着以恒体温的伞，悄悄换到离他更近的那只手上，像先把一处遮风的地方，挪到他一伸手就够得着的位置。栏杆上的水顺着袖口往下滴，滴进你的鞋面，凉得脚趾一缩。"},
    {t:"choice", prompt:"他蹲在雨里，肩膀薄得让人心口发紧。你要怎么靠近这一步？", options:[
      {x:"挨着他蹲下，什么也不说。", heart:{沈时雨:2}, flag:"rain_silent",
       cb:"你在他身边蹲下。两个人的影子在积水里靠在一起，谁都没开口，雨声替你们说了。他往旁边挪了一点，给你空出半块还算干的台阶，动作很轻，像怕你嫌弃。"},
      {x:"“你不用一直撑着。累了就靠过来。”", heart:{沈时雨:3}, flag:"rain_lean",
       cb:"你把手搭在他颤着的肩上。他的呼吸停了一拍，额头慢慢抵进你臂弯。雨水顺着你们的袖口连成一条细线，滴在栏杆下那点黑里，听不见落地的声。"},
      {x:"脱下外套裹住他：“今天就当靠着我。哭也不丢人。”", heart:{沈时雨:5}, flag:"rain_hold",
       cb:"你把他整个裹进外套里。他松开咬紧的牙，眼泪混着雨水，无声地洇进你肩头。外套里的温度收拢得很快，他抖的幅度一点点小下去，手指却抓紧了衣襟那一角。"}
    ]},
    {t:"n", x:"他哭得很轻，像怕占用太多你的时间。你没催，只把手稳稳停在他背后，隔着湿透的衣料，摸到那截脊背薄得惊人。睫毛上挂着一滴水，不是雨。那是他忍了很久才肯放出来的东西。"},
    {t:"d", who:"沈时雨", x:"队长哥……我怕我配不上你们。我爸躺着的钱，都是我跳出来的。", fx:"sad"},
    {t:"n", x:"你蹲得更低些，让视线与他齐平。他躲了一下，终究没躲开。雨顺着你们之间的空隙落下去，把那句配不上冲得模糊，却冲不散他声音里那点不肯认的倔。那是一个少年把全家扛在背上时，发着颤也要挺直的骄傲。你听见自己的袖口被雨水泡透后，摩擦时发出的那点湿响。"},
    {t:"choice", prompt:"他说出那句配不上，声音轻得像怕被风听见。你要怎么接？", options:[
      {x:"“你早就配上了。从你最早到练习室那天。”", heart:{沈时雨:3}, flag:"worthy_always",
       cb:"沈时雨抬眼看你，睫毛上还挂着水。他没说话，只是把绷紧的肩，慢慢放了下来。天台的铁门被风推了一下，磕在墙上，响了一声，谁也没去扶。"},
      {x:"“别拿家里的事罚自己。这段舞，跳给你爸看。”", heart:{沈时雨:4}, flag:"worthy_father",
       cb:"他喉结动了动，像把这句话咽进了最软的地方。雨里，他第一次没有躲开你的目光。他把手机翻过来，屏幕亮了一下，又自己灭了。"},
      {x:"握住他的手，等他说完。", heart:{沈时雨:2}, flag:"worthy_hold",
       cb:"你握住他冰凉的手。他愣了愣，回握的力道很轻，却实实在在，像终于肯借一点重量给你。两个人的手都湿着，指缝里全是雨，滑得几乎握不住，可谁都没有松。"}
    ]},
    {t:"n", x:"风把后半句吹散。你听清的是自贬，是亏欠，是一个永远最早到、最晚走的人，把自己压得太低。你想说不是这样，又咽了回去——这种时候，道理抵不过他亲耳听见自己说出的那句话。你能做的，只是把这片雨陪他听完。雨顺着你的后颈往衣领里钻，凉得人打了个颤，你没去擦。"},
    {t:"d", who:"沈时雨", x:"……工友说，我爸怕耽误我，不让家里告诉我。", fx:"sad"},
    {t:"n", x:"他把额头抵在膝盖上，声音闷在臂弯里。雨水顺着他的发梢往下滴，一滴一滴砸在积水里，砸出很小的一个窝，又立刻被下一滴填平。你没接话，只把伞往他那边又偏了一寸。伞面上的雨声忽然密了一阵，像有人把整片天往下压了压。"},
    {t:"n", x:"雨小了些，变成绵密的细丝，落在脸上几乎察觉不到。他站起来，胡乱抹了把脸，深吸一口气，像把刚才那个自己叠好、收进兜里。下楼时他走在你后面半步，脚步比来时稳，背影也不再缩成一团。楼道灯一盏盏灭过去，把影子里的水汽慢慢烤干。"},
    {t:"n", x:"你这才想起温以恒那把伞，还攥在另一只手里。他早算到你用得上，也早算到你会先把伞递给别人，才连伞带余地一起留给了你。这个人把退路铺在别人脚下，自己站在雨里，也站在你背后。四楼的楼梯口还站着一个人影：陆清越举着一把撑开的伞，金色头发湿了一半贴在额角，运动鞋踩在积水里，鞋带散了也没顾上系。看见你们，他把伞举高了一点，眼睛在昏暗的楼道里亮得不像话。"},
    {t:"heart", who:"温以恒", delta:1},
    {t:"d", who:"陆清越", x:"队长哥哥！我找了时雨哥好久！", fx:"shy"},
    {t:"n", x:"他把伞往沈时雨那边送，自己半个肩膀露在雨里，还伸手去摸沈时雨的袖子，摸到一片湿，眉头立刻皱起来。他把自己的外套脱下来要递，又想起什么，先回头看了你一眼，像在等一个许可。"},
    {t:"diary", who:"沈时雨", date:"第5周 雨夜", x:"今天队长哥在雨里找到了我。我爸从脚手架上摔下来，腿折了，家里瞒着没告诉我，是工友偷偷打的电话。我躲到天台，是不想让别人看见我那样子。可队长哥还是来了，带着以恒哥的伞。我想说谢谢，张了嘴只会哭。队长哥说，累了就靠过来。我从来没敢靠过谁。如果有一天我也能站到前面，替队长哥挡一次，那我这些年吃的苦就不算白吃。可我配吗。队长哥，你别嫌我慢，好不好。"},
    {t:"bg", v:"dorm"},
    {t:"n", x:"宿舍走廊的灯是暖的，照得瓷砖反出一层橘色的光。温以恒从厨房探出头，围裙上沾着一点姜末，灶上的小锅咕嘟咕嘟响，姜味辛辣，冲得人鼻子发酸。他看见你们一前一后进门，先把两条干毛巾递过来，才转身去关火。"},
    {t:"d", who:"温以恒", x:"小队长，先擦头发。他呢？", fx:"smile"},
    {t:"n", x:"你把毛巾按在沈时雨头上，揉了两下。他没躲，任由那块布盖住眼睛，只从毛巾边缘露出一截发红的耳朵。温以恒把姜茶倒进两个杯子，推到桌边，没问天台上发生了什么，也没问那把伞去了哪里。"},
    {t:"n", x:"顾知遥从洗手间出来，头发还滴着水。他路过桌边，把一杯热水搁在沈时雨手边，杯底磕出一声轻响。本少爷没多倒，他说，顺手。说完就坐回自己的床上，把毛巾盖在脸上，肩膀往下沉了沉，再没出声。苏景行拎着湿外套从玄关进来，说楼下便利店关门了，跑了两条街才买到一包感冒冲剂，他把袋子往桌上一放，谁都看得出他自己先淋透了。林墨轩最后回来，怀里抱着一叠谱子，纸角被雨汽洇出波浪，他把最上面那张抽出来压在沈时雨桌前——明天排练，节拍改了，右手先走。"},
    {t:"n", x:"杯壁烫手，姜味窜进鼻腔。沈时雨捧着杯子，双手都包在上面，像捧着一小团刚捡回来的火。窗外雨还在下，玻璃上爬着一道道水痕，把外面的灯拉成一条条流动的线。陆清越在沙发上缩成一团，抱着靠枕先睡了过去，手里还捏着那把没收起来的伞。"},
    {t:"m", x:"有些光，要蹲下来才看得清。我蹲下去的那一下，没看见弱者，只看见一个把所有人都扛在肩上的人，终于肯让人替他撑一会儿。"},
    {t:"end"}
  ]
});


// ===== ch12.js =====
// 第十二章 · 二公《潮汐》 —— 作者批次B
window.STORY.push({
  id: "ch12",
  title: "第十二章 · 二公《潮汐》",
  phase: "选秀",
  week: 6,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"雨停后的第三天，二期公演的曲目定了下来：《潮汐》。新的训练表被重新打印，末尾多出一行字——水舞台，全员水中编舞。你盯着那行字，想起天台那一夜的雨。水都一样，先是逼人沉下去，再逼人学会浮起来。纸面上还留着打印机的余温，油墨味很淡，混在会议室里那股没散尽的咖啡气里。训练表右下角有一行更小的字：次日八点，舞台合排。"},
    {t:"bg", v:"stage"},
    {t:"n", x:"舞台中央挖出一方水池，蓝膜覆底，顶光打下去，像把一小片海搬进了礼堂。空气里是消毒水和潮湿木头混在一起的味道，连脚底踩着的也是凉的。你脱了鞋踩进池边，水凉得脚踝一缩，池底的软胶踩上去像退潮后的沙滩。你蹲下去摸了摸水面，波纹把你的眉散开，也把倒映在池底的那张脸晃成一片碎光。水本身就是节拍，一下一下拍在小腿上，拍得人忘了冷，只记得要跟上这片蓝的呼吸。"},
    {t:"d", who:"林墨轩", x:"那段副歌，我改了三个版本。你试第二个。", fx:"neutral"},
    {t:"n", x:"他坐在池边的钢琴前，黑色短发垂着，深邃的黑眸没抬，指尖落下几个音。黑白灰的衣袖蹭上水痕，他没理会。你听见副歌里多了一层弦，不抢，只托，像有人在你脚底悄悄铺开一整片海。他把谱子往你这边推了推，食指在第二个版本上敲了一下，轻得像盖章。谱面右上角有一小块铅笔印，是被反复擦过的痕迹。"},
    {t:"n", x:"三个版本摊开在谱架上，笔迹一层压一层。第一版干净，收在拍子里；第三版被他用铅笔画了一道斜线划掉，划得很轻。只有第二版旁边写着两个小字：留白。他没解释，只把铅笔横放在谱架上，笔尖朝着你。"},
    {t:"choice", prompt:"他为你重编的副歌摆在面前。你要怎么接这道题？", options:[
      {x:"“第二个版本，我加一个气声转音。”", heart:{林墨轩:3, 苏景行:1}, flag:"tide_arrange_a",
       cb:"林墨轩抬眼，极轻地点了下头。对你而言，这已是他盖过章的最高认可。他把铅笔推过来半寸，像把修改权交到你手上。"},
      {x:"“先按你的来，今晚我自己找感觉。”", heart:{林墨轩:2, 温以恒:1}, flag:"tide_arrange_b",
       cb:"他把谱子推给你，指尖在第二个版本上又敲两下，算是答应你先摸索。走的时候他把琴盖上，压在上面那张草稿也一起收走了。"},
      {x:"“墨轩，间奏留一段给我和景行即兴。”", heart:{林墨轩:2, 苏景行:2}, flag:"tide_arrange_c",
       cb:"林墨轩难得弯了下嘴角。苏景行在旁边吹了声口哨，像早就等着你这句。他把吉他横在膝上半蹲下去，当场试了两个和弦，第二个他停住了，说就这个。"}
    ]},
    {t:"n", x:"苏景行那两个和弦最后成了间奏的骨架。他把手机横在谱架上录，录到第三遍忽然按停，说要的就是这一遍里你喘气的地方。林墨轩没反对，只把那一小段的谱子重抄了一份，字很小，四行排得笔直。"},
    {t:"n", x:"之后的日子被水填满。水温比想象中低，你们一遍遍踩进池里，出来时嘴唇发青，没人先喊停。湿透的衣料贴在背上，沉甸甸的，像把这一周的累都穿在了身上。可每个人的眼睛是亮的，像都在等水池亮起的那一刻，把自己交出去。更衣室的地板永远擦不干，踩上去咯吱响。温以恒每天拎着一个保温壶站在池边，杯盖拧开，姜味混着水汽冒上来，一人一小杯，他自己总是最后喝。"},
    {t:"n", x:"沈时雨总在别人散了以后，自己再下池走两遍。他说怕水，却把怕压进了节拍里，每一下踩得更准。他落下最后那一步时，你想起他说过要跳给谁看——那一步稳得像钉进池底，水花只溅起很小的一圈。"},
    {t:"n", x:"陆清越第一天进池的时候，站在浅水那侧迟迟不动，两只手抓着裤缝。他回头看你，又看沈时雨，最后自己数了三下，一脚踩进去，溅起的水花打湿了半张脸。他抹了把脸说好凉好凉，然后又笑，说这比想象中好玩。顾知遥在旁边嫌他吵，转头却把自己那条干燥的备用毛巾搭在了他的椅背上。"},
    {t:"d", who:"温以恒", x:"小队长，水温低，下来先喝姜茶，好吗？", fx:"smile"},
    {t:"n", x:"彩排第七遍，你踩到湿滑的池沿，身体一歪。三双手同时伸过来：温以恒托住你手肘，苏景行勾住你衣领，沈时雨在另一侧死死拽住你手腕。水花溅起来，落在每个人脸上，分不清是汗还是池水。只听见三声同时松掉的呼吸，和一句叠在一起的你没事吧。"},
    {t:"n", x:"顾知遥站在台下，脸色白了一下，随即嗤了一声，说队长大人连路都走不稳。他转身跟场务要了一把拖把，自己把那一小段池沿来回拖了两遍，拖完把拖把往墙边一靠，什么都没说。"},
    {t:"d", who:"林墨轩", x:"池沿第七块砖是松的。走右边两步。", fx:"neutral"},
    {t:"n", x:"他不知何时站到了池边，手里还捏着那支铅笔。你顺着他说的走了一遍，脚下果然有一段轻微的沉陷。第二天再排，那块砖已经被他用红胶带贴了个角，胶带边压得很平，不仔细看根本发现不了。"},
    {t:"sys", x:"【节目组】二期公演即将直播。本场采用实时票务，严禁任何形式的违规拉票与刷票，违者当场取消成绩。"},
    {t:"n", x:"后台的暗处，王腾和另外两人凑在一起。那撮红发在应急灯下像一小簇火。三台手机屏幕亮着，拇指飞快，像在键盘上数钱。他抬头撞上你的视线，立刻把手机扣进怀里，动作太急，连耳根都红了一瞬。那一扣，比任何解释都更像心虚。"},
    {t:"n", x:"其中一个瘦高的人低声说了句什么，王腾没应，只把怀里那台手机的屏幕按灭。另一个把手机塞进袜子，走开的时候肩膀绷得很直。走廊那头，一个抱着平板的工作人员正在核对名单，边走边在本子上画勾，经过他们时停了一秒，又走过去了。"},
    {t:"choice", prompt:"那一下藏手机的动作，你看见了。怎么处理？", options:[
      {x:"悄悄记下面孔，先报给导演组。", heart:{江慕白:2, 林墨轩:1}, flag:"ticket_report",
       cb:"你退到监控的死角，把那三个人记在流程表背面。江慕白后来扫到那行字，镜片后掠过一丝冷意。他把流程表折起一角，什么也没问。"},
      {x:"当众盯回去，让他知道你看见了。", heart:{苏景行:2, 顾知遥:1}, flag:"ticket_stare",
       cb:"你慢悠悠看了他一眼。他耳根一热，把怀里的手机攥得更紧，却再没敢抬眼。苏景行在旁边把肩往你这边靠了靠，什么也没说，只是挡了半个身位。"},
      {x:"不戳破。用舞台说话。", heart:{沈时雨:2, 温以恒:1}, flag:"ticket_stage",
       cb:"你转回身，把腿上的水珠甩掉。沈时雨在旁边悄悄挺直了背，像替你撑着这口气。温以恒把手里的保温壶盖拧紧，盖子的响声在后台的嘈杂里格外清楚。"}
    ]},
    {t:"d", who:"顾知遥", x:"队长大人，本少爷的part可别被你的水花盖了。", fx:"cool"},
    {t:"n", x:"他靠在化妆台边，银灰色头发被造型师梳得一丝不苟，湛蓝的眼睛斜过来，语气硬，手却把一件干浴袍扔在你旁边的椅子上，袍角还带着烘干机的暖。陆清越在后面踮着脚，把你散在桌上的水杯盖好，金色短发上别着一枚星星发卡。"},
    {t:"n", x:"上台前最后一遍点名，七个人在幕布后面站成一排。温以恒挨个把每个人的领口理了一遍，理到你的时候停了一下，问水温还行吗。林墨轩闭着眼，手指在大腿侧打着拍子，嘴里不出声地数。苏景行甩了甩手腕，凑过来说一句要下雨了，然后笑。顾知遥把发丝拨到耳后，抬着下巴不动。沈时雨把手心在裤缝上蹭了两下，指节发白。陆清越小声说了一句今天也要加油。"},
    {t:"n", x:"灯光暗下，又轰然亮起。池水被追光染成流动的银蓝，前奏像潮水从地底涌上来，鼓点一下一下砸在胸骨上。全场倒吸一口气。你听见自己的心跳，终于和这段编排踩成了同一个拍子。潮认得岸，你认得这片等你太久的蓝。"},
    {t:"danmaku", items:[
      "潮汐冲鸭🚀|这个水舞台我直接跪了",
      "苏苏的小甜饼🍪|队长的声线被那层弦托得好绝",
      "墨轩的编曲神了|副歌第二版谁懂啊",
      "时雨的水瓶💧|时雨今天站得好稳",
      "知遥今天也贵气|红衣泡在水里还是贵气",
      "以恒哥哥温柔|姜茶梗什么时候上热搜",
      "星蓝应援🌟|二公第一必须是他们"
    ]},
    {t:"n", x:"你踩进池心，水漫过膝，凉意顺着腿骨往上爬。林墨轩改的那段副歌准时落下，弦声托着你，聚光灯烫在脸上。你听见自己的声音第一次这么稳，稳得连自己都陌生，稳得像所有的怕都被水接住了。间奏那段即兴来的时候，苏景行在你右侧抬了一下手，两个和弦落下去，池面被声浪压出一层细密的抖。"},
    {t:"d", who:"苏景行", x:"我们队长，今天像潮汐本身。", fx:"laugh"},
    {t:"n", x:"灯光跟着拍点切，白、蓝、白，把七个人的影子反复打进水里又捞出来。沈时雨那一拍踩得极准，水花只溅到脚踝；陆清越跳错了半步，立刻自己拧回来，脸上还挂着笑；顾知遥的红衣泡在水里，转身的时候甩出一道弧。耳返里全是自己的呼吸声，混着台下那片翻涌的响。"},
    {t:"n", x:"尾声你跃起，水花炸开成一圈银亮的环，把整片海甩向天空。全场尖叫叠着鼓点，把礼堂的顶掀高一寸。你落回水里，涟漪一圈圈荡开，把你和脚下这片蓝连成一个完整的潮。七个人在同一片浪里，谁也没被落下。"},
    {t:"n", x:"结果出来，你们是第一。导演组随后公布：王腾联盟涉嫌票务违规，查证属实，当场降级处理。大屏扫过他的名字时，他把脸别开了。那撮红发在白光里暗下去，像烧剩下的灰。你站在水里，听见全场喊的不是名次，是那三个字。水从发梢淌进眼睛，涩得人睁不开，你却不想抬手去擦，怕错过这一秒的响。"},
    {t:"n", x:"后台通道里，那三个人被工作人员带往另一个方向，脚步很杂，鞋底在地砖上拖出短短的响声。王腾没有回头。有个场务抱着一摞核对单从他身边过去，纸角蹭到他的手臂，他也没躲。"},
    {t:"weibo", items:[
      "#星途二公潮汐# 3.4亿",
      "#林墨轩重编封神# 2.0亿",
      "#临时队长水舞台第一# 1.9亿",
      "#王腾联盟票务违规降级# 1.2亿",
      "#星蓝应援潮汐# 0.9亿"
    ]},
    {t:"n", x:"后台的灯一盏盏熄了。你拧干头发，水珠滴在地板上，和窗外还没干透的夜连成一片。有人把毛巾扔过来，有人瘫在椅子上笑，笑到没力气。温以恒把最后一个保温壶盖拧开，往每个人杯里分了最后一点姜茶，壶底只剩一层姜末。上半程的选秀到这里收住了呼吸，像一个长长的俯冲终于触到水面。地板上的水迹映着最后一盏没关的灯。"},
    {t:"d", who:"江慕白", x:"第一。小队长，这只是上半场的句号。下半场，我要看你能不能自己涨潮。", fx:"neutral"},
    {t:"n", x:"他把评分册夹在腋下，转身走进走廊的暗里，皮鞋声一下一下退远。你握着那条湿毛巾站在原地，听见池水还在舞台中央轻轻地晃，一圈，又一圈，像还没说完的话。"},
    {t:"m", x:"上半程到此为止。下半程，潮水才刚起。我把池里那圈银亮的环折好，存进要去的下一段路，连同那层托着我的弦，和三双手同时伸过来时那一声叠在一起的你没事吧。"},
    {t:"end"}
  ]
});


// ===== ch13.js =====
// 第十三章 换宿风波 —— 作者批次B
window.STORY.push({
  id: "ch13",
  title: "第十三章 · 换宿风波",
  phase: "选秀",
  week: 7,
  nodes: [
    {t:"bg", v:"dorm"},
    {t:"n", x:"二公的水退进记忆里去之后，走廊尽头那块白板换上了新的等级重排表。凌晨三点贴上去的，墨迹里还压着夜里的潮气，边角卷起，指甲一刮就沾一层灰蓝。你从更衣室抱回来的那条毛巾还挂在阳台栏杆上，风一吹就晃，带着一点没散尽的水腥味。上半场在池水里画完了句号。下半场的第一件事，是搬一张床。"},
    {t:"n", x:"白板的铝框是凉的，走廊的灯管坏了一根，剩下的那根压在头顶一闪一闪，把人脸照得发青。饮水机在尽头咕噜了一声，又安静下去。你的名字仍停在A栏最上面一行；往下数第三行，沈时雨三个字第一次排了进来，笔画端正，像打印的人特意放轻了手。他站在白板前，指尖在自己名字的边角上按了一下，又很快收回，像怕按重了字会掉下来。"},
    {t:"sys", x:"【节目组】二公成绩已结算，A级名单调整完成。涉及等级变动的练习生请于今日18:00前完成宿舍搬迁。另：二公票务违规处理结果已公示，请引以为戒。"},
    {t:"n", x:"搬迁的动静比想象中小。没有人鼓掌，也没有人起哄。走廊里只有行李箱轮子碾过地砖的声音，一格一格，像谁在数拍子。有人把箱子从A级宿舍推出来，轮子卡在门槛上，顿了一下，又被人抬过去。王腾那一行名字从重排表上消失的时候，也是这么安静的，只剩黑板上没擦净的一层粉笔灰。"},
    {t:"n", x:"他的箱子是全楼最旧的一只。米白色箱体磨出了毛边，四个角贴过快递单，撕到一半，编号还留着一截；拉杆上缠着一圈泛黄的医用胶布，缠得很仔细，一圈压着一圈。他抱着它站在A级宿舍门口，鞋尖在地砖缝里蹭了蹭，没有先迈进来。门里的灯亮着，门外那盏是坏的，他就站在那道明暗交界的线上，两只手把箱子往上托了托。"},
    {t:"d", who:"顾知遥", x:"啧。本少爷的置物架，可没地方塞你的破箱子。……靠窗那块地板漏风，别直接搁地上，回头潮了别怪本少爷没提醒。", fx:"cool"},
    {t:"n", x:"话音没落，他已经单手把那只箱子拎了进去，指节在拉杆上绷出一小片白。箱子举过肩的时候他眉头皱了一下，没出声，只有外套往上缩了一寸。银灰色发梢掠过门框上的灯，亮了一下又暗下去。沈时雨的手停在半空——像刚要伸出去扶，又就地收了回来，指尖蜷了一下，垂在裤缝边上。"},
    {t:"heart", who:"顾知遥", delta:1},
    {t:"d", who:"温以恒", x:"先放这儿吧。早餐还有十分钟，我给你留了靠窗那张床，夜里通风。好吗？被套是新换的，洗过一次，硬一点，睡着踏实。", fx:"smile"},
    {t:"heart", who:"温以恒", delta:1},
    {t:"n", x:"他把围裙往下拽了拽，面粉的手印留在腰侧。平底锅里煎蛋吱吱地响，油烟在走廊的白光里浮着，把整层楼烘得像真有人在这里过日子。沈时雨背靠墙站了一会儿，才把箱子放平，伸手去抚箱盖上那道旧划痕，指腹来回蹭了两遍。厨房那边传来一声轻响，温以恒把煎好的蛋拨进盘子，蛋黄晃了晃，没破。"},
    {t:"choice", prompt:"他还站在光与影子的交界线上。你要——", options:[
      {x:"走过去，替他把靠窗那张床的灯拧亮。", heart:{沈时雨:2}, flag:"shiyu_lamp",
       cb:"灯亮起来的一瞬，他抬眼看了你一下，很快又低下头，嘴角却悄悄弯了一点。那是床头最旧的一只灯，拧开时闪了两下才稳住，光圈落在枕头上，像有人提前替他把这一夜铺好了。"},
      {x:"把我的置物架空出一半，先推到他面前。", heart:{沈时雨:2, 顾知遥:1}, flag:"shiyu_shelf",
       cb:"你把半边架子推空。顾知遥哼了一声：本少爷的架子……算了，谁让你是队长。他原先并排放着的两瓶喷雾被挪到了最上层，腾出来的那一格，干净得像刚擦过。"},
      {x:"什么都不说，先蹲下来帮他把箱子摆正。", heart:{温以恒:2}, flag:"shiyu_box",
       cb:"温以恒在厨房门口看着，眼角的笑纹软下来：小队长这招，比我管用。箱子推正之后，箱角那圈旧胶布擦过地板，留下一道很浅的痕，谁也没有去擦。"}
    ]},
    {t:"n", x:"晚饭是七个人挤在小方桌上吃的。米饭的热气爬上玻璃，糊成一片白。有人用筷子敲了两下碗沿，被温以恒隔着桌子按住手腕，敲碗的动静就停了。九点整，走廊那台机器的红灯熄灭，屋里所有人都松了一口气，连呼吸都慢了半拍，像终于可以把肩胛骨放回原来的位置。汤碗传了一圈回来，谁把青椒挑到了隔壁的碗里，也没人说。"},
    {t:"d", who:"苏景行", x:"小队长，A级宿舍今天正式开张，你不讲两句？", fx:"smile"},
    {t:"d", who:"陆清越", x:"队长哥哥快讲！我要听！", fx:"laugh"},
    {t:"n", x:"你刚开口，陆清越就从口袋里掏出六枚一模一样的星星钥匙扣，一枚一枚摆到每个人碗边。塑料壳子，边角有点毛，按一下亮一小朵红光。他说是地摊上买的，一枚两块，有魔法，紧张的时候按三下。他自己一边说一边按，红光在汤面上晃出一串小点，又一枚一枚地凑过去吹了口气，说这叫激活。"},
    {t:"heart", who:"陆清越", delta:1},
    {t:"n", x:"林墨轩把那枚星星捏在指间看了两秒，收进袖口。他没说谢谢，也没说幼稚，只抬眼看了陆清越一下。那眼神里有种罕见的东西，像冬天窗台上化开的一小片水。后来有人看见，那枚钥匙扣挂在了他谱架的夹子上，挂得很正，塑料星星正对着钢琴的中央C。"},
    {t:"heart", who:"林墨轩", delta:1},
    {t:"weibo", items:[
      "#星途等级重排# 2.4亿",
      "#沈时雨终于升A# 1.8亿",
      "#王腾票务违规降级# 1.1亿",
      "#二公潮汐第一名# 8600万",
      "#队长的A就是定海神针# 5400万",
      "#理性讨论｜A级重排有黑幕吗# 2300万"
    ]},
    {t:"n", x:"夜里十一点，宿舍熄了大半盏灯，只剩桌面那一圈光。你回到桌边，发现摊在最上面的是一本被翻软的笔记本，封皮用铅笔描过团名的草图，边缘起了毛，纸页上有几处被橡皮擦得起球。旁边压着他明天要穿的练功服，叠得四角对齐，袖口往里折了一寸，是练熟了的折法。"},
    {t:"diary", who:"沈时雨", date:"第7周 周二 晴", x:"今天我的名字，第一次和队长排在了同一栏。搬箱子的时候手一直在抖，不是重，是怕。怕自己配不上那张纸，怕哪天又被换回去，怕二公那晚替我挡下的那些目光，最后落了空。顾知遥嘴上说没地方，手却把最沉的那只箱子拎上了最上层。以恒哥留了靠窗的床，说夜里通风。林墨轩没说话，只是我经过时把谱架往这边挪了半尺。队长替我把灯拧亮了。灯很暖。我不敢说谢谢，说出口就显得我还把自己当外人。可我把那盏灯的形状记在这里了。以后要练到让他们觉得，沈时雨待在A级，是理所应当的事。如果我明天又把哪一拍跳错了，请你还是看着我看。有人看着，我就敢往下跳。"},
    {t:"heart", who:"沈时雨", delta:2},
    {t:"n", x:"你把本子合好，塞回练功服下面。转身时，外间的地毯上已经坐了三个人，膝盖挨着膝盖，中间留了一个刚好容身的空位。地毯被坐出浅浅的凹，空调的风口把窗帘下摆吹得一晃一晃。苏景行的吉他横在腿上，琴弦上落着一层灯光的白。"},
    {t:"d", who:"苏景行", x:"小队长，站那儿干什么。这个位置给你留的。", fx:"laugh"},
    {t:"d", who:"顾知遥", x:"队长大人，本少爷第一天就学会让座了，你还不感动？", fx:"cool"},
    {t:"n", x:"林墨轩靠窗站着，没参与这场抢座。他把手里的素描本合上，往你这边推了半尺，封皮朝外。画的是二公水幕里你转身的那一帧，铅笔的水线还留着没擦净的反光。纸背有一小片橡皮屑，被他用拇指扫过一次，没扫干净。"},
    {t:"d", who:"林墨轩", x:"二公那场，第七拍，比排练准。", fx:"neutral"},
    {t:"heart", who:"林墨轩", delta:1},
    {t:"d", who:"苏景行", x:"老林夸人了，稀奇。这得记进团史吧？", fx:"laugh"},
    {t:"d", who:"顾知遥", x:"哼，那个弹琴的，你也就这点出息。", fx:"blush"},
    {t:"n", x:"夜话将散，苏景行把手机从口袋里摸出来，翻出一段录音塞到你手上。十九秒，画面黑着，只有你在二公后台擦着头发随口哼的两句。备忘录紧接着一页谱，是他画满的箭头和和弦名，角落里一行小字：副歌往这里走。他说灵感来了不分场合，说完把手机往你怀里一塞，像随手扔来一颗糖，又把胳膊往你肩上一搭：小队长，明天三公选人，我先排个号。话还没落地，一只抱枕从斜里飞过来，正砸在他背上。顾知遥抱着另一只，一脸若无其事。"},
    {t:"heart", who:"苏景行", delta:1},
    {t:"choice", prompt:"两个人都看着你。你要——", options:[
      {x:"“明天先跟景行过一遍流程。”", heart:{苏景行:2, 顾知遥:-1}, flag:"pick_jingxing",
       cb:"苏景行挑眉笑了一声，把吉他往膝上按了按。顾知遥扭过头去，临出门还丢下一句：明天别迟到，本少爷不等人。门被他带上，留了一条缝，缝里还有一点灯。"},
      {x:"“知遥，明天先把声部对一遍。”", heart:{顾知遥:2, 苏景行:-1}, flag:"pick_zhiyao",
       cb:"顾知遥嗯了一声，耳尖在灯下有点红。苏景行耸肩：行，我们队长说了算，我先去睡。他走的时候顺手把地毯上那只抱枕捡起来，放回沙发角，摆得很正。"},
      {x:"“你们俩自己对，我听谁更稳。”", heart:{苏景行:1, 顾知遥:1}, flag:"pick_both",
       cb:"两人对视一眼，破天荒没斗嘴，各自站到了地毯中央。窗外的风把窗帘掀起一角，两个人影被灯拉长，谁也不肯先动，像等着同一段前奏落下来。"}
    ]},
    {t:"n", x:"灯熄之后，屋里只剩空调的低鸣。走廊那台饮水机又咕噜了一声。有人在梦里翻了个身，塑料星星在枕头边亮了很小的一下，随即被压灭。上铺传来被角被掖好的轻响，掖了两次，才对上。"},
    {t:"m", x:"搬家这件事，原来不是换一张床，是有人替你留了一张。连那张床的灯，也是有人先替你拧过的。"},
    {t:"end"}
  ]
});


// ===== ch14.js =====
// 第十四章 三公选人 —— 作者批次B
window.STORY.push({
  id: "ch14",
  title: "第十四章 · 三公选人",
  phase: "选秀",
  week: 8,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"夜里说过的那个明早来得很快。七点十分，训练室的镜墙被人擦得发亮，空气里浮着地板蜡和速溶咖啡混在一起的味道，纸杯壁上挂着一圈没化开的奶精。有人在白板上写下了三个字：分、配、表，最后一笔拖得很长，像不想收。字的下方还留着上一个人用袖口蹭出来的半片白痕，白板笔的盖子没盖，笔尖晾在槽里，墨正在一点点干。"},
    {t:"n", x:"门外已经站了六个人。苏景行拎着吉他靠在门框上，亚麻色发梢被晨光镀了层毛边，鞋跟没提上，脚踝那一截露在外面。顾知遥坐在镜前整理袖口，银灰色头发一丝不苟，袖扣被他反复扣了两遍。林墨轩站在最角落的黑钢琴边，指尖压着琴盖，没出声。温以恒把一只保温壶搁在窗台上，壶口还冒着白气。沈时雨站在走廊尽头，谱子抱在怀里，纸边被他捏出一道软折。陆清越蹲在地上数镜墙的格子，数到第三排就忘了数到几，从头再来。"},
    {t:"sys", x:"【节目组】三公《银河坠落》采用分队制。第一轮由队长将六名成员分配至三支执行小队；第二轮由队长亲自组建主舞台组。分组结果一经确认不可更改，请于今日12:00前提交。"},
    {t:"n", x:"你的名字被单独列在表头，后面跟着六个待填的空格。铅笔是你自己的，削得很尖，笔杆上有一圈被指甲掐出来的浅痕。铅笔芯在纸面上划过的声音很轻，却让屋里每个人都抬了抬眼。你把铅笔转了半圈，笔尖对着自己的名字，像对着一道必须先答出口的题。有人在等被需要，有人在等被证明。"},
    {t:"d", who:"江慕白", x:"规则看着复杂，核心只有一句。你要让每个人相信，自己所在的位置，是被选中的。", fx:"neutral"},
    {t:"n", x:"他站在玻璃隔断后面，银白色头发压得很服帖，细框眼镜后的灰眸看不出倾向。说完这句他就不再给任何提示，只把钢笔在指间转了半圈，像把难题原封不动地推回来。玻璃上反出你的侧脸，也反出他袖口那颗很暗的袖扣。"},
    {t:"weibo", items:[
      "#星途三公选人# 2.6亿",
      "#今天队长会把谁带走# 1.9亿",
      "#苏景行顾知遥抢人现场# 1.2亿",
      "#银河坠落分队制# 8800万",
      "#林墨轩又被安排了# 4300万",
      "#黑｜队长根本不会分配# 1900万"
    ]},
    {t:"choice", prompt:"第一轮，六个人的去向落在你笔尖上。你怎么填？", options:[
      {x:"沈时雨去主唱组，跟林墨轩，把怯练成底气。", heart:{沈时雨:2, 林墨轩:1}, flag:"group_vocal_shiyu",
       cb:"沈时雨抬头看了你一眼，嘴唇动了动没出声。林墨轩只点了一下头，把谱子往他那边推过去，推得很平，像把一段路先替他铺好。"},
      {x:"陆清越去舞蹈组，交给温以恒带，给小太阳兜底。", heart:{陆清越:2, 温以恒:1}, flag:"group_dance_qingyue",
       cb:"陆清越一把抱住温以恒的胳膊，脸埋在他袖子上蹭了一下。温以恒笑着揉了揉他的金发，答应得比谁都快，顺手把保温壶往他怀里塞了塞。"},
      {x:"苏景行与顾知遥拆开，各领一队，让锋利分两头。", heart:{苏景行:1, 顾知遥:1}, flag:"group_split_two",
       cb:"两人同时啧了一声，又同时别过脸去。屋里安静得能听见琴弦的余振，那声音在镜墙上弹了两下才散。"}
    ]},
    {t:"n", x:"第一轮落定，纸面上多了三个清晰的箭头。铅笔的灰痕沾在你虎口，蹭在白色袖边上，留下一道浅灰。训练室的空调嗡嗡作响，把纸上没干的墨吹出一点毛刺。有人把椅子往外挪了半寸，像是给纸上的名字让路。那三个箭头画得很直，直得不像你平时的笔迹——落笔的时候，你的手其实在抖。铅笔尖断了一小截，落在表上，你用指腹把它拨到桌角。"},
    {t:"d", who:"林墨轩", x:"主唱组八度进，别抢拍。给的那段，你可以唱上去。", fx:"neutral"},
    {t:"heart", who:"林墨轩", delta:1},
    {t:"n", x:"他说完就坐到了钢琴前，一个音一个音地把那段和声敲给沈时雨听。琴槌落在弦上，余振一圈圈荡开；敲到第三遍时，沈时雨跟着哼了出来，声音先是抖，到一个长音的尾巴上突然稳住了。他自己愣了一下，耳朵红得像被烫到。琴盖上倒着两个人的影子，一个始终没动，另一个晃了两下才站直。踏板踩到底的时候，地板跟着轻轻震了一下。"},
    {t:"d", who:"沈时雨", x:"……队长，我会练会的。", fx:"shy"},
    {t:"n", x:"主舞台组的名额只有两个。这句话一出口，训练室里所有假装的轻松都收了回去。温以恒把保温壶的盖子拧紧了半圈；陆清越举了一半的手又放下去，指尖在裤缝上蹭了蹭；沈时雨往钢琴那边退了半步，像在找一个能站住的地方。顾知遥从镜台上跳下来，慢条斯理地走过来；苏景行把吉他往肩上挪了挪，背带收紧了两扣，笑意里多了一点认真。窗台上那只保温壶还冒着白气，没有人去倒。"},
    {t:"d", who:"苏景行", x:"小队长。我编的那段副歌，除你之外没人唱得出那个味。这个位置，我预定了。……你听我一句，有些位置不是抢来的，是贴着长出来的。", fx:"smile"},
    {t:"d", who:"顾知遥", x:"队长大人，本少爷的声线跟你的才叫贴。带他？不如带我。哼，反正你心里有数。", fx:"cool"},
    {t:"n", x:"他们一左一右站到你身前，谁都不肯往后退半步。镜子里映出三道影子，中间那道被两边的光框住，像一幅还没上色的构图。空气里有洗发水的柑橘味和吉他弦上的松香味，缠在一起分不开。两个人的呼吸都不重，可谁也没有先错开眼。"},
    {t:"n", x:"你回头的两秒里，白板上多了一点东西。有人在你名字右边拉了一道很轻的箭头，指向主舞台那一栏；箭头底下又被另一只手画了个圈，圈得更用力，把纸面压出一道凹痕。等你再抬眼，两道痕迹都已经被指腹抹开，只剩一片灰。桌子这头，铅笔少了一支。白板笔的盖子仍旧开着，笔尖晾在槽里，谁也没有伸手去盖。"},
    {t:"choice", prompt:"主舞台组的两个名额，你要怎么点？", options:[
      {x:"“景行来。另一个名额我留给知遥。”", heart:{苏景行:2, 顾知遥:1}, flag:"main_both",
       cb:"苏景行吹了声口哨，把吉他往肩上又抬了一寸。顾知遥哼了一声，转身时嘴角没压住：算你有眼光，本少爷勉强答应。"},
      {x:"“只带知遥。景行，你去镇住另一队。”", heart:{顾知遥:3, 苏景行:-1}, flag:"main_zhiyao",
       cb:"顾知遥把下巴抬了抬，耳尖在镜灯下泛红，顺势替你把桌角那支铅笔收进笔筒。苏景行摊手：行，谁让我们队长最会拿捏人。"},
      {x:"“只带景行。知遥，我需要你在别的组发光。”", heart:{苏景行:3, 顾知遥:-1}, flag:"main_jingxing",
       cb:"苏景行笑出声，把肩上的吉他往你这边偏了偏。顾知遥冷冷转身：……本少爷本来也没稀罕。他扣袖口的那颗扣子，扣了第三次才扣上。"}
    ]},
    {t:"n", x:"名额填完，剩下的三个人里有陆清越。他举了很久的手，被你点到时整个人都亮了一下，金发在灯下炸成一团。第一轮他没能进你的组，这第二轮他站得笔直，像早就把答案背熟了，连身后那把椅子都被他蹭得往外挪了一寸。他把两只手贴在裤缝上，掌心在裤料上按出两个深色的印。温以恒站在门口，一只手搭在他肩上，像替他按住那点太亮的光。"},
    {t:"d", who:"陆清越", x:"队长哥哥！我哪里都能去！你指哪儿我打哪儿！", fx:"laugh"},
    {t:"choice", prompt:"还剩最后一个机动名额。你要把他放在哪儿？", options:[
      {x:"把他留在身边，主舞段的收尾交给他。", heart:{陆清越:2}, flag:"qingyue_lead_out",
       cb:"陆清越愣了两秒，然后认真地敬了个不像样的礼，转头就跑去镜前站位置了，站得笔直，像怕那半寸站歪了会被收回。"},
      {x:"让他跟温以恒，去补舞蹈组最吃劲的位置。", heart:{陆清越:1, 温以恒:2}, flag:"qingyue_with_yiheng",
       cb:"温以恒伸手接住他：来，跟以恒哥一组，我教你那两个八拍收胸的技巧。陆清越点头点得太快，头发都飞了起来。"}
    ]},
    {t:"n", x:"十二点差七分，你把分配表交了上去。PD核对时抬头看了你一眼，食指在表上某处点了点：这一组，你自己请第三方老师再看一遍。你顺着他的指尖看过去——他点的是你名字所在的那一行。走廊另一头有人拖着道具箱经过，金属边擦过墙角，发出很短的一声。"},
    {t:"sys", x:"【舞台技术组】三公主舞台启用高空轨道，涉及吊升的成员须于彩排前完成安全绳负重测试，并安装双重卡扣。请持安全确认单于周五前提交。"},
    {t:"d", who:"江慕白", x:"悬在半空的人，最容易忘了地面还有六双眼睛。你上去之前，先想清楚为谁在跳。", fx:"neutral"},
    {t:"heart", who:"江慕白", delta:1},
    {t:"n", x:"他说完便转身进了控制室。玻璃上映出你的脸，也映出你身后那六道散开又聚拢的影子。走廊尽头有人搬来了第一卷黑色的轨道钢索，滚轮碾过地砖，声音沉得像提前敲了一记鼓。钢索的断口裹着一层防锈油，反出来的光是乌的。控制室里传出一声很轻的推杆声，随即又静了下去。走廊的灯在钢索上扫出一道长长的亮痕，从这头一直拉到看不见的拐角。"},
    {t:"m", x:"分配表上那六个空格终于都有了名字。可我知道，落笔那一刻开始，每个人的重量，都压在了同一根绳子上。那根绳子今天还躺在走廊里，明天就要收进我的背带。"},
    {t:"end"}
  ]
});


// ===== ch15.js =====
// 第十五章 三公《银河坠落》 —— 作者批次B
window.STORY.push({
  id: "ch15",
  title: "第十五章 · 三公《银河坠落》",
  phase: "选秀",
  week: 8,
  nodes: [
    {t:"bg", v:"stage"},
    {t:"n", x:"周五的安全确认单交上去那天，暴雨预警也发了下来。彩排厅的顶部架起十二米高的黑色轨道，钢索垂下来的时候像一排倒挂的雨线。你伸手拉了一下，掌心立刻印出一道铁锈色的痕。场馆外的天压得很低，风从侧门灌进来，把地上的防尘布吹起一角，又放下。"},
    {t:"n", x:"威亚背带是哑光的深灰，金属扣比想象中沉，扣合时要听见两声脆响才算锁死。技术人员蹲在你脚边收紧腿环，反复检查了三次，末了把手掌垫在你肩胛骨下面，示意可以试吊。背带内衬垫着一层旧海绵，吸过汗，有一股淡淡的金属味混着洗衣粉的味道。"},
    {t:"d", who:"江慕白", x:"上升的时候，别低头看地面。看你的位置，那是你唯一的坐标。", fx:"neutral"},
    {t:"n", x:"他把眼镜往上推了一下，镜片后的灰眸在你手腕上停了半秒。随后他侧过身，对技术组说了句很小的话：安全绳的备用绳，再加一条。声音低得几乎被风机的噪声吃掉。技术员应了一声，转身从货架上又取下一卷，绕线的时候钢丝发出一阵细密的响。"},
    {t:"n", x:"化妆间里没人说话。苏景行把耳机挂在脖子上，指尖在膝上敲一段没有节拍的鼓点。顾知遥对着镜子补最后一层唇釉，手抖了一下，粉色的线画出镜，他用指腹擦掉，重开始。林墨轩在角落里把耳返线一圈一圈绕好，绕完又解开，重新绕了一遍。温以恒把一卷绷带塞进外套口袋，塑料封口被他捏得轻响。沈时雨对着镜子练口型，嘴唇动了很久，没有一个音出来。陆清越抱着自己的水瓶站在门口，瓶身上的贴纸撕掉了一半，又被他按了回去。"},
    {t:"d", who:"苏景行", x:"别怕。我在下面接你。这句话今天有效，明天也有效。", fx:"smile"},
    {t:"n", x:"他说得很轻，像顺口，可那双总带着笑的眼睛盯着你的背带看了很久，直到确认卡扣全都扣死才肯转身。候场灯绿了，前方传来导播倒数，六个人按顺序把手叠在一起。最上面那只手是陆清越的，压下去的时候还用了点劲，像要把这一叠手按进地板里。"},
    {t:"sys", x:"【节目组】三公《银河坠落》直播正式开始，本次启用高空威亚环节，全网并发已进入峰值预警。请现场人员保持通路。"},
    {t:"n", x:"灯光暗下的前一秒，你被吊离地面。风从场馆顶部的缝隙灌下来，把耳返里的节拍吹得忽远忽近。你悬在半空的第八米位置上低头，看见下方是一片黑，以及黑里浮着的六点亮——是他们的应援色。钢索在头顶绷直，发出一声低沉的长音。"},
    {t:"danmaku", items:[
      "队长的应援蓝🌌|升空那一秒我鸡皮疙瘩起来了",
      "苏苏的小甜饼🍪|威亚好高啊队长小心",
      "老林的琴键🎹|主唱今晚稳得像唱片",
      "遥遥的墨镜😎|门面站那儿就是一张卡面",
      "清越冲鸭⭐|小太阳开场那句让我喊破音",
      "以恒哥的姜茶🍵|镜头切到副队他手在抖",
      "时雨今天不许怕💪|这次你站中间了"
    ]},
    {t:"n", x:"前两段很顺。器乐在底下托着，弦像从地面往上长。你在八米高处完成了第一个转身，领口灌进冷风，后背紧贴的安全带发出轻微的皮革摩擦声。台下那片黑里，有人在你转身的瞬间抬了一下手里的灯牌，光点晃了半秒，又稳住。一切都像排练过一百遍那样。"},
    {t:"n", x:"第三段副歌刚起，左肩上方传来一声极脆的响。不是音乐。金属摩擦的锐音从耳后掠过去，身体侧着往下坠了半米，又被另一根绳硬生生拽住。左腕擦过轨道边缘，一道热辣辣的亮线，从腕骨一直烧到手背。血珠很小，顺着腕骨往下走，在半空里拉成一条几乎看不见的细线。"},
    {t:"d", who:"江慕白", x:"……继续。别看伤口。看七十五秒后的那个落点。", fx:"neutral"},
    {t:"choice", prompt:"伤口还在烧，音乐只剩四十秒。你要——", options:[
      {x:"“原动作撑到底。”", heart:{林墨轩:1, 江慕白:1}, flag:"wire_full_move",
       cb:"你把重心压回原来的轴线，膝盖先动，手臂最后收。耳返里那层和声紧跟着你，一寸也没松。"},
      {x:"把后半段的高度收半米，先保落地。", heart:{温以恒:1, 沈时雨:1}, flag:"wire_lower",
       cb:"你朝技术组的方位比了一个很轻的手势。返场位上的沈时雨几不可见地松了下肩，技术组的两只手同时按在了控制台上。"}
    ]},
    {t:"n", x:"音乐没有停。你也没有停。吊在你身下的追光晃了一瞬便被稳住，影子在观众席上扫过去，像一颗没坠到底的星重新被拉回轨道。你听见自己唱出的那个字，比排练时还稳。落地前最后半米，你把左臂收在身后，谁也没有看见那道亮线。"},
    {t:"n", x:"第一个反应过来的是林墨轩。他在返场位抬起眼，黑眸里那点惯常的冷，碎成一片。他没有喊，也没有停下，和声只晚了半个音——他在下一句里把调子提了半度，用最不动声色的方式，替你接住了那口差点散掉的气。他的手指在琴键上多按了半秒，那个音才肯松开。"},
    {t:"heart", who:"林墨轩", delta:2},
    {t:"n", x:"温以恒站在侧台的幕布后，手里攥着一卷本该在候场才拆的绷带，塑料封口被掌心的汗泡软。他不能上台，就走到你视线最容易够到的那块地板上站定，两只手垂着，像一棵随时能被靠上去的树。幕布被他拽出了一道折，一直到散场都没抚平。"},
    {t:"heart", who:"温以恒", delta:2},
    {t:"n", x:"顾知遥把墨镜往鼻梁上推了推，嘴角的笑塌了一瞬。他侧过身，用肩膀挡住追光最刺的那道斜切，让你落地那一秒不至于被晃到眼。手肘一直虚抬着，直到你完全站稳才放下。放下的时候他顺手理了一下袖口，动作快得像刚才什么都没发生。"},
    {t:"heart", who:"顾知遥", delta:2},
    {t:"n", x:"沈时雨在离你最远的角落发着抖。他平时连抬头对视都不敢，此刻却往前挪了一大步，越过自己被编排的位置。你刚落地，一瓶常温的水就递到了垂着的手边，瓶盖已经被拧松。递出去之后他才想起缩手，指头在裤缝上蹭了一下，像要擦掉什么。"},
    {t:"heart", who:"沈时雨", delta:2},
    {t:"n", x:"苏景行几乎是同一秒从升降台上下来的。他笑着凑近，声音却哑：小队长，帅是真帅，下次能不能别这么吓我。他在你腕上那道红痕外面虚虚握了一圈，指尖悬着，始终没有落下来。松开的时候，他把那只手插回口袋里，攥了一下。"},
    {t:"heart", who:"苏景行", delta:2},
    {t:"n", x:"陆清越在台口跳着够你的视线，金发被灯烤成一团暖色。他喊的那句被音乐盖了过去，可你从口型认出来了——队长哥哥，疼不疼。他一边喊一边把自己的手放在嘴边吹了吹，像那样也能替你吹。吹完他把手指举起来给你看，说没有破。"},
    {t:"heart", who:"陆清越", delta:2},
    {t:"n", x:"谢幕时，六个人不约而同收拢过来，把你圈在中间。后台的冷气很足，腕上的伤还在跳，可那圈体温把你裹得严严实实，像一颗终于落回地面的星，重新有了重力。有人把手搭在你肩上，有人替你挡着过道里来回的机器臂，谁也没有先松开。"},
    {t:"sys", x:"【节目组】三公直播实时观看人数突破纪录，弹幕服务器已完成第二次扩容。请各分队于十分钟后前往一号访谈区，另请受伤成员立刻到医疗点处理。"},
    {t:"d", who:"江慕白", x:"呈现出来的东西是假的，疼是真的。处理完再来找我。", fx:"neutral"},
    {t:"heart", who:"江慕白", delta:1},
    {t:"n", x:"他把一瓶碘伏放在不锈钢台面上，瓶底磕出一声轻响。银白色的发在白炽灯下安静地亮着，他没有再多说一个字，只点了下头，转身时把医疗灯往你这边拨了拨。消毒水的味道很冲，纱布擦过伤口时先是一阵凉，凉过去了才开始疼。"},
    {t:"choice", prompt:"医疗点外站满了等着的人。包扎刚结束，你要——", options:[
      {x:"出去说没事，还不太疼。", heart:{苏景行:1, 顾知遥:1}, flag:"injury_hide",
       cb:"苏景行挑了挑眉，没拆穿。顾知遥把药膏塞进你手里：本少爷盯着你涂，别想糊弄。药膏的铝管被他捏出了一道折痕。"},
      {x:"对大家说清楚伤情，让今晚的排练顺延。", heart:{温以恒:2, 陆清越:1}, flag:"injury_tell",
       cb:"温以恒长出一口气：这才对。明天的训练表我来改，你今晚只负责睡觉。陆清越在你旁边小声跟着重复了一遍只负责睡觉，像在替这句话盖章。"},
      {x:"只告诉景行一个人。", heart:{苏景行:3}, flag:"injury_only_jingxing",
       cb:"他被你拉到走廊尽头，听完沉默了几秒，然后把今晚的陪睡名额预定给了自己：行，我守着。走廊尽头的灯管闪了一下，他把手按在墙上，替你把那截黑走完了。"}
    ]},
    {t:"weibo", items:[
      "#银河坠落威亚事故# 3.1亿",
      "#队长威亚高空稳得像钉进轨道# 2.4亿",
      "#星途舞台安全保障存疑# 1.7亿",
      "#苏景行冲下升降台的那一秒# 1.4亿",
      "#林墨轩和声提了半度# 9600万",
      "#节目组回应隐患# 6200万",
      "#黑｜靠受伤博同情# 3100万"
    ]},
    {t:"n", x:"深夜的宿舍走廊只亮着地灯。你把手腕上那道浅影对着光看，红色已经转成淡褐，像一条被时间慢慢擦短的句子。手机屏里有七条未读，每一条都写着不同的叮嘱，没有一句话是相同的。"},
    {t:"n", x:"窗外高架上的车灯拉出长线，一盏接一盏往黑里去。你把手机扣在胸口，听见隔壁传来吉他很低的几个音——有人今晚打算一整夜不睡地守着，并且固执地认为，只要弦还响着，你就不会疼。灯灭之后那几个音还在，隔一阵响一次，像有人在黑暗里数着你的呼吸。"},
    {t:"m", x:"八米之上我以为自己在坠落。后来才明白，落下来的每一步，都有人接着。"},
    {t:"end"}
  ]
});


// ===== ch16.js =====
// 第十六章 · 停播的十二小时 —— 作者批次X
window.STORY.push({
  id: "ch16",
  title: "第十六章 · 停播的十二小时",
  phase: "选秀",
  week: 9,
  nodes: [
    {t:"bg", v:"night"},
    {t:"n", x:"三公《银河坠落》的余温还没散，第九周的夜就先黑了。傍晚起基地就不太对劲：走廊的顶灯闪了两回，编曲室那台风扇停了一拍又转起来，食堂的电视忽然没了声，屏幕里的人还在张嘴。谁也没往心里放，只当是电压的问题。凌晨两点，设备一并发作，整栋楼沉进黑暗，连应急灯都只亮了半扇，绿莹莹地挂在走廊尽头，像一只没睡醒的眼睛。窗帘没拉严，窗外那片城市的夜空一下子近了，写字楼的光一格一格地亮着，像另一个还在照常运转的世界。"},
    {t:"n", x:"停电的那一下，配电间的方向先传出一声长鸣——不是响，是一种从骨头里退出去的低频。然后所有声音被一起抽走：空调外机、饮水机、走廊尽头那台永远在转的风扇。安静得能听见隔壁谁翻了个身。有人喊了一声灯，又有人笑出声；拖鞋踩着地砖，从走廊这头响到那头，一路都是摸索的节奏。有人在楼梯口喊了句是不是跳闸了，没有人应。你站在原处，先听见自己的心跳，再听见别人的呼吸——原来这栋楼里住着这么多人，平时都被机器的声音盖住了。"},
    {t:"n", x:"你在黑暗里摸到手机，屏幕的微光照出地板上几道熟悉的影子。有人划了火柴，火头一抖，一支蜡烛被点亮。暖黄的光晕从地板升起来，像一盆水慢慢满上，先照见一双拖鞋，再照见六张脸——陆清越的眼睛睁得最圆，沈时雨站在最外圈，半个身子还在暗里。"},
    {t:"d", who:"苏景行", x:"别往前，那块砖上礼拜还有人滑过。踩我脚印走，一步一步来。", fx:"neutral"},
    {t:"n", x:"你踩着他的脚印往前挪，手被他虚虚挡了一下，没碰上，却一直停在半空里等着。与此同时，六片小小的屏幕在黑中次第亮起来，像谁撒了一把没落地的星。消息一条顶一条往上涌，掌心被震得发麻。"},
    {t:"phone", who:"Stellar Drift预备团", msgs:[
      {f:"them", x:"苏景行：小队长，还在不？灯坏了别乱走，台阶那块我刚绊过。", time:"02:13"},
      {f:"them", x:"顾知遥：本少爷的香薰蜡烛居然派上用场了。队长大人，过来坐。", time:"02:15"},
      {f:"them", x:"温以恒：都别慌，我去厨房摸黑煮了点粥，一会儿端来。", time:"02:17"},
      {f:"them", x:"陆清越：队长哥哥！我的小夜灯还有电！借你！", time:"02:19"},
      {f:"them", x:"沈时雨：……我、我在这儿，需要什么说一声。", time:"02:21"},
      {f:"me", x:"都聚到客厅来，点蜡烛的那间。"},
      {f:"them", x:"苏景行：[语音] 3″", time:"02:22"}
    ]},
    {t:"n", x:"你们摸到那间摆着长沙发的客厅。地砖白天被拖过，此刻凉得透过拖鞋底一层层往上走；窗帘拉着，只在边角漏进一点城市的光，远处高架上还有车驶过。矮桌中央立着顾知遥那支香薰蜡烛，火苗被人走过的风推得歪了一下，又直回来。蜡油的味道，和温以恒手里那锅白粥的米香，先把黑填满了一半。"},
    {t:"n", x:"烛光把客厅照成一片小小的海。六个人围着那支蜡烛坐着，影子在墙上轻轻晃，谁动一下，满墙的影子就跟着动一下。谁都没提比赛，没提名次，连平时挂在嘴边的练习时长也没人说。黑暗像把每个人身上那层被镜头训练过的部分剥掉了一半，剩下的都很素，像刚洗完脸的样子。"},
    {t:"d", who:"陆清越", x:"原来停电这么黑呀，但是有大家就不怕！队长哥哥坐我这边，我这边亮！小夜灯还有一格电，省着给你用，我摸黑也能走！", fx:"laugh"},
    {t:"d", who:"温以恒", x:"来，先喝口粥。黑着也好，省得谁又躲角落练到天亮。碗我一排摆好了，谁饿了伸手就有，别客气。小太阳，慢一点，烫。", fx:"smile"},
    {t:"n", x:"苏景行把吉他横在膝上，拨了一下弦，声音在黑暗里格外清，像有人往静水里丢了一枚硬币。那一格音掉在半空，久久没落地。顾知遥靠在窗边，难得没接话，只把蜡烛往你这边挪了挪——光斜着走，照见他翘着的嘴角和一双没地方放的手。弦音落下去以后，屋子里静了两秒；那两秒里，谁都没有往比赛上想。"},
    {t:"choice", prompt:"烛光里，你要——", options:[
      {x:"“景行，弹一首吧，就现在这首。”", heart:{苏景行:2}, cb:"苏景行低笑，指尖落下，旋律像顺着烛泪淌出来。弹到第二句，他抬眼看你，那一眼不懒，很稳，像在确认什么东西还在原地。"},
      {x:"“知遥，你挪蜡烛的样子，比平时顺眼。”", heart:{顾知遥:2}, cb:"顾知遥耳尖一红，把脸扭向窗外：……才不是给你挪的。手却把那支蜡烛又推近了半寸，米香和蜡油味混在一起，暖得让人发困。"}
    ]},
    {t:"n", x:"安静里，林墨轩忽然开了口。他很少在人群里主动说话，声音比平时更低，像怕惊动什么。他把杯子放下，动作已经很轻了，杯底碰到桌面还是响了一下，六个人的目光一起转过去，没有人出声打断。"},
    {t:"d", who:"林墨轩", x:"我家里，开过一间画廊。父亲是教古典的，母亲是学画的。三楼的窗朝北，光很稳，她说过那是最适合挂画的地方。母亲走后，那间屋子就只剩唱片转动的声音——父亲再没弹过琴，只把唱针一遍遍放下去，放同一张，第三首，第二乐章，她最爱听的那段。", fx:"sad"},
    {t:"n", x:"烛火在他深邃的黑眸里跳了一下。他垂着眼，指尖无意识地在膝上敲着一段很老的旋律，节拍慢，像有人在很远的地方报出小节数。没有人接话，也没有人催他；陆清越本来举着的小夜灯，慢慢放回了腿上。"},
    {t:"d", who:"林墨轩", x:"他们希望我接班，把画廊留着，把墙挂满，做一个体面的人。可我更愿意站在这里——和你们，和一束要自己亮起来的光。这句话，我在心里放了两年，今天第一次说出口。", fx:"neutral"},
    {t:"heart", who:"林墨轩", delta:2},
    {t:"n", x:"他说完就没再出声，只是把那本素描本轻轻放在你手边。封皮那幅二公的画，被他添了一笔——画里的人，身边多了一圈很淡的暖光。纸边还留着他拇指蹭上去的一道灰印，像有人来过的痕迹，没擦掉。"},
    {t:"heart", who:"林墨轩", delta:1},
    {t:"choice", prompt:"蜡烛矮下去一截。这一夜的安静，轮到你了。", options:[
      {x:"“那我也说一件：我小时候，也怕黑。”", heart:{林墨轩:2, 苏景行:1}, cb:"苏景行的弦轻轻响了一声，像替你点了头。林墨轩看了你一眼，没说话，把那支蜡烛朝你这边推了半寸——光先落在了你的手上。"},
      {x:"“今晚谁都不许说比赛、说名次。”", heart:{温以恒:2, 陆清越:1}, cb:"温以恒低低地应了一声好。陆清越立刻举手发誓，说队长哥哥说了算；沈时雨在暗里很轻地笑了一下，那是他这一晚第一次露出声音。"},
      {x:"什么也不说，把蜡烛往桌子中间推了推。", heart:{顾知遥:2, 沈时雨:2}, cb:"顾知遥看了你一眼，哼了一声，把本来想说的话咽了回去。火苗晃了一下，六个人的影子跟着往中间挪了一点，像一屋子人同时往火边靠了靠。"}
    ]},
    {t:"d", who:"苏景行", x:"老林，你这话，比写进歌里都好听。行，那我就先欠着——哪天我写出来，你负责别嫌它俗。", fx:"smile"},
    {t:"d", who:"顾知遥", x:"哼，那个弹琴的，今晚倒是会说人话。本少爷的蜡烛也算立了功，明天谁再嫌它味道冲，我就把它收起来。", fx:"smile"},
    {t:"n", x:"温以恒把第二碗粥递到你手里，碗壁是热的，正好不烫嘴，热气往上走，把眼睛熏得发潮。沈时雨在暗处把你的水杯悄悄满上，动作轻得像怕被谁看见。陆清越靠着你肩膀，已经半梦半醒，嘴里还含含糊糊地念着明早要早起，念到一半就没了下文。"},
    {t:"d", who:"沈时雨", x:"……队长，能在这里，挺好的。灯坏了，我反而不怕。以前家里停电，我妈就点一支蜡烛，说黑的地方有人陪着，就不算黑。", fx:"shy"},
    {t:"heart", who:"沈时雨", delta:1},
    {t:"n", x:"凌晨四点，配电间的方向传出两声试探的嗡鸣，电还没有真的来。可没有人想去睡。烛泪积成一小汪，光却比来时更稳。林墨轩把速写本压在膝上，笔尖一直没停；苏景行哼着半句旋律，哼到一半忘了词，自己先笑了；顾知遥把外套搭在睡着的小太阳身上，动作快得像做贼，回头还瞪了你一眼，像是要你别作声。"},
    {t:"m", x:"原来黑，也可以这么暖。"},
    {t:"n", x:"天快亮时，第一缕灰白从窗帘缝里漏进来，落在地板上，把那一汪烛泪照成了琥珀色。有人在暗里小声说了句什么，没人听清，也没人再问。沈时雨的呼吸落在沙发角上，很轻很匀；温以恒把空碗一只只收拢，碗沿相碰，声音压到最低；顾知遥没睡，睁着眼看那点火苗，谁也没跟谁说话。蜡烛燃到了底，火苗缩成豆大的一点，光却好像还留在每个人眼里——谁都没说散，只是靠着，等那一点自己灭。"},
    {t:"end"}
  ]
});


// ===== ch17.js =====
// 第十七章 · 综艺特辑 —— 作者批次X
window.STORY.push({
  id: "ch17",
  title: "第十七章 · 谁最了解队长",
  phase: "选秀",
  week: 9,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"电是凌晨四点来的。灯管一盏盏嗡地亮起，把客厅地板上那汪凝住的烛泪照得发白。林墨轩收素描本的时候，你看见封皮上那幅二公的画被添了一笔——画里的人身边，多了一圈很淡的暖光。他没解释，你也没问。有些话在黑里说过一次，白天就不必再说第二遍。"},
    {t:"n", x:"那之后的两天，训练照旧，只是食堂的椅子和练习室的地板之间，多了几处说不清的松动：顾知遥会顺手把水推到你这边，沈时雨加练时不再躲着你的脚步声，温以恒的早餐多煎了一个蛋，谁也没说是为什么。有些东西一旦被照亮，就回不到原来的暗处去了。"},
    {t:"n", x:"第三天，节目组的团建特辑开录。一楼大厅被重新布过灯，暖黄的光压在刚铺好的驼色地毯上，空气里混着咖啡、发胶和一点新油漆的味道。墙边立着综艺组的logo板，摄像机轨道从入口一路铺到沙发区，像一条等着谁来走的河。今晚不排名，不淘汰，只录一场让观众看见你们七个人怎么相处的游戏。"},
    {t:"n", x:"你们陆续落座。温以恒把七杯温水在矮桌上排成一排，杯壁很快凝出细密的水珠；顾知遥把靠垫挪了三次才肯坐下，袖口露出一截冷银色的袖扣；陆清越盘着腿，已经开始跟摄像机打招呼；沈时雨挑了最靠边的位置，把自己收进灯光的边缘；苏景行占了你斜对面的单人沙发，下巴搁在椅背上，像来听戏的。"},
    {t:"d", who:"PD", x:"欢迎来到团建夜。今晚第一个环节，叫作「谁最了解队长」。规则很简单：我念题，六位成员抢答。答得最贴近队长真实习惯的人加分，不许商量，不许提醒，抢到才算。"},
    {t:"danmaku", items:["弹幕护法|谁最了解队长这题也太会了🍪","温以恒的小棉袄|早餐口味直接破防了","墨轩观察员|老林今天居然肯抢答","景行家的小玩家|竹马从小盯到大yyds","清越后援会|队长哥哥先给清越递饮料","知遥毒舌组|顾少爷记耳返笑死我","团建特辑bot|这期我能循环十遍"]},
    {t:"n", x:"PD从手卡里翻出第一题，纸角被他捏出一道褶。第一题：队长每次说「我没事」的时候，身体会先做哪一个动作？话音还没落地，温以恒已经举了手，稳得像课堂上那个永远先把作业写完的人。"},
    {t:"d", who:"温以恒", x:"右手，会轻轻按一下左胸口。小队长每次把累藏进笑里之前，手都先替他说了实话。你不吃葱，蛋黄要全熟，凌晨那杯奶得温到不烫嘴；低血糖那次我塞进你包侧袋的糖是橘子味的，因为你说别的太甜。这些不用抢，我每天备早餐时就记下来了。", fx:"smile"},
    {t:"n", x:"第二题在笑声里念出来：队长听别人示范演唱的时候，眼睛是怎样的？林墨轩没有举手，只抬了一下眼，开口却比谁都早，像那答案早就在舌尖上放着，等人来取。"},
    {t:"d", who:"林墨轩", x:"闭眼。你会把呼吸放轻，睫毛在颤，像把每个音往身体里收。从初评级那天到现在，没变过。专注得……很标准。我画过你听琴的样子，纸上的那支笔，总比你先停。", fx:"neutral"},
    {t:"danmaku", items:["现场导演|六个人一人守一个细节","以恒厨房|按住左胸口那下我没了","时雨躲在角落|没扔掉的水瓶我哭死","清越弹幕|队长哥哥念错我的姓好可爱","景行弹幕|左眉高半寸是从小数过的","知遥弹幕|新耳返硅胶套破案了","护法联盟|七双眼睛都长在队长身上了"]},
    {t:"n", x:"第三题：队长上台前三分钟，一定会做的一件小事是什么？厅里安静了两秒，摄像机轨道上的红灯转了半圈。顾知遥挑了下眉，慢半拍才开口，像只是顺手接住了别人没接住的那句话，语气里一点得意的痕迹都没有——他大概自己也没察觉。"},
    {t:"d", who:"顾知遥", x:"摸左耳的耳返，调整两次，第二次比第一次轻。队长大人，你那点仪式感以为没人看见？哼，本少爷记性好而已。你那副耳返的硅胶套早裂了，新的上周放你柜子里了，别到头来又说是自己买的。", fx:"cool"},
    {t:"n", x:"第四题的声音低下去：队长第一次带沈时雨加练，说的第一句话是什么？沈时雨从角落里抬起头。厅里忽然静了一层，他说话的声音比灯还轻，每个字却都送到了中央。"},
    {t:"d", who:"沈时雨", x:"……你说，慢一点，不是输。那天的水瓶我没扔，放在柜子最里面。队长哥每次路过角落，都会多看我一眼，怕我又偷偷加练。后来我慢慢懂了——那不是在盯我，是在等我抬头。", fx:"shy"},
    {t:"n", x:"第五题：队长压着情绪的时候，脸上哪里会先露馅？苏景行支着下巴，笑意比答案先到，像这道题，他等了整整一个童年，早把答案在口袋里捂热了。他开口前先看了你一眼，那一眼很短，短得像小时候巷口回头确认你有没有跟上。"},
    {t:"d", who:"苏景行", x:"左边眉毛，比右边高半寸。小玩家，你从小就这样——小时候跟我置气，鼓着腮帮子，我数到三你就敢睁眼瞪我。现在倒学会绷着了，可眉毛它不配合你啊。还有，你一紧张就先咬一下嘴唇再松开，这个别人看不出来。", fx:"laugh"},
    {t:"n", x:"第六题：队长第一次点名，念错了谁的姓，又悄悄改了回来？陆清越两只手都举了起来，整个人几乎要离开坐垫，眼睛亮得像攒了一整晚的星星，生怕被谁抢了先。"},
    {t:"d", who:"陆清越", x:"是我！队长哥哥第一次点名把陆念成了路，然后红着耳朵改回来的！还有每次庆功，你都先把饮料递给我，再拿自己的。我数过，一次都没漏！队长哥哥最疼我！", fx:"laugh"},
    {t:"n", x:"六道题念完，六个人各抢到了一个属于自己的细节。没有人答错，也没有人多答——像早就分好了工，一人守着你的一个褶皱。厅里那几盏灯把地毯烘得温热，咖啡凉在杯子里没人喝，你垂着眼，听见自己的心跳压过了摄像机的嗡鸣。原来那些你以为藏得很好的疲惫，早就落在了六个人的眼睛里，只是谁都没舍得先说出来。"},
    {t:"n", x:"场边那台监视器后面，江慕白抱着手臂站着。银白的头发被屏幕的蓝光照出一层薄霜，细框眼镜后的灰眸半垂着，他从头到尾没有插话，只在第六题答完时，极轻地点了一下头，像在一份判词的末尾，落下了一个不必写出来的字。"},
    {t:"d", who:"江慕白", x:"小队长，被人看穿不是危险，被人懒得看才是。这六道题里，藏着一支团的形状。别把它浪费在镜头前面。", fx:"neutral"},
    {t:"n", x:"他说完就转身走了，皮鞋踩在轨道边缘，声音轻得几乎听不见。PD把话筒递过来，厅里安静了一拍。六道目光同时落向你，没有抢，也没有比，只是等着——像六扇门，同时为你留了一条缝，而你站在门外的风里，一时不知道先推开哪一扇。"},
    {t:"choice", prompt:"你要怎么回应这场抢答？", options:[
      {x:"“被你们记住，真好。”", heart:{"温以恒":2, "沈时雨":1}, cb:"温以恒把保温壶轻轻推到你手边，沈时雨低着头，耳尖红了一点点。"},
      {x:"“那下一次，换我记住你们。”", heart:{"苏景行":2, "陆清越":2}, cb:"苏景行吹了声口哨，陆清越已经举起两只手比了个心。"},
      {x:"“记住归记住，别飘。”", heart:{"林墨轩":2, "顾知遥":1}, cb:"林墨轩几不可察地点了下头，顾知遥哼了一声，把脸别向摄像机那一侧。"}
    ]},
    {t:"n", x:"录制散场在夜里十一点。走廊的灯一盏盏暗下去，把七个影子叠成一道。你在后台通道看见苏景行靠着墙，指尖按着太阳穴，眉心拧着一个白天没解开的结。听见脚步，他睁开眼，懒洋洋地笑：小队长，你怎么哪儿都有你。那笑底下压着一层连他自己都不肯认的乏。"},
    {t:"choice", prompt:"你看着他，要怎么开口？", options:[
      {x:"“走，回去我给你泡杯热的。”", heart:{"苏景行":3}, cb:"他没推，把分量往你肩上靠了靠：小玩家，还是你疼我。"},
      {x:"“又通宵写东西了？从明天起，十二点前睡。”", heart:{"苏景行":1, "温以恒":2}, cb:"他笑着应了一声好，那声好松得像没打算兑现。温以恒在走廊尽头听见，脚步顿了顿。"}
    ]},
    {t:"n", x:"回宿舍的路上，夜风把每个人的影子拉得很长。你想起那六道题里被说出来的自己——按住的左胸口，闭着的眼，摸过两次的耳返，没扔掉的水瓶，挑高的左眉，念错又改回来的那个姓。原来被人记住，是这样具体的一件事：具体到一只杯子的温度，一处没愈合的旧伤，一次没说出口的回头。"},
    {t:"n", x:"走廊尽头，苏景行房间的灯还亮着，门缝里漏出一线很窄的光，像谁在夜里替你留了盏没关的灯。你站在那道光外面听了一会儿，里面有吉他拨弦的声音，断断续续，试了三个和弦，又全部推翻。你没有敲门。"},
    {t:"end"}
  ]
});


// ===== ch18.js =====
// 第十八章 · 第二次顺位 —— 作者批次X
window.STORY.push({
  id: "ch18",
  title: "第十八章 · 第二次顺位",
  phase: "选秀",
  week: 10,
  nodes: [
    {t:"bg", v:"stage"},
    {t:"n", x:"团建特辑播出那天，留言区比舞台还热闹。有人把六个人抢答时的表情截成九宫格，说这才叫团魂。可热闹是别人的，那一周真正压过来的，是周日晚八点的第二次顺位发布。你数着日子过，越近越想起走廊尽头那道没关的灯——苏景行房里的吉他声，后来响了三个晚上。"},
    {t:"n", x:"期间你只见过他两次。一次在早餐桌上，他把咖啡当成水端起来喝了一口，皱着眉咽下去，说这玩意儿怎么这么苦，惹得陆清越笑到呛住；一次在编曲室门口，他隔着玻璃朝你比了个OK，手背上有刚被纸割破的一道浅痕，创可贴贴歪了，露出一点边。你问过他睡没睡，他说睡了，答得太快，快得像早就预备好的台词。"},
    {t:"n", x:"周日晚上八点，主舞台候场区。冷气开得很足，地板被顶灯照成一面还没醒的湖，倒映着头顶密密麻麻的灯架。大屏暗着，偶尔闪过一行小字，预告今晚要揭晓的是去留，也是座次。你攥了攥耳返，塑料壳被手心焐出一缕温，指尖却还是凉的。"},
    {t:"n", x:"六个人在你身后站成一排，谁也没坐。沈时雨把袖口拽到指关节，又松开；陆清越的脚尖一直在轻轻点地，像给自己打着拍子；顾知遥靠在柱子上，看似在看手机，屏幕却是黑的；林墨轩闭着眼，嘴唇无声地动着，在过一遍呼吸；温以恒站在最外侧，手边放着七瓶拧开一半的水。队伍最前面空着一小块，那是给第一名留的位置，此刻还谁都不敢站上去。"},
    {t:"n", x:"顾知遥背对着灯，把手机屏幕按灭又点亮，反反复复，像个在等的姿势。导师席在舞台另一侧，比练习生席高出两级台阶。江慕白坐在最中间，细框眼镜后的灰眸扫过大屏，指尖在膝上那本册子的封皮上轻轻一叩，像在给什么打拍子。他没有朝你们这边看，可你把那一声叩响听得很清楚。"},
    {t:"d", who:"PD", x:"各位练习生，今晚八点，第二次顺位发布全程直播，本轮将淘汰排名末尾的十人。接下来我们要揭晓本轮的第一名——也是本季节目，第一次有人从第二的位置，登顶。请大屏，做好准备。", fx:"neutral"},
    {t:"m", x:"第二的位置。上一次是苏景行站在我前面，把我护在身后，还回头笑了一下。这一次轮到我去够那个数字，手心竟有点潮。"},
    {t:"weibo", items:["#星途第二次顺位# 3.1亿","#队长首次登顶第一# 2.6亿","#苏景行第二# 1.8亿","#王腾淘汰# 9100万","#江慕白导播间那个笑# 6800万","#星途是不是有剧本# 4300万"]},
    {t:"n", x:"大屏开始滚动前八名的名字，光一格一格地跳，像有人在很远的地方翻一本很厚的书。你听见自己的呼吸，和身边六个人的呼吸，不知什么时候叠在了同一拍上。前八念完，没有你，也没有苏景行——心跳在耳膜上敲，一声一声，像倒计时。"},
    {t:"n", x:"然后大屏定格。你的名字停在最顶端，票数比上一名多出整整十二万。耳返里涌进观众席的声浪，你怔了一秒，才敢把那行字看成真的。身侧的苏景行轻轻碰了下你的手背，没说话，只是笑，笑意里有一点你才看得懂的、松了口气的弧度。", fx:"smile"},
    {t:"n", x:"第二名念的是苏景行。他笑着上台，路过你身边时，用只有你们两个人能听见的音量说了一句：小队长，这回换我在下面看着你。他站定，抬手朝你比了个很轻的手势，像小时候巷口赛跑，他每次都故意慢半步，把你让到前面去。"},
    {t:"n", x:"你走上台中央。追光落下来的那一瞬，皮肤先一步知道了暖。耳返的重量压着耳朵，把世界隔成两层——一层是台下沸腾的暗，一层是胸腔里忽然稳住的自己。你听见自己的名字被一遍遍念着，像潮水，漫过这一季所有的凌晨。"},
    {t:"danmaku", items:["弹幕护法|第一名啊啊啊啊队长牛啊🚀","景行家的小玩家|苏苏碰手背那一下我没了","墨轩观察员|老林在台下点头了！","清越后援会|队长哥哥！我哭到看不清屏幕","以恒厨房|以恒哥眼眶红了呜呜呜","时雨躲在角落|队长哥 你看 你做到了","知遥毒舌组|顾少爷鼓掌鼓得最用力别装了"]},
    {t:"n", x:"导播间的灯很暗，只有十几块监视器亮着，蓝幽幽的光铺在江慕白银白的头发上，像落了一层霜。他坐在最里侧，指尖停在一杯没动过的茶上，水汽早散了。屏幕上你的脸被推到最大，他极轻地弯了一下嘴角，又很快收平，像怕被人看见。"},
    {t:"d", who:"江慕白", x:"小队长，你终于肯站上去了。这一路我对你最严，是因为我相信你能站到别人够不到的地方。这一秒，我等了很久。剩下的赞美，留到你能守住的时候。", fx:"neutral"},
    {t:"choice", prompt:"感言的话筒递到你手里，全场静下来。你要说什么？", options:[
      {x:"“谢谢所有人，这一程我替大家也站上来了。”", heart:{"温以恒":2, "陆清越":2}, cb:"陆清越在台下跳起来，被温以恒一把按住肩膀，可那双眼睛亮得藏不住。"},
      {x:"“第一不是终点，是我们七个的起点。”", heart:{"苏景行":2, "林墨轩":2}, cb:"苏景行在台下吹了声口哨，林墨轩几不可察地点了下头，像是默许了这句话。"},
      {x:"“我还差得远，下一站见。”", heart:{"江慕白":2, "顾知遥":1}, cb:"导播间里江慕白挑了下眉，顾知遥在台下撇嘴，说还行吧，勉强配得上队长大人。"}
    ]},
    {t:"n", x:"话音落下，台下那一片属于你们的区域炸开了。陆清越踮着脚朝你挥，被温以恒按住肩膀，可眼睛亮得藏不住；温以恒远远朝你比了个手势，嘴角是少见的、放得很开的笑，像终于敢为你松一口气，把一直绷着的那根弦悄悄放低了一寸；沈时雨把头低了又抬起，眼眶红着，却笑得很用力。"},
    {t:"n", x:"名次继续往下念，声音越来越轻，像退潮。念到中段时，台下响起了几声很短的抽气——那是有人被念到，有人没有。沈时雨的手一直攥着衣角，直到听见自己的名字落在第六，才把那口气吐出来，肩膀塌下去一寸，像终于敢相信这一轮自己还在。"},
    {t:"n", x:"念到末尾，王腾的名字没有再出现。他站在出口通道的阴影里，听见自己的号码被跳过去，肩膀僵了一瞬，又故意挺得很直，像不肯认输的某种姿势，硬撑着最后一点体面。他手里那瓶水被捏得变了形，瓶身发出一声细响。"},
    {t:"d", who:"王腾", x:"呵，队长当得真风光。我倒要看看，你能风光到第几站。这位置坐稳了再说，别哪天摔下来，连个接的人都没有。", fx:"angry"},
    {t:"m", x:"他的话像一根刺，不大，却卡在风里，一时拔不掉。"},
    {t:"choice", prompt:"面对王腾的放话，你要怎么做？", options:[
      {x:"伸手，“路还长，你也保重。”", heart:{"温以恒":1, "沈时雨":1}, cb:"他没接那只手，转身走了。沈时雨悄悄往你身侧挪了半步，像在替你挡住什么看不见的东西。"},
      {x:"“我不回头看。”", heart:{"苏景行":2, "顾知遥":1}, cb:"苏景行搭上你肩膀，懒懒地说：这才对，我们队长从不回头。顾知遥哼了一声，说算你有点风度。"},
      {x:"什么都不说，目送他走进更衣室。", heart:{"林墨轩":2}, cb:"林墨轩站在一旁没动，只在你转身时，把自己的外套披到了你肩上。"}
    ]},
    {t:"n", x:"你想起第一次顺位时他掉出A级，站在公示牌前看你的那一眼——原来那口气，早就埋下了。更衣室的门在他身后合上，声音很轻，轻得像一声没说出口的认输，也轻得像他其实也累了的某种证据。走廊的安全灯把两个人的影子拉成两道相反的痕，一道往里，一道往外，从此不再叠在一起。"},
    {t:"n", x:"直播结束，灯光次第熄灭，只剩安全出口的绿光在地板上洇开一小片安静。空气里还留着方才人声的余温，和设备散热的嗡鸣，像一场大雨刚停，屋檐还在滴水，人却已经敢喘气了。"},
    {t:"phone", who:"七个人（没有群名）", msgs:[
      {f:"them", x:"温以恒：我煮了面，在厨房。谁回来谁吃，凉了我就再煮。", time:"23:07"},
      {f:"them", x:"陆清越：队长哥哥第一名！！！我今晚不睡了！！！", time:"23:08"},
      {f:"them", x:"顾知遥：睡。明天七点集合，谁顶着黑眼圈我骂谁。", time:"23:09"},
      {f:"them", x:"沈时雨：……恭喜队长哥。我会更努力，不拖后腿。", time:"23:11"},
      {f:"them", x:"林墨轩：决赛曲，明天谈。", time:"23:12"},
      {f:"them", x:"苏景行：[语音] 4″", time:"23:14"},
      {f:"me", x:"都在厨房等我，我马上到。"}
    ]},
    {t:"n", x:"厨房的灯是暖的。温以恒的面煮得有点软，没人抱怨。陆清越一边吃一边数今天弹幕里出现最多的词，顾知遥说吵死了却一直没走，沈时雨把碗端到角落，吃得很快，像怕耽误谁。那碗面的热气把七个人的脸都熏得模糊了一层，你看着看着，忽然觉得第一名的重量，在这张桌子上才终于落了地。", fx:"smile"},
    {t:"n", x:"你回宿舍时路过编曲室。玻璃后面那盏灯还亮着，椅背上搭着他的外套，屏幕上是没关的工程文件，波形停在凌晨三点的位置，光标还在闪。你没有进去，只是把走廊的灯关了一盏，留了一盏。"},
    {t:"n", x:"窗外城市还亮着零星的灯。你摸了摸耳朵上被耳返压出的浅印，想起江慕白那句「能守住的时候」。决赛的倒计时已经翻到了个位数——下一站不再是排名，是一场要拿命去打的舞台，而你们手里，还没有一首真正属于自己的歌。"},
    {t:"end"}
  ]
});


// ===== ch19.js =====
// 第十九章 · 决赛前哨 —— 作者批次X
window.STORY.push({
  id: "ch19",
  title: "第十九章 · 决赛前哨",
  phase: "选秀",
  week: 10,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"第二次顺位发布之后的第三天，日程表上多了一行新字：决赛曲目提案会。你是在食堂的白板上看见的，粉笔字没擦干净，决赛两个字下面被人用指腹蹭出一道灰痕。白板边上还压着上周的课程表，边角卷起来，露出底下更旧的一层纸。温以恒盛的粥你端在手里，一路端到座位，凉了才想起喝。"},
    {t:"n", x:"走廊里的空气从那一天起变了。不再是练到几点的问题，也不再是谁的顺位掉了一位的问题——是你们要拿什么去打最后那一仗。练习室的灯开始亮得比往常早，熄得比往常晚；凌晨三点的镜面上蒙着一层薄雾，有人用指腹在上面写过字，又被下一次呼吸盖掉。你每天经过时都看见那行字剩一半，谁也没去补。"},
    {t:"n", x:"会议室在三楼。长桌擦得发亮，投影仪的光柱里浮着细小的灰，缓慢地上下漂。节目组把七杯咖啡摆成一排，温度刚好，杯壁凝着水汽，谁也没动。总导演翻着文件夹，纸页的声响在安静里被放大，像有人把一把尺子一下下敲在桌沿上。空调出风口正对着你这一侧，冷气落在手背上，凉得很均匀。"},
    {t:"d", who:"总导演", x:"决赛曲，我们准备了两个方案。A方案：外请制作人团队的作品，成熟、安全、编曲完成度高，名字叫《Ascend》。B方案：由你们自己提交原创，但要在三天内拿出完整demo，通过盲听评审，才能上决赛舞台。", fx:"neutral"},
    {t:"m", x:"三天。你数了一下，七十二小时，扣掉睡觉、扣掉体能与vocal课、扣掉节目组一定会临时塞进来的物料拍摄，真正能用来做歌的时间还剩多少，你不太敢往下算。"},
    {t:"sys", x:"【节目组】决赛曲目提案会：A方案《Ascend》（外请制作人）／B方案（练习生原创，需通过盲听评审）。请队长于会议现场表态。"},
    {t:"n", x:"A方案先放。前奏是标准的电子弦乐推进，鼓点稳得像一条被熨过的直线，副歌的hook咬得很准，准到挑不出一点毛病。整首歌华丽、工整、无懈可击——也像一件挂在橱窗里的外套，尺寸标准，谁穿都合身，谁的身上都不留褶。副歌推到最高那一句时，会议室里的所有人都不自觉地坐直了半寸，那是被声音按出来的姿势，不是被歌打动的。"},
    {t:"d", who:"顾知遥", x:"技术层面没得挑。可这件衣服不是给我们裁的。副歌那句最高音，时雨唱上去是喊，清越唱上去是扯，队长大人唱上去——嗯，也就是能唱。它不认识我们。", fx:"cool"},
    {t:"d", who:"温以恒", x:"稳妥一点也没错吧？决赛舞台那么大，出一点差错……我只是觉得，别让大家冒险。", fx:"sad"},
    {t:"d", who:"沈时雨", x:"……我、我两版都可以。我练得快。", fx:"shy"},
    {t:"n", x:"陆清越坐在长桌最靠里那一头，两只手一直压在膝盖上，压得指节都泛白。他听完全曲，又听了一遍顾知遥那句不认识我们，嘴唇动了动，最后也没能忍住，把手举得很高，高得像在教室里抢答，随即又自己缩回去一半。"},
    {t:"d", who:"陆清越", x:"那个……我可以说一句吗！我觉得A方案好听，真的超好听！可是刚才放的时候，我一直在想我该站哪一拍、该看哪边，想了半天没想出来。老林哥编的那首我不用想，我一听就知道我在哪儿。", fx:"smile"},
    {t:"sys", x:"【节目组】补充说明：A方案《Ascend》词曲版权归节目组与合作方共有；B方案原创作品版权归创作者本人，节目组仅保留舞台首演权。条款详见会议材料第二页。"},
    {t:"n", x:"江慕白一直没说话。他坐在长桌顶端，指尖转着那支笔，银白的头发在投影的余光里显得更冷。他把视线落在你身上，等了很久，久到总导演都开始翻第二页纸，久到那七杯咖啡上最后一点热气散尽。"},
    {t:"d", who:"江慕白", x:"小队长，这半年我教你听音，不是为了让你在今天挑一首最不会出错的歌。舞台上最贵的不是正确，是真。你打算用哪一半的耳朵做这个决定？", fx:"neutral"},
    {t:"n", x:"会议室的门被推开一条缝。苏景行站在外面，亚麻色的头发翘着一边，眼下浮着淡淡的青，脖子上的耳机只挂着一边，另一边垂在肩上晃。他穿的那件外套比上周更松了，肩线垮下去一块，袖口卷到小臂中段，手背上有一道浅浅的纸割痕。他没进来，只敲了敲门框，木头的响声很轻。"},
    {t:"d", who:"苏景行", x:"不好意思，来晚了。哦对了，B方案我们有。不是即兴，不是玩票——写了十一天，改到第七版。老林编的曲，我写的词和旋律。名字叫《长风》。", fx:"smile"},
    {t:"d", who:"林墨轩", x:"结构我重排过。前两小节留白，七个人的呼吸各占一拍。副歌不做齐唱，做叠——外面听起来是一句，里面其实是七个声部。它需要你们每一个人，缺一个就塌。", fx:"neutral"},
    {t:"n", x:"总导演把评审细则推到桌子中央，两张纸，一行行条款压得很密：匿名报送、不看创作人、七位导师加十位业内评审、成品缺一分钟算弃权。他抬眼看你，意思是流程上还有没有要说的。"},
    {t:"choice", prompt:"细则推到你面前。你要先提一个条件吗？", options:[
      {x:"“盲听可以。但成品送出去之前，别改我们任何一个音。”", heart:{苏景行:2, 林墨轩:1}, cb:"苏景行靠在门框上，把耳机线绕了一圈又松开。总导演在这条下面画了一道线，说好，一言为定。"},
      {x:"“那三天，请把我们的物料拍摄全部挪到决赛之后。”", heart:{温以恒:2, 沈时雨:1}, cb:"总导演翻了翻另一册日程，说可以，我去协调。温以恒轻轻吐了一口气，像有人替他把最沉的那块先搬走了一角。"},
      {x:"“条件等结果出来再谈。现在，先让大家听歌。”", heart:{江慕白:2, 顾知遥:1}, cb:"江慕白的笔尖在纸上停了一下。顾知遥挑了下眉，说队长大人这回倒是不客气，我喜欢。"}
    ]},
    {t:"n", x:"文件载入。前奏没有乐器，是一段很轻的底噪——凌晨练习室的木地板、脚步、呼吸，七个人的呼吸错落着叠在一起，像一扇门被推开之前，屋里的人都在等。然后钢琴进来，只有三个音。那三个音你听过，在停电那晚的烛光里，苏景行的吉他拨过一模一样的一句。"},
    {t:"n", x:"demo有杂音，人声是苏景行自己哼的，跑调的地方有两处，混音粗糙得像没洗过的底片。可它一响，你就认出来了——那是你们七个人排练到凌晨三点时，谁都累得说不出话、却谁都不肯先走的那种形状。"},
    {t:"n", x:"会议室里没有人说话。温以恒的手指在桌沿停了，没有敲下去；林墨轩闭着眼，嘴唇无声地跟着低音声部走；沈时雨的肩膀在第二个小节处轻轻抬了一下，像被人叫了名字；陆清越整个人前倾，两只手撑在桌面上，桌角的水杯被他推得挪了半寸。江慕白没有看屏幕，他一直看着你们七个。"},
    {t:"weibo", items:["#决赛曲到底用谁的# 1.2亿","#星途队长力挺原创# 8600万","#外请制作人Ascend# 5400万","#苏景行林墨轩联合创作# 4700万","#选秀该不该让练习生写歌# 3300万","#队长登顶后飘了# 2200万"]},
    {t:"choice", prompt:"总导演看着你，全桌都在等。你要怎么表态？", options:[
      {x:"“用B方案。《长风》，我们自己这首。”", heart:{"苏景行":3, "林墨轩":3, "沈时雨":1}, cb:"苏景行靠在门框上笑了一下，没出声。林墨轩把笔记本往前推了推，屏幕转向总导演。"},
      {x:"“两版盲听，谁赢用谁。我认结果。”", heart:{"江慕白":2, "温以恒":1}, cb:"江慕白的笔停在指间，停了两秒，又转起来。温以恒轻轻舒了口气。"},
      {x:"“能不能合：用《Ascend》的编曲，配《长风》的旋律。”", heart:{"顾知遥":2, "林墨轩":1}, cb:"顾知遥挑了下眉：这个说法，勉强算聪明。林墨轩没点头，也没摇头。"}
    ]},
    {t:"n", x:"会议最后给了三天。三天后盲听，七位导师加十位业内评审，不看名字，只听成品。总导演临走时把文件夹合上，说了句：demo要完整，缺一分钟都算弃权。门合上后，会议室里那七杯咖啡还是满的，凉了，杯壁上凝的水汽淌下来，在桌面留下七道很短的痕。"},
    {t:"n", x:"散会的人往两头走。林墨轩夹着笔记本回编曲室，走之前看了苏景行一眼，那一眼意思是今晚别迟；沈时雨跟着温以恒去搬晚餐，走到楼梯口还回头看了看那台还亮着待机灯的投影仪；陆清越被顾知遥一路拎着领子拖走，嘴里还在说我还想再听一遍。"},
    {t:"n", x:"走廊尽头，温以恒拦住你，声音压得很低，像怕被墙听见。他从口袋里摸出两板药，是退烧和缓解咽痛的，铝箔被捏得有点皱，边角有一处指甲压出的白印。"},
    {t:"d", who:"温以恒", x:"他这两晚没回宿舍。我在编曲室门口捡到过空的咖啡杯，三个。小队长，我不反对他写歌，我只是……怕他倒下来。他那个人，倒下来是不会叫人的。", fx:"sad"},
    {t:"n", x:"你回头看，苏景行正把耳机挂回脖子上，跟林墨轩比划着什么，手指在空中点着拍子，笑得还是那副懒洋洋的样子。那件外套的肩线被他穿得松松垮垮，风一吹就空了一块，像里面的人比上次见时又薄了一点。他察觉到你，隔着半条走廊朝你抬了抬下巴，嘴唇动了两下，你读出来是两个字：放心。"},
    {t:"choice", prompt:"你走过去，要怎么对他说？", options:[
      {x:"“三天。三天之后，你给我睡满一整天。”", heart:{"苏景行":2, "温以恒":2}, cb:"他笑着应了，说好啊，听队长的。温以恒在走廊那头看着，没走。"},
      {x:"“我陪你。你写，我在这儿。”", heart:{"苏景行":3}, cb:"他愣了一下，那点懒散的笑慢慢收起来：小队长，这话你可别随便说，我会当真的。"},
      {x:"“编曲让老林多担一点，你只管词。”", heart:{"苏景行":1, "林墨轩":2}, cb:"林墨轩淡淡接了句：可以。我已经把第二部分写完了。苏景行啧了一声：老林你抢我活儿。"}
    ]},
    {t:"n", x:"那天夜里两点，你从练习室出来，编曲室的灯还亮着。玻璃上凝着一层薄雾，里面的影子伏在桌前，肩膀随着节拍轻轻动，手边那杯水从满到凉，始终没碰过。清洁工推着车从走廊那头过去，轮轴吱呀地响了一阵，又远下去。你在门口站了一会儿，最后只发了条消息，然后回宿舍睡了——你需要明天早上六点，还站得起来。"},
    {t:"phone", who:"苏景行", msgs:[
      {f:"me", x:"写完就睡，别熬。"},
      {f:"them", x:"小队长，灵感这东西它不等人的。", time:"02:14"},
      {f:"them", x:"[语音] 5″", time:"02:14"},
      {f:"me", x:"那我明天早上看。看完给你改意见。"},
      {f:"them", x:"行。那你先睡。晚安，宝贝。", time:"02:15"},
      {f:"them", x:"……这句当我没发。[撤回了一条消息]", time:"02:15"}
    ]},
    {t:"n", x:"你把那条被撤回的消息看了一遍，屏幕的光在黑暗里把脸照得发白。上面一行是提示，说对方撤回了一条消息，连影子都没留下。窗外的城市还醒着，远处高架上有车驶过，轮胎擦过路面的声音被夜拉得很长。你没有回。有些话一旦接住，就再也放不回去了——而现在，你们还有一首歌要写完，还有一场决赛要打。"},
    {t:"n", x:"床头那两板药你终于拆了一板，铝箔撕开的声音在宿舍里响得很清楚。上铺的林墨轩翻了个身，你以为他醒了，等了几秒，没有动静，只有呼吸又慢慢沉下去。你把药放进背包侧袋，跟充电线挤在一起，明天早上记得塞给他。"},
    {t:"n", x:"三天，七十二小时。你把闹钟调到了五点四十，把《长风》的demo存进手机，设成来电铃声。睡过去之前最后听见的声音，是走廊尽头那台空调外机在响，一下，一下，像有人在很远的地方，替谁数着拍子。"},
    {t:"end"}
  ]
});


// ===== ch20.js =====
// 第二十章 · 裂痕与缝合 —— 作者批次X
window.STORY.push({
  id: "ch20",
  title: "第二十章 · 裂痕与缝合",
  phase: "选秀",
  week: 11,
  nodes: [
    {t:"bg", v:"night"},
    {t:"n", x:"提案会给了三天，盲听定在周六晚上。这是第二天的夜里，一点五十。你从练习室出来，整条走廊只剩编曲室那一格的灯还亮着——白光从磨砂玻璃里渗出来，在墙上切出一块发青的方。口袋里温以恒塞的那两板药还在，铝箔的边角硌了你一路，你一直没想起要吃。"},
    {t:"n", x:"走廊里没有人。地砖白天刚拖过，此刻凉得从拖鞋底一寸寸往上走，脚踝那一圈先冷起来。楼外的空调外机在响，一下，一下，像替谁数着拍子。玻璃门上凝了一层薄雾，里面的影子伏在桌前，肩膀随着某个节拍极轻地动，动得均匀，均匀得像另一种安静。你在门口站了几秒，手按在门把上，金属是凉的。门边墙根立着两个空杯子，杯底各留着一圈深褐色的印，早就干了。"},
    {t:"n", x:"门一推开，热气和味道一起涌出来——冷掉的咖啡、受潮的纸、被电器烘了一整夜的塑料味。编曲室不大，两块吸音棉的边角翘着，桌上摊满谱纸，铅笔屑积在键盘的缝里，被灯照得发亮。苏景行伏在桌上，脸侧压在纸上，亚麻色的头发散开来，盖住了半块屏幕。他指间还夹着笔，指腹上蹭了一道铅笔灰。屏幕停在一段循环播放的音轨上，工程名是《长风》，后面跟着一个字：v7。"},
    {t:"d", who:"苏景行", x:"……这段不对。小玩家，你听第二遍……低音没跟上来。", fx:"sleepy"},
    {t:"n", x:"他的手指在桌沿敲了两下，没敲到第三下。你把掌心贴上他的额头——烫。不是熬夜那种浮上来的热，是烧，掌心贴上去，温度顺着掌纹往里走。他外套的肩线在你手下轻轻一颤，风从门缝里挤进来，掀起了谱纸的一角，又落下。三天期限，还剩一天。"},
    {t:"choice", prompt:"凌晨两点的编曲室。你要先做什么？", options:[
      {x:"“以恒，你来一趟，带上退烧的。”", heart:{温以恒:2, 苏景行:2}, cb:"电话响了一声就被接起。温以恒只说了一句知道了，三分钟，就挂了。他没问是谁病了——这栋楼里，只有一个人会在凌晨两点还坐在编曲室。"},
      {x:"先把他扶回宿舍，物理降温。", heart:{苏景行:3}, cb:"你把他一只手绕过自己的肩。他整个人往你这边沉了半寸，烧得连话都软了：“……我还没写完。就差副歌那一句。”"},
      {x:"先把《长风》存盘，再扶他走。", heart:{林墨轩:2, 苏景行:1}, cb:"你把工程存了三份，一份进硬盘，一份发进群里，一份留在桌面。他半睁着眼看了你一会儿，笑了一下：“还是我们队长。”"}
    ]},
    {t:"n", x:"你给他套上那件松垮的外套，把笔记本合上，屏幕的光一收，屋里立刻暗了半格。走廊很长，灯只亮了三分之一，隔几米一盏，中间是成片的黑。你扶着他一步步走，脚步声一深一浅，他的重量大部分压在你右边肩上。走到楼梯口，他烧哑的嗓子在你耳边响起来：这条路，我们小时候也走过。你以为他在说胡话，只把他的手往肩上又抬了抬。"},
    {t:"bg", v:"dorm"},
    {t:"n", x:"宿舍的窗朝东，凌晨的月光薄薄地铺在地板上，像谁泼了一层洗过笔的水。你掀开被子一角让他躺下。温以恒来得比三分钟还快——他没敲门，只在门边站了一下，把两板药和一支体温计放在矮凳上，又从保温壶里倒了半杯温水，然后退出去，把门轻轻带上。他一个字也没多问。走廊上他的脚步走远了，又停下来，大概是站在那儿听了几秒，才真的回房。"},
    {t:"phone", who:"Stellar Drift预备团", msgs:[
      {f:"them", x:"温以恒：38度7。药放在门口矮凳上，今晚别叫他起来。", time:"02:26"},
      {f:"them", x:"顾知遥：本少爷早就说过，那个写歌的迟早把自己写进医院。楼下我温了姜茶，谁下来拿，过时不候。", time:"02:27"},
      {f:"them", x:"陆清越：队长哥哥我能不能上去守着他！我就坐着不出声！真的不出声！", time:"02:28"},
      {f:"them", x:"沈时雨：……我把编曲室那台电脑的电源拔了，它一直在响，我怕吵到他。", time:"02:31"},
      {f:"me", x:"都去睡。明早六点的早功照旧，谁都不许迟到。"},
      {f:"them", x:"苏景行：[语音] 2″", time:"02:34"}
    ]},
    {t:"phone", who:"温以恒", msgs:[
      {f:"them", x:"烧退一点没有？", time:"03:10"},
      {f:"me", x:"38度2，睡沉了。"},
      {f:"them", x:"毛巾别敷太久，凉了就得换，不然他要踢被子。你也在椅子上眯一会儿。", time:"03:11"},
      {f:"them", x:"上一次你低血糖，他也是这么坐着，坐了一夜。第二天照样上台。", time:"03:12"}
    ]},
    {t:"n", x:"那条语音只有两秒：他烧哑的嗓子跟着《长风》哼了半句，尾音没接上就断了。你把手机扣在桌上。铁腿折叠椅比床矮一截，坐久了腰发酸。毛巾在冷水里浸过两次，你叠成长条搭在他额上，水顺着他的鬓角滑下去一小道，很快洇进枕头。他睡着的时候眉头还是拧着的，像梦里也还在改一个和弦。你想找体温计，翻遍了床头和抽屉，都没找到——多半还在他背包里。"},
    {t:"n", x:"你把背包提过来，拉开侧袋。里面全是纸：揉过的车票、便利店的收据、撕下来又没舍得扔的谱纸，边角都软了。最底下压着一个牛皮纸小袋，捏起来硬硬的，袋口被人反复折过，折痕很深。倒出来是一枚校徽——铜的，边角已经磨圆，正面那两个字被磨掉了左下的一角；背面的别针歪着，缠了两层黑胶布，缠得很旧，胶布边缘发白发毛。"},
    {t:"m", x:"你认得这枚校徽。也认得那两层胶布。"},
    {t:"n", x:"那时候，你们住在同一条巷子里。巷口有棵老槐树，夏天把影子铺满一地；卖冰棍的老伯骑着车经过，铃铛从街尾一路晃到街头。你们上同一所小学，校服洗到发白，校徽别在左边胸口。他的那枚别针是早就松了的，你提醒过他两回，他都摆摆手说没事。"},
    {t:"d", who:"苏景行", x:"我那个别针断了。找了一节课了。我妈说再买一个，可这个上面有我的名字。", fx:"sad"},
    {t:"n", x:"那天下午的风把下课铃吹得很长，操场上的白线被晒得发亮。你把自己胸前那枚摘下来，铜片还带着体温，扣进他手心里。你说得很轻，像怕被风抢走：“反正我不爱戴，跑操的时候它还响。”他愣着，没接，也没推回来，就那么托着那枚校徽站了一会儿。"},
    {t:"d", who:"苏景行", x:"那我记着了。以后还你一个更好的。", fx:"neutral"},
    {t:"n", x:"他后来也没还。那枚别针上的胶布是他自己缠的，缠了两层，因为他怕再掉——这件事你到今天才知道。再往后的事你记得清楚：初二那年他第一次抱着吉他上台，你坐在第三排，从头到尾没敢眨眼；初中毕业那个夏天，你们在巷口那块砖上用钥匙刻下两个歪歪扭扭的浅痕，说好以后一起站到最大的舞台上。刻痕很浅，浅到那年的雨一冲就淡，可你们都没回头去补。"},
    {t:"heart", who:"苏景行", delta:3},
    {t:"n", x:"毛巾已经捂热了。你翻过一面，又去浸了一次冷水，指节在凉水里停了一会儿才抽出来。窗外那块天开始泛灰，灰里透出一点很淡的蓝。他的睫毛动了两下，眉头松开，像从很深的地方慢慢往上游，游到一半，又停住不动了。"},
    {t:"choice", prompt:"他还没醒，你手里还捏着那枚校徽。你要——", options:[
      {x:"放回牛皮纸袋，按原样塞回侧袋。", heart:{苏景行:2}, cb:"你把袋口的折痕一点点压平，塞回最底下，和那些车票挤在一起，像从没被人动过。有些东西，不该在他没准备的时候被翻出来。"},
      {x:"放在他枕边，等他睁眼自己看见。", heart:{苏景行:3}, cb:"铜片落在枕上，几乎没有声音。你退开半步，像退出一句还没说出口的话。晨光挪过来，先照到的是那枚磨圆了的边角。"},
      {x:"攥在手里，什么也不做。", heart:{苏景行:1}, cb:"你把它攥在掌心，铜片被体温一点点捂热。天快亮透的时候你才发现，自己一直没松手。"}
    ]},
    {t:"d", who:"苏景行", x:"几点了……你一晚上都在这儿？《长风》我到第七版了。副歌那句我总觉得不对——刚才睡着的时候，我知道哪儿不对了。", fx:"sleepy"},
    {t:"n", x:"他说完这句，眼睛又慢慢阖上，睫毛在晨光里投下很浅的一道影。呼吸往下沉，稳了，额头只剩一点温热不退的余韵。你替他把被角掖好，目光落在桌上那个卷了边的笔记本上——摊开着的那一页，写满了他的字，字迹到后面开始往下斜，像写字的人也在一点一点往下坠。笔记本旁边散着十几张揉皱又展平的谱纸，每一张上都写着同一句词，划掉，重写，再划掉。"},
    {t:"diary", who:"苏景行", date:"第11周 周一 04:20", x:"半梦半醒的时候，听见放毛巾的水声，一下一下，很轻，像怕吵着我。桌子上的工程没关，我知道有人替我存过盘。那枚校徽她不知道我留着。小学四年级，队里发了两枚，一枚别在我胸口，一枚别在她那儿。我的别针断了那天，她把自己的摘下来扣给我，说反正不爱戴。她记性那么差，第二天就忘了。我记了十几年。副歌那句写不下去，是我一直绕着走：写得太直，她会装作没听见；写得太绕，她听不懂。第七版我把那两层胶布写进去了，就四个小节。要是这次盲听过了，我想跟她讲这个。要是没过，就先不讲。"},
    {t:"n", x:"天光已经亮到能看清窗台上的灰。走廊里开始有脚步声，先是一个人，然后是几个，拖鞋、拉链、保温杯碰在一起。编曲室那台电脑被人拔了电源，安静得像从没亮过一整夜。他把脸埋进枕头，翻了个身，含糊地念了半句谁也听不清的话，又睡沉了。"},
    {t:"sys", x:"【节目组】决赛周单人采访今日上午十点开始，按顺位依次进行。请各位练习生于九点半前到达基地二楼采访间。"},
    {t:"n", x:"手机在掌心震了一下，那条通知浮在最上面。你起身时，铁腿椅子在地上刮出一声轻响，你没敢让它响第二下。走到门口回头看了一眼：被子鼓起一个平稳的轮廓，呼吸一起一落，慢得像谁把拍子调到了最缓。你把门带上，走廊尽头的窗正对着初升的太阳——决赛周，从今天开始。"},
    {t:"end"}
  ]
});


// ===== ch21.js =====
// 第21章 决赛周·单人采访 —— 剧本写手批次A
window.STORY.push({
  id: "ch21",
  title: "第二十一章 · 决赛周·单人采访",
  phase: "选秀",
  week: 11,
  nodes: [
    {t:"bg", v:"interview"},
    {t:"n", x:"凌晨你合上宿舍的门，动作放得很轻。苏景行的烧退了，睡颜安静，亚麻色头发散在枕上，像终于肯把力气交还给睡眠；桌上那台笔记本被你合了盖，工程文件存过三遍，可他还是把一张谱纸攥在手里，纸角被掌心的汗浸得发皱。窗外的天光正一点一点泛白，不敢惊动什么，只在窗帘缝里留一道浅灰。"},
    {t:"n", x:"决赛周第一天。节目组把采访间搬进基地二楼最靠里那间仓库改的屋子，只放得下一张单椅、一盏暖灯和一台架在三角架上的机器。旧地毯吸走了脚步声，踩上去像踩在很厚的灰上；空气里有地毯受潮的霉味和金属支架的凉气。电缆沿着墙脚绕了半圈，用灰胶带粘在地上，每隔一段就鼓出一个小小的包。"},
    {t:"sys", x:"【节目组】决赛周单人采访开始。本轮采访不涉及舞台与顺位，主题只有一个：队长是什么。"},
    {t:"n", x:"PD说，今天不问舞台，只问一个问题——队长是什么。你抱着记录本坐在监视器后，看六个人一个一个走进去，又走出来。灯亮着，每个人的脸都被照得很清楚，连睫毛投下的影子都看得清。监视器有轻微的电流声，红的REC灯一直亮着，像一粒不肯灭的火。"},
    {t:"n", x:"苏景行最先走进去。他往椅背上一靠，椅腿在地板上磨出一声轻响，懒洋洋地笑，眼下那点倦意被灯揉淡了，像刚从一场长梦里被轻轻叫醒，还舍不得把笑意收起来。他穿着那件松垮的灰外套，领子立着一半，袖口有一道洗旧的毛边。"},
    {t:"d", who:"苏景行", fx:"smile", x:"“队长啊？小玩家就是那种，你掉进海里队长第一个跳下来捞你的人。烦得很。”"},
    {t:"d", who:"苏景行", fx:"sleepy", x:"“也是我写歌的时候，唯一不怕被听见的人。”"},
    {t:"d", who:"苏景行", fx:"smile", x:"“哦对，还有一条。队长管我叫起床。三天里叫了四回，最后一回是隔着门骂的，骂完自己笑了。我听见了。”"},
    {t:"heart", who:"苏景行", delta:1},
    {t:"n", x:"他出来的时候没有回宿舍，靠在采访间外面的墙上，耳机重新戴上，只戴一边，另一边垂在胸前晃。他看见你，抬了抬下巴，意思是你的那份我等着听。走廊的感应灯隔二十秒暗一次，他就抬手挥一下，灯又亮起来，像在跟什么东西较劲。"},
    {t:"n", x:"温以恒第二个。他坐得端正，双手放在膝上，褐色眼眸弯着，像怕说错什么似的先笑了笑，眼角软得像晨里的棉花。他说完会习惯性地看一眼镜头外——你在的那个方向。你想起每天清晨那七份摆好的早餐，热粥，鸡蛋，每人碗边不同的小菜；他自己的疲惫，从不在桌上，也从不对谁说。"},
    {t:"d", who:"温以恒", fx:"smile", x:"“小队长吗……是把所有人的口味都记在心里，自己却总忘了吃饭的那个人。还好吗？”"},
    {t:"d", who:"温以恒", fx:"neutral", x:"“我知道这个问题答得太像废话。可是队长这两个字，落在我这里，就是每天要先问的一句话。问出口了，我才算把这一天开起来。”"},
    {t:"n", x:"他不等PD追问，自己又补了一句，说得很轻，说完就把视线收回到膝上，像那句话本来不打算给镜头听。"},
    {t:"heart", who:"温以恒", delta:1},
    {t:"n", x:"林墨轩走进来时，背挺得很直。黑眸在灯下很静，像进了不属于他的领地，却也不打算敷衍，只把最准的那句话留给你。清晨练声的人，吝啬赞美像吝啬空气，可今天他破例多说了半句。他坐下之前先把椅子摆正，对准了镜头，动作像调一件乐器。你的记录本上，他这一段是唯一一页被写满的。"},
    {t:"d", who:"林墨轩", fx:"neutral", x:"“队长，是让每一次走位都站得住的人。”"},
    {t:"d", who:"林墨轩", fx:"cool", x:"“刚才那句，是我能给的最高评价。”"},
    {t:"heart", who:"林墨轩", delta:2},
    {t:"n", x:"他出来的时候手里多了一张纸——是采访桌边上放着的便签，他把它折成四折，塞进了口袋。他没解释，只在走过你身边时，把脚步放慢了半拍。那半拍你注意到了，可你没有问。"},
    {t:"n", x:"顾知遥翘着腿进来，银灰发在灯下泛冷光，翘起的眉梢写满本少爷不情愿。他把椅子往后拖了半步，像要跟镜头保持一个体面的距离，肩上那件外套搭得一丝不苟。你想起他偷偷塞东西又矢口否认的样子，那时他说，过时了，不要了——可那东西第二天就出现在你柜子里，摆得很正，连包装的折角都对得齐齐的。"},
    {t:"d", who:"顾知遥", fx:"angry", x:"“队长大人？哼，就是那个明明不行还要硬撑的人。本少爷才不是被队长大人忽悠来的。”"},
    {t:"d", who:"顾知遥", fx:"cool", x:"“而且，队长大人记性差。上周三谁把外套忘在车里，是我拎回来的。这事儿没人谢我，无所谓，本少爷不图那个。”"},
    {t:"m", x:"你把膝上的记录本翻过一页，铅笔停在纸上，没往下写。这些人嘴上说的，和眼睛里藏的，从来不是同一句话，可你都接住了。"},
    {t:"heart", who:"顾知遥", delta:1},
    {t:"n", x:"沈时雨是攥着衣角进来的。他坐下时只用了椅面前三分之一，脚趾在鞋里蜷着；声音低得几乎听不见，深棕色头发遮住半张脸，耳尖却先红了，像被自己的话烫到。你想起那晚天台，他把伞忘在谁的外套里，自己淋着雨回去，第二天还说没事。"},
    {t:"d", who:"沈时雨", fx:"shy", x:"“队长哥……是、是光。我总怕拖后腿……可队长哥每次都说，时雨很好。”"},
    {t:"d", who:"沈时雨", fx:"neutral", x:"“采访之前我想了很久，怕说得不对。以前我练习的时候老想，要是谁都不看我就好了。现在不是。现在……我想被看见。就这一点，是队长哥给的。”"},
    {t:"heart", who:"沈时雨", delta:2},
    {t:"n", x:"陆清越最后一个，眼睛亮得惊人，金色短发下的脸绷着一股劲，像把一整天的太阳都攒在了眼里。他坐得笔直，两只手按在膝盖上，答话的时候整个人往前倾，椅子被带得吱呀一声。他说完自己先红了眼眶，又很快笑开，怕你担心，像怕你担心是他的错。"},
    {t:"d", who:"陆清越", fx:"laugh", x:"“队长哥哥是最厉害的人！没有队长哥哥就没有我们！我要成为让队长哥哥骄傲的成员！”"},
    {t:"d", who:"陆清越", fx:"smile", x:"“还有还有！队长哥哥上次分蛋糕，把有草莓的那块给我了，还说是随机的！我知道的！我一点都不笨！”"},
    {t:"n", x:"他出去以后，采访间安静了几秒。PD低头看回放，暖灯还亮着，椅子被六个人坐过，椅面上留了一点温。你把散在桌边的六只纸杯收走——前面每个人进来时都有人递水，走出去了，杯子都还剩大半。只有陆清越那杯是空的，杯底压着一张他随手画的小人，头上画了一颗星。"},
    {t:"n", x:"采访灯灭了一次。你合上记录本，起身准备走，PD却抬手拦住你，指了指那盏灯，又指了指椅子。摄像机转过来，红点重新亮起。他把同一张写着问题的卡递到你面前，那张卡的边角已经被七个人的手摸得发软。"},
    {t:"n", x:"PD在每段采访之后都要清一次机器，重新对一次焦，重新调一次色温。你在监视器前坐了一整个下午，记录本上真正写下的字不多，大半页是空的。空白的地方你自己知道记着什么：谁答话的时候看的是镜头，谁看的是地板，谁在说完了之后还停了两秒没起身。"},
    {t:"choice", prompt:"镜头对着你。这个问题的第七份答案，你要怎么给？", options:[
      {x:"“队长不是一个位置，是一个方向。”", heart:{江慕白:2, 林墨轩:1}, cb:"你说完就没再解释。监视器后没人出声，只有灯丝在玻璃里轻轻响。第二天你听说，江慕白把这句话抄在了他那本册子的扉页上。"},
      {x:"“队长是那个被六个人接住的人。”", heart:{温以恒:2, 沈时雨:1}, cb:"你把话说得很短。说的时候你想起被递到手里的水、被塞进口袋的药、被搭上肩膀的外套——话说完，你自己先愣了一秒。原来这些也算答案。"},
      {x:"“还不知道。等成团夜过了再答。”", heart:{苏景行:2, 顾知遥:1}, cb:"你把卡轻轻推回去，说了句等一等。PD笑了，说这是我们收到的最诚实的一份。走廊那头传来苏景行吹口哨的声音，不知他听见了多少。"}
    ]},
    {t:"n", x:"你抱着记录本往回走，经过空荡的练习室，门虚掩着，里面两本摊开的日记被风轻轻吹得翻页，纸角软软地颤，像两个没敢说出口的秘密，在等你看见。练习室的镜面还留着白天擦过又没擦净的水痕，一道一道斜下来，把灯切成很多条细长的白。"},
    {t:"diary", who:"顾知遥", date:"第11周 周一 晴", x:"今天那个PD问我队长是什么。镜头前我又说了那套本少爷才不是被队长大人忽悠来的鬼话。其实……江制作说得对，我是不是被忽悠来的？第一次初评级，队长替沈时雨挡王腾那一下，我站在旁边，心里想的竟是这人倒是够胆。后来发现队长记性烂得要命，却记得每个人练到几点。我的领带被悄悄理过一次，我没敢动。哼，就当是过时了，不要了。反正那本子队长大人也不会翻到这一页。"},
    {t:"diary", who:"沈时雨", date:"第11周 周一 夜", x:"今天采访，PD问我队长是什么。我说队长是光。说出口就后悔了，太肉麻，队长哥会不会觉得我奇怪。可是真的。第一次在门外想敲又不敢敲的那晚，是队长先看见了我。后来每次我说我怕拖后腿，队长哥都认真说时雨很好。我把这句话写在日记本第一页了。决赛了。如果我能站上去，我想让队长哥看见，时雨也可以的。以恒哥说我可以的，队长哥也说过，那我就信。"},
    {t:"n", x:"你合上两本日记，按原样摊开在桌上，位置恢复到没有被人动过的样子，又站了一会儿。走廊尽头，江慕白站在灯影里，细框眼镜反着一点冷光，像早就在那里，只是没出声。你把记录本抱紧了一点，胸口有什么沉下去，又有什么立起来，像把这一季的乱线，终于找到了线头。决赛周的灯还亮着，十二周走到尽头前，今晚先落一次幕。"},
    {t:"d", who:"江慕白", fx:"neutral", x:"“小队长，明天开始，十二周要在这几天里还清。”"},
    {t:"choice", prompt:"回到宿舍，你决定——", options:[
      {x:"去练习室再加一轮。", heart:{苏景行:1, 林墨轩:1}, cb:"你转身往练习室走。苏景行在走廊那头哀嚎一声，还是跟了上来，懒洋洋地搭住你肩，说陪你疯到底。"},
      {x:"先去看看景行。", heart:{苏景行:2}, cb:"你轻手轻脚推开宿舍门。苏景行没睡，睁着眼冲你笑：“小玩家，我还以为你把我忘了。”"}
    ]},
    {t:"choice", prompt:"顾知遥和沈时雨的日记，你打算——", options:[
      {x:"谁也不说，替他们收好。", heart:{沈时雨:2, 顾知遥:1}, cb:"你把日记本轻轻合上，塞进书架最里层。有些话，不必说出口，也好。"},
      {x:"找个机会，让知遥知道你看见了他的别扭。", heart:{顾知遥:2}, cb:"你在心里记下了那一页。下次他再说过时了不要了，你要当没听见，把那点别扭悄悄收下。"}
    ]},
    {t:"end"}
  ]
});


// ===== ch22.js =====
// 第22章 成团夜（上）—— 剧本写手批次A
window.STORY.push({
  id: "ch22",
  title: "第二十二章 · 成团夜（上）",
  phase: "选秀",
  week: 12,
  nodes: [
    {t:"bg", v:"stage"},
    {t:"n", x:"决赛周的第六天，晚上七点四十。基地的排练厅换成了这座能坐两万人的场馆，后台通道比基地的走廊宽三倍，也冷三倍。化妆间镜子一圈灯泡全开着，亮得人脸上没有一处阴影；空气里是定型喷雾、汗和皮革台面混在一起的味道。桌角排着七瓶拧开的矿泉水，瓶身上的水珠一颗一颗往下滚，在台面上积成很小的七滩。"},
    {t:"n", x:"成团夜。场馆外的星蓝灯海晃成一片，风里都是应援牌的反光，像把整条街的星都搬到了这里。你站在后台入口，听见自己的心跳盖过了音响的试音，一下一下，比鼓点还清楚。门帘被风顶了一下，又落回去，缝隙里漏进一阵人声，像远处的潮。"},
    {t:"n", x:"十二周前你也在这样一扇门前站过，那晚你谁都不认识，只认得苏景行递过来的半瓶水。现在门后面是两万人，是十二周，是六个名字。你把耳返戴上又取下，塑料壳被手心焐出一缕温。"},
    {t:"n", x:"苏景行挨过来，懒洋洋碰了碰你肩，亚麻色头发在廊灯下泛着柔光，外套的领子终于被他立正了，袖口那道旧毛边压在手表带上。他手里那瓶水，瓶身还凝着一层凉的汗。"},
    {t:"d", who:"苏景行", fx:"smile", x:"“小玩家，紧张了？”"},
    {t:"n", x:"你摇头。他笑了笑，没再逗你，只是把一直攥着的那瓶水塞进你手里，指尖凉凉的，瓶身却留着他的温度。他塞完就往后靠回墙上，双手插进口袋，视线越过你看向那块写着入场顺序的白板。舞台的风从幕缝里钻进来，带着铁锈和灯粉的气味。"},
    {t:"n", x:"幕布另一侧，六个人分别在动。温以恒把所有人的耳返逐一摸了一遍，确认每一只都有电，像清点一整箱的鸡蛋；林墨轩背对着人墙，在做无声的开口练习，下颌线绷得很紧；顾知遥对着反光的柱子理第三遍领口；沈时雨把手掌贴在腿上，一下一下压着，那是他给自己数拍子的方式；陆清越在原地小跳，跳两下就回头看一次你的方向。"},
    {t:"sys", x:"【节目组】成团夜直播即将开始。本场最终顺位按实时票数锁定，结果当场公布。"},
    {t:"n", x:"灯光暗下，又炸开。七个人从升降台升起，追光落在每个人肩头，像把整片星海搬上了台。鼓点砸下来，地板都在震，空气里浮着汗、香水和不肯散的紧张，混成一种只属于今晚的味道。第一句歌词进入的时候，台下两万支应援棒同时翻了颜色，从白变成星蓝，那一片蓝光涌过来，把舞台的地屏都染亮了一格。"},
    {t:"danmaku", items:[
      "星蓝应援团|开场这个升降台绝了",
      "队长的小望远镜📡|七个人同框美哭",
      "墨轩圈外观众|林墨轩今天好稳",
      "知遥的银灰发|顾少爷这张脸是犯规吧",
      "时雨勇敢飞|沈时雨加油啊孩子",
      "清越后援会|清越眼睛亮得像装了星星",
      "景行家的猫|苏景行一笑我没了"
    ]},
    {t:"choice", prompt:"开场舞台收势，七个人退回侧台，还有四分钟的空档。你——", options:[
      {x:"挨个拍一下每个人的肩，从温以恒拍到最后。", heart:{温以恒:2, 陆清越:1}, cb:"你走过去，一路上拍了拍七次肩膀。轮到温以恒时，他反过来按住你的手，只按了一下，什么也没说。"},
      {x:"站到沈时雨旁边，什么也不做。", heart:{沈时雨:2}, cb:"你只是站着。沈时雨低着头，过了十几秒，忽然说了一句：队长哥，我刚才一句都没错。声音很小，却比平时稳。"},
      {x:"把水递给林墨轩，他刚才那一段的最高音。", heart:{林墨轩:2, 顾知遥:1}, cb:"林墨轩接了水，喝了一口，把瓶盖拧回原样递还给你。顾知遥在旁边哼了一声：偏心。可他自己的那份，也没见他少喝。"}
    ]},
    {t:"n", x:"舞台的尾音还在空气里震，像潮水退去前最后的涌动。主持人的声音切进来，带着笑，把全场从那股劲里轻轻拎起来：“现在，进入最终顺位宣读。”"},
    {t:"n", x:"大屏幕亮起。倒计时的一秒一秒，被投在你们脚下的地屏上，红得发烫，像谁把十二周的日夜都压缩成了这几道光。你听见身侧六个人的呼吸，一个比一个轻，又谁都不肯先漏掉。倒计时跳到最后一个数时，全场忽然静得能听见看台上有人把应援棒放在了腿上。"},
    {t:"n", x:"第七名——"},
    {t:"n", x:"沈时雨。名字落下的那一刻，他愣了一瞬，然后弯了弯眼睛，像不敢相信又像等了太久。灯光打在他抖动的肩上，他没有躲，只是把攥了一路的手，慢慢松开了，指尖还留着月牙形的印。"},
    {t:"n", x:"第六名——陆清越。他跳起来，又赶紧捂住嘴，金色短发在光里晃成一团暖。他回头，朝你比了个最大的笑，眼睛亮得像刚充好电，连鼻尖都泛着光，是七个人里最先相信奇迹的那个。"},
    {t:"n", x:"第五名——顾知遥。他挑眉，银灰发微扬，看向你的方向哼了一声，嘴唇却弯起来，湛蓝的眼眸里没有半分轻视，只有一点不肯认的认真，像在说，本少爷本来就该在这。"},
    {t:"n", x:"第四名——温以恒。他轻轻握了握拳，褐色眼眸弯成月牙，目光扫过每一个人，像在确认大家都还在，一个都没少。他朝你点了点头，那是他每次把心放回去的动作，安静，却准。"},
    {t:"weibo", items:[
      "#星途成团夜直播# 3.1亿",
      "#沈时雨第七名出道# 1.2亿",
      "#陆清越第六名# 8900万",
      "#顾知遥第五名# 7600万",
      "#温以恒第四名# 6500万",
      "#成团夜家人VCR# 2.0亿",
      "#星途决赛实时票数# 4.5亿"
    ]},
    {t:"n", x:"大屏幕暗了一瞬。主持人的声音放轻，像怕惊碎什么：“接下来，有一段话，想先放给台上的他们。”风从场馆缝隙钻进来，吹得追光轻轻晃，把气氛从欢呼里，慢慢按进另一种安静。"},
    {t:"n", x:"画面亮起。是沈时雨的父母。工地，风把安全帽吹得轻响，父亲戴着安全帽，母亲在旁边笑，身后是没砌完的墙，钢筋露着冷光，远处有搅拌机的闷响，一下一下，像这座城市的另一场心跳。"},
    {t:"n", x:"镜头晃了两下才稳住，一看就是拿手机举着录的，举得久了，画面有一点抖。父亲搓了搓手，掌心的灰在镜头前蹭出一小道痕：“时雨啊，爸和妈在工地上给你录的。你别省，吃好点。”母亲在旁边补了一句：“甭操心家里。你只管跳你的。”说完她把脸别开，去扶那顶被风吹歪的安全帽。"},
    {t:"n", x:"沈时雨低下头，追光里他肩膀轻轻抖了一下，又稳住了。台下安静得能听见呼吸，没有人鼓掌，怕一拍手就破了那层薄薄的克制。"},
    {t:"n", x:"画面一切，陆清越的全家挤在镜头前，爸妈身后还探出一只狗的脑袋。“清越，加油！”全家人齐声，狗也汪了一声。画面晃得厉害，有人笑场，有人喊再来一遍，最后还是那只狗把这一条录完了。"},
    {t:"n", x:"陆清越在台上笑出了眼泪，又赶紧擦，擦不干净，就由它挂着——那是被一整个家托在手掌里的孩子，第一次知道自己的光有人接。"},
    {t:"n", x:"最后是顾知遥的父母。书房里灯很白，书架排得整齐，两人背挺得笔直，和他一个模子刻出来的。父亲先咳了一声，像在清嗓子，也像在给自己找台阶：“知遥，家里不需要你光宗耀祖。你高兴就行。”"},
    {t:"n", x:"母亲别过脸，声音比丈夫低一些：“反正你从小到大，什么事都自己扛。下次，偶尔想想家里人。”她说完这句就抬手把镜头推远了一点，画面里只剩下半张桌子。"},
    {t:"n", x:"顾知遥盯着屏幕，喉结动了动，哼了一声：“谁想你们了。”眼睛却红了，红得那点银灰的傲气，一下子软了边。他把手插进口袋里，又抽出来，最后只是很轻地在裤缝上擦了擦指腹。"},
    {t:"choice", prompt:"看着沈时雨还低着的头，你——", options:[
      {x:"在台上悄悄朝他伸出手。", heart:{沈时雨:3}, cb:"沈时雨抬头，看见你的手，慢慢把自己的覆上来，指尖还在抖，却攥得很稳，像终于敢接住别人递来的光。"},
      {x:"把目光稳稳落在他身上，不挪开。", heart:{沈时雨:2}, cb:"沈时雨似乎感觉到那道目光，肩膀一点点松下来，终于抬起了头，对你点了点，很小，却很用力。"}
    ]},
    {t:"n", x:"大屏幕还暗着。VCR的余温留在空气里，像谁悄悄把一盏灯放在了每个人手边，不说话，却一直在。你听见身侧有人轻轻吸了下鼻子，又很快忍住。台上没有人说话，六个人的影子被顶灯拉长，并排落在同一块地屏上，谁也没往前多走一步。"},
    {t:"n", x:"黑屏持续了整整五秒。那五秒里，两万人都在看台上，台上七个人都在看自己的脚尖。耳返里导播的声音压了又压，数着拍子等信号回来。第五秒过去，屏幕重新亮起，看台上那一片星蓝慢慢举了起来，没有人喊，只有塑料棒相互碰到的细响，像雨落在很远的棚顶上。"},
    {t:"n", x:"你忽然想起沈时雨第一次在练习室门口把手举起来又放下的样子，想起顾知遥把领带别过去的那张脸，想起陆清越把有草莓的那块蛋糕推给别人时还要说这是随机的。这些和台上那块屏没有关系，可它们在同一秒里一起涌上来。"},
    {t:"n", x:"温以恒伸手把陆清越眼角那点湿按掉，动作很快，像替弟弟擦掉嘴角的饭粒；林墨轩的手垂在身侧，指节动了一下，最后什么也没做；苏景行望着大屏那块黑，笑还挂在脸上，只是弧度低了两分。"},
    {t:"choice", prompt:"这一夜还长，你心里想着——", options:[
      {x:"顺位还没念完，沉住气。", heart:{林墨轩:1}, cb:"你闭上眼，把十二周的日子在心里过一遍，像把乱掉的谱子重新理顺，每一个名字都落回它该在的位置。"},
      {x:"等会儿无论第几，都要和六个人站在一起。", heart:{温以恒:1, 苏景行:1}, cb:"你把手收进掌心，像提前握住了一样东西，七个名字，一个都不少，连呼吸都往同一个节奏里靠。"}
    ]},
    {t:"n", x:"后台的灯还亮着。你听见身后六个人的呼吸，和你的，叠在一起，分不出彼此，像同一片海里的浪，谁也分不开谁，也不想分开。"},
    {t:"n", x:"侧台的阴影里，工作人员抱着流程板一路小跑过去，板子上还夹着下一段的台词卡。你低头看了一眼自己的手——指甲缝里卡着一点彩带的亮粉，怎么都搓不掉。有人在你身后把水递过来，没说话。"},
    {t:"end"}
  ]
});


// ===== ch23.js =====
// 第23章 成团夜（下）—— 剧本写手批次A
window.STORY.push({
  id: "ch23",
  title: "第二十三章 · 成团夜（下）",
  phase: "选秀",
  week: 12,
  nodes: [
    {t:"bg", v:"stage"},
    {t:"n", x:"大屏幕重新亮起，蓝白的底色一闪，像有人把窗帘拉开了一道缝。VCR的余温还没散，空气里还挂着刚才那种不敢大声呼吸的静。主持人的声音已经带着笑：“顺位，继续。”你听见自己的心跳，又一次盖过了音响，一下一下，像在数着剩下的名字，也像在数十二周里那些没能睡熟的夜。"},
    {t:"n", x:"“第三名——”主持人的尾音拖长，吊着全场的气。大屏幕滚动，名字一格一格往上跳，光扫过看台时，那一片星蓝跟着一闪。名字落定，追光偏过去，把那个人从夜里捞出来，光束里浮着细小的金粉。"},
    {t:"n", x:"林墨轩。他微微颔首，背挺得笔直，黑眸在追光里很静。台下有人喊他的名字，他像是没听见，只把目光轻轻落在你身上，像在说，稳住，还有你，别抢我的词。那份克制，是他能给的最重的托付。上台的台阶他走了四步，每一步都踩在同一个节拍上，最后一阶踏上去时，舞台的地屏震了一下。"},
    {t:"n", x:"他站定，没有像别人那样先看大屏，而是先低头看了一眼脚边的位置标——那是他彩排时用胶带贴过的地方。确认过，才抬头。台下有人举着一块手写的牌子，字很大，写的是名字，他看见了，微微点了一下头，那个幅度小得只有站在侧台的人能察觉。"},
    {t:"n", x:"“第二名——”这一回，心跳慢了半拍，像谁在嗓子眼处按了一下，又松开。"},
    {t:"d", who:"苏景行", fx:"smile", x:"“小玩家，压你一头可不容易。”"},
    {t:"n", x:"苏景行挑眉，转头看你，懒洋洋地笑。他伸了下手，又收回去，把那句恭喜摁回口袋里。湛蓝的眼眸里，没有一点输的不甘，只有一点你才看得懂的骄傲，像早在竹马的那二十年里，就料到了今天这束光会落在你身上。"},
    {t:"n", x:"他走过你身边时脚步慢了半拍，肩膀极轻地碰了你一下，像小时候在巷口赛跑，他每次都故意落后半步，站在你身后替你挡风。他手上那瓶水早喝完了，空瓶被他捏得有点扁，握在掌心里，一路带上台。"},
    {t:"sys", x:"【导播间】顺位宣读进行中，实时票数已锁定，最终结果将于本场公布。"},
    {t:"n", x:"全场安静了一拍。大屏幕开始滚动，速度慢得像在吊所有人的胃口，红光亮得人不敢眨眼。你听见自己的呼吸，和六个人的，叠在一起，谁也没有先开口。看台上有人的应援棒没电了，那一点白在黑压压的人里，很小，很亮。"},
    {t:"n", x:"第一名。"},
    {t:"n", x:"中央升降台缓缓升起。追光只打向中央，光束里浮着细小的金粉，像十二周的尘埃终于肯落定，不再飘着。风从台口吹过，把那束光揉得微微晃，像在确认，是你。台下两万人一起站起来的那一下，声浪不是涌过来的，是砸过来的，砸在你耳膜上，又顺着骨头往下走。"},
    {t:"danmaku", items:[
      "全站都在喊队长|第一名是你啊啊啊",
      "星蓝大海|十二周你配得上这个C位",
      "墨轩的素描本|哭死 队长C位",
      "景行后援|苏景行第二也笑得开心",
      "知遥嘴硬心软|顾少爷眼睛红了",
      "时雨的小太阳|沈时雨你做到了",
      "团魂这一刻|七只手叠起来我爆哭"
    ]},
    {t:"n", x:"你的名字，打在屏幕正中央。字体很大，大到你看不清它的笔画，只看见那几个字一直在闪。那一瞬间，场馆的声浪掀起来，又被人硬生生压成一声整齐的喊，像整片海同时吸气，又同时把那口气，交还给你。"},
    {t:"n", x:"侧台那边先炸开。陆清越第一个跳起来，两条手臂举过头顶，喊得脸都变了形，被身后的人一把拽住衣角；温以恒一手按着他，另一只手抬起来朝你比了个大拇指，比完又赶紧扶正旁边差点倒下的谱架；顾知遥站在原地鼓掌，拍得很快，嘴型是两个字，你没听清，但看懂了；林墨轩只是把手抬起来，掌心朝你，停了两秒；沈时雨整个人往前探，被隔离带挡回去，只能攥着那根带子，攥到指节发白；苏景行没动，他看着你，笑得很慢，像终于把一口憋了十二周的气，慢慢吐完。"},
    {t:"n", x:"你也终于看清了台下。第一排有人举着一块很大的手绘牌子，星蓝的纸壳被顶灯照得发亮，上面写着你的名字，笔画歪歪扭扭，一看就是熬夜赶出来的。那双手一直举着，举到你都能看见它在轻轻抖。"},
    {t:"n", x:"十二周。你听见自己心里有什么，终于落地。不是轻，是重——是每天清晨的镜面、深夜的地板、沙哑过的嗓子和抖过的膝，是苏景行写废的谱、林墨轩改到天亮的编、温以恒凉掉的早餐、顾知遥别过去的脸、沈时雨不敢停的步、陆清越亮到发烫的眼，一起沉进脚底，把你钉在了光里。你伸手，接住那一束只属于你的追光，掌心是暖的。"},
    {t:"n", x:"追光贴着皮肤，热得发烫，掌心的汗和灯光一起亮。你听见耳返里自己的呼吸被推得很近，也听见台下那一声喊的尾音还没有散尽，像潮水退到一半，又被谁叫了回来。"},
    {t:"m", x:"原来C位不是被托上去的。是十二周的重量，一层一层，把你磨成了能站住的那个人。"},
    {t:"n", x:"团名在这一刻揭晓，打在屏幕上：Stellar Drift。漂流之星。全场跟着念了一遍，念得不整齐，反而更像真的。七个名字，一艘船，从此要一起往未知的海里去，风浪都还没名字，可桨已经在手里。"},
    {t:"n", x:"屏幕上的英文字母边上有两块小小的动画：一颗星，一道浪。设计得很素，没有多余的花。你盯着看了两秒，发现那颗星的位置在屏幕左下角，刚好压在七个人站位图的第一格上。台下的喊声把这两个词拆开来喊，先是Stellar，隔一拍再是Drift，两万人的拍子竟然对上了，像有人在指挥。"},
    {t:"choice", prompt:"团名在屏幕上亮着，台下在喊那四个字。你——", options:[
      {x:"在心里把那三个词默念了一遍。", heart:{林墨轩:1, 温以恒:1}, cb:"Stellar，Drift。你把它们拆开又合上。台上很吵，你却很静，像终于给这十二周找到了一个装得下它的盒子。"},
      {x:"回头看了一眼侧台的六个人。", heart:{苏景行:1, 沈时雨:1}, cb:"你回过头。六个人站在同一道光里，温以恒在点头，陆清越在跳，沈时雨把手举到一半又放下——那一眼，你打算记很久。"},
      {x:"把话筒握紧了一点。", heart:{顾知遥:1, 陆清越:1}, cb:"你握紧了话筒，金属是凉的。顾知遥在侧台看见这个动作，嗤了一声，说队长大人紧张起来也这样。可他自己，把手在裤缝上擦了两遍。"}
    ]},
    {t:"n", x:"七人站成一排。主持人的声音放轻，像怕惊散这一刻：“把手，叠上来。”"},
    {t:"n", x:"你把手心摊开。六只手先后落上来——温以恒的，指尖暖，指腹有点粗，是常年洗碗和切菜留下的；林墨轩的，掌心凉，压得很稳，不晃；顾知遥的，先虚虚碰了一下才肯压实，银灰发垂下来遮住半只眼睛；陆清越的，热得发烫，落下来的时候还轻轻弹了一下；苏景行的，最随意，却压得最重，像把小半个体重都交了过来；沈时雨的最后，轻得像怕压碎你，却也最不肯松开，指尖在你掌心蜷了一下，又稳稳贴住。"},
    {t:"n", x:"七只手叠成一座很小的塔。谁也没说话，谁也没有先抬起来。台下的星蓝一起亮了，从看台最远端开始，像潮水一层一层推过来，推到台口，把七个人的影子全淹进去。"},
    {t:"n", x:"那座塔在灯下停了很久。你数得清每一只手的温度和重量，也数得清十二周里每一次有人先松开、又有人先伸回来的时刻。台下的喊声一层压一层，可你耳朵里最清楚的，是这七只手掌叠在一起时，那一点几乎听不见的摩擦声。"},
    {t:"n", x:"江慕白在导播间，镜片后的眼微微弯了一下。他没说话，只是把耳返里那句很好咽了回去，端起杯子，杯壁映着满屏的星蓝，像把这一夜收进了他最珍重的那层抽屉，连指纹都不肯留下。他手边那本册子摊开着，扉页上多了一行字，墨还没干透。"},
    {t:"weibo", items:[
      "#StellarDrift出道# 5.2亿",
      "#队长第一名C位出道# 4.8亿",
      "#七人团魂名场面# 3.3亿",
      "#苏景行第二名# 2.1亿",
      "#林墨轩第三名# 1.8亿",
      "#温以恒顾知遥沈时雨陆清越# 2.6亿",
      "#星途决赛屠榜# 6.0亿"
    ]},
    {t:"choice", prompt:"C位的追光还打在你身上，你——", options:[
      {x:"把六只手一起举高。", heart:{苏景行:1, 陆清越:1}, cb:"七只手一起举过头顶，星蓝的灯海瞬间炸开。陆清越喊得破了音，苏景行在旁边笑得直不起腰，却把手举得比谁都高。"},
      {x:"转身，先给六个人鞠了一躬。", heart:{温以恒:1, 沈时雨:1}, cb:"你弯下腰的瞬间，沈时雨慌忙去扶你，又听见全场欢呼。温以恒在身后，轻轻按了按你的肩，像在说，该的。"}
    ]},
    {t:"choice", prompt:"面对镜头，你想说的第一句话是——", options:[
      {x:"“这条路，是我们七个人一起走完的。”", heart:{林墨轩:1, 顾知遥:1}, cb:"林墨轩几不可察地点了下头。顾知遥哼了一声，偏过脸，却把你的话在嘴里念了一遍，像要记住。"},
      {x:"“十二周，谢谢你们没放开我的手。”", heart:{苏景行:2}, cb:"苏景行在旁边笑出了声：“小玩家，以后也别想甩开。”他伸手，在你肩头轻轻一拍，很轻，却很重。"}
    ]},
    {t:"n", x:"灯光收拢成星蓝。全场Stellar Drift的喊声，掀翻了屋顶，又落回每个人发烫的耳根。台上散场时，彩带从顶棚落下来，粘在汗湿的肩膀上，粘在睫毛上，谁也没去摘。地屏上留着一层被踩乱的彩带印，像潮水退后留在沙滩上的痕。"},
    {t:"n", x:"第一支安可曲的前奏起来之前，七个人还没有把手放下。你站在中间，左边是温以恒，右边是苏景行，再往两边数过去，一个不少。十二周的重量，在这一刻，终于成了翅膀——不是谁托着你飞，是你和六个人，一起把自己，练成了能飞的形状。"},
    {t:"end"}
  ]
});


// ===== ch24.js =====
// 第24章 尾声·庆功宴 —— 剧本写手批次A
window.STORY.push({
  id: "ch24",
  title: "第二十四章 · 尾声·庆功宴",
  phase: "选秀",
  week: 12,
  nodes: [
    {t:"bg", v:"banquet"},
    {t:"n", x:"成团夜散场后两个半小时。保姆车从场馆后门开出，绕了三条街，停在一栋写字楼的顶层。妆已经卸干净了，耳朵上还留着耳返压出的两道浅印，指尖还有一点彩带的亮粉，怎么搓都搓不掉。电梯上行的十几秒里，七个人谁都没说话，只有轿厢的风在响。"},
    {t:"n", x:"庆功宴设在一间安静的包厢。窗外是城市的夜，灯一簇簇落进江里，被水揉成碎金，晃啊晃，像把十二周的重量先替你们接住了。没有镜头了，空气里只剩酒杯相碰和彼此呼吸的声音，每个人都终于敢松一口气，把背从那根绷了许久的弦上，轻轻卸下来。圆桌上转盘边摆着一圈冷盘，虾是刚剥的，汤还在小砂锅里滚，白汽顶着盖子一下一下地跳。"},
    {t:"n", x:"七个人围着圆桌。苏景行难得没说话，只是把果盘往你这边推了推，亚麻色头发在暖光下松松垮垮，像把今晚的C位，悄悄让回你手边。他左手还压着一张折过的谱纸，是刚才从外套里掏出来的，一直没打开。陆清越趴在桌上，眼睛还亮着，像没从刚才那一声喊里醒过来，指尖在桌布上一下一下地敲，替心跳打拍子。"},
    {t:"n", x:"温以恒先做的事是给每个人倒水，从你开始，一圈倒下来，水温刚好。林墨轩把外套挂在椅背上，袖子叠了两折；顾知遥进门先看了眼窗帘的缝，把它拉严了；沈时雨坐在最靠里的位置，背靠着墙，膝盖上放着那个旧布偶，他一直没放下过。"},
    {t:"n", x:"江慕白最后进来，银白色头发在灯下泛冷光，仪态永远完美，细框眼镜擦得很干净。他把外套搭在椅背，落座主位，灰眸扫过每一个人，像在清点他亲手雕过的作品，确认一件都没缺，也没一件走样，才肯在自己心里，给这一季画一个逗号。"},
    {t:"d", who:"江慕白", fx:"neutral", x:"“小队长，从明天起，我不再是只做评委。”"},
    {t:"n", x:"他放下酒杯，杯底磕在桌面，一声轻响，像给这句话盖了章。“团综，我来当导师。这趟漂流，我陪你们走。”银灰的眸子里没有评判，只有一句落定的承诺，像把一直攥在手里的线，终于递到你掌心，由你决定往哪片海放。"},
    {t:"n", x:"说完这句，他从西装内袋里抽出一份薄薄的文件，纸角挺括，放在转盘上推到你面前，没让你马上翻。封面是哑光的，指尖压上去有一点粗糙的摩擦感，上面印着《漂流季》四个字，字不大，压在一个手绘的波浪标记下面。你没翻，只把它挪到转盘靠里的位置，让它别被汤汁溅到。"},
    {t:"weibo", items:[
      "#江慕白担任团综导师# 2.4亿",
      "#StellarDrift庆功宴# 1.1亿",
      "#出道夜之后# 9800万",
      "#团综预告# 7600万",
      "#星蓝应援色# 6500万",
      "#七人下一程# 1.3亿"
    ]},
    {t:"m", x:"你怔了一下。团综——是下一程了。十二周之后，故事没有句号，只是换了片海，浪还等着你们去踩，风也还不知道往哪边吹。"},
    {t:"n", x:"温以恒先开口。他声音很轻，褐色眼眸弯着，像把明天清晨的粥和鸡蛋已经在心里摆好了。他看向你的时候，手指无意识在桌沿敲了两下——那是他每次确认大家都好好的小动作，十二周里你见过太多次，比任何承诺都让人安心。"},
    {t:"d", who:"温以恒", fx:"smile", x:"“小队长，下一程的早餐，我还是包了。还好吗？”"},
    {t:"d", who:"温以恒", fx:"neutral", x:"“我看了团综的行程表，第一天早上六点半集合。我把闹钟调在五点四十五。你们别笑，这个我熟。”"},
    {t:"m", x:"你把那句还好吗，在心里接住了。十二周里，他问过你无数次，每一次都像在替所有人，先把你这块地方按实。"},
    {t:"phone", who:"Stellar Drift", msgs:[
      {f:"them", x:"陆清越：出道物料出来了！我存了十张！！！", time:"21:40"},
      {f:"them", x:"顾知遥：存一张就够了。十张是手机没内存的意思吗。", time:"21:41"},
      {f:"them", x:"温以恒：都别抢，我整理成相册了，明天发群里。", time:"21:42"},
      {f:"me", x:"先吃饭。菜要凉了。"},
      {f:"them", x:"沈时雨：……好的队长哥。", time:"21:43"}
    ]},
    {t:"n", x:"林墨轩坐着，背挺得笔直，黑眸在暖光里少了几分舞台上的冷。他说话向来短，像把一句话磨到没有多余的边，才肯递出来。他端起杯子，杯沿映着一点光，像已经替下一首歌，在心里画好了第一个音符，只等你开口。"},
    {t:"d", who:"林墨轩", fx:"neutral", x:"“出道只是开始。下一首歌，我写给你。”"},
    {t:"d", who:"林墨轩", fx:"cool", x:"“旋律我先起了两句。等团综录完，你听一遍再决定要不要。不喜欢就退回给我，不用客气。”"},
    {t:"n", x:"顾知遥哼了一声，银灰发在灯下泛冷光，却先别过了脸。耳尖那点红，比任何一句表白都诚实。他端起杯子挡住半张脸，像要把那点软藏进杯壁后面，可嘴角的弧度，早就出卖了他，也早就，把位置让给了你。"},
    {t:"d", who:"顾知遥", fx:"angry", x:"“哼，C位又怎样。下一程，本少爷罩你。”"},
    {t:"d", who:"顾知遥", fx:"cool", x:"“还有，行李箱别自己拎。上次在机场，你一个人拖着两个箱子走了两百米，本少爷看着都替你累。这不是关心，是嫌你走得慢。”"},
    {t:"m", x:"你没拆穿他。本少爷罩你这种话，从他嘴里出来，分量比谁都重，因为他从不肯把轻易二字，给任何人。"},
    {t:"sys", x:"【节目组】提醒：团综《漂流季》第一站集合时间为明日上午九点，地点已私发至各位手机。行李请控制在两件以内。"},
    {t:"n", x:"沈时雨低下头，又鼓起勇气抬起来，深棕色头发遮不住眼里那点光。他声音不大，却比任何时候都稳，像终于敢把自己，轻轻放进那个叫未来的词里，不再先问可不可以，只先说我会。他放在膝上的手把布偶的耳朵捏了一下，又慢慢松开。"},
    {t:"n", x:"果盘转到第三圈的时候，虾壳在盘边堆成了一小座。陆清越把最大的那只剥好了放进你碗里，说是还上次蛋糕的账；顾知遥立刻剥了一只更大的推过来，说是本少爷看不过去；温以恒没参与这场比试，只把两个人的手一起按回桌面，顺手给沈时雨添了半勺汤。"},
    {t:"weibo", items:[
      "#StellarDrift出道夜回放# 2.9亿",
      "#队长捧杯那个镜头# 1.6亿",
      "#成团夜最想重看的一段# 6200万",
      "#苏景行第二名发言# 8100万",
      "#七个人一间包厢# 3200万",
      "#星蓝# 1.4亿"
    ]},
    {t:"d", who:"沈时雨", fx:"shy", x:"“队长哥……下一程，我、我会跟上来的。”"},
    {t:"d", who:"沈时雨", fx:"neutral", x:"“……还有。今天我上台之前，在走廊里数了三十下。以前要数到一百。是你说的，慢一点也没关系。”"},
    {t:"n", x:"苏景行懒洋洋地碰了碰你的杯，亚麻色头发松松垮垮，湛蓝的眼眸里却亮着一种你熟悉的光——不是舞台上的恣意，是回到家才肯松开的那种认真。他没多说，可那一下轻碰，比谁的保证都先到，像竹马二十年，早把默契写进了骨缝。"},
    {t:"d", who:"苏景行", fx:"smile", x:"“小玩家，下一程我还当你的竹马。这次换我跟着你漂。”"},
    {t:"d", who:"苏景行", fx:"sleepy", x:"“那张谱纸我留着。等团综空下来，我弹给你听。要是你又听不出来是给你的，我就再写一首，写到你能听出来为止。”"},
    {t:"n", x:"他说这话的时候没看你，眼睛落在转盘上那盘快化完的冰。谱纸在他指间被捏出一道新的折痕，压在旧折痕旁边，两道并排。你从他手里把纸抽过来看了一眼，只看见一行被涂了三遍的词，最后一遍写得很轻，像怕被人认出来。"},
    {t:"n", x:"陆清越几乎是弹起来的，金色短发晃成一团暖，眼睛亮得能照亮整间包厢。他说话总像在许愿，可这一次，许的是关于你的愿，许得理直气壮，像早就认定了你值得被这样盼着，也值得被他，追成一颗星。"},
    {t:"d", who:"陆清越", fx:"laugh", x:"“队长哥哥！下一程我要更厉害，让你骄傲！”"},
    {t:"d", who:"陆清越", fx:"smile", x:"“我把我的幸运石带来了！是漂流屋里捡的那块白石头！我明天要放在队长哥哥的房间门口，这样你早上开门就会踩到好运！”"},
    {t:"choice", prompt:"江慕白说要当团综导师，你——", options:[
      {x:"“有江老师在，我安心。”", heart:{江慕白:2}, cb:"江慕白唇角几不可察地弯了一下，端起杯子朝你举了举，像是应了这份托付，也像是收下了你给的信任。"},
      {x:"“那导师，下一程请多指教。”", heart:{江慕白:1}, cb:"他微微颔首，灰眸里掠过一丝满意，像你终于接住了他递来的那根线，没有让它，落回地板。"}
    ]},
    {t:"phone", who:"苏景行", msgs:[
      {f:"them", x:"小玩家，庆功宴坐我旁边。", time:"21:13"},
      {f:"me", x:"你又想抢果盘？"},
      {f:"them", x:"[语音] 3″", time:"21:14"},
      {f:"them", x:"明天团综报道，别迟到的又是你。", time:"21:15"}
    ]},
    {t:"n", x:"九点半，江慕白拿起外套。他把那本册子夹在腋下，站起来的时候椅子几乎没有响——他做什么都没有多余的声音。转盘上那份文件还停在原处，谁都没碰。"},
    {t:"n", x:"窗外江面上过了一艘船，灯一排一排地走，走得比室内的说话声都慢。林墨轩不知什么时候站了起来，绕着桌子给每个人的杯子里续了一次水，续到沈时雨那里特意少倒了半杯，续完就坐回去，什么也没说。"},
    {t:"n", x:"走到门口他停了一下，没回头。包厢外的走廊灯是白的，把他的影子拉得很长，一直伸回圆桌这头。"},
    {t:"choice", prompt:"江慕白站在门口，还没走。你——", options:[
      {x:"起身送他到电梯口。", heart:{江慕白:2}, cb:"你送到电梯口，一路无话。电梯到了，他进门前说了一句：小队长，明天开始，我按团综导师的身份管你。门合上，那句话才慢慢落地。"},
      {x:"坐着举了举杯子，什么也不说。", heart:{江慕白:1, 温以恒:1}, cb:"你举起杯子。他从门缝里看了一眼，点了下头，走了。温以恒在旁边轻声说：江老师今天喝的是茶，一滴酒都没碰。"},
      {x:"问他团综第一个任务是什么。", heart:{江慕白:1, 陆清越:1}, cb:"他侧过脸，镜片反了一下光：明天你就知道。陆清越在你身后小声说队长哥哥你胆子好大，敢问江老师问题。"}
    ]},
    {t:"choice", prompt:"六个“下一程”摆在你面前，你——", options:[
      {x:"把六只酒杯一起碰响。", heart:{温以恒:1, 陆清越:1}, cb:"七只杯子撞在一起，清脆一声。陆清越笑得往后仰，温以恒伸手护住差点倒了的果盘，像护着这一屋子的暖。"},
      {x:"悄悄在心里，把六个人都记进下一程的名单。", heart:{沈时雨:1, 顾知遥:1}, cb:"你垂下眼，把七个名字在心里又念了一遍。顾知遥瞥见你唇角，哼了一声，却没移开目光，耳尖还是红的。"}
    ]},
    {t:"n", x:"包厢的灯很暖。窗外的江还在流，灯影在水里晃啊晃，像十二周的重量，终于舍得轻轻放下，托着七颗星，往下一程去。砂锅底下那点火终于熄了，汤面平静下来，映着七个低头夹菜的人。桌上那份文件始终没被翻开，明天的车票已经在节目组的群里发出来了。没有人急着说话，可每只杯子都还温着，每个名字都还在，故事才刚写到，漂流二字。"},
    {t:"end"}
  ]
});


// ===== ch25.js =====
// 第25章 入住漂流屋 —— 团综期开篇
window.STORY.push({
  id: "ch25",
  title: "第二十五章 · 入住漂流屋",
  phase: "团综",
  week: 13,
  nodes: [
    {t:"bg", v:"villa"},
    {t:"n", x:"庆功宴的香槟气泡还没从指尖散尽，大巴已经拐过沿海公路的最后一道弯。海风从半开的车窗灌进来，带着咸涩的凉意，把昨夜江慕白那句「担任团综导师」的尾音吹得忽远忽近。你靠着椅背，听见身侧苏景行把耳机摘下来，顺手塞了一只到你耳边，里面是他新写的、还没填词的旋律，像潮水一样一下一下漫过耳膜。这一路选秀期积下的紧绷，第一次在耳机里松了个结。"},
    {t:"n", x:"白色别墅卧在礁石与草坪之间，落地窗把整片海框成一面晃动的镜子。草坪被傍晚的潮气洇成深绿，几盏地灯已经亮了，在草叶上落下一小圈一小圈毛茸茸的暖黄。行李箱轮子碾过木板栈道，发出闷闷的咕噜声。苏景行把箱子往你脚边一靠，亚麻色发梢被风吹得乱翘：「漂流屋，不错嘛，比基地那间十人宿舍奢侈多了。」他说话时眼睛弯着，像真的松了口气。"},
    {t:"d", who:"江慕白", x:"「从今晚起，这里是你们未来十周的客厅、厨房与舞台。二十四小时直播开启，镜头无处不在——」他推了推细框眼镜，银白发丝在门廊灯下泛着冷光，「但我说过，该松弛的，还是要松弛。团综不是又一场考核，是让你们做回七个活生生的人。」", fx:"cool"},
    {t:"sys", x:"【节目组】团综《漂流季》第一夜任务发布：自行抽签分配四人房两间、双人房一间。分配结果将计入今夜的互动数据，不影响出道位。"},
    {t:"n", x:"签筒是木质的，被PD搁在餐厅长桌中央，七张折好的纸条露出整齐的纸沿，像一排等待被翻开的命运。长桌是老船木做的，纹路里还嵌着些看不分明的旧渍。温以恒把每个人的水杯摆正，杯壁凝着细密的水珠；他轻声问你还累不累，你摇头，指腹却无意识蹭了蹭行李箱拉杆上那道旧痕——那是选秀期一路拖出来的，磨得发亮。"},
    {t:"d", who:"陆清越", x:"「队长哥哥！抽签抽签！我紧张得手心都是汗——今天也要加油哦！」他举着两只手在你面前晃，金色短发在夕阳里像一小簇跳动的火，眼睛亮得几乎能反光，整个人恨不得原地转个圈。", fx:"smile"},
    {t:"choice", prompt:"签筒转到你面前。你要怎么抽？", options:[
      {x:"“闭着眼抽一支，顺其自然。”", heart:{温以恒:2, 陆清越:1}, cb:"你指尖捻起一张，没看名字就塞进口袋。温以恒弯了弯眼睛，把另一杯温水推到你手边，像早知道你会这么干，杯沿轻轻碰了碰你的手背。"},
      {x:"“把签筒往林墨轩那边推了推，示意他先抽。”", heart:{林墨轩:3, 沈时雨:1}, cb:"林墨轩抬眼看了你一下，抽出一张，纸上只写了两个字：和你。他没说话，把签扣在桌面，指节在木纹上敲了一下，算是应了，黑眸里有一丝极淡的动容。"},
      {x:"“在苏景行的签上停了一瞬，还是抽了别人。”", heart:{苏景行:2, 顾知遥:1}, cb:"苏景行挑眉，懒洋洋凑近：「我们队长，心虚了？」顾知遥在旁边哼了一声，把脸扭向窗外，银灰色的发丝却翘了一下，泄露了点好奇。"}
    ]},
    {t:"n", x:"纸签摊开，结果落定。你被分到的那一间朝海，窗下能听见潮水一下一下拍着礁石，节奏慢得让人想叹气。床是铺好的，米白色的被子叠成方正的一块，枕头上搁着节目组手写的欢迎卡，字迹歪歪扭扭，像怕显得太正式。窗外海面浮着远处渔火的几点橘红，被浪推得轻轻晃。摄像头在吊灯旁无声地亮着小红点，像一只不肯合眼的眼睛，把这一屋子的初来乍到都收了进去。"},
    {t:"d", who:"沈时雨", x:"「队长哥……这个房子，好大。」他抱着自己的枕头站在走廊，声音比平时还低，身形在暖光里显得更薄，像怕占太多地方，「我、我有点不敢一个人睡走廊尽头那间。灯关了，会不会太静。」他攥着枕头边的布偶角——那是他从不离身的旧物，被洗得发白，边角磨出了毛，「队长哥，你那间……还有空位吗。」", fx:"shy"},
    {t:"n", x:"你这才注意到，别墅的灯光是暖黄色的，落在每个人肩上都镀了一层毛边。选秀期那种绷紧的、随时要计算顺位与镜头得失的空气，在这里被海风吹散了大半。连王腾式的敌意都暂时搁在了岸上，只剩下七个人和一间会呼吸的房子。甚至连空气都软了，软得能兜住每个人藏了一路的疲惫，不让它漏出来硌着谁。"},
    {t:"n", x:"走廊尽头的窗对着海，夜色把浪声滤得很远，远得像另一个赛季的事。你站在窗前，看玻璃上自己的影子叠进沉沉的海里。成为队长这几个月，你第一次不必在睡前复盘谁的排名掉了、谁的状态虚了——今晚，只是住进来。"},
    {t:"phone", who:"苏景行", msgs:[
      {f:"them", x:"[漂流屋信号还行嘛]", time:"19:02"},
      {f:"them", x:"小队长，晚上别又躲去改流程表，镜头都看着呢", time:"19:02"},
      {f:"me", x:"知道，今天不躲。"},
      {f:"them", x:"乖。窗边那台望远镜归我，给你留了位置", time:"19:03"},
      {f:"them", x:"等会儿上来，带你认星星", time:"19:04"}
    ]},
    {t:"n", x:"晚饭时间，冰箱上贴着节目组的便签：今夜第一餐，自己解决。厨房是开放式的中岛，大理石台面凉津津的，刀架里的刀排得整齐。顾知遥已经挽起袖子，银灰色头发在厨房灯下泛着冷光，一副少爷下厨的架势。他拉开料理台抽屉的样子，像在巡视自家私厨，挑剔地皱了皱鼻尖。"},
    {t:"d", who:"顾知遥", x:"「队长大人，你行不行啊？本少爷今天露一手，让你们见识见识什么叫高阶料理。」他拎起一把锅铲，摆出红衣卡面上那副精致又矜持的表情，耳尖却因为跃跃欲试红了一点点，嘴上还要端着，「看好了，别说是我教你们的。」", fx:"cool"},
    {t:"n", x:"三十分钟后，厨房飘出的不是香气，是一缕固执的焦糊味，像有人把黄昏整个煎糊了。平底锅里那团黑乎乎的东西分不清是肉还是蔬菜，边缘还冒着细烟，咕滋咕滋地响。温以恒站在门口，眉心慢慢拧成了一个结，又松开，像习惯了替所有人兜底。"},
    {t:"choice", prompt:"焦味漫开。你要怎么接？", options:[
      {x:"“挽起袖子，接过锅铲。”", heart:{温以恒:2, 顾知遥:1}, cb:"你关了火，把那团黑物倒进垃圾桶。顾知遥别过脸：「哼，才不是为你，是这锅不行。」可他没把锅铲收回去，任你握着，指尖在铲柄上松了又紧。"},
      {x:"“笑着拍拍他肩：下次，下次一定行。”", heart:{顾知遥:2, 陆清越:1}, cb:"顾知遥耳尖动了动，把锅铲往你手里一塞：「本少爷批准你接手了，别得意。」陆清越在旁边拍手，差点打翻盐罐，被温以恒一把扶住。"},
      {x:"“回头喊温以恒：以恒哥，辛苦你救场。”", heart:{温以恒:3, 沈时雨:1}, cb:"温以恒无奈地笑起来，系上围裙：「早该叫我了。」沈时雨在旁边悄悄松了口气，把抱着枕头的两臂放了下来，肩膀塌下一点点。"}
    ]},
    {t:"n", x:"温以恒的汤锅很快咕嘟起来，是整个漂流屋第一个像样的气味，白雾顺着锅沿爬上他的下颌，又散进暖黄的灯里。陆清越搬来矮凳围在岛台边，晃着腿背儿歌；沈时雨破天荒伸手帮着剥蒜，指尖碰到你手背时顿了半秒，才慢慢缩回去，像怕惊扰什么，又舍不得真的收回。剥好的蒜瓣在他掌心排成整齐的一小列，像某种笨拙的、不肯说出口的靠近。"},
    {t:"d", who:"苏景行", x:"「看，还是我们队长镇场。」他倚着门框，把一颗剥好的虾递到你嘴边，又在你瞪过来之前自己吃了，「逗你的。江老师说得对，该松弛——今晚这屋子，像家，不像战场。」", fx:"smile"},
    {t:"m", x:"海风、热汤，还有七个人挤在一间厨房里的吵闹。原来所谓团综，是把日子过给我们自己看，不是过给名次看。紧了那么久的弦，今晚肯松一松。"},
    {t:"n", x:"饭后的岛台边堆着碗，谁也没急着收，任由那点人间烟火多留一会儿。你帮顾知遥冲了冲烫红的指尖，他嘴上说「本少爷才不需要」，却没抽手。陆清越趴在温以恒肩上讲今天第几次想家，被揉了揉金色的脑袋。这一刻的松弛，是选秀期谁都不敢奢望的。"},
    {t:"n", x:"深夜，导播间的 monitor 墙亮着七块画面，海浪声从某块屏里漏出来，又被人声盖过。江慕白端着杯没动过的茶，目光停在你那一格——你正低头，把顾知遥烫到的指尖轻轻拢进掌心吹气。他放下茶杯，在记录本上写了一行，想了想，又划掉了。笔尖在纸面停了很久，像在和一个念头较劲。"},
    {t:"end"}
  ]
});


// ===== ch26.js =====
// 第26章 泳池挑战赛 —— 湿身名场面
window.STORY.push({
  id: "ch26",
  title: "第二十六章 · 泳池挑战赛",
  phase: "团综",
  week: 13,
  nodes: [
    {t:"bg", v:"pool"},
    {t:"n", x:"昨夜导播间那面 monitor 墙的灯，好像刚熄不久又被人按亮了。江慕白是最后收工的那个，走时把记录本压在茶杯底下，杯口留下一圈凉透的茶渍。你睡得不深，梦里全是潮水的节拍。清晨六点半，海雾顺着落地窗的缝隙漫进来，把走廊的木地板洇出一层薄薄的水汽。你换上训练服下楼，泳池的水面在雾里平得像一块没说出口的承诺。"},
    {t:"n", x:"氯水的清冽气味先一步撞上来，混着海风里那点咸腥，凉丝丝地往鼻腔深处钻。池边的瓷砖被晨光刷得发白，隔着一层雾也能晃眼；节目组的彩色浮板和一排计分牌立在塑胶架里，红蓝两色的号码牌还留着上一档节目蹭掉的一小块漆。陆清越已经趴在池沿上，用脚尖一下一下点水，金色的头发在晨光里毛茸茸地翘着，每点一下水面就小声数一个数，数到七就忘，又从一重新开始。"},
    {t:"n", x:"江慕白坐在岸边的白阳伞下，银白发丝被风掀起一小缕，又被他不紧不慢地按回去。他膝上摊着今天的分组表，纸角压着一支钢笔，像在等一场早就写好的开场。他没有抬头，只把表翻过一页。"},
    {t:"d", who:"江慕白", x:"「团综第二课：在水里，没有人能端着。水上分组对抗，三局两胜——输的一队，今晚刷碗。」他抬眼，灰眸里有一丝几乎看不见的笑意，「我也好奇，你们脱了紧绷感之后，是什么样子。」", fx:"cool"},
    {t:"n", x:"七个人陆续换好衣服在池边集合。苏景行一身松垮的黑背心，袖口卷到肩头，亚麻色的头发随手扎成个小揪；林墨轩是整套素色，肩上搭着一条叠得方正的灰毛巾，站在水边像一截被潮水磨圆的石头；顾知遥全副武装，鼻梁上架着墨镜，手臂涂了厚厚一层防晒霜，凑近了能闻见那股清苦的椰香；沈时雨把长袖防晒衣的拉链一路拉到下巴，袖口攥进掌心；陆清越套着一对印了小黄鸭的充气臂圈，转着圈问每个人好不好看；温以恒先把保温壶放在躺椅边，再绕场走了一圈，把每个人脚边的拖鞋摆正。"},
    {t:"sys", x:"【节目组】泳池挑战赛分组抽签：红队（队长、温以恒、顾知遥）对阵蓝队（苏景行、林墨轩、沈时雨、陆清越）。第一局：合力运浮板。"},
    {t:"n", x:"名单念完，池边的空气先动了一下。顾知遥把墨镜往下拉了半寸，从镜片上方扫了苏景行一眼，像在清点家底；苏景行单手把浮板拎起来转了个圈，懒洋洋朝红队这边扬了扬下巴：「以恒哥，你们这队，有点轻啊。」温以恒笑着没接话，只把你肩上的毛巾角往里掖了掖。陆清越已经开始和沈时雨击掌，拍空两次，第三次才拍响，响声在瓷砖上弹了两下。"},
    {t:"choice", prompt:"第一局的哨子还含在裁判嘴里。浮板只有一块，两个人扛。你伸手——", options:[
      {x:"「和苏景行并排，浮板扛在两人肩上。」", heart:{苏景行:3, 陆清越:1}, cb:"苏景行挑眉，懒洋洋把浮板另一头接过去：「我们队长终于不躲我了？」两人一高一低地踩进水里，膝弯以下立刻被凉意咬住，水花溅起来，把袖口洇成两片深色。岸上陆清越喊了声加油，回音撞在池壁上，又弹回来。"},
      {x:"「和林墨轩一组，听他报节奏。」", heart:{林墨轩:3, 沈时雨:1}, cb:"林墨轩点头，把浮板稳稳托平，毛巾往肩上一甩：「听我数。一、二、起。」他的声音在水面上异常清楚，像给整池子定了拍。你跟着他的音节抬脚落步，水波顺着板沿一层层荡开，池面第一次安静得只剩他数数的声音。"},
      {x:"「把温以恒拉在身侧，让他兜底。」", heart:{温以恒:3, 顾知遥:1}, cb:"温以恒笑起来，把你的手腕轻轻扶稳：「交给我，慢点走。」他的掌心是干的、温的，隔着一层水汽也稳。顾知遥在旁边哼道「以恒哥偏心」，却悄悄把浮板往你们这边推了半寸，推完立刻扭头去看计分牌，那半寸仿佛和他毫无关系。"}
    ]},
    {t:"n", x:"哨声落进水里。浮板被举过头顶的时候，水沿着板沿哗哗地往下淌，落回池面又溅起一串碎白。红队这边节拍稳，蓝队那边起步快——苏景行一个人顶了两个人的力，肩胛骨绷出清晰的弧线；林墨轩压着步子贴在他身侧，只在过中线时低声说了半句往左半寸。陆清越把浮板举得几乎要碰到天，臂圈上的小黄鸭一浮一沉；沈时雨攥着板沿的指节泛白，脚尖在水下踩不到底，整个人像被水托着，又被水追着。"},
    {t:"n", x:"浮板刚运过半程，苏景行忽然从侧后方探手，勾住你的手腕，往池心轻轻一带。世界翻了个面。凉意从锁骨一路漫到脚踝，水灌进耳廓的那一瞬，池边的喧闹被按了静音，只剩他落在水面上的那声笑，隔着水传过来，闷闷的，很近。你再浮上来时，头发全贴在脸侧，水珠顺着睫毛一颗一颗往下坠，训练服洇出深色的轮廓，黏在背上，凉得你打了个哆嗦。阳光在晃动的池面上碎成一片一片，晃得人睁不开眼。"},
    {t:"danmaku", items:[
      "苏苏的小甜饼🍪|景行哥你故意的吧哈哈",
      "队长冲鸭🚀|这水花也太突然了",
      "星蓝后援会|湿发队长我可以",
      "墨子yyds|墨轩哥在水里也好稳",
      "小遥遥守护者|知遥少爷别嘴硬了",
      "时雨的小太阳☀|时雨终于下水了呜呜",
      "清越号列车|队长哥哥笑得好甜"
    ]},
    {t:"d", who:"苏景行", x:"「现在，谁还躲流程表？」他懒洋洋地抹了把脸，水顺着下颌滴回池里，一滴一滴，正好落在你脚边的水面上，散开一圈一圈的印子。", fx:"laugh"},
    {t:"n", x:"你抬手把湿发往后捋，池水晃着两个人的影子，叠成一团晃动的暖。他没急着游开，就浮在你身侧半步远的地方，肩膀随着水波轻轻起伏，像怕你呛着，又像在等你开口说点什么。选秀期那层永远得体的壳，被水冲开了一道缝，缝里透进来的，是海风，是阳光，是此刻谁都不必计算的松弛。"},
    {t:"n", x:"岸边很快递来一片手忙脚乱。温以恒第一个蹲到池沿，把干毛巾抖开，一手一个地按住你和苏景行的后脑勺就擦，嘴里轻声念着慢点慢点；林墨轩弯腰拾起你被水冲歪的拖鞋，在池边摆正，鞋头朝着你的方向；顾知遥把墨镜往上一推，嘴上说着「本少爷才不救落水的队长」，手却把另一条毛巾丢到你脚边，落点精准得像提前量过；陆清越趴在池沿笑个不停；沈时雨站在最外圈，脚尖在瓷砖上蹭了两下，视线一直跟着你，等你转头看他，他立刻挪开眼，去盯计分牌上还空着的那一格。"},
    {t:"weibo", items:[
      "#星途泳池湿身名场面# 1.9亿",
      "#苏景行把队长拉下水# 1.1亿",
      "#沈时雨第一次玩水# 7600万",
      "#漂流屋泳池挑战赛# 5300万",
      "#队长湿发好绝# 4200万",
      "#有人说剧本感强# 2900万",
      "#江慕白泳池旁看monitor# 1800万"
    ]},
    {t:"n", x:"热搜在手机里一条条往上顶的时候，岸上的欢呼还没停。顾知遥把湿透的银发往后捋，嘴里嫌弃「本少爷才不玩这种幼稚项目」，身体却诚实地往沈时雨那边靠了半步，像随时准备伸手兜住那个还在屏息的背影。沈时雨没察觉，只把防晒衣的下摆拧了又拧，水从衣角滴成一小串。连江慕白都从记录本上抬起眼，看了这池子很久，钢笔悬在纸面上方，一个字也没落下去。"},
    {t:"n", x:"计分牌上的数字被谁翻过一格，又被海风翻回去。午后的光斜斜地压过来，把池水照成一层流动的琥珀色，热气从瓷砖上升起。水池另一头反倒安静得反常。沈时雨一个人挪到池子最窄的那一侧，两手抱着池边的金属栏杆，脚尖堪堪点在瓷砖边缘，身子往后仰成一道绷紧的弧。他嘴唇动了动，没出声。你认得那种僵——是怕，是水底下某种说不清的旧东西，把他钉在了岸上。"},
    {t:"d", who:"温以恒", x:"「时雨，你看我。」他蹲到沈时雨身边，声音轻得像怕惊飞什么，「水不深，到我腰这里。你以恒哥先下去，你只要伸手，我接着。来，慢慢来，不急。」他伸出手，掌心朝上，等在那里，连指尖都不曾晃一下。", fx:"smile"},
    {t:"n", x:"陆清越也蹭过来，膝盖在瓷砖上磕了一下也不喊疼，把一颗捡来的小贝壳塞进沈时雨手里。贝壳被海水泡得发白，边缘有一道细小的裂口：「时雨哥，这是魔法贝壳！握着它就不怕了。队长哥哥说过的，今天也要加油！」沈时雨低头看着掌心那枚贝壳，指节慢慢松了，又攥紧，像在跟自己商量。"},
    {t:"n", x:"栏杆上被握出一层薄薄的水痕。沈时雨的呼吸很浅，胸口几乎看不出起伏，你数了三下，才等到他吸进第四口气。他身后的影子被午后斜光拉得很长，一直伸到水边，像有半个人已经先替他把脚探了进去。"},
    {t:"choice", prompt:"沈时雨还悬在岸边，脚尖离水只有半寸。你要怎么做？", options:[
      {x:"「也蹲下来，和他平视：我们陪你。」", heart:{沈时雨:3, 温以恒:1}, cb:"你蹲到温以恒另一侧，和他视线齐平。瓷砖的凉透过裤缝往上爬，你也不动。沈时雨吸了口气，把那枚贝壳握紧，脚尖终于离开瓷砖：「队长哥……那、我下来了。」"},
      {x:"「向温以恒递个眼神：你带，我在此刻守着。」", heart:{温以恒:2, 沈时雨:2}, cb:"温以恒接住你的眼神，反手握了握沈时雨的手腕：「看，队长在呢。」沈时雨闭上眼，往水里探了半步，水漫过小腿时整个人抖了一下，膝盖弯了弯，终究没有退回去。"},
      {x:"「回头喊陆清越：再讲个笑话给他听。」", heart:{陆清越:3, 沈时雨:1}, cb:"陆清越立刻举起两只手：「时雨哥！为什么星星不游泳？因为——它们在天上漂！」沈时雨肩膀一抖，居然漏出一点笑，顺着那点笑，脚尖滑进了水里，水花小得几乎听不见。"}
    ]},
    {t:"n", x:"沈时雨整个人落进温以恒臂弯的那一刻，水花很小，却像替他卸下了一块背了很久的石头。他呛了一下，被温以恒稳稳托住，睫毛上挂着的不是害怕，是亮晶晶的、还没来得及命名的轻松。池子那头，连林墨轩都停下了划水的手，看了他一眼。岸边有人轻轻鼓了掌——是林墨轩，他朝沈时雨极轻地点了下头。那一点肯定，比任何喝彩都重，主唱从不轻易把目光给谁。"},
    {t:"d", who:"林墨轩", x:"「时雨，入水别屏气。先呼气，再抬头。」他站在池边，毛巾搭在肩上，语气平得像在念谱号，「明天继续。」", fx:"neutral"},
    {t:"d", who:"苏景行", x:"「看，我们小主舞也会玩水了。」他远远朝沈时雨比了个OK，又朝你挤眼，「队长，今天这池子，值了。」水珠从他发梢甩出来，在阳光里划出一道小小的虹。他浮在你身侧没游开，像怕你呛着——嘴上从没说过，动作却比谁都近。", fx:"laugh"},
    {t:"d", who:"沈时雨", x:"「队长哥……谢谢你陪我。」他把那枚贝壳攥在湿透的手心里，声音低得几乎被水声吃掉，说完飞快垂下眼，像怕这句话太重，会砸到谁。", fx:"shy"},
    {t:"d", who:"顾知遥", x:"「本少爷勉强承认，这池子今天，不算太幼稚。」他叉着腰站在池边，银发湿成一缕一缕，下巴还抬高半寸，说完自己先别开了脸，弯腰去把被风吹倒的防晒霜瓶子一只只扶正。", fx:"cool"},
    {t:"m", x:"原来让人靠近光，不一定是把他推上去，也可以是陪他，先愿意湿了脚。而今天湿了脚的，又何止时雨一个——连你自己，也被苏景行那一拽，从队长的高台上，拽回了人间。"},
    {t:"sys", x:"【节目组】泳池挑战赛结束，三局两胜已判定。败方今晚负责漂流屋的碗筷——七人份，一只都不能少。"},
    {t:"n", x:"计分牌最后停在哪个数字，后来谁也没再去翻。倒是陆清越第一个想起要算账，掰着手指头数七个人的餐具，数到一半忘了数到哪，被温以恒笑着揽走了。沈时雨跟着众人往屋里走，走了两步又回头，看了一眼那片已经把夕阳泡软的水面，才小跑着追上来。"},
    {t:"n", x:"天光沉到海平面以下之前，导播间里开始过今天一整天的素材。江慕白停在午后那一格——画面里你正把沈时雨湿透的刘海往后捋，动作自然得像做过千百遍。他端起凉透的茶，在记录本上写：敢把壳交给水的人，才扛得住更大的舞台。写完，他顿了顿，又补了一行：这孩子，比我以为的更像队长。他把笔帽扣上，把这一格往回拖了三次，第三次停在同一个画面上——你蹲在池边，拧着沈时雨的衣角帮他挤水，两个人低着头，谁也没看镜头。江慕白唇角弯了弯，那一点笑，落进没人看见的 monitor 反光里。直播的红灯还亮着，把这一池子的笑，原原本本收进了今晚的正片素材。"},
    {t:"end"}
  ]
});


// ===== ch27.js =====
// 第27章 花园迷宫 —— 专属糖点章
window.STORY.push({
  id: "ch27",
  title: "第二十七章 · 花园迷宫",
  phase: "团综",
  week: 14,
  nodes: [
    {t:"bg", v:"garden"},
    {t:"n", x:"泳池那天的笑还没凉透，漂流屋后山的花园就接过了接力。第二周的地图翻到了新的一页，清晨的雾从花丛里升起来，一层一层往上爬，把整座迷宫染成半透明的绿。你踩着碎石小径往里走，鞋底碾过落瓣，发出细碎的、像谁在远处鼓掌的声响。海风被山挡了一程，到这里只剩下甜软的草木气，混着露水的凉，贴在皮肤上。"},
    {t:"n", x:"迷宫的墙是齐肩的常绿 hedge，被修得方方正正，顶端却故意留了些乱翘的枝，像在跟规矩开玩笑。阳光从叶缝漏下来，在地上铺了一地晃动的碎金。空气里混着蔷薇、湿泥，还有一点被太阳晒暖的薄荷味。蜜蜂在你耳侧绕了半圈又飞走，翅膀的声音细细的。江慕白站在迷宫入口的石柱旁，银白发丝被风掀起一点，膝上照旧压着那本记录本，像在等这场早已写进流程的迷路。"},
    {t:"d", who:"江慕白", x:"「团综第三课：在迷宫里，你会看清自己想牵着谁的手。寻宝任务，两两组队，找到中心许愿池的人，各实现一个小愿望。」他顿了顿，镜片后的灰眸扫过你们每个人的脸，「镜头会跟着你们——包括你们以为没人的时候。」", fx:"cool"},
    {t:"n", x:"陆清越第一个冲进迷宫，金色头发在绿影里一闪就不见了，远远传来他「今天也要加油哦」的喊声，撞在 hedge 上又弹回来，像迷宫自己在替他鼓劲。其余人三三两两散开，脚步声在墙与墙之间叠成好听的回响，像一封信，被拆成了七段，又终将拼回同一句。沈时雨走在最后，手里攥着一小截白粉笔，走在人后的时候，脚步反而比谁都稳。"},
    {t:"sys", x:"【节目组】花园迷宫寻宝：七人两两组队（一人落单由PD补位），沿途藏有线索卡，中心许愿池为终点。配对结果计入今夜互动数据。"},
    {t:"n", x:"成员们安静了一瞬，目光却不约而同往你这边飘。苏景行把胳膊懒洋洋搭上你肩：「我们队长，今天归我？」林墨轩没说话，只把一张折好的纸在指间转了转，纸角已经磨得起了毛。温以恒笑了笑，把一颗苹果塞进你外套口袋，还顺手按了按，怕它硌着你。顾知遥哼了一声，把视线扭向迷宫深处，耳尖却诚实地红了一小块——谁都想和你一组，又谁都不肯先把那句话说出来。"},
    {t:"choice", prompt:"分组哨响了。你要和谁一组？", options:[
      {x:"「伸手挽住苏景行：竹马优先。」", heart:{苏景行:4, 陆清越:1}, cb:"苏景行把你往怀里带了带，懒洋洋念了句旧巷口的童谣：「小时候你走丢，我也是这么把你领回来的。」迷宫的墙把外面隔成另一个世界，他忽然压低了声音，「这次换我，怕你再走丢。」"},
      {x:"「走向林墨轩：跟他走，准没错。」", heart:{林墨轩:4, 沈时雨:1}, cb:"林墨轩在岔路口停下，从口袋里抽出一张素描——是你刚才低头看地图的侧脸，铅笔印还很新，纸背透着光。他把纸折好塞进你手心：「路会迷，人不会。记着这个，别慌。」"},
      {x:"「拉过温以恒：以恒哥，带我。」", heart:{温以恒:4, 顾知遥:1}, cb:"温以恒把外套披你肩上，怕你被 hedge 缝里钻出来的风激着：「迷宫再绕，也有出口。饿了我带了苹果，随时说。」他替你把被枝桠勾住的发丝理好，指尖绕着发梢迟了半拍才松开。"},
      {x:"「朝顾知遥挑眉：本少爷，带路？」", heart:{顾知遥:4, 苏景行:1}, cb:"顾知遥哼了一声「勉强陪你」，却把一张手绘的迷宫捷径图塞你手里，边角还印着他的小皇冠：「过时不候啊，队长大人。」他走在你外侧，把有风的那一边，悄悄留给了自己。"}
    ]},
    {t:"n", x:"你们并肩钻进第一条岔路。hedge 把风滤得很软，绿影在你们肩上慢慢淌。石板路上有些地方积着薄薄的水，踩下去会轻轻溅起一点泥点，落在鞋帮上。你忽然发觉，和谁走这件事本身，比找到出口更让人安心——迷宫把外界的喧嚣关在墙外，只剩两个人的脚步，一声一声，踩着同一种节奏。"},
    {t:"n", x:"第二道弯口立着一根木牌，上面别着一张折起的线索卡，纸边被露水泡软了。你把卡展开，上面只写着四个字：听见水声。木牌旁边留着别人的手印，几个大小不一，看得出有人在这儿停过很久。"},
    {t:"sys", x:"【节目组】线索卡提示：中心许愿池的水声在午后最清。请各小组把握节奏，直播信号全程开启。"},
    {t:"n", x:"拐过墙角的瞬间，一道喊声从 hedge 那头劈过来，枝叶被震得抖了一下。那声音离得很近，又隔着一整排灌木，像隔了一整个季节。"},
    {t:"d", who:"陆清越", x:"「队长哥哥！这边是死路——不对不对，那边也是死路！我找到三条死路啦，我是不是很厉害！」他的声音兴高采烈，尾音上扬，显然完全不觉得迷路有什么不对。", fx:"laugh"},
    {t:"n", x:"你身边的搭档没忍住，肩膀轻轻动了一下。再往前，过第三道弯时，你看见了挂在枝桠上的一小段白线——是粉笔。箭头画得极工整，横平竖直，像用尺子量过，旁边还标了个小小的叉，标在一条走不通的路上。粉笔头就搁在墙根，被苔藓蹭白了一小角。"},
    {t:"d", who:"沈时雨", x:"「队长哥……左边那条，我走过，绕回去的。」他从两道 hedge 的缝隙里探出半张脸，声音低得几乎被叶子吃掉，说完又缩了回去，「我在后面把路都画上了……你们跟着白线走就行。」", fx:"shy"},
    {t:"n", x:"你身边那个人忽然放慢了脚步，把领路的那一侧让给你，自己退到风口。你没回头，却听见衣料摩擦的轻响，和一声很轻的、几乎被风吃掉的笑——这一刻的糖，不用名字，也甜。hedge 的影子在肩上淌过去，像某种只属于这条岔路的、不肯说破的偏爱。"},
    {t:"diary", who:"沈时雨", date:"第14周 周四 晴（但迷宫里没有太阳）", x:"今天分队，我把手举了又放。我想和队长一组，可我怕拖慢他。最后他选了别人，我蹲在岔路口帮大家记路线，用粉笔画了小小的箭头。其实我来这里，最怕的不是迷路，是怕自己永远只能站在光外面。可队长每次低头看我，都像在说：你在，就好。许愿池边我没敢许太大的愿，就许：明年这个时候，我还站得够稳，能替他挡一次风。不求他看见，只求他平安。如果这段被拍到，请别剪掉我脸红的那秒。"},
    {t:"n", x:"绕过第三道弯，绿意忽然豁开。中心是一方小小的许愿池，水面沉着几枚硬币和不知谁丢的幸运扣，被阳光照得像撒了一把碎钻。池边围着一圈野蔷薇，花瓣落进水里，打着旋，慢得让人想停下所有事，就为了看它沉。石砌的池沿被水汽养出一层滑腻的苔，摸上去凉得让人清醒。"},
    {t:"n", x:"你俯身，池水映出你和自己身后的绿影。心里那句话，没说出口——大概是希望今天组队的那个人，别嫌你走得太慢；或者，更贪心一点，希望七个人能一直这样，在同一个院子里迷路，又总能找到彼此。风把这句话吹散了，只有水知道。你没敢说出口的那部分，其实比说出来的更重，重得连蔷薇落进去都没溅起声。"},
    {t:"choice", prompt:"低头许愿时，藤架里红灯一闪——是隐藏摄像机。你要？", options:[
      {x:"「装作没看见，继续弯腰许愿。」", heart:{江慕白:1, 陆清越:1}, cb:"你垂下眼，指尖在池沿停了停。镜头忠实地记下了你睫毛的弧度，和那点没说出口的从容——像早知道会被看。"},
      {x:"「回头，对着镜头比了个轻轻的OK。」", heart:{江慕白:2, 陆清越:1}, cb:"红灯闪了一下，像在回应你。导播间的 monitor 前，江慕白挑了挑眉：这孩子，开始懂镜头了，也懂怎么把真心藏进一个手势里。"},
      {x:"「下意识低头，把愿望捂进掌心。」", heart:{江慕白:1, 沈时雨:1}, cb:"你把手拢紧，像护着什么易碎的。那点慌乱被镜头收得清清楚楚——以后这段怎么剪，由不得你，只由那一秒的表情决定。"}
    ]},
    {t:"n", x:"你没注意到，许愿池上方的藤架里，藏着一个不眨眼的镜头。它把你的侧脸、你拢着池水的手、你那句没说全的愿望，原原本本收了进去。导播间的硬盘亮了一下，像在悄悄记笔记。这段素材，会在正片里怎么剪？是剪成「队长的小心愿」，还是剪成「某人眼神里藏不住的东西」？没人告诉你。你只记得池水很凉，愿望很轻，而某个镜头，比你自己更先记住了这一秒。"},
    {t:"m", x:"迷宫教人的，从来不是怎么走出去，是走出去时，你愿意伸手牵的那只手，是谁的。"},
    {t:"n", x:"傍晚收队，七个人在出口处重新聚齐。影子被夕阳拉得又细又长，交叠在碎石路上。谁都多了点没说破的、属于自己那一条岔路的心事。陆清越的膝盖上沾着泥，温以恒蹲下来给他拍，拍了两下没拍干净，索性把湿巾掏出来擦。林墨轩把一张折了又折的谱纸按平，收进口袋。沈时雨站在最边上，粉笔已经用完了一整截。"},
    {t:"d", who:"顾知遥", x:"「本少爷走了整整两个小时，一条近路都没用上。」他把手里那张纸折了又折，最后还是放轻了力道，塞回外套内袋，「……明天换双鞋。」", fx:"shy"},
    {t:"d", who:"苏景行", x:"「诶，谁在池子里丢了硬币？」他摊开手掌，掌心躺着两枚被水泡暗的硬币，边缘都磨圆了，「我替你们收着，将来谁先红，谁来赎。」", fx:"laugh"},
    {t:"d", who:"温以恒", x:"「都饿了吧。」他把兜里的苹果挨个分出去，分到最后自己手里空了，才笑着拍了拍掌，「回去我煮点面，谁想要荷包蛋的，举个手。」", fx:"smile"},
    {t:"d", who:"林墨轩", x:"「白线画得准。」他走过沈时雨身边时停了一步，语气还是那样平，「下次画在岔口内侧，不容易被风磨掉。」", fx:"neutral"},
    {t:"n", x:"沈时雨愣了两秒才反应过来这是在跟他说话，喉咙动了一下，把粉笔头攥进掌心，像攥住了一件很要紧的东西，用力点了点头。江慕白合上记录本，目光在你和那扇藏着镜头的藤架之间停了一瞬，唇角浮起一点极淡的、近乎腹黑的笑。他大概，已经想好了这段要怎么用。"},
    {t:"end"}
  ]
});


// ===== ch28.js =====
// 第28章 粉丝见面会 —— 星蓝揭晓
window.STORY.push({
  id: "ch28",
  title: "第二十八章 · 粉丝见面会",
  phase: "团综",
  week: 14,
  nodes: [
    {t:"bg", v:"stage"},
    {t:"n", x:"迷宫那天的蔷薇瓣好像还粘在鞋底，风一吹就想起许愿池的凉。三天后，天光换了一种颜色——黄昏的金把海面烧成一片橘，然后慢慢退成灰蓝。你们从漂流屋出发的时候，沈时雨把掌心那颗魔法贝壳留在了房间里，说是重要场合不该带着它分心。车开到山脚下，人声就先到了。"},
    {t:"n", x:"环形剧场外的草坪已经支起一排应援棚，蓝色的小旗在风里翻飞，像一片提前到来的海。空气里有海水的咸、人群的汗、还有远处烤棉花糖摊子飘来的焦甜。有女孩举着自制的灯牌站在隔离带外，灯还没亮，手臂却已经酸得换了好几次姿势，仍然没肯放下。你从车窗望出去，她们忽然一起转头，声浪隔着玻璃撞进来，闷闷的，很响。"},
    {t:"n", x:"你站在后台帘缝里往外看，陆清越正扒着幕布数星星灯，数到一半就忘了数，被温以恒笑着按回座位，还顺手把他翘起来的领子抹平。苏景行的琴箱靠在脚边，他坐着调音，手指拨过一根弦，声音很轻，帘外的人浪却刚好把这一声盖了过去。"},
    {t:"n", x:"户外舞台是环形的，木质台面被夕阳晒得温温的，脚踩上去有轻微的弹性，边缘绕着一圈暖白的小灯，还没点亮。风从海面过来，绕过音响的支架，把谱架上的一张纸掀得哗啦响。这是成团之后第一场面对面的见面会——不是比赛，没有顺位，只有七个人，和台下那一片等了很久的人。江慕白坐在台侧的导播位，银白发丝在灯下泛着冷光，像这场温柔里唯一的、不动声色的标尺。"},
    {t:"sys", x:"【节目组】应援色揭晓仪式即将开始。Stellar Drift 官方应援色：星蓝（Stellar Blue）。请全体粉丝点亮应援灯。"},
    {t:"n", x:"倒数的三秒里，整个草坪安静得能听见旗子拍在杆上的声音。然后灯暗下去。大屏亮起一片渐变的蓝——从黎明的雾蓝，到深夜的星蓝，一层一层往上漫，像把一整段从练习生到出道的夜，都凝进了一种颜色里。那是属于你们的应援色，叫「星蓝」。台下瞬间举起一片蓝色的灯海，光在风里晃，晃出细密的波纹，像把整片海搬进了夜里的环形剧场，也像无数双眼睛，终于认出了你们。"},
    {t:"danmaku", items:[
      "星蓝后援会|星蓝！是我们家的颜色！",
      "队长冲鸭🚀|应援色好温柔啊",
      "苏苏的小甜饼🍪|景行哥眼睛亮了",
      "墨子yyds|墨轩哥今天绝了",
      "小遥遥守护者|知遥少爷耳朵红了",
      "时雨的小太阳☀|时雨今天站得稳",
      "清越号列车|队长哥哥最感谢谁呀"
    ]},
    {t:"n", x:"首演的歌是成团曲《Drift》的 acoustic 版，没有炸裂的灯效，只有木吉他、一具和声和一整片海风。苏景行抱琴坐在最前，懒洋洋扫弦，把副歌那句「我们漂着，也亮着」唱得像说给某一个人听；弦上偶尔滑过一个泛音，清得让台下的灯海跟着轻轻一荡。林墨轩的和声垫在底下，稳得像地基，一句不多，一句不少。沈时雨今天站得比任何一次彩排都直，顾知遥没抢镜，只在镜头切过来时把下巴抬高半寸。你站在中心，忽然觉得这半年所有的紧绷，都在这一片蓝里，被轻轻接住了。"},
    {t:"d", who:"陆清越", x:"「队长哥哥！台下有粉丝姐姐举牌问你——」他踮起脚，把一张手写的牌子举到你眼前，字迹歪歪扭扭，被海风吹得发颤，「她问：出道这么久，你最感谢谁？」他眼睛亮得像那片灯海，显然自己也迫不及待想知道答案。", fx:"smile"},
    {t:"n", x:"台下的灯海忽然矮了半寸，像是所有人同时屏住了呼吸。话筒递到你嘴边的时候，你听见海风从耳廓上擦过去，听见吉他的尾音还在空气里慢慢散开，听见自己的心跳落在木台面上，钝钝的，很实。"},
    {t:"choice", prompt:"话筒递到你嘴边。你要怎么答？", options:[
      {x:"「最感谢一直陪我的竹马，苏景行。」", heart:{苏景行:4, 陆清越:1}, cb:"苏景行指尖一顿，琴声没断，眼睛却弯了起来：「我们队长，终于肯认了。」台下蓝光晃了晃，像替你们鼓掌。他没看你，耳根却红了一小块——这是竹马才有的、藏不住的默契。"},
      {x:"「最感谢永远兜底的以恒哥。」", heart:{温以恒:4, 沈时雨:1}, cb:"温以恒在旁边笑出声，把温水杯往你手边推了推：「小队长，这话我可记下了。」杯壁上凝着的水珠被他一推，滚下来，落在谱架脚边。沈时雨在另一侧悄悄低头，嘴角动了动——他记得，每一次被兜底的，也有他。"},
      {x:"「最感谢把我雕琢到现在的江老师。」", heart:{江慕白:4, 林墨轩:1}, cb:"台侧的江慕白挑了下眉，镜片后的灰眸掠过一丝极淡的、近乎满意的弧度：「璞玉，总要有人肯磨。」林墨轩垂眼，像是认同这句判词，指节在琴颈上轻轻敲了一下。"},
      {x:"「最感谢每一个不肯掉队的我们。」", heart:{陆清越:2, 顾知遥:2, 沈时雨:2, 林墨轩:1, 苏景行:1}, cb:"你环视一圈七张脸：「最感谢的，是每一个不肯掉队的我们。」顾知遥哼了声「本少爷才不要你谢」，却把应援灯举到了最高。蓝光里，七个人的影子叠在一处，像当初手叠手的那一下。"}
    ]},
    {t:"n", x:"话音落进风里，台下的蓝海忽然齐齐晃了一下，像有人带头，整片灯海轻轻起伏，一波接着一波，久久没停。你看见前排有个女孩把牌子翻过来，背面写着「你们七个人，都要好好的」。那行字被风吹得发颤，却稳稳地，落在每个人心上。"},
    {t:"n", x:"你话音落下时，身侧的六个人都没出声，只是各自把应援灯举高了一点。苏景行用肩膀碰了碰你，琴弦在他指下嗡了一声；林墨轩垂眼拨了下和弦，像在把这句感谢也收进和声里。顾知遥别过脸，却把灯举到了最高——这少爷的偏爱，从来都藏在动作里，不挂在嘴上。沈时雨把灯牌举到与肩齐平，站得笔直，灯光在他眼睛里晃出一小片蓝。"},
    {t:"d", who:"温以恒", x:"「小队长，这话既然说出口了，我就当是欠条。」他笑着，声音很轻，只够你听见，「往后你要是不肯多睡一会儿，我就拿着它来找你。」", fx:"smile"},
    {t:"d", who:"陆清越", x:"「队长哥哥！那我也要举到最高！我举得比知遥哥哥还高！」他把手臂绷得直直的，应援灯举过头顶，整个人因为用力而微微发抖。", fx:"laugh"},
    {t:"sys", x:"【节目组】安可环节倒计时：60 秒。请全体成员回到舞台中央，直播观看人数已突破本季纪录。"},
    {t:"choice", prompt:"安可的呼声起来了。你要——", options:[
      {x:"「朝身旁伸手，七个人一起鞠躬。」", heart:{温以恒:2, 苏景行:1, 陆清越:1}, cb:"温以恒第一个接住你的手，其余人一个接一个搭上来，七只手叠成当初成团夜那形状。台下的蓝海晃了晃，像被这一下戳中了泪点。"},
      {x:"「把话筒塞给陆清越：你来。」", heart:{陆清越:4, 温以恒:1}, cb:"陆清越瞪大眼睛，却真的喊出了「今天也要加油哦」——破音了，全场笑成一团。他脸红到耳根，却站得笔直，把忙内的那点天真，亮给了所有人看。"},
      {x:"「退后半步，喊出团名。」", heart:{苏景行:2, 林墨轩:1, 顾知遥:1}, cb:"你退后半步，把整片场子让给七个人：「Stellar Drift——」七道声音叠上来，盖过了风。顾知遥在旁边勾起嘴角，林墨轩的和声稳稳托住，像早排练过千百遍。"}
    ]},
    {t:"weibo", items:[
      "#星途粉丝见面会# 2.1亿",
      "#应援色星蓝# 1.4亿",
      "#队长最感谢谁# 9600万",
      "#StellarDrift户外首演# 7200万",
      "#沈时雨站C位稳了# 4100万",
      "#江慕白现身见面会# 2600万"
    ]},
    {t:"n", x:"散场时，最后一批粉丝被工作人员慢慢劝离，隔离带外还留着几盏没关的应援灯，蓝幽幽地亮在草地上，像退潮之后遗落的几颗星。江慕白在台侧把记录本翻到新的一页。他写下：星蓝，是七个人共同的夜。又停笔，补了一行更小的字：而队长，是让这七盏灯肯聚到一起的那阵风。风把页角掀起来，又被他轻轻按回去，像替这段日子，盖了个只有他自己知道的章。"},
    {t:"m", x:"原来被那么多人记着，不是负担，是有人替你把「你要好好的」说出了口。星蓝亮着，我们漂着，也亮着。"},
    {t:"n", x:"车开出剧场，应援灯的蓝还糊在视网膜上，闭眼也散不掉。顾知遥难得没闭眼假寐，望着窗外那片被夜涂黑的海，忽然说：「本少爷今天，没嫌吵。」苏景行在旁边笑：「那是因为，是你家的人。」顾知遥耳尖动了动，没反驳，只把手里那盏应援灯又举高了些，举了两秒，又像是嫌自己蠢，飞快放下。"},
    {t:"n", x:"回漂流屋的车上，陆清越靠着窗睡着了，手里还攥着那支应援灯，灯没关，把车窗玻璃映出一小块蓝。苏景行把外套盖在他肩上，又往你这边挪了半寸，没说话。海风从车窗灌进来，带着咸和甜，把这一天的蓝，轻轻吹进了下一个章节。团综还长，而七个人的夜，才刚刚亮起来。车灯划开夜色，七道呼吸在车厢里慢慢齐了拍，像又一首没写完的《Drift》。"},
    {t:"end"}
  ]
});


// ===== ch29.js =====
// 第二十九章 夜潮 —— 作者批次A
window.STORY.push({
  id: "ch29",
  title: "第二十九章 · 夜潮",
  phase: "团综",
  week: 15,
  nodes: [
    {t:"bg", v:"villa_night"},
    {t:"n", x:"见面会的回响还停在耳膜里。环形舞台上那一片星蓝，像被人打翻的夜空，晃得你有些睁不开眼。主持人最后问你的那句话——最感谢谁——你答得很慢，慢到话筒都安静了，慢到你自己听见了那片海。散场之后，音响被一个个推进箱子里，草地上只剩几盏忘了关的应援灯，还蓝盈盈地亮着。"},
    {t:"n", x:"大巴回漂流屋的路上，车窗外的路灯一盏一盏退后，把七个人的影子在车厢里轮流点亮又熄灭。陆清越靠着你肩膀睡着了，手里的应援棒还亮着，蓝光映在他睫毛上，随着车轮的颠簸轻轻晃。车厢里很静，只有温以恒在前排数着谁少了外套，数到最后发现都齐了，才把手里的毯子叠好放回膝上。"},
    {t:"d", who:"苏景行", x:"「小玩家，今天你那句最感谢他们，把江制作都逗笑了。」他靠在前排椅背上回头，声音压得很低，怕吵醒旁边睡着的人，「我认识他这么多年，他笑一次要记账的。」", fx:"smile"},
    {t:"n", x:"回到别墅时已过 midnight。客厅只留了一盏落地灯，光晕落在地毯上，暖得有点不真实。海风从半开的窗缝里钻进来，把窗帘吹得鼓一下、瘪一下，像有人在慢慢呼吸。温以恒说每人都该睡了，明天还有录制，可没人真的动，像都还泡在那片星蓝里没上岸。"},
    {t:"d", who:"温以恒", x:"「小队长，先喝点热的再睡，海风凉。」他把保温壶拧开，热气一下子涌出来，模糊了他半张脸。杯壁有点烫，他先在自己手背上试了一下，才递过来。", fx:"smile"},
    {t:"n", x:"你端着那杯热的东西站在走廊口。六扇房门缝里各自透出一点光，深浅不一：有的已经熄了，有的还亮着一条细缝。走廊尽头的窗对着海，夜色把浪声滤得很远，远得像另一个赛季的事。"},
    {t:"choice", prompt:"回房前，你停在那盏落地灯下。", options:[
      {x:"「再挨个看一眼大家的房间。」", heart:{温以恒:1, 沈时雨:1}, cb:"你轻轻推开每扇虚掩的门。沈时雨已经睡着了，手里还攥着耳机线，松了又紧，像梦里还在数拍子。顾知遥那间的床头灯没关，人却把脸埋进被子，只露出一撮银发。"},
      {x:"「今天到此为止，回房休息。」", heart:{顾知遥:1}, cb:"顾知遥从自己房间探出头，头发乱着，哼了一声：「队长大人，发什么呆，快去睡。」说完门就关上了，隔了两秒，又开了一条缝，确认你真的走了才合严。"}
    ]},
    {t:"n", x:"你躺下时，窗外的海声一阵一阵，像有谁在极远的地方反复掀动一张很厚的纸。别墅的安防系统绿灯常亮，嵌在门边的面板上，像一只半阖的眼，守着这一屋子的呼吸。枕头还留着白天晒过的太阳味，你以为这一夜会像别的夜一样，被海声哄睡。"},
    {t:"n", x:"凌晨两点十七分。一声短促的警报割裂了安静——不是火警，是周界的红外触发。面板上的指示灯由绿转红，红光在走廊尽头一跳，又灭，像有人拿指甲刮了一下黑夜的玻璃。紧接着是第二声，比第一声短，像被谁按住了嘴。"},
    {t:"sys", x:"【安保系统】周界红外触发，位置：东侧花园。请所有成员待在房间内，勿擅自外出，安保正在核查。"},
    {t:"m", x:"那一瞬间，你听见自己的心跳，比警报还快。"},
    {t:"n", x:"走廊的灯刷地亮了，白光把所有影子都逼到墙根。你听见门外的脚步，不是一个人的——拖鞋踩在木地板上，一重一轻，很急。温以恒先冲出来，睡裤外面胡乱套着外套，衣襟都没对齐，手里攥着那只保温壶，像攥着没说出口的胆子。他的头发还翘着，是被惊醒的形状。"},
    {t:"d", who:"温以恒", x:"「小队长，别开门。先跟大家聚到客厅，好吗？」他的声音压得很低，尾音却有一点不稳，「都到客厅去，别站在窗边。」", fx:"sad"},
    {t:"n", x:"七个人在客厅汇合。没有人开大灯，落地灯的光把七个人的轮廓投在墙上，挤成一团。沈时雨缩在沙发角落，两手抱着膝盖，指尖发白；顾知遥把陆清越整个挡在自己身后，脸色比平时冷得多，下颌线绷得死紧；林墨轩已经拨通了电话，声音压得很低，一边说一边走去玄关，把鞋架挪开，堵在门后；苏景行把你往自己身后带了带，动作比话快，肩膀横在你前面，像一道不长不短、刚好够用的墙。"},
    {t:"d", who:"林墨轩", x:"「江老师，东侧花园，有人翻入。已报警。」他一手按住话筒，一手把窗帘拉严，只留一条能看见院子的窄缝，「录像我调了，人在东边栅栏外，只有一个。」", fx:"cool"},
    {t:"d", who:"苏景行", x:"「小玩家，深呼吸。」他侧着头跟你说话，眼睛却盯着院子的方向，「有我在。七个人，少一个都不行。」", fx:"smile"},
    {t:"n", x:"陆清越被顾知遥挡在身后，只探出半个脑袋，声音小得几乎听不见：「队长哥哥……是坏人吗？」顾知遥立刻回头瞪了他一眼，那一眼里没有半点平日的嫌弃，只有一句没说出口的闭嘴，然后他把自己的外套脱下来，反手披在小忙内肩上，动作粗鲁，力道却很轻。"},
    {t:"n", x:"温以恒一个一个地看过去，看到谁就把手搭在谁背上，一句话也不说。他的手心是凉的。你注意到他攥着保温壶的那只手在抖，幅度很小，久不久一下，像漏了拍的节拍器。他把壶放在茶几上，然后刻意把手插进外套口袋里。"},
    {t:"n", x:"等警察的十分钟被拉得很长。远处有警笛由远及近，先是像一滴水，然后是整片雨。雨也开始落，打在玻璃上，碎成一片白噪，把院子里的树影揉得看不出形状。你听见自己的呼吸，和六个人的叠在一起，竟比警报更让人安心。"},
    {t:"n", x:"警察十分钟后到了。手电的白光在院子里扫了两圈，停在东侧栅栏边。被带走的人低着头，脖子上挂着一台相机，带子勒出一道红痕，镜头盖没盖，还反着光。林墨轩隔着窗看了很短的一眼，把帘子放下了。你没有看清脸，也不想去看清。门重新关好，门轴响了一声，风从门缝里退出去。"},
    {t:"n", x:"警车走了，红色的尾灯在院墙外拐了个弯，看不见了。客厅里没人说话，只有冰箱在远处嗡嗡地响，和雨声叠在一起。陆清越忽然打了个很轻的嗝，自己被吓了一跳，顾知遥伸手按住他的后脑勺，把他往自己肩上按了按。"},
    {t:"sys", x:"【安保系统】周界警报已解除。东侧花园风险点位完成复查，夜间巡逻频次临时上调。"},
    {t:"n", x:"江慕白半小时后出现在门口，银发被夜风掀起，几缕贴在额角上。他身后跟着两名新增的安保，雨水顺着他们的风衣下摆往下淌，在玄关的瓷砖上积成两小滩。他先扫了一眼众人，一个一个数过去，最后落在你脸上，问了一句：「都齐了？」"},
    {t:"n", x:"得到回答之后，他没再说别的，转身走进雨里，站在东侧花园的栅栏边看了很久。你隔着玻璃看见他抬起手，在虚空里比了一下围墙的高度，然后拿出手机，说了很长的一段话——语速很快，句子很短——最后只留下一句「天亮之前，我要看到人」。他回来时袖口全湿了，却先把记录本从怀里拿出来，确认没被雨打湿。"},
    {t:"d", who:"江慕白", x:"「我的队员，不容有失。」他把记录本扣在茶几上，声音不高，屋里每个人都听清了，「今晚起，安保翻倍。周界全部重做，二十四小时的人，我今晚就调到位。」他停了一下，看向你，「这件事，明天不对外说太多。你们只负责好好休息。」", fx:"cool"},
    {t:"weibo", items:[
      "#星途漂流屋私生饭闯入# 2.1亿",
      "#守护星蓝# 粉丝呼吁节目组重视艺人安全",
      "#私生饭必须追责# 路人支持依法处理",
      "#住别墅还说不安全# 公众质疑资源差距",
      "#理性追星反对私生# 中间派呼吁边界",
      "#温以恒第一个护住大家# 网友泪目",
      "#七个孩子好好休息# 暖心祈愿"
    ]},
    {t:"n", x:"天快亮时，雨停了，玻璃上留着没干的水线，像谁用指尖划过又收回。你煮了壶茶，七只杯子在茶几上摆开，热气把每个人的眉眼都熏得软了些。地毯上散着七双拖鞋，摆得歪歪扭扭，像退潮后搁浅的小船，谁也没舍得先挪。江慕白坐在单人沙发里没走，外套挂在椅背上，人却一直没合眼。"},
    {t:"d", who:"沈时雨", x:"「队长……我今天，有点不敢一个人睡。」他把杯子捧在两只手里，杯口离嘴唇很近，却迟迟没喝，「就今天一晚。」", fx:"sad"},
    {t:"d", who:"顾知遥", x:"「哼，本少爷的房间大得很。」他把毯子往沙发上一丢，别过脸，「谁要是非要去挤，我也懒得赶。」他说完就挪开半米，把那半米的位置空了出来。", fx:"shy"},
    {t:"d", who:"陆清越", x:"「队长哥哥！我今晚可以睡在你旁边吗？我不吵的，我已经不害怕了——真的，就一点点。」他扒着你的袖子，指节还是凉的，眼睛却努力睁得很亮。", fx:"sad"},
    {t:"n", x:"你忽然想起昨晚见面会那片星蓝，和那句最感谢谁。你当时答的是他们。原来他们会在凌晨两点，为你挡在身前，把害怕藏进攥白的指节、藏进夹进口袋的手、藏进一句故作轻松的打趣里，一声不响。"},
    {t:"choice", prompt:"你要怎么安顿这一夜的余震？", options:[
      {x:"「把客厅的灯留着，大家凑在一起睡。」", heart:{沈时雨:2, 陆清越:1}, cb:"你抱来所有的毯子，一条压一条，把沙发和地毯连成一片。陆清越立刻挤到你旁边，像只找到窝的小动物，很快呼吸就匀了。沈时雨迟疑了很久，最后在地毯最边上坐下，离你半臂远，手却虚虚朝着你的方向。"},
      {x:"「挨个陪每个人说一句，没事了。」", heart:{温以恒:2, 林墨轩:1}, cb:"你走到温以恒身边时，他正揉着太阳穴，对你笑了一下：「小队长，辛苦了。」你说没事了，他点头，眼眶却红了一瞬，很快低头去收茶几上的杯子。"},
      {x:"「让江老师安排，你们先休息。」", heart:{江慕白:1}, cb:"江慕白颔首：「交给我。」他关掉刺眼的大灯，只留地灯，影子在墙上软了一截。他挨个把房门推开检查了一遍，动作很轻，回来时手里多了一串新房卡。「今夜我留在客厅。」"}
    ]},
    {t:"n", x:"灯留着。你靠在温以恒肩边，他今晚难得没问你还好吗，只是安静陪着，偶尔抬手把滑下去一点的毯子往你肩上掖。沈时雨在角落翻了个身，手还虚虚朝着你的方向，像怕人走了。顾知遥最终还是没有回房，抱着胳膊坐在单人沙发的扶手上，装睡装到呼吸真的慢了。"},
    {t:"n", x:"窗外海声渐平，天边从灰蓝里透出一点更浅的蓝，正是他们在屏幕上看了一整晚的那种蓝。七个人的呼吸落在同一片安静里，像谁也不肯先醒。院子东侧的铁栅栏边，新到的安保已经换了第一班岗，手电的光柱缓缓扫过草地，扫过被雨压弯的花，最后停在那扇重新锁好的门上。你闭眼时想，这片海今晚翻过潮，可岸还在，灯还在。"},
    {t:"end"}
  ]
});


// ===== ch30.js =====
// 第三十章 创作周 —— 作者批次A
window.STORY.push({
  id: "ch30",
  title: "第三十章 · 创作周",
  phase: "团综",
  week: 16,
  nodes: [
    {t:"bg", v:"studio_day"},
    {t:"n", x:"警报那一夜之后的几天，漂流屋安静得有点小心翼翼。东侧花园的栅栏在两天内被换成了更高的那一种，灰色的立杆每隔十米立一根，顶端一盏小灯，整夜不灭。安保从两人变成了六个，夜里换岗的脚步声很轻，却谁都听得见。雨把草坪泡得发亮，谁也没再提那台相机。江慕白在客厅的沙发上睡了两夜，第三夜才回自己的房间。"},
    {t:"n", x:"温以恒能下床那天的阳光很好。厨房照例飘出香味，七份早餐摆得整整齐齐，好像那夜的警报从没来过。他笑着问谁要加蛋，和从前一模一样。可平静只维持了三天——从创作周的第一天算起，正好三天。要把这三天讲清楚，得从第一天讲起。"},
    {t:"n", x:"创作周第一天。迷你专立项会上，江慕白把一张空白母带推到你面前，说你们该有自己的声音了。录音室的灯比昨天亮，一整面隔音棉像被压平的灰云，玻璃上凝着一层薄薄的水汽，像谁也舍不得醒。调音台上一排推子还停在昨晚的位置，烟灰缸里没有烟，只有一颗被人忘了带走的薄荷糖。"},
    {t:"d", who:"江慕白", x:"「团综走到中段，你们该有自己的声音了。」他指尖在空白母带盒上敲了一下，「这三首歌，我不写一个字。我只负责在你们写歪的时候，把你们拽回来。」", fx:"neutral"},
    {t:"sys", x:"【节目组】首张迷你专辑正式立项：收录曲三首，母带由团队自主完成，制作周期十天。全部创作过程纳入正片素材。"},
    {t:"choice", prompt:"你要先和谁碰这首主打的创作？", options:[
      {x:"「林墨轩。他的编曲最克制，正合我意。」", heart:{林墨轩:2}, cb:"林墨轩点了下头，把耳机线从手腕上解下来绕好：「录音室，三点。」他离开时脚步很轻，走到门口又停了一下，「带上你自己没唱过的那一段。」眼底有一点难得的亮，像琴键反的光。"},
      {x:"「苏景行。他脑子里永远有怪旋律。」", heart:{苏景行:2}, cb:"苏景行笑出声，把吉他往背上一甩：「小玩家，终于想起我了？」他倒退着走，差点撞上谱架，伸手扶住，顺势朝你比了个上楼的手势，「走，天台写去。录音室太像考场。」"}
    ]},
    {t:"n", x:"你推开录音室的门，林墨轩正戴着耳机听一段钢琴 demo。他摘下一只，示意你坐。空气里是旧木和松香的味道，混着一点被日光晒热的毛呢椅面。窗外的光被百叶切成一条一条，落在他黑色的袖口上，随着外面的人走过，一条一条地亮、又暗。"},
    {t:"d", who:"林墨轩", x:"「副歌留白三拍，给观众喘气的余地。」他把铅笔横放在谱纸上，笔尖朝着你，「先别急着唱满。留白也是一种声音。」", fx:"neutral"},
    {t:"n", x:"他画了一段谱线推过来，指尖在五线谱上停了一瞬。那是你名字的首字母，藏进间奏里，若不细看只是个随意的装饰音。他收回手，把铅笔立起来转了一圈，什么也没解释。你假装没看见，耳廓却先一步热了，像被他的笔尖轻轻点了一下。"},
    {t:"n", x:"天台的风很大，把乐谱的页角掀得啪啪响。苏景行抱着吉他随口哼，松垮的外套被风鼓成一团，他也不去整理，由着它乱。远处的海面铺着碎银似的阳光，一群海鸟从上面掠过去，影子一闪就没了。他忽然停下来，把一句词改成了你昨天随口说过的一句话，念了一遍，又念一遍，然后低头咬住笔帽，笑了。"},
    {t:"d", who:"苏景行", x:"「这句，归你。」他把歌词纸折起来递给你，纸边被风吹得往前一送，正好落进你手里，「算我们俩的。以后唱到这句，你得想起今天。」", fx:"smile"},
    {t:"n", x:"两段 demo 都录进了母带。你戴上耳机听了一遍，一个声部冷，一个声部暖，并排躺着，像两个人同时把手搭在你肩上，谁也没抢谁的位置。你忽然觉得，这首歌已经不只是你的了。"},
    {t:"n", x:"录音室的日子过得很像潮汐。沈时雨每天最早到，在隔壁的空房里对着镜子把副歌那八拍跳到衬衫湿透，回来时只肯说「还差一点」；陆清越抢着去按每一个按钮，被音控老师赶了三次，最后一次抱着一盒牛奶坐回角落，认真得像在听讲；顾知遥嘴上说「本少爷不碰这种土气的东西」，却把自己关在隔间里录了整整三十遍和声，挑出最漂亮的一条交上去。温以恒照常送餐，保温壶、水果盒、还有一个记满每个人口味的小本子。"},
    {t:"n", x:"几天下来，每个人都熬得眼皮发沉。温以恒照常早起做早餐，照常睡前挨个确认谁还醒着。只是你有一回撞见他端碗时手抖了一下，汤沿晃出来，他迅速拿袖子抹掉，像抹掉什么不该被看见的东西，然后把那只袖子叠到里面，用另一只手在围裙上按了按。前一夜你从录音室出来倒水，看见他坐在楼梯上，膝盖上摊着那个小本子，笔悬在纸上很久没落下去。"},
    {t:"choice", prompt:"忙碌到傍晚，温以恒又端来宵夜。你察觉他脸色不对。", options:[
      {x:"「以恒哥，今天你别忙了，我来收拾。」", heart:{温以恒:3}, cb:"温以恒愣了下：「哪能让你——」话没说完，他身子晃了一下，手里的保温壶脱了手，在瓷砖上滚出很远。他伸手去扶墙，指尖在墙上划了一道，没抓住。"},
      {x:"「以恒哥，你最近，睡得够吗？」", heart:{温以恒:2}, cb:"温以恒笑得依旧软：「小队长操心这个？我好得很。」他说话时低着头去摆碗，可你看见他眼下那两片散不开的青灰，也看见他把碗摆错了位置，又不动声色地挪回来。"},
      {x:"「先吃饭，吃完大家陪你早点睡。」", heart:{温以恒:1, 陆清越:1}, cb:"陆清越立刻举手：「以恒哥我帮你洗碗！」温以恒被逗得弯了眼，伸手揉了一把他的金发——那只手抬起来的时候，停在半空里迟了一瞬，像忘了自己原本要做什么。"}
    ]},
    {t:"n", x:"他晃的那一下，保温壶脱手。汤洒了一地，热气贴着地板散开，白雾短暂地笼住他的裤脚。温以恒想扶墙，膝盖却先软了，整个人往你怀里坠。你接住他的时候，第一个念头是——比想象中轻。轻得不像那个每天扛着七个人胃口的人。"},
    {t:"n", x:"医务组在十分钟内就位。走廊的灯一盏一盏亮起来，担架轮子碾过木地板，声音很低。诊断只有四个字：透支，缺觉。护士把输液瓶挂好，调了滴速，站在床边皱着眉说，这种人最危险，把自己当成不会坏的零件，坏起来连招呼都不打。江慕白站在门口听完，什么也没说，只把记录本合上，夹在腋下。"},
    {t:"diary", who:"温以恒", date:"团综第十六周 阴", x:"今天又比昨天早起半小时，想把大家的口味再记一遍。小队长最近压力大，我得把后勤稳住，不能让他分心。这半个月其实没怎么睡好，凌晨总在想明天谁会低血糖、谁会想家、谁又偷偷加练到腿软。他们都叫我团队的胃和心，那我就不能先垮。只是刚才端汤时眼前黑了一阵，没事的，睡一觉就好。等他们需要我的时候，我得还在，还得是那个笑着问谁要加蛋的我。"},
    {t:"n", x:"那一晚，厨房第一次没有温以恒的影子。灶台上的火是别人开的，锅铲是别人拿的。沈时雨笨拙地煮了粥，一边搅一边数秒，数到一百就重新数，盐放多了自己先皱了眉；顾知遥默默把碗洗了，嘴上说着本少爷赏你的，手却把每只碗底的水珠都擦干，一只一只扣进消毒柜。"},
    {t:"d", who:"沈时雨", x:"「我……会煮粥了。」他把碗放在你手边，指尖蜷了蜷，「味道不好，下次，下次我少放半勺盐。以恒哥教过我一次。」", fx:"shy"},
    {t:"d", who:"顾知遥", x:"「哼，才不是心疼他。」他把最后一双筷子插进筷笼，声音低下去，「……只是没人做饭，本少爷要饿死。你们谁都不许跟他说我洗碗了。」", fx:"shy"},
    {t:"d", who:"林墨轩", x:"「母带推后三天。」他把谱纸收进文件袋，动作很稳，「歌等得起，人不等。」", fx:"neutral"},
    {t:"d", who:"苏景行", x:"「流程表我改完了。」他瘫在沙发上，把改得密密麻麻的一页纸递给你，「明天上午的收音调后，理由是设备保养——理由我编的，你们谁也别拆穿我。」", fx:"smile"},
    {t:"n", x:"你坐在温以恒床边，把体温计取出来，甩了甩又放回去。他睡着时眉心是松的，像卸下了什么一直扛着、却没人准许他卸下的东西。输液管里一滴一滴地走，比秒针慢。你想起他每天记的那张口味纸条，和睡前那句轻声的还好吗。床头柜上那个小本子摊开着，最新的一页写了一半——明天那一栏，七个人的早餐已经排好了。江慕白后来进来过一次，站在床尾看了半分钟，只说了一句话就出去了。"},
    {t:"d", who:"江慕白", x:"「后勤不该只有一个人。」他把一张新排的值班表压在床头柜上，纸边对着你的方向，「从明天起，早餐排班。你排第一。」", fx:"cool"},
    {t:"d", who:"陆清越", x:"「队长哥哥，以恒哥会好起来的对不对？」他把脸贴在床沿，声音闷闷的，「我们以后都乖乖吃饭，不挑食，不把牛奶剩下——我保证！」", fx:"sad"},
    {t:"choice", prompt:"温以恒醒来后第一句话是，对不起，耽误大家。你要怎么回？", options:[
      {x:"「以恒哥，这次换我们照顾你。」", heart:{温以恒:3}, cb:"温以恒别过脸：「小队长，别学我说话。」可他耳根红了一截，没有把搭在他手背上的那只手推开，反而在被子底下，很轻地回握了一下。"},
      {x:"「你先睡，明天的早餐我包了。」", heart:{温以恒:2, 苏景行:1}, cb:"苏景行在门口笑出声：「听见没老温，你也有人兜底了。」温以恒闭着眼，嘴角却往上翘了一点点，翘得很小心，像怕被谁看见。"}
    ]},
    {t:"n", x:"夜很深了。漂流屋第一次安静得只剩呼吸，连安保换岗的脚步声都被地毯吃掉了。你忽然懂了，那个一直照顾别人的人，也需要一个能让自己放心倒下的地方。而他肯在这里倒下，是因为知道有人会接。"},
    {t:"n", x:"清晨你第一次比他早起。天还没亮透，海是灰的，厨房的灯只开了一半。你翻到他贴在柜门内侧的口味纸条，密密麻麻，从上到下排了七行，连谁喝豆浆不加糖、谁不能碰香菜都写着。你照着抄，手忙脚乱，煎蛋破了两个，第三个总算留住了一个圆。"},
    {t:"n", x:"温以恒下楼时愣在原地，扶着楼梯的手停了两秒，才慢慢走下来。他没说话，先把那两个破掉的蛋小心盛进自己碗里，又把你煎糊的那半个角也拨过去吃掉。他说：「小队长，下次还是我来。」可这一次，他没拦你把他按回椅子上，由着你把热豆浆推过去。窗外的天一点点亮起来，灰蓝慢慢变成浅蓝，正是那段日子大家都在看的那种颜色。"},
    {t:"end"}
  ]
});


// ===== ch31.js =====
// 第三十一章 解约风波 —— 作者批次A
window.STORY.push({
  id: "ch31",
  title: "第三十一章 · 解约风波",
  phase: "团综",
  week: 16,
  nodes: [
    {t:"bg", v:"meeting_room"},
    {t:"n", x:"温以恒能端着锅铲笑的那天，创作周已经过半。母带渐成，录音室的灯不再通宵亮着，每个人都松了半口气——厨房重新有了声响，切菜、起锅、保温壶磕在台面的一声轻响，比任何一句安慰都实在。你记得那天早餐，温以恒在每个人的碗边多放了一颗溏心蛋，说补一补。可这股松快没能撑过下午。三点五十分，一通没有署名、也没有归属地的电话打进来，把你从录音室叫去了行政楼。你把耳机从脖子上摘下来的时候，母带里的那段副歌还在放，留白三拍，是林墨轩坚持留下的呼吸口。"},
    {t:"n", x:"一位西装的人把一份合同推过桌面。纸很新，边角齐得能立在桌上。会议室在行政楼三层，朝走廊那一面是整块玻璃，外面的灯白得发冷，冷气却开得太低。桌上摆着一瓶矿泉水，瓶身凝着细密的水珠，从你进门到现在没人动过。他说话很客气，笑意停在嘴角，不进眼睛。条款里藏着一行小字——单人约，排他，解约即赔。窗外的天，灰得像没洗的胶片。"},
    {t:"sys", x:"【内部通知】星澜娱乐拟以单人合约接触成团成员，条款含排他约定，请各成员谨慎对待，任何签约须经纪方书面确认。"},
    {t:"n", x:"对方把条件说得漂亮，单人约，专属资源，三年冲顶流。他连你的日程都背得比你自己熟：哪一场舞台的数据最好，哪一段直拍涨粉最快，一条一条摆在桌上，像替你算一笔稳赚不赔的账。他说，七个人分一锅汤，谁都吃不饱，而好的资源，从来只喂一张脸。他每说一句，就用指尖把桌上的合同往你这边推半寸，推到第五次的时候，纸已经碰到你的笔记本边。玻璃门外，江慕白抱臂站着，没有进来，也没有敲玻璃，隔着一层反光的墙面看你，像在等你自己走出来。"},
    {t:"choice", prompt:"面对资本方的试探，你要怎么回？", options:[
      {x:"把合同推回去：“我和我的团，不拆。”", heart:{顾知遥:1, 沈时雨:1}, cb:"对方笑了笑，年轻人，想清楚。你走出门，江慕白在走廊里，什么也没说，只把外套搭你肩上。"},
      {x:"先收下合同：“我需要考虑。”", heart:{林墨轩:1}, cb:"你把合同折好放进口袋。林墨轩在门外看你，聪明，弄清陷阱，才有筹码。"}
    ]},
    {t:"n", x:"走廊很长，鞋底踩在地胶上，声音被吸掉一半。电梯下行时有一股金属的凉气，混着保洁用的消毒水味。窗外开始起风，梧桐把天光扫来扫去。回漂流屋的路上，你把那些条款一句一句过了两遍：单人约，排他，解约即赔。每一句都读得通，每一句也都能咬人。司机在红灯前停了很久，雨刷没动，挡风玻璃上落了几点灰。你想起上个月那场泳池挑战，陆清越把水花拍到你脸上，笑得直不起腰；想起花园迷宫中心许愿池边，有人偷偷把愿望说给了水面听。"},
    {t:"n", x:"你回到别墅，把事说了一半。客厅的灯只开了一半，另一半留给走廊。六个人围过来，没有人抢话，客厅忽然很静，连茶杯被放回桌面的那一声都收着。陆清越把到了嘴边的感叹硬咽了回去，喉咙滚了一下，没滚出声。你数了数他们的位置，像是排练过，又像本来就该这样：林墨轩靠窗站着，手里还捏着铅笔；温以恒在厨房门口，围裙带子系了个歪结；顾知遥歪在沙发扶手上，一条腿悬着；沈时雨坐在最外面那把椅子上，手指扣着椅沿；苏景行把吉他搁在脚边，鞋尖抵着琴箱；陆清越蹲在茶几和沙发之间那块地毯上，仰着脸看你。七个影子被同一盏灯压在木地板上，谁也没有先开口。墙上那排合影里，七个人还停在成团夜的位置，笑得毫无防备。"},
    {t:"d", who:"林墨轩", x:"少一个声部，就不是这首曲子。", fx:"neutral"},
    {t:"n", x:"他说得很平，像在陈述一条乐理。说完他把膝上的谱纸合上，对齐，边角朝下压了压——那是他每次交作业前都会做的动作。窗外有一辆车驶过，灯光扫过他的袖口，一闪就没了。他没有再看你，只把铅笔立在桌沿——立住了，没让它滚下去。"},
    {t:"d", who:"温以恒", x:"小队长，胃和心都在这儿，你往哪儿走？", fx:"smile"},
    {t:"n", x:"围裙的带子还系在他腰上，打了个歪结。他一边说一边给你倒了杯温水，推到你手边，杯底在木桌上转了半圈才停。杯壁是温的，他手上有洗洁精和姜的味道。他站的位置离厨房最近，像随时准备回去把火关小。"},
    {t:"d", who:"顾知遥", x:"哼，本少爷的队长大人，谁也别想拐跑。", fx:"shy"},
    {t:"n", x:"他别过脸去看窗帘，耳朵先红了。悬着的那条腿荡了两下，又停住。他伸手把歪掉的抱枕拍正，拍得比平时用力；拍完才发现那是沈时雨那一边的，手顿了顿，又收了回去。"},
    {t:"choice", prompt:"你要怎么回应他们？", options:[
      {x:"把合同摊在茶几上，翻到那行小字，指给他们看。", heart:{林墨轩:1, 温以恒:1, 沈时雨:1}, cb:"六个人凑过来，纸页被翻动的声音很轻。沈时雨看到那行小字时，指尖在纸上停了一秒，又慢慢收回去，在膝盖上攥成了拳。"},
      {x:"把合同折起来，只说：“给我点时间。”", heart:{苏景行:1, 江慕白:1}, cb:"苏景行把吉他抱回怀里，拨了一根弦，又用手掌按住，响声刚起就被掐断。他说：行，时间我们有。"}
    ]},
    {t:"d", who:"沈时雨", x:"队长……我，只跟得上你。", fx:"sad"},
    {t:"n", x:"他声音很低，说完低下头去看自己的鞋尖，鞋面上还沾着下午练舞留下的灰印。那双手白天刚在空房里把副歌的八拍跳到衬衫湿透，此刻却不知道该往哪儿放，最后落在膝盖上，指尖压着裤缝，压出两道浅浅的白痕。"},
    {t:"d", who:"苏景行", x:"小玩家，竹马这么多年，你甩不掉我的。", fx:"smile"},
    {t:"n", x:"他笑得懒洋洋，尾音往上挑，像平时逗你那样。可他抱吉他的姿势比平时紧，指节把琴颈扣出一道白印，一直到你说完话才松开。他偏过头，用肩膀很轻地撞了你一下，撞完就退开半步。"},
    {t:"d", who:"陆清越", x:"队长哥哥不要丢下我们！七个人好不容易在一起！", fx:"cry"},
    {t:"n", x:"他喊出声，眼圈立刻红了，蹲在地毯上没起身，两只手撑在膝盖上，像怕一站直就会哭得更凶。温以恒伸手把他往自己那边拢了拢，他没躲，只把脸埋进胳膊，声音闷在袖子里，含混地说了一句谁都听不清的话。顾知遥站起来，把自己那杯没动过的水放在他手边。"},
    {t:"sys", x:"【经纪方】已就星澜娱乐的接触向节目组报备。任何成团成员不得单独签署外部合约，请队长与成员知悉。"},
    {t:"n", x:"十一点多，你到二楼阳台透气。雨还没落下来，风先来了，带着草地和湿土的味道，把晾在栏杆上的毛巾吹得一下一下拍打。楼下安保在换岗，手电的光在灌木上扫过。你正要把窗推上，身后响起脚步——苏景行披着那件松垮的外套，站到了你旁边。"},
    {t:"d", who:"苏景行", x:"小玩家，明天早上七点，天台风大。你写不出词就来。", fx:"smile"},
    {t:"n", x:"他靠着栏杆仰头看云，亚麻色的头发被风吹得乱翘。他也不催你，就那么站着，站到你把按在窗框上的手放下来，才一起下楼。下楼时已经过了十一点半。楼梯的感应灯一亮一亮，把他的影子甩在你前面。深夜，手机亮了一下，屏幕的光在黑暗里显得太亮。你拿起来，是江慕白。"},
    {t:"phone", who:"江慕白", msgs:[
      {f:"them", x:"合同我已压住，星澜动不了你。", time:"23:58"},
      {f:"them", x:"剩下的，你自己选。", time:"23:58"}
    ]},
    {t:"n", x:"雨又落下来，打在漂流屋的窗上，先是一层细密的沙沙，接着才听出阳台铁栏杆上那一下一下更脆的响。你忽然想起见面会那片星蓝，想起应援色揭晓那晚台下的光，和那句最感谢谁——你当时答的，是“他们”。两个字很轻，落进雨声里，又被雨声托住。"},
    {t:"choice", prompt:"你要怎么回应这份选择？", options:[
      {x:"把合同撕了，回到他们中间。", heart:{林墨轩:2, 温以恒:2, 顾知遥:2, 沈时雨:2, 苏景行:2, 陆清越:2}, flag:"stay_together", cb:"你撕掉纸页的声音很轻。客厅里七盏灯，一盏不少，谁也没问你为什么。"},
      {x:"把合同收进抽屉：“让我再想一夜。”", heart:{江慕白:1}, flag:"solo_considered", cb:"你关了灯。窗外的雨没停，可你第一次听见，自己心里也有一片海，正悄悄涨上来。"}
    ]},
    {t:"n", x:"那一夜，漂流屋的灯熄得很慢，一盏，又一盏，走廊最后才暗下去。二楼的窗缝里透出一条细光，很久很久，才跟着灭了。无论怎么选，有些东西已经落在了心底，像雨后的根，看不见，却扎下了。"},
    {t:"end"}
  ]
});


// ===== ch32.js =====
// 第三十二章 雨中的首唱会 —— 作者批次A
window.STORY.push({
  id: "ch32",
  title: "第三十二章 · 雨中的首唱会",
  phase: "团综",
  week: 17,
  nodes: [
    {t:"bg", v:"outdoor_stage"},
    {t:"n", x:"解约风波过去三天。雨停了，天没晴，云一直压在漂流屋上头，像谁把一块湿布搭在了屋檐。周六傍晚六点，迷你专首唱会定在别墅外的户外影院区——节目组铺了防潮垫，摆了两百把折叠椅，一块巨幕挂在两棵樟树之间，风一过，幕布就鼓起一道浅浅的弧。"},
    {t:"n", x:"首唱会的灯牌早早亮了。星蓝的萤光手环一片一片亮起来，在雨前的风里晃，晃成一层流动的水。工作人员给音响套上透明防雨罩，胶带撕开的声音一声接一声。空气闷得发黏，草叶上有水，鞋底一踩就是一道印，混着烤肠车飘过来的油香和湿泥的味道。这是迷你专的第一场，也是团综留给观众的礼物。"},
    {t:"n", x:"你望着台下，想起那夜闯入的警报，想起温以恒倒下的厨房，想起玻璃会议室里推回来又收起的那份合同。这一路，漂得不轻。"},
    {t:"n", x:"五点半开始放人。两百把椅子很快坐满，前排有人把雨衣叠好垫在腿上，后排站着的观众把星蓝手环举得老高，像一小片提前亮起来的夜。有个姑娘把写着队长两个字的灯牌抱在怀里，拿外套裹着，怕淋湿。广播念了三遍安全提示，声音被风削得断断续续，最后一遍干脆只剩半句。"},
    {t:"n", x:"后台的帐篷里，林墨轩把琴键擦了三遍，最后一遍用的是干的软布。沈时雨在场边压腿，压到一半停下来看天，云压得很低，边缘泛着一点紫。顾知遥把刘海往后拨了拨，皱着眉看袖口沾到的一点胶。温以恒挨个拧开矿泉水又拧上，怕谁喝太急；陆清越蹲在音箱边上，对着自己的影子练开场那句招呼。你对了一遍流程单，第五首是主打，第七首全员合唱，耳机里导播数的秒干得像在念说明书。"},
    {t:"n", x:"侧台的折叠椅上放着一只纸袋，是温以恒下午跑出去买的，里面七颗水果糖。他说上台前含一颗，嗓子不干。陆清越把自己那颗分给了场务的小姑娘，回来又眼巴巴看着苏景行手上那颗，苏景行笑着把糖纸给他，糖自己留着。江慕白站在侧幕的阴影里，没拿流程单，也没戴耳机。"},
    {t:"d", who:"陆清越", x:"队长哥哥！下雨了！但是大家都在，我们唱！", fx:"smile"},
    {t:"n", x:"雨真的落下来，先是一滴两滴，砸在防雨罩上啪的一声，而后成帘。台下有人撑伞，有人干脆把伞收了。导播的声音在耳机里停了两秒，犹豫要不要中止，说设备进水不划算。紧接着，江慕白的声音切进来，只说了很短的一句——让他们自己选。"},
    {t:"d", who:"江慕白", x:"舞台是你们的。", fx:"cool"},
    {t:"choice", prompt:"雨越下越大，你要怎么决定这场首唱？", options:[
      {x:"“淋着雨，把歌唱完。”", heart:{林墨轩:1, 沈时雨:1}, cb:"你摘下耳返的防潮套，把话筒举向雨里。六个人同时点了头，没人犹豫。"},
      {x:"“先护着设备，改室内清唱。”", heart:{温以恒:1}, cb:"温以恒把吉他往怀里收了收，小队长，听你的。可他眼里，有一点没说出口的遗憾。"}
    ]},
    {t:"n", x:"你们选了雨。第一句出来的时候，雨声把你的尾音吃掉一半，你索性把话筒往前送，让雨替你和声。沈时雨把湿透的刘海往旁边一拨，站回彩排时那个位置；林墨轩把琴凳往雨棚外挪了半步，让琴键能接到大屏的光；苏景行把吉他背带收紧两格，肩线绷起来。台下两百个星蓝的光，没有一个灭。你听见自己的呼吸从耳返里折回来，粗，也稳。"},
    {t:"n", x:"七个身影站成一排，雨水顺着发梢淌进衣领。沈时雨站在你左手边第二位，衬衫贴在背上，能看出肩胛骨绷紧的形状。他在发抖，从手腕开始，一直抖到小腿，可和声进来的时候比哪一次都稳，像终于不再躲的那个人。他咳了一声，把气息重新压回肋骨底下，肩膀跟着落了下去。"},
    {t:"d", who:"沈时雨", x:"队长……雨里，好像没那么怕了。", fx:"smile"},
    {t:"n", x:"温以恒把外套脱下来罩住前排的音响，自己湿透半边，里面的白衬衫贴在身上。他弯腰去压外套的角，膝盖在水里磕了一下，没停，只把另一只手撑在音箱上。他把外套的下摆又往里掖了半寸，像给一台不会说话的机器掖被角。顾知遥难得没嫌水脏，把陆清越往自己身后拢，银灰色的发梢滴着水，墨镜早不知被塞进了哪个口袋。"},
    {t:"d", who:"顾知遥", x:"本少爷今天破例，不讲究了。", fx:"shy"},
    {t:"n", x:"苏景行在间奏里即兴改了词，把漂流两个字，换成了靠岸。他唱得很轻，像怕惊动什么。林墨轩的琴声没停，雨水打在琴键的防尘布上，闷成鼓点，一下一下。他偏头看了你一眼，下巴往下一压——那是他给你数拍子的方式，从不喊出来。"},
    {t:"n", x:"陆清越唱到那句上扬的尾音时，整个人往上窜了半寸，水花从他鞋跟后面跳起来。顾知遥接了后面那半句和声，稳得不像一个平时只肯站C位的人，音量压着，谁也没抢。你听见台下有人在喊你们的名字，喊得七零八落，喊到一半被雨声盖过去，又冒出来。"},
    {t:"d", who:"苏景行", x:"小玩家，副歌那句——今天归你了。", fx:"smile"},
    {t:"d", who:"林墨轩", x:"别抢拍。剩下的交给我们。", fx:"neutral"},
    {t:"n", x:"你对着雨幕举话筒，声音被雨声磨得发哑：我们漂了这么久——台下有人跟着念了后半句，声音杂，却对上了。你看清最前排那个举灯牌的女孩，雨衣帽檐压得很低，牌子上的字被水泡得发晕。那盏灯牌又被举高了一些，举过头顶，好让那点光落在台上多一点。可你看，漂流的星，也会落地生根。"},
    {t:"danmaku", items:[
      "星蓝守护者|雨好大但他们还在唱 呜呜",
      "苏苏的小甜饼🍪|苏苏改词了 靠岸！！",
      "老林的头号迷妹|林墨轩雨里弹琴杀我",
      "以恒的保温壶|温以恒先护设备真的泪目",
      "知遥的墨镜|顾少爷不爱讲究了哈哈",
      "时雨的小透明|时雨雨里不抖了宝宝加油",
      "队长冲鸭🚀|漂流的星也会落地生根 爱了"
    ]},
    {t:"n", x:"雨小了。台下星蓝的萤光没灭，反而被雨水洗得更亮，一片连着一片，像谁把整片夜空搬到了地上。有人把雨衣脱下来系在椅背上，有人在鼓掌，掌声湿漉漉的，散在空气里。地上浮着一层薄薄的水光，把舞台的灯反上来，踩一脚就碎，抬脚又合。巨幕上的字还亮着，光落在积水里，晃成一条条碎掉的线。"},
    {t:"n", x:"侧幕那头，江慕白一直没坐下。他把伞收在身后，肩膀湿了一片，也没往台上递一句话。场务给他搬椅子，他摆了摆手。等副歌彻底落下去，他才把手从口袋里拿出来，很轻地拍了两下，像怕惊了台上的谁。"},
    {t:"n", x:"导播在耳机里说了一句，雨天的收音比棚里好。回放切到巨幕上，是刚才那段副歌——七个湿透的人挤在同一个画框里，谁的脸都看不清楚，只有星蓝的光在雨里连成一片。台下有人开始跟着唱，先是几个，然后半场，最后连后排站着的人都张了嘴。陆清越仰着头看巨幕，嘴巴张着，忘了合上。"},
    {t:"d", who:"温以恒", x:"小队长，回家吧，我煮姜汤。", fx:"smile"},
    {t:"n", x:"七个人踩着水往回走。鞋底啪嗒啪嗒，像某种笨拙又笃定的鼓点，踩碎了一路的水洼。陆清越一路蹦，水花溅到顾知遥裤脚上，被瞪了一眼也不改。沈时雨走在最后，走到一半追上来，把自己的毛巾递给你，手伸到一半又觉得不妥，往回缩了半寸。路灯把七个人的影子铺在湿漉漉的水泥地上，长的短的，歪歪扭扭跟着走。陆清越回头问沈时雨冷不冷，沈时雨摇头，又补了一句不冷。温以恒走在最前面，手里拎着那件已经湿透的外套，走几步就回头点一次人数，点到第七个才继续往前。"},
    {t:"choice", prompt:"回别墅的路上，你要怎么做？", options:[
      {x:"把所有人拢成一排，合唱最后一句。", heart:{陆清越:2, 沈时雨:1}, cb:"陆清越踮脚勾住你胳膊，七个湿漉漉的声音叠在一起，跑调也跑得理直气壮。"},
      {x:"默默走，把这一刻记进心里。", heart:{林墨轩:1, 苏景行:1}, cb:"苏景行斜你一眼，小玩家，记性一向差，这次别忘。林墨轩在另一侧，轻轻哼起了副歌的留白。"}
    ]},
    {t:"n", x:"漂流屋的灯在雨幕那头亮着。厨房的窗透出一层暖黄，有人已经把姜切好，锅坐在灶上，水汽糊了半扇玻璃。你回头看了一眼影院区，巨幕已经暗了，支架上的防雨布还在滴水，折叠椅歪歪扭扭地站在雨里，像刚散场的一场热闹还留在原地。你知道，有些根，是一起淋过雨，才真正扎下的。"},
    {t:"end"}
  ]
});


// ===== ch33.js =====
// 第三十三章 · 陆清越的十八岁 —— 团综收官（week:17）
window.STORY.push({
  id: "ch33",
  title: "第三十三章 · 陆清越的十八岁",
  phase: "团综",
  week: 17,
  nodes: [
    {t:"bg", v:"villa"},
    {t:"n", x:"第17周，团综录制进入尾声。漂流屋的客厅被悄悄清空了一角，沙发推到了墙边，地毯卷起来立在门后。天花板那盏红灯还亮着——二十四小时直播从没关过，镜头后头，不知多少双眼睛正盯着这场密谋，连呼吸都放轻了，怕惊散这攒了一整年的小心思。空气里浮着乳胶气球和胶带的味道，混着窗缝里钻进来的夜风。墙上的钟指向九点，秒针走得很响，离陆清越回来，还有最后几分钟。"},
    {t:"n", x:"陆清越还蒙在鼓里，被温以恒以『晚间体能补测』骗去了一小时。你蹲在沙发后，看沈时雨把气球一个个按进墙缝，指尖沾了胶也舍不得擦；顾知遥正挑剔彩带歪了三毫米，贵族少爷的苛刻全用在装饰上，一句『重贴』把沈时雨支使得团团转，两人倒因此凑成了难得的搭档。贴到第七个的时候，气球从沈时雨手里滑脱，他没敢出声，踮着脚追了两步，又被顾知遥一个眼色钉在原地。"},
    {t:"d", who:"顾知遥", x:"队长大人，你那边的星星挂正了没有？本少爷的审美不容糟蹋。", fx:"cool"},
    {t:"choice", prompt:"你要怎么搭把手？", options:[
      {x:"“挂歪了才像我们，别动。”", heart:{顾知遥:1, 陆清越:1}, cb:"顾知遥哼了一声，手却老实停住：『哼，才不是听你的。』"},
      {x:"“交给我，你退后当监工。”", heart:{顾知遥:2}, cb:"他挑眉，抱臂退到一旁：『队长大人亲自上，那本少爷就赏个脸。』"}
    ]},
    {t:"n", x:"苏景行蹲在茶几边，正用裱花袋给蛋糕描那颗歪歪扭扭的小太阳，亚麻色头发垂下来，遮住半边笑意。『我们小太阳的十八岁，』他低声说，『总得有点仪式感。』空气里已经浮起淡淡的奶油甜，混着窗外飘进来的夜风，凉而干净。"},
    {t:"n", x:"礼物是提前一周备下的，藏在储物间最里层，用一条旧毛巾盖着。你摸黑进去取的时候，指尖先碰到的是一只限量手办——原厂的塑封还套着，价签没剪，边角磨得起了毛。买回来就搁下了，一直没舍得拆。你把它捧出去，塑封蹭过毛巾，发出很轻的一声响。"},
    {t:"n", x:"灯被苏景行啪地按亮。纸花落了陆清越满肩，蛋糕上插着『18』的蜡烛，奶油裱着他最爱的、歪歪扭扭的小太阳。暖黄的光泼下来，把每个人的影子都揉成了一团柔软的轮廓，像这一年所有吵闹与靠近，终于安静地叠在了一起，谁也没有再提镜头还亮着。"},
    {t:"danmaku", items:[
      "清越的小太阳🌞|十八岁快乐呀！！",
      "队长哥哥好温柔|刚才那下抹奶油我没了",
      "直播间的狗粮|陆清越你小子好福气",
      "小太阳生日快乐🎂|这届队长真宠",
      "江慕白居然没穿西装|慕白哥今天放过他们了",
      "温以恒的长寿面|以恒哥永远的神",
      "团魂这一块|七个人真好啊"
    ]},
    {t:"d", who:"陆清越", x:"队长哥哥！你们在干嘛呀！", fx:"shock"},
    {t:"n", x:"他眼睛瞪得溜圆，声音拔高，像拆开礼物前的那一秒。书包还背在肩上，鞋没来得及换，一只鞋带散着拖在地上。江慕白破例没穿西装，只松松系着围巾，站在镜头外，难得没开口挑刺，灰眸里映着那点烛火，竟没有平日的压强，倒像被这屋子的暖烘得松动了些。"},
    {t:"n", x:"江慕白从镜头外递来一只小盒子，是给陆清越的成年礼——一支他常用的指挥棒。『十八岁了，』他难得没用判词口吻，『该学着自己掌舵，别总躲在队长身后。』陆清越双手接过，郑重得像接过了某种长大，连盒子上的缎带都没舍得解，先捧在手心里看了半天。"},
    {t:"n", x:"温以恒把一碗长寿面轻轻放在你手边，汤面上漂着一颗溏心蛋，是他一贯的用心。『先垫垫，等会儿别饿着。』他说完，又去给每个人的杯子里续了温水，动作轻得像怕惊散这晚的暖，也像在替所有人把这一刻稳稳托住。他的袖口还卷着，手背上有一小块被锅沿烫红的印子。"},
    {t:"d", who:"温以恒", x:"小队长，今天的主角可是小太阳，你少操点心。", fx:"smile"},
    {t:"n", x:"你忽然想起，这一整年，都是他替所有人记着饿不饿、冷不冷。而此刻，他把自己排到了最后，像从来如此，也像从来甘愿。你握着筷子的手，不自觉地紧了紧，喉头有点发酸，又被奶油甜盖了过去。"},
    {t:"n", x:"许愿环节到了。陆清越被推到蛋糕前，闭上眼。顾知遥抬手把客厅的大灯关了，只留蛋糕上那十八点光。客厅很静，连那盏红灯都像屏住了呼吸，只剩烛火在他睫毛上投下细碎的影，空气里全是甜的、暖的、屏息的期待，像所有人都在替他守着一个还没说出口的秘密。"},
    {t:"n", x:"他许的愿，后来你一个人想了很久。镜头只录到他嘴唇动了动，没录进声音——那愿望像是写给『队长哥哥』的，又像是写给某个更特别的人；是『想永远留在你身边』，还是『想成为你最特别的那一个』，你始终没问出口，他也始终没说破。烛火摇了摇，像替他保密。"},
    {t:"m", x:"你只记得他睁眼时，目光越过烛火，落得很轻，很准，正好在你脸上，像一束被攒了一整年的光，终于敢落下来，不躲，也不问你接不接得住。"},
    {t:"choice", prompt:"你要怎么接这个瞬间？", options:[
      {x:"弯腰与他平视，替他抹掉鼻尖的奶油。“许了什么？”", heart:{陆清越:2}, cb:"他摇头，笑得像揣着全世界的秘密：『说出来就不灵啦，队长哥哥！』"},
      {x:"悄悄在手机里记下一行：十八岁生日愿望，待查证。", heart:{陆清越:1, 苏景行:1}, cb:"苏景行从身后探过头：『哟，队长还写日记呢？』"}
    ]},
    {t:"n", x:"切蛋糕时，陆清越忽然从兜里掏出一只玻璃小瓶，里面装着折成星星的糖纸，在烛光里透出细碎的彩。『这个是魔法！攒了一整年，能实现一个愿望。』他郑重塞进你手心，指尖还带着少年人才有的、晒过太阳的暖，烫得你心口发麻。瓶身是温的，像被谁在口袋里焐了一路，玻璃上还留着几道被他反复摩挲出来的浅痕。"},
    {t:"d", who:"陆清越", x:"队长哥哥，我的愿望先寄放在你这里！", fx:"laugh"},
    {t:"n", x:"你握着那只小瓶子，玻璃被手心焐得越来越热。忽然想起他刚进营时把『让时雨哥笑起来』当日常任务，想起他每天清晨那声『今天也要加油』，想起他相信队长无所不能的那股傻气。十八岁的太阳，把这一年的所有人都烤得暖烘烘的，连最角落里的沈时雨，此刻都亮了一度，像被悄悄焐过。"},
    {t:"n", x:"陆清越忽然踮脚抱了你一下，金色的发顶蹭过你下巴，又飞快松开，像怕唐突，又像怕不够。『队长哥哥，』他小声说，『我今天，真的十八啦。』烛火在他眼里晃，那点光，比直播间的任何一条弹幕都真。"},
    {t:"n", x:"不止瓶子。沈时雨塞来一张折成方胜的纸，写着『生日快乐』，字迹比练舞时还工整；顾知遥丢过来一只限量手办，嘴硬『过时了不要』，耳尖却红了。陆清越眼睛亮得像盛了星，把每样都小心收进怀里，像收着一整个宇宙的善意。"},
    {t:"n", x:"林墨轩站在最外围，一直没说话。等大家都送完了，他才从文件袋里抽出一张纸——是他手抄的生日版主题曲简谱，右上角端端正正写着陆清越的名字，音符排得干干净净，一个涂改都没有。他说，唱不唱随你。纸却是三天前就誊好的，边角压得很平。"},
    {t:"n", x:"苏景行在旁举起手机录下这一幕，低声说『小太阳的十八岁，得存着』；沈时雨破天荒笑出了声，被顾知遥逮到，两人又拌了一句嘴。镜头把这些都原样收了进去，连一点杂音都没落下，像怕漏掉任何一寸真心。"},
    {t:"n", x:"陆清越把江慕白的盒子翻来覆去看了半天，最后还是舍不得拆那根缎带，只把盒盖掀开一条缝。他抽出指挥棒，学着江慕白的样子在空中比划了两下，差点戳到吊灯。江慕白别过脸去，肩线几不可察地动了一下。温以恒抬手把吊灯往旁边拨了拨，没说话，只是笑。"},
    {t:"n", x:"窗外夜色很软，直播间的弹幕还在刷，有人猜他许了什么，有人只刷着生日快乐。远处海面的方向传来一声很闷的船笛，飘进来又被风吹散。你低头看瓶子里那颗糖纸星星，心想，有些愿望不必说破，因为它早就长成了日常里的光，亮在你没注意的角落，亮了很久，也还会继续亮下去——比烛火长久，比镜头诚实，比任何一句告白都安稳。"},
    {t:"sys", x:"【星途练习生·团综】陆清越十八岁生日企划录制完成。距离团综终章，还剩最后一期。"},
    {t:"end"}
  ]
});


// ===== ch34.js =====
// 第三十四章 · 团综终章·给彼此的信 —— 团综收官（week:18）
window.STORY.push({
  id: "ch34",
  title: "第三十四章 · 团综终章·给彼此的信",
  phase: "团综",
  week: 18,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"第18周，团综最后一期录制。漂流屋的客厅今晚没有灯串，只有一圈暖黄的落地灯，把七个影子温柔地拢在一起。茶几挪到了正中，七把椅子围成半圆，椅背上还搭着谁忘了收的毛巾。茶几上摞着七只信封，封口处印着各自的名字，字是上一周大家一起写的，笔迹新旧不一，像某种郑重的约定，也像这一程终于要交到彼此手里的答卷。"},
    {t:"n", x:"江慕白坐在最外侧，细框眼镜后的灰眸难得没有压强。他面前也摆着一只信封，比别人的厚些，边角压得齐整，像他一贯的作风——连交心都要交得规整。窗外的海在夜里只剩一条很淡的线，远处偶尔过去一辆车，光扫过天花板，又走了。『最后一期，不比舞台，只比真心。』他说这话时，声音比往常轻，却比任何一次判词都重，落进每个人耳朵里，久久没散。"},
    {t:"d", who:"江慕白", x:"给彼此的信——写给一年后的我们。谁先来？", fx:"neutral"},
    {t:"n", x:"客厅很静，落地灯的光在每个人脸上缓缓挪过。这一年里，这间屋子听过争论、听过笑、听过半夜的吉他声，也听过警笛和输液瓶的滴答，却很少像此刻这样，安静得能听见信封被捏紧的轻响，以及谁都不愿先打破的、一种近乎珍惜的沉默。落地灯的灯罩上落了点灰，光就从那点灰后面漏出来，把七个人的侧脸照得毛茸茸的。"},
    {t:"choice", prompt:"你要让谁先读？", options:[
      {x:"“让小太阳先，他最藏不住话。”", heart:{陆清越:2}, cb:"陆清越蹦起来，信封都拿反了，金色的发顶晃成一小团光，逗得沈时雨也弯了嘴角。"},
      {x:"“以恒哥吧，他总把话说给别人听。”", heart:{温以恒:2, 沈时雨:1}, cb:"温以恒一愣，笑得眼角软了：『小队长，倒是懂我。』"}
    ]},
    {t:"n", x:"温以恒的信很短。他说，这一年在厨房学会的，比从前二十四年都多；最骄傲的不是哪顿饭，是某天发现，有人开始替他记着『以恒哥别太晚睡』，有人在他晕倒那回轮流守着，没让他一个人。『原来被惦记，是这种滋味。』他念到这句，声音低下去，指尖却弯起来，像把这句话悄悄攥暖了，藏进了围裙口袋。念完他喝了口水，杯底磕在茶几上，很轻的一声，像给这段话盖了个章。"},
    {t:"d", who:"温以恒", x:"……所以明年，也请继续麻烦我。", fx:"shy"},
    {t:"n", x:"沈时雨的信抖得厉害，纸角被他攥出了褶。他说从前不敢想自己会被需要，现在每天最盼的，是收工那句『以恒哥，明天见』。信纸上的字写得比平时大，一笔一笔压着格子，像怕谁看不清。读到一半他停住，喉头动了动，没出声，温以恒悄悄把纸巾推到了他手边，像早料到这一刻会来，也早准备好了接住它。"},
    {t:"d", who:"沈时雨", x:"我……我会努力，不拖大家后腿。", fx:"sad"},
    {t:"n", x:"念完，他低着头把信折好，手指还在微微抖。温以恒伸手揉了揉他后脑勺，没说话；你看见他肩膀慢慢松下来，像有什么一直绷着的东西，终于被这间屋子稳稳接住了，没让它掉在地上。"},
    {t:"danmaku", items:[
      "慕白最后的判词|我又被上了一课",
      "温以恒那句请继续麻烦我|以恒哥破防了",
      "陆清越的小太阳信|小太阳永远的神",
      "知遥耳尖红了|嘴硬王者没跑了",
      "苏景行的老照片|竹马这一块",
      "林墨轩舞台见|老林你话真少",
      "这一年是我们|蹲一个结局选择夜"
    ]},
    {t:"n", x:"顾知遥的信只写了三行，字迹却很用力，力透纸背。『队长大人，下次布丁归我。还有——别总一个人扛。』他念完别过脸，耳尖红得藏不住，被苏景行在旁边轻轻笑了一声，他抬手作势要打，到底没舍得真落下，只把信紧紧攥成了胸口一小团温热。落地灯的光挪过去，照见他袖口那道昨天被器材刮出来的口子，他自己拿线缝过，针脚歪歪扭扭。"},
    {t:"d", who:"顾知遥", x:"哼，才不是关心你。", fx:"blush"},
    {t:"n", x:"轮到苏景行。他拆得很慢，抽出的却不是信，是一张旧照片——你们七岁在巷口老槐树下的合影，边角磨得发白，两个小孩笑得没牙关。他把照片举起来，灯影里，连江慕白都多看了两眼。照片背面用铅笔写着一行小字，年份，还有四个字：还没散场。"},
    {t:"n", x:"那张照片你也有一张，夹在旧钱包里，边角都磨毛了。七岁的你和七岁的他，一个笑得缺了门牙，一个故作严肃。苏景行把照片轻轻放回茶几，像把一段太长太久的陪伴，轻轻搁在了所有人面前，不声不响。"},
    {t:"m", x:"你认出那是你俩第一次同框。他指尖在上面停了停，没说话，只是笑，像把二十年的默契都按进了那张薄薄的相纸里。"},
    {t:"n", x:"陆清越的信画满了小太阳，最后一句是『希望队长哥哥每天都笑，这样我的魔法就一直有效』。林墨轩的信最短，只有一句：『舞台见。』——惜字如金，却比谁都准，像他每次点头的那一下，不喧哗，却把所有的认真都压在了两个字里。"},
    {t:"n", x:"他念完那三个字，屋里安静了两秒。有人没听懂，有人听懂了。他把信纸按原折痕折回去，压平，放回茶几，动作干净得像收一段刚录完的音轨。江慕白看了他一眼，什么也没说——那是他们之间惯常的、不用出声的过招。"},
    {t:"choice", prompt:"轮到你了。你要——", options:[
      {x:"拆开自己的信，念给所有人听。", heart:{苏景行:1, 林墨轩:1}, cb:"信上是你三个月前写下的：『谢谢你们，让我敢当这个队长。』灯圈轻轻晃了一下，有人轻轻吸了吸鼻子。"},
      {x:"把信收好，先说一句此刻的话。", heart:{温以恒:1, 江慕白:1}, cb:"你说：『这一年，是我们。』客厅安静了一瞬，又被暖黄填满，像被这句话轻轻抱了一下。"}
    ]},
    {t:"n", x:"你念完的时候，落地灯的光正好挪到茶几中央，照在那七只信封上。温以恒起身把每个人面前的水杯都续了一遍，续到你的时候，手停了一瞬，像想说什么，最后只把杯子往你手边推了推。"},
    {t:"n", x:"最后是江慕白。他起身，把信封轻轻放在茶几中央，像落一枚印章，也像把这一年所有的挑剔与护短，都盖了章、收了尾。落地灯把他的影子拉得很长，覆过你们所有人的鞋尖，像一个不动声色的、把所有人都拢进来的拥抱。"},
    {t:"d", who:"江慕白", x:"我的判词，留给今晚。", fx:"cool"},
    {t:"n", x:"他开口，声音还是那样低，像把一年的重量压进几句话里，尾音在空旷的客厅里散得很慢。『你们七个，从一百颗星里落进同一片海里。我雕过你们，也从你们身上，看见了我自己少年时想成为的样子——那时我也以为，完美是要一个人站到最高处，直到看见你们肯为彼此弯下腰，才明白那不是弱，是另一种强。』"},
    {t:"d", who:"江慕白", x:"最后一课——所谓完美作品，从来不是一个人站到最高处，是你们愿意为彼此，把光分出去。", fx:"neutral"},
    {t:"n", x:"他说到『分出去』时，目光依次扫过每一个人，最后停在你脸上，多停了半秒。那半秒里没有压强，只有一种近乎骄傲的、被验证过的确信，像匠人终于肯对自己的作品点头——不是因为完美，是因为活生生的、会彼此护着的、七个名字凑在一起才成立的温度。你听见身后有人很轻地把椅子往后挪了半寸，又挪回来。"},
    {t:"n", x:"镜头红灯熄灭的瞬间，他补了一句，轻得几乎听不见：『小队长，下一程，看你的了。』这句话他没写进信，却比信里任何一句都像判词——不是给你的结论，是给你的信任，像一个一直站在你身后的人，终于肯把你推到台前，自己退成了光里的背景。"},
    {t:"n", x:"录制结束，七人散在夜色里，却没有真的散。门口有人互相揉了揉头发，有人约了明早的早餐，陆清越还举着那只小瓶子不肯放，说要替你收着愿望。夜里的风有点凉，把门口那串风铃碰响了两声。茶几上的信封被一只只收回去：陆清越那只塞进了背包最里层，说要等一年后再拆；沈时雨把信重新折成三折，和之前那张方胜纸放在一起；苏景行把老照片收回钱包，夹层里并排着两张——一张七岁，一张上周在雨里拍的。你知道，今晚还有一道门没开——结局选择夜。明早，系统会把心动值最高的人，领到你面前，而无论那是谁，屋里的灯都会为你们一起亮着。"},
    {t:"sys", x:"【星途练习生·团综】全部录制完成。明晚开启『结局选择夜』，请队长做好准备。"},
    {t:"end"}
  ]
});


// ===== ch35.js =====
// 第三十五章 · 长风与信 · 苏景行线（结局章）
window.STORY.push({
  id: "ch35",
  title: "第三十五章 · 长风与信 · 苏景行",
  phase: "结局",
  week: null,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"结局选择夜之后的第三天傍晚。苏景行把你约到了老地方——城东那栋老居民楼的六层，他家里腾出来的那间小工作室。走廊的声控灯得跺两下才亮，第二下总比第一下响。消息里他没说叫你上去做什么，只留了四个字：来听个东西。门虚掩着，缝里漏出一线暖黄的台灯光，像有人提前替你把路留好了。楼下修车摊收了，只剩一地油渍和一把被人踢翻的小马扎。"},
    {t:"n", x:"这间小工作室堆着合成器、旧海报和一箱箱没拆封的唱片。墙上钉着一张手写的和弦表，边角卷起，被图钉按出四个孔。他背对着门调音，亚麻色头发乱糟糟的，像刚睡醒，又像刚写完歌，指尖还沾着一点铅笔灰，是常年写谱的人才有的痕迹。角落那台老风扇转一下停一下，把一张卷了边的海报吹得鼓起来，又落回去。空气里混着旧纸张和咖啡的味，还有一点电位器受潮后微酸的金属气。他没多寒暄，只把椅子挪近，挪得椅子腿在木地板上叫了一声，像有很多话，又觉得不必急着说。"},
    {t:"d", who:"苏景行", x:"先听个东西。耳机只有一副，凑合一下。", fx:"sleepy"},
    {t:"n", x:"他把耳机一半扣在你耳边，自己戴另一半。Demo响起的头三秒，你听见一段采样——风穿过窄巷的呼啸，混着远处一声自行车铃，还有两个小孩追逐的笑。声音被二十年压得发闷，底噪沙沙的，像旧磁带擦过磁头，却清晰得像昨天。他没说话，只抬起下巴朝耳机那侧点了点，示意你听完再问。"},
    {t:"m", x:"那一串声音像钥匙，咔哒，打开了你忘了多久的某扇门。门后全是槐花的甜，和某个再没回去过的下午。"},
    {t:"heart", who:"苏景行", delta:1},
    {t:"n", x:"你闭上眼。风声里裹着孩童的笑，像隔了二十年的回声忽然贴到耳畔。你几乎能闻见那年巷口槐花的甜，能想起冰棍老伯的铃声从街尾晃到街头的节奏，连那辆二八大杠的链条声都在。耳机线不短，他却没往旁边坐，肩膀离你只隔一指宽，那点热度隔着薄毛衣递过来，稳稳的，一点没晃。"},
    {t:"d", who:"苏景行", x:"认出来没？", fx:"smile"},
    {t:"n", x:"认出来了。那是你们小时候住的那条巷口。老槐树把影子铺了一地，自行车铃是卖冰棍老伯的——夏天他骑车从街尾晃到街头，铃响一次，你就知道该往门外跑一次。这段声音二十年前录进他手机里，他一直没删。不是忘了，是舍不得，像把一段童年存成了不会过期的糖。他说，有阵子几乎天天听这一段：写不出歌的时候听，想家的时候听，半夜睡不着的时候也听，隔着一副耳机把那条巷子从头走一遍。录音里笑声最响的那一段，是他抢你手里那半根冰棍的那回，你追了他半条巷子，最后两个人在槐树下蹲着，把化了一半的那根分着吃完，甜水顺着指缝流到手背。"},
    {t:"d", who:"苏景行", x:"怕哪天丢了，就再也找不回那个敢跟你说永远的小鬼了。", fx:"neutral"},
    {t:"n", x:"他说得轻描淡写，指节却把耳机线绞紧了一圈，塑料外皮被拧出很细的一声响。桌角压着一叠谱纸，最上面那张写着第七版，副歌那行字被划掉又重写，墨迹叠了三层，最后一行旁边只有两个小字：别删。纸面还有两处咖啡渍洇开的圆，边缘泛黄。"},
    {t:"choice", prompt:"你要怎么接这段采样？", options:[
      {x:"“你藏着这个，藏了二十年？”", heart:{苏景行:3}, cb:"他笑：“宝贝，我藏的何止这个。”手指停在你手背上，没挪开，温度透过皮肤，慢得像潮。"},
      {x:"把耳机取下来，还给他。“先听你现场的。”", heart:{苏景行:2}, cb:"他挑了下眉，顺手把谱纸抽过来卷成筒，在你肩上敲了一下：“行啊，那就听活的。”"}
    ]},
    {t:"n", x:"他关掉Demo，从椅背上抓下外套往你肩上一搭，拉你起身。楼梯间的灯要跺脚才亮，他就跺得很有节奏，一级一级，像给这段路配了拍。推开单元门，夜风迎面灌进来，把那股旧纸张的味儿一下吹散，只剩槐树的气味跟上来。"},
    {t:"bg", v:"night"},
    {t:"n", x:"巷口的路灯还是旧时的暖黄，光落在水泥地上，照出一小片带毛边的圆。老槐树粗了一圈，树皮的纹路却没变，像岁月只肯在外圈绕，不肯动里头那点东西。风里有一层槐叶被夜露泡过的青气，混着街角便利店热关东煮的味道，从巷子那头慢慢荡过来。一辆电动车驶过，喇叭短促地响了一下，很快就没了。你们站到当年并排刻下名字的那块砖前——砖在墙体最底下那一排，离地不到一掌，当年得蹲着才够得着。两道歪扭的刻痕还在，被岁月磨得浅了，却没消失，像两个小孩执意要留下的、对世界的第一次宣言。他蹲下去，用手机电筒照了照，光一晃，那些年轮似的凹凸就浮起来——你的名字在前，他的在后，中间隔着谁用钥匙多划的一道横线。他说，写新歌那晚他反复听这段采样，听到第四十遍，才敢把“永远”两个字写进副歌。"},
    {t:"choice", prompt:"你要不要碰那道刻痕？", options:[
      {x:"蹲下去，用指尖把那两个名字描一遍。", heart:{苏景行:2}, cb:"指腹划过砖面，粗粝，还带着一点白天没散尽的余温。他蹲在旁边没出声，等你描完最后一横，才把手也放了上去。"},
      {x:"就站着看，不上手。", heart:{苏景行:1}, cb:"你把两只手插回兜里，看着那道浅痕。他笑了一声，说不急，砖又不会跑。"}
    ]},
    {t:"n", x:"那只手在砖上又停了两秒，才收回来。"},
    {t:"n", x:"他站起来，从外套内袋里摸出一个牛皮纸袋，袋口被反复折过，折痕很深，捏起来硬硬的。倒出来是一枚铜校徽——边角已经磨圆，正面那两个字缺了左下的一角，背面的别针歪着，缠着两层黑胶布，胶布边缘发白发毛，一碰就有细小的毛絮翘起来。他没有递给你，只托在掌心，像托着一件贵重又轻得过分的东西。他说，小学四年级那天你把胸前那枚摘下来扣给他，铜片还带着体温，还说自己反正不爱戴、跑操的时候嫌它响。原话是以后还一个更好的，他记了十几年，一直没还上——不是忘了，是每次想还的时候，都觉得还没攒够。那两层胶布是他自己缠的，因为怕再掉；掉了他就真没法还了。"},
    {t:"d", who:"苏景行", x:"想过还你一个更好的。后来发现，好像没有比这个更好的了。", fx:"neutral"},
    {t:"d", who:"苏景行", x:"小时候我跟你约定，长大要一起站到最大的舞台上。现在舞台有了，我想加一条——", fx:"blush"},
    {t:"n", x:"他顿了顿，没说完。话卡在喉咙口，像怕一出口就太重，又像在等你先给一个眼神。街角便利店的光映在他侧脸，他把那点犹豫悄悄咽了回去，换成一个更软的笑，指腹在那枚校徽上压了一下。然后他重新从兜里摸出那张磨白的老照片——团综那晚他读信时抽出的那一张。七岁的你们在槐树下，笑得没心没肺，一个缺了门牙，一个故作严肃。相纸的边角已经起毛，被他用透明胶从背面粘过两次，胶带泛黄。他说照片和校徽一直放在同一个内袋，一个硬的，一个软的，走哪儿带哪儿；他说照片里那棵树，比现在细整整一圈。"},
    {t:"d", who:"苏景行", x:"永远这个词，我很少说。但对你，我愿意说一遍，再说一遍。", fx:"smile"},
    {t:"phone", who:"温以恒", msgs:[
      {f:"them", x:"小队长，今天按时吃饭没？", time:"21:30"},
      {f:"me", x:"在巷口，挺好的。"},
      {f:"them", x:"那就好。小太阳刚还问你呢。", time:"21:31"},
      {f:"them", x:"回来路上慢点，楼下有人给你留了宵夜。", time:"21:32"}
    ]},
    {t:"n", x:"不远处，漂流屋的群聊还在手机里震。温以恒问你按时吃饭没，陆清越甩来一串小太阳，顾知遥补了句“队长大人又夜游”，林墨轩只发了一个句号，沈时雨在下面小心翼翼地跟了一句“路上小心”。苏景行把屏幕朝你偏了偏，回了一个字：在。团的生活没散，只是今晚，这条巷子只属于你们两个，连风都识趣地放轻了脚步。"},
    {t:"m", x:"你想说点什么，喉咙却被风吹得发紧。他伸手，额头轻轻抵住你的，没再往前，像把所有的近，都留在这一寸刚刚好的距离里。"},
    {t:"d", who:"苏景行", x:"不用现在答。我只是把永远放这儿了，你什么时候来取都行。", fx:"smile"},
    {t:"n", x:"风又穿过巷口，和Demo里那声自行车铃一模一样。这一次，你在现场，他在身边，老槐树的影在你们脚边叠在一处，像一个没说完的承诺，终于有人陪着一起守。他把那枚校徽塞回牛皮纸袋，折好袋口，按进外套内袋——动作很慢，像在给什么东西盖上盖子，又没打算真盖严。然后把耳机挂在脖子上，笑意懒散：“回去吧，小队长，明天还有人等你吃早饭呢。”路灯把两个人的影子拉得老长，又慢慢交叠，像二十年前那张照片里，怎么也分不开的两个小孩。"},
    {t:"verdict", x:"长风替你说完了二十年的话。\n槐树下的名字还没淡。\n他把永远，轻轻放在你手边。\n你不必此刻回答。"},
    {t:"end"}
  ]
});


// ===== ch36.js =====
// 第三十六章 · 静音键 · 林墨轩线（结局章）
window.STORY.push({
  id: "ch36",
  title: "第三十六章 · 静音键 · 林墨轩",
  phase: "结局",
  week: null,
  nodes: [
    {t:"bg", v:"studio"},
    {t:"n", x:"结局选择夜之后的第五天。林墨轩发来的消息只有两行：一个地址，一个时间。没有多余的字，连句号都省了。你按导航穿过半座城，找到城郊那片旧厂房改的艺术区——红砖墙爬了半面爬山虎，铁楼梯被雨蚀出褐色的斑，三楼尽头那扇门上钉着一块手写木牌，字很小，笔画干净：画室，勿访。时间下面他另外加了一行：今天除外。玻璃上凝着黄昏的橘，像有人提前把一盏灯放在了里面。你抬手敲门之前，先在门外站了两秒。"},
    {t:"n", x:"推门进去，先闻到的是松节油——那种微甜又发涩的气味，混着亚麻油和旧木头的灰味。画室比外面看着大，北墙留了一整排高窗，光斜着劈进来，把空气里浮着的细尘照成一根根柱子。地上立着七八个画框，有的蒙着白布，有的露出半截没画完的底色；靠窗的矮桌上摊着一排铅笔，从4H一直排到6B，长短不一，最短的那支只剩指甲盖那么长。墙角摞着一叠裁好的画纸，最上面那张压着一块被捏得发亮的橡皮，窗台上一只缺口的搪瓷杯里插着两支秃了头的画笔。暖气片还温着，偶尔咔一声。屋里没有开顶灯，只有桌角一盏台灯，光圈很小，刚好罩住那本摊开的册子。"},
    {t:"n", x:"他坐在靠窗的矮桌前，正低头翻一本素描册。翻得很慢，一页要停上几秒，拇指压在纸边，像怕它自己合上。听见门响，他的指尖停在一页上，没抬眼，只把册子往身侧挪了半寸——挪得不重，但足够让你看清他不想让你先看见。他先开口，三个字：“来了。坐。”"},
    {t:"d", who:"林墨轩", x:"画册里记了些东西。先听琴。", fx:"neutral"},
    {t:"n", x:"画室深处立着一架老立式钢琴，漆面泛着温润的光，琴盖上有一道浅浅的划痕，像被谁用钥匙尖拖过一次，划痕里积了一点灰。他坐下，把琴凳调到最矮的那一档，那是他的高度；琴凳的布面正中磨白了一片，边缘起了细细的毛球。谱架上没有谱，琴盖内侧贴着一张泛黄的调音单，日期是上个月；琴腿边靠着一个小木盒，盒盖开着，露出几块叠得整齐的擦琴布。"},
    {t:"n", x:"他抬手，手指落在键上。第一声就偏了半个音——不是错指法，是按下去了，音却矮了半度，像一块石头没踩稳。他顿住，指尖在键上悬了两秒，然后往下走。第二声也错了，一个小节里两个音撞在一处；第三个音他停了一下，才按下去。他最终把手从琴键上收回，在裤腿侧面按了一下，力道大得布料发出一点摩擦声。"},
    {t:"m", x:"林墨轩弹走音。你第一次见。他的耳廓，在暮色里，一点点红了。"},
    {t:"d", who:"林墨轩", x:"……手生了。", fx:"shy"},
    {t:"n", x:"他没回头，也没解释。画室里安静得能听见墙上挂钟的秒针——那是一只很旧的木壳钟，走一下要犹豫半拍，钟摆擦着空气，沙、沙。他把手重新放回琴键，又收回来，像在等一个自己给不了的许可。窗外的橘光往墙根那边退了一格，恰好退到他手背的高度，把指节的影子落在琴盖上。"},
    {t:"choice", prompt:"你要怎么接这一刻？", options:[
      {x:"走到琴边，把手覆上他的手背。“错了也好听。”", heart:{林墨轩:3}, cb:"他没抽手，指节在你掌心慢慢松开，像卸下什么。"}
    ]},
    {t:"n", x:"他终于把那本册子推到你面前。册子是硬壳的，牛皮纸封面，边角被磨得发亮，书脊上压着一道折痕，针脚缝得很密。他没有翻到第一页，而是把整本塞进你手里——塞过来的时候，指腹在封面上多停了半秒才撒开。"},
    {t:"d", who:"林墨轩", x:"从这个赛季第一天，就在画。没给你看，是怕分你心。", fx:"neutral"},
    {t:"n", x:"翻开第一页，日期是初评级那天。整个赛季的素描都在这里，往后一页不落：练习室里你低头改流程表的侧影，铅笔帽还咬在嘴里，纸上连嘴角的弧度都留着；舞台上你转身时扬起的衣角，被画成几道干脆的斜线，线条一笔到位；天台你裹着毯子看星的背影，毯子的褶子画得很细，肩线只用三笔。每一张的角落都标着日期和地点，小字写得规整，像给一段一段日子编号。中间有几页被撕掉了，撕口笔直，是拿尺子逼着撕的。"},
    {t:"n", x:"有一张你多看了两眼——决赛周那天，凌晨的走廊，窗玻璃上结着雾，你站在窗前，背对着画的人。那一张的阴影压得比别的都深，背景几乎全黑，只有你的轮廓被留白留了出来，像黑暗里先有了人，才有光。纸的右下角被反复摩过，起了毛，又压平，再起毛。最后一张是全空的，整页纸干干净净，只在正中间写了一行小字，笔画很轻，像怕压坏了纸：主角一直是一个人。他指尖点了点那行字，没说话。"},
    {t:"d", who:"林墨轩", x:"现在，想补上另一个人。", fx:"smile"},
    {t:"choice", prompt:"你要怎么翻这本册子？", options:[
      {x:"从头再翻一遍，慢慢看。", heart:{林墨轩:2}, cb:"你翻得很慢，他就站在旁边看你翻，中途伸手把台灯拧亮了一档，灯光落下来，那些铅笔线忽然都立了起来。"},
      {x:"“那最后一页，你想画什么？”", heart:{林墨轩:2}, cb:"他没立刻答，拿起桌上的铅笔在指间转了一圈，又放回原处：“画你抬头看画的样子。”"}
    ]},
    {t:"phone", who:"温以恒", msgs:[
      {f:"them", x:"小队长，画室冷，记得披外套。", time:"19:02"},
      {f:"me", x:"披了。他弹琴给我听。"},
      {f:"them", x:"那就好。别耽误人家太久。", time:"19:03"}
    ]},
    {t:"n", x:"门被敲了两下，很轻，像敲的人怕惊着屋里的人。进来的是沈时雨，怀里抱着一个不锈钢保温壶，帽檐压得很低，看见满墙的画框先愣了一下，脚步停在门口没敢往里迈。壶盖上缠着一圈胶带，壶身磕掉了一小块漆，是漂流屋那只用了整个团综期的旧壶，壶嘴还烫手，冒着一点白汽。"},
    {t:"d", who:"沈时雨", x:"队长……以恒哥说画室冷。我、我放这儿就走。", fx:"shy"},
    {t:"n", x:"他把壶放在门边的矮凳上，指尖在壶身上蹭了一下才收回去。走到门口又回头看了眼墙上那排画框，像想说什么，最后只把门轻轻带上，留了一条缝。脚步声沿着铁楼梯一级级往下，越来越轻，被晚风收走。"},
    {t:"heart", who:"林墨轩", delta:1},
    {t:"n", x:"画室重新静下来，只有窗外最后一点橘光在退。温以恒的叮嘱停在手机里，沈时雨的脚步也在楼下散尽了——团的日子还在继续，只是此刻，画里画外只有你。那只保温壶搁在矮凳上，热气从壶嘴一线一线往上走，在光里看得清清楚楚。挂钟走到整点，敲了一声，很轻，像怕扰了谁。"},
    {t:"n", x:"他走到墙边，把其中一个蒙布的画框掀开一角，又放下。白布下面是一幅刚起了稿的画，只有炭笔的轮廓，看着像一间厨房，灶台上摆着七个杯子，杯子的高矮各不相同。他没解释，把布重新盖严，边角压了压。"},
    {t:"m", x:"你想说很多，最后只把册子合上，轻轻放在他手边。"},
    {t:"d", who:"林墨轩", x:"不必回。我只是把话，画完了。", fx:"smile"},
    {t:"n", x:"他伸手，与你指尖相触，没再靠近。他的手比琴键凉一点，指腹上有一层薄茧，是常年按弦和握笔的人才有的。钢琴上还留着刚才那两个走音的余温——琴弦没完全静下来，能听见一线很细的嗡鸣，凑近了才听得见。"},
    {t:"n", x:"他按下静音键，屋里只剩你们的呼吸。暮色彻底沉下去，画室像被收进他那本册子的某一页。远处有火车经过，声音从地板底下传上来，闷闷的，把窗玻璃震得轻轻响了一下。片刻之后，他重新把手放回琴键上，静音键还按着。这一次一个音都没错，只是所有声音都被压在毡子里，闷闷的，像贴着耳朵说。最后一个和弦他没放，就那样让它在沉默里一直持续着，直到余音彻底散完，才把手抬起来。灯没开，那本册子摊在你手边，翻开在最后一页。窗外最后那点橘色也退干净了，画室里只剩下你和他，还有一只搁在矮凳上、还没凉透的保温壶。"},
    {t:"verdict", x:"整季的素描，主角都是你。\n他第一次弹错，因为是你。\n静音键按下，话却说完了。\n画里的人，终于等到了另一个。"},
    {t:"end"}
  ]
});


// ===== ch37.js =====
// 第三十七章 · 恒温 · 温以恒线（结局章）
window.STORY.push({
  id: "ch37",
  title: "第三十七章 · 恒温 · 温以恒",
  phase: "结局",
  week: null,
  nodes: [
    {t:"bg", v:"villa"},
    {t:"n", x:"结局选择夜之后的第二天，凌晨三点五十。你回了漂流屋，从三楼下来的时候，走廊的夜灯还亮着，橘色的一小格，隔几步一盏，把地毯照出深浅不一的道。楼梯扶手的漆掉了一小块，露出底下深色的木头。别墅里静得能听见冰箱压缩机启动的嗡声，还有厨房水龙头关不严、隔一会儿滴一下的那种响。窗外偶尔有一声很远的鸟叫，短促的一下，又没了——这个点醒着的鸟不多。"},
    {t:"n", x:"温以恒照例天不亮就进了厨房。他穿着那件洗得发软的灰色长袖，袖口卷到手肘上面一点，小臂上有一道很淡的烫痕，是去年煎鱼时溅的。外面系着围裙——浅蓝格子的，右下角有一块洗不掉的番茄渍，已经褪成了淡粉色。灶上搁着那口很旧的煎锅，锅底有一圈常年烧出来的深色。煎蛋的滋滋声比闹钟还准。灶台上一字排着七个杯子，杯柄朝着同一个方向，像有人拿尺子量过。你在门框边停了一下才迈进去。他听见脚步声回头，笑得眼角很软，眼下有一层很淡的青。“小队长，今天想吃什么？我来做就好。”像说了无数遍的话，从没问过自己累不累。"},
    {t:"d", who:"温以恒", x:"你再去睡会儿，早餐马上好，还好吗？", fx:"smile"},
    {t:"choice", prompt:"你要怎么做？", options:[
      {x:"走进厨房，把锅铲轻轻拿过来。“今天，换我来。”", heart:{温以恒:3}, cb:"他愣住，手悬在半空，随即乖乖让开了位置，眼里有一点没藏好的光。"}
    ]},
    {t:"n", x:"你第一次站在他的位置。灶台比他矮不了多少，锅却很沉，手腕要一直端着；油星子溅上手背是细小的、弹开的疼。你把他那条围裙从挂钩上取下来系上，带子绕到身后，多出长长一截，垂在腿边晃。凌晨四点的厨房很静，窗外还是浓得化不开的墨蓝，只有对面人家亮着一格黄色的窗。你照着他的习惯做事：煎两颗溏心蛋，蛋黄要能流，边缘要焦一圈；牛奶热到锅边起细泡就关火；再把每个人的杯子摆回老地方——杯底对齐橱柜上那七道浅浅的划痕，那是他一年里磨出来的。"},
    {t:"n", x:"打第三颗蛋的时候，一小片蛋壳掉进碗里。你拿筷子去捞，滑了一下，又滑了一下。他从门边走过来，没说别的，只把食指伸进碗里，一挑就出来了，指尖在水龙头下冲了冲，顺手把火拧小半格。整个过程没超过十秒，他又退回了门边。"},
    {t:"m", x:"原来他每天的“顺便”，是要站在这里，记住七种口味，在谁都没醒的时候，把一天的第一口温热摆好。"},
    {t:"n", x:"他倚在门边看你忙，没抢，只是轻轻笑。他站的位置正好背着光，晨光还没爬上来，他的眼睛却比平时亮，像是被灶上那点火映的。有一回你转身差点撞上他，他侧了半步让开，指腹在门框上按了一下。他手里什么也没拿，两只手空着，反倒显得不知道往哪儿放，最后插进了裤子口袋。"},
    {t:"n", x:"陆清越揉着眼睛飘下来，睡衣领口歪着，发顶翘起一小撮，怀里还夹着一只印了应援色的抱枕，是粉丝送的那只。他看见你掌勺，惊得整个人都清醒了一度：“队长哥哥在做饭？！”他刚往灶台边凑了两步，就被温以恒笑着按了回去，连人带抱枕一起按回被窝的方向。他退到楼梯口还不忘补一句：“那我要吃两个蛋——”声音拖得很长。"},
    {t:"d", who:"温以恒", x:"让他们多睡会儿。你第一次碰锅，还好吗？", fx:"smile"},
    {t:"heart", who:"温以恒", delta:2},
    {t:"n", x:"沈时雨是被香味引下来的。他站在楼梯口犹豫了两秒才走过来，先在水池边洗了手，然后把袖子往上撸了两折，一声不响地开始摆筷子——七副，按老位置，筷尖朝左。他摆得很慢，每一副都要把尾端对齐桌沿，像在做一件很正式的功课，摆完还退后半步看了看，又回去把第三副挪正了一点点。"},
    {t:"d", who:"沈时雨", x:"队长……我、我摆好了。要不要我去叫大家？", fx:"shy"},
    {t:"n", x:"楼梯上传来拖鞋声。顾知遥披着一件深色家居服下来，头发还压着一边的弧度——他起床后要花一小时打理外表，这是难得一见的样子。他径直拉开冰箱门，弯腰翻了半天，没翻到，直起身时正看见灶上那口锅。坐下之前，他顺手把搭在椅背上的毛毯扯下来，往温以恒肩上一搭，动作快得像没发生过。"},
    {t:"d", who:"顾知遥", x:"……豆浆。无糖的。别的我也不挑。", fx:"blush"},
    {t:"n", x:"你把那盘蛋推到他面前，自己在对面坐下。这是这间屋子里，头一回有人把早餐，端给他。蛋是他习惯的那种溏心，边缘焦了一圈，酱油按他自己的量只滴了三滴。盘子推过去的时候，瓷底在木桌上蹭出很短的一声。他低头看了一会儿，没动筷子，手指搭在桌沿上，指节比昨晚松。"},
    {t:"choice", prompt:"冰箱贴就在他手边。你要——", options:[
      {x:"走过去，把那块冰箱贴翻过来看背面。", heart:{温以恒:2}, cb:"背面用铅笔写着一行小字，浅得快看不见：今天也辛苦了。旁边还有更小的一列日期，一天一行，最近的一行停在昨天。"},
      {x:"什么也不翻，把筷子递到他手里。", heart:{温以恒:2}, cb:"他接过去，指尖碰到木筷的时候停了一下，说了声谢谢，很轻——这两个字他平时说得最多，收得最少。"}
    ]},
    {t:"d", who:"温以恒", x:"其实我也有撑不住的晚上。只是习惯了先顾着你们。", fx:"shy"},
    {t:"n", x:"他说起某次晕倒后被你们轮流守着——那夜他醒过来，床边坐着三个人，桌上堆着一排半途换下来的毛巾，凉的摞在左边，热的摞在右边，谁分的他都不知道。他说起自己在冰箱贴背面写“今天也辛苦了”，本来是写给自己的，写着写着，变成了写给第二天开冰箱的人看的。窗外的墨蓝开始往灰里走，有一线很淡的白从楼顶那边压下来。你忽然明白，恒温不是不会冷，是有人一直替大家焐着。"},
    {t:"phone", who:"苏景行", msgs:[
      {f:"them", x:"听说队长大人下厨了？", time:"04:12"},
      {f:"me", x:"以恒哥的位子，我替他坐了。"},
      {f:"them", x:"行啊，那明天我蹭饭。", time:"04:13"}
    ]},
    {t:"n", x:"群聊在手机里跳。苏景行发了张你们小时候的合影——照片里两个小孩蹲在巷口，手里各捏着半根冰棍，一个笑得缺了门牙；顾知遥甩来一句“队长大人下厨，太阳打西边出”；林墨轩只回了两个字：辛苦；沈时雨偷偷发来一张他刚摆好的筷子照，角度拍歪了，桌沿占了半张图。团的生活没停，只是今早，这桌早餐只属于你们两个。"},
    {t:"m", x:"你想说很多，最后只把牛奶往他手边推了推，像他每次对你那样。"},
    {t:"n", x:"你起身要收碗，他先一步按住你的手腕，指腹搭在你的腕骨上，说自己来就好。你没让。两个人在桌边僵了半秒，他先松开手，笑着往后靠进椅背，两只手都放到了桌子底下，像被缴了工具的人。碗碟不多，水冲两遍就干净了；你把它们倒扣在沥水架上，摆成他平时的顺序——大的在外，小的在里侧，勺子单独一格。晨光照到水槽边缘，水流里浮着细小的气泡。关掉水龙头的一瞬间，屋里安静了一下，能听见楼上有人翻身，床板轻轻响了一声。"},
    {t:"d", who:"温以恒", x:"以后……也让我被你照顾一次，可以吗？", fx:"blush"},
    {t:"n", x:"他伸手，覆上你放在桌面的手，没再动。他的掌心是温的，比刚热好的牛奶低一点温度，指节上有常年握锅铲磨出的硬处，硌着你，却不重。窗外那片墨蓝正一点点被晨光揉软，从窗台流到桌面上，把两双手的影子拉在一起。"},
    {t:"n", x:"你没抽手。他就那样坐着，肩膀慢慢塌下去一寸，另一只手还搭在膝盖上。过了一会儿你才发现，他靠着椅背睡着了——呼吸很轻，睫毛在晨光里投下一道很短的影，眉心那道总也舒展不开的褶，松开了。这是这间屋子里，第一次有人在他的早餐桌上睡着。"},
    {t:"n", x:"陆清越举着手机踮脚往这边挪，被沈时雨一把拉住了袖子，两个人站在楼梯口小声地比划。顾知遥从鼻子里哼了一声，把手边那条毯子抖开，隔空扔过来，毯子落在温以恒肩上，边角盖住他半边手背，他连眼睛都没睁开。你把那盘蛋往他那边又挪了挪，拿盖子扣上保温。厨房的水龙头还在滴，一滴，一滴，晨光已经爬到桌沿了。"},
    {t:"verdict", x:"恒温的人，第一次被人焐热。\n凌晨四点的桌，换了你摆。\n他说，也让我被照顾一次。\n早餐还温着，话也还温着。"},
    {t:"end"}
  ]
});


// ===== ch38.js =====
// 第三十八章 顾知遥线《傲娇宣言》 —— 剧本写手
window.STORY.push({
  id: "ch38",
  title: "顾知遥线 · 傲娇宣言",
  phase: "结局",
  week: null,
  nodes: [
    {t:"bg", v:"banquet"},
    {t:"n", x:"顾家宅邸的宴会厅挑高近两层，水晶灯把整张长桌照得通明，银器与瓷盘在光里低声互映，连空气都显得矜贵。这是顾知遥二十岁生日宴，也是他第一次把你的名字写进邀请名单的末尾，又用钢笔重重圈了一遍，像在宣示某种不肯说出口的主权。门口的侍者接过你的外套，目光在你脸上多停了一秒——今夜你能站在这里，本身就不寻常。你低头看了一眼自己被圈了名的那张请柬，墨迹还新，压在顾家烫金的家徽之下，像一枚不肯被收进抽屉的、小小的叛逃。"},
    {t:"phone", who:"顾知遥", msgs:[
      {f:"them", x:"队长大人，六点准时到。别让我家等。", time:"17:20"},
      {f:"me",   x:"已经在路上了，顾少爷。"},
      {f:"them", x:"哼，迟到的后果你清楚。", time:"17:21"}
    ]},
    {t:"n", x:"香槟的气泡在杯壁碎裂成细密的星点，空气里浮动着白檀混着柑橘调的冷香，像他这个人——看着矜贵疏离，凑近了才闻见一点暖。顾知遥站在你身侧，银灰色的头发比平日更服帖，耳钉换成了一枚你没见过的深蓝，在灯下偶尔闪一下，像他藏起来的那点心思，不肯老实待着。"},
    {t:"d", who:"顾知遥", x:"队长大人，站直一点。别给我家丢人。", fx:"cool"},
    {t:"n", x:"他母亲从远处走来，旗袍上的苏绣牡丹随步轻晃，鞋跟敲在大理石上，一声一声，像在丈量你够不够格站在这里。她打量你的目光像在评估一件藏品，嘴角的弧度却与儿子如出一辙——那是不肯服软的人，才有的、藏在客套里的审视。她开口，“知遥，这位是？”声音很淡，却把顾知遥的脊背悄悄绷直了。你注意到她耳垂上也缀着一枚深蓝的耳钉，与儿子那枚是同一对——原来有些傲气，是会被刻进骨血、再一代代传下去的。"},
    {t:"heart", who:"顾知遥", delta:1},
    {t:"d", who:"顾知遥", x:"一个朋友。", fx:"shy"},
    {t:"n", x:"他说得随意，视线却始终没从你脸上移开，耳尖那点红被鬓角的银灰压着，像雪地里藏不住的炭。你忽然想起初评级那天，他当众质疑江慕白钦点你做队长，嘴上说着“队长大人你行不行啊”，眼睛却亮得藏不住——那时你就该知道，他的刺，从来只对着自己在意的人。如今那点亮，正落在你身上。江慕白那时只淡淡说了句“璞玉”，他便嗤笑出声，说队长大人未必撑得住；可每一次你真的撑住了，他又是第一个把“哼，还行吧”藏进嘴角的人。"},
    {t:"n", x:"酒过半巡，几位世交长辈围拢过来，雪茄的甜苦气漫开，话里话外绕着顾家继承人该定下来了。有人笑着提了门当户对的亲事，顾知遥搭在椅背上的手指，慢慢收紧，指节泛白，像一头被踩了领地的猫，炸着毛，却不肯吭声。长辈压低声音，“知遥，下个月林家的千金回国，你父亲可是念叨许久了——”尾音拖得很长，像一根无形的线，要往他脖子上套。顾知遥的下颌线绷得更紧了，却没看你，只是把你杯里空了的香槟，不动声色地换成了温的柠檬水——他记着你在训练期从不碰冰。"},
    {t:"d", who:"顾知遥", x:"哼，我的事，轮不到别人安排。", fx:"angry"},
    {t:"n", x:"顾父在远处放下酒杯，没接话，只是朝你这边极轻地点了下头，像默许了什么，又像什么都没看见。顾知遥的耳尖，因为这一个动作，又红了一寸——他这般嘴硬，原来也有肯低头的人。你忽然觉得，这座看上去滴水不漏的宅子，其实把最软的那块，悄悄留给了他。"},
    {t:"choice", prompt:"你该怎么接这句话？", options:[
      {x:"那就让他们少操心。", heart:{顾知遥:2}, cb:"顾知遥的耳尖肉眼可见地红了一瞬，别过脸去，指尖却悄悄勾住了你的袖口，像怕你跑了。"},
      {x:"需要我陪你演到什么时候？", heart:{顾知遥:1,温以恒:1}, cb:"温以恒在旁轻笑，往你手里塞了块桂花糕，眼神里全是了然，仿佛早看穿了这场戏。"}
    ]},
    {t:"n", x:"苏景行不知何时晃到了你们这桌，懒洋洋往顾知遥肩上一靠，亚麻色的头发被灯光镀了层金。他是最爱看顾知遥炸毛的人，此刻眼里全是看好戏的笑意，却又在顾知遥瞪过来时，不动声色地把你往自己这边挡了半寸——竹马之间的默契，从来不必说破。"},
    {t:"d", who:"苏景行", x:"小玩家，顾少爷今天格外护食啊。", fx:"sleepy"},
    {t:"n", x:"温以恒不知何时也跟了过来，手里还端着那碟桂花糕，像怕你们饿着。他轻轻碰了下顾知遥的肩，“小遥遥，别把客人勒红了。”顾知遥哼了一声，却没甩开，反而把那点红从耳尖漫到了颈侧。温以恒把糕递给你，低声补了句，“他今天，比谁都紧张。”糕上还沾着一点他手心的温度，甜得克制，像这个总把别人照顾得妥帖的人，唯一一次把关心，悄悄分了一勺给不该操心的你。"},
    {t:"heart", who:"温以恒", delta:1},
    {t:"n", x:"酒过三巡，顾知遥忽然拉住你的手腕，把你带出喧闹的厅堂。走廊的地毯吞掉了脚步声，他的掌心烫得反常，却又在触及你脉搏的地方，轻轻收了力道，像是怕弄疼你，又怕松开你就消失在身后的灯火里。你们一前一后，像逃离一场为他安排的、温柔的围猎。你听见身后有长辈的轻笑，像在说“到底还是顾家少爷任性”，可他的手没有松，反倒在转角处把你往他身后带了半步，用脊背替你挡住了那些目光。"},
    {t:"bg", v:"garden"},
    {t:"n", x:"露台的夜风凉得恰到好处，把身后的笑语隔成一层薄雾。远处城市的灯火连成一片星河，有晚归的航班闪着红绿信号灯，缓慢地、固执地，划过那片人造的银河。风里带来一点花园里夜来香的甜，混着他还未散去的冷香，把你俩裹进一个只属于此刻的小小天地。"},
    {t:"d", who:"顾知遥", x:"刚才那句话……不是演的。", fx:"shy"},
    {t:"n", x:"他的耳尖红透了，在月光下像被晚霞染过，连颈侧都洇着一点薄红。嘴还是硬的，声音却低了下去，几乎融进风里，只有你能听见——这个人，连坦白都要先用刺把自己裹上三层，再探出一点柔软的、发烫的真心。他挑了这么多年最贵的衣料，却把最笨的告白，留到今夜。"},
    {t:"d", who:"顾知遥", x:"队长大人是我的人。这话我说的，你听好。", fx:"blush"},
    {t:"n", x:"你忽然想起他从前送你的那枚领带夹——说是过时了不要了，却挑了最衬你领色的那一只；想起他每一次嘴硬的背后，都藏着这样细小的、不肯说出口的认真。原来傲娇不是脾气，是他唯一会用的、笨拙的告白。他从不说喜欢，却把喜欢，一寸寸缝进了你忽略的角落。"},
    {t:"m", x:"我原本以为，像他这样被宠大的人，永远不会把心意摊开在人前。可今夜他连耳尖都红了，却还梗着脖子，把“是我的人”说得像一份宣战书。我忽然很想伸手，替他把那层刺，轻轻按回去——然后告诉他，我也是。"},
    {t:"heart", who:"顾知遥", delta:2},
    {t:"verdict", x:"队长大人是我的人。\n耳尖的红，藏不住，也不必藏。\n那枚说过失时的领带夹，终于不必再否认。\n印章落下，星河无声。"},
    {t:"end"}
  ]
});


// ===== ch39.js =====
// 第三十九章 沈时雨线《向光生长》 —— 剧本写手
window.STORY.push({
  id: "ch39",
  title: "沈时雨线 · 向光生长",
  phase: "结局",
  week: null,
  nodes: [
    {t:"bg", v:"backstage"},
    {t:"n", x:"巡演第三站的加演夜，晚上七点四十，体育馆后台。今晚是沈时雨出道以来第一场个人solo舞台——节目单上，他的名字单独占了一行，字号比别处大两号。走廊尽头的通风管一直在响，低低的，像隔了三道墙的海；外场的应援声一波一波渗进来，到这儿只剩下一点钝钝的潮。化妆镜前的灯泡坏了一颗，剩下的把他半边脸照得发白，另半边沉进影子里。化妆台上摆着一只旧相框，七个人挤在一起笑，玻璃上那道细划痕，是搬家时磕的。"},
    {t:"n", x:"他一遍遍攥紧又松开麦架，指节泛白，金属杆上留下浅浅的湿痕。他今天穿的是白色短外套，肩线比他本人宽，是造型师反复别过三次才服帖的；锁骨下方贴着一小块肤色胶布，底下是连排磨红的一块。镜子里映出你站在他身后的影子，他每抬一次头，都要先确认你在，才敢重新低头去数拍子。"},
    {t:"phone", who:"沈时雨", msgs:[
      {f:"them", x:"队长哥，我……可以吗。", time:"19:48"},
      {f:"me",   x:"你早就准备好了。"},
      {f:"them", x:"嗯。你教的那个动作，我一直留着。", time:"19:49"}
    ]},
    {t:"n", x:"地胶被体温焐出暖意，远处主舞台的灯还亮着，低音炮的震动穿过墙板，把空气烤出一层薄薄的焦糖味。你忽然想起那个深夜的练习室——你教他的那一拍，他练到腿颤也不肯停，汗水落在地板上，洇出一小片深色，像他不肯让人看见的倔强。那双舞鞋的鞋头磨破过三次，都被他自己用粗线缝上，针脚在灯下露出一圈浅白。"},
    {t:"n", x:"那时他连对着镜子都低头，说“队长哥，我是不是……拖后腿了”。你没安慰，只是把手覆上他的手背，把那一拍的发力，一遍遍拆给他看：脚跟先落，重心压低，气息留半口。他学的时候不敢抬眼看你，只盯着地板上你们并排的影子；练到第二十遍，他才小声问，这样可以吗。他说他记性不好，可这一拍，他记了一整个赛季。编舞老师前后改过两版，他都只把那半秒，原封不动地留着。"},
    {t:"d", who:"温以恒", x:"时雨，还好吗？", fx:"smile"},
    {t:"n", x:"温以恒端着保温壶走过来，往你手里也塞了一杯温的，又替沈时雨理了理耳返的线。壶盖拧开的一瞬，一缕桂花与红枣的气味漫出来，把后台那股汗和金属的味道压下去一点。他顺手把沈时雨松掉的护踝往上提了提，说上场前再压一次腿，别省这三十秒。他记得每个人的口味与紧张，却总把自己的疲惫藏进“还好吗”三个字里——这是他照顾人的方式，从不声张。走之前他把壶里剩下的又倒了一杯，搁在旁边的矮柜上，注明是留给一会儿下台的鼓手的。"},
    {t:"d", who:"沈时雨", x:"……队长哥，谢谢你，当初没嫌我慢。", fx:"shy"},
    {t:"heart", who:"沈时雨", delta:1},
    {t:"n", x:"林墨轩路过，脚步停了一瞬。他手里还捏着谱夹，指腹压在一页折角上，指甲修剪得很短。他难得在彩排时开口点评，赞美吝啬得像金子，此刻却看着沈时雨的背影，极轻地点了下头。他随后看了你一眼，什么也没说，只把谱夹换到另一只手上。对一个把“标准”挂在嘴边的人而言，这已经是最隆重的、压箱底的认可。"},
    {t:"d", who:"林墨轩", x:"那一拍，按他教的做。很标准。", fx:"cool"},
    {t:"n", x:"走廊另一头，顾知遥正让造型师把他肩上的亮片一颗颗按平，嘴里嫌弃着土，人却站着没动，说到一半自己把话咽了回去，又多按了两下肩线。苏景行靠着墙打拍子，鞋尖一下一下点地，速度恰好是那首歌的速度，把整条走廊的节奏都带得轻起来。林墨轩在不远处合上谱夹。陆清越抱着三瓶水小跑过来，先塞给你一瓶，瓶身挂着冰化开的水珠，凉得人一激灵；他张了张嘴想喊什么，又自己捂住嘴巴，只朝台上比了个小太阳的手势，随后蹲下去，把沈时雨散开的鞋带重新系成一个双结。"},
    {t:"choice", prompt:"登台前，你想对他说什么？", options:[
      {x:"那一拍，交给你了。", heart:{沈时雨:2}, cb:"沈时雨点头，指尖攥紧麦架，眼神第一次没有躲开你的眼睛，像终于敢把光接住。"},
      {x:"别怕，我在台下看着。", heart:{沈时雨:1,温以恒:1}, cb:"温以恒轻轻拍了拍你的肩，沈时雨的肩膀，肉眼可见地松了一寸，呼吸也跟着稳了。"}
    ]},
    {t:"n", x:"登场前最后一秒，他回头望你，睫毛上还沾着一点没扑匀的亮片，在灯下闪了一下又灭了。你冲他比了个你教他的那拍起手式，他愣了一下，随即低下头，肩膀微微发抖——不是怕，是忍着，不让眼泪抢在音乐前面出来。"},
    {t:"bg", v:"stage"},
    {t:"n", x:"灯光亮起，前奏如水漫过耳膜。主舞台的温度扑面而来，像一头温和的兽，把人整个裹住；脚下的台板还在上一首歌的余震里发麻，观众席的星蓝光海起伏着，一波推一波，拍到台沿上。耳返里导播的倒计时压得很低，三四五，像有人在替心跳数拍。你退到台下固定的那个位置——那是他每次彩排，都会偷偷把视线落过来的地方。"},
    {t:"n", x:"他站进光里，不再是那个缩在角落、把别人的话往坏处想的小孩。副歌将至，他忽然在你教的那一拍上停住——没有照编排绕开，而是原封不动把那一拍留给聚光灯，留给台下你曾站过的位置。脚跟先落，重心压低，气息留着半口。台下的光海在那半秒里静了一下，随即涌上来，像把藏了一季的告白，终于敢摆到明处。"},
    {t:"danmaku", items:[
      "雨雨的小尾戒💍|这一拍是队长教的吧",
      "时雨冲鸭🚀|从角落走到光里",
      "drift观察员|他终于敢看镜头了",
      "以恒的桂花糕🍡|温哥在抹眼泪我哭死",
      "小太阳陆陆☀|时雨哥最棒",
      "苏苏的小甜饼🍪|副歌那一拍绝了",
      "江老师的小本本📒|这孩子成了"
    ]},
    {t:"n", x:"音乐落定，他走到台前，呼吸还没平，话筒举到唇边又放下。全场星蓝应援棒汇成一片海，在他眼里晃成碎光，也晃在他颤着的、却第一次挺直的肩线上。台下有几万人在喊他的名字，声浪一层压一层，他听了一会儿，才像是终于把这三个字，认成了自己。手心的汗把麦架镀铬的地方印出一个模糊的掌印，他没擦。"},
    {t:"d", who:"沈时雨", x:"我不再问可以吗，因为你说我很好。", fx:"cry"},
    {t:"m", x:"我记起雨夜的天台，他抖着问自己配不配站在这里；记起练习室的地板，他被汗水洇深的一片。那时他只敢把话说成问句，把每一次靠近都缩回去半步。如今他不再问，因为他信了我给的答案。原来有些光，不是照上去的，是被一个人，一句句托起来的。"},
    {t:"n", x:"陆清越在侧台跳着抹眼泪，苏景行吹了声长长的口哨，温以恒背过身去，悄悄抹了下眼角，回头时还得装作在看提词器。林墨轩抱着手臂站在控台边，难得没说一个字——可他眼底那点光，比任何评语都重。顾知遥把手里那瓶没开的水塞给你，说了句拿着，就转身去催下一组流程，耳根有点热。沈时雨从台上下来时，被staff团团围住，他却在人群的缝里先找到你，抬了抬手。"},
    {t:"d", who:"陆清越", x:"时雨哥你好厉害！", fx:"laugh"},
    {t:"heart", who:"沈时雨", delta:2},
    {t:"n", x:"谢幕的余温散得比想象中慢。后台重新忙起来，有人拖着线缆从你脚边经过，有人蹲在地上卷地胶，胶带撕开的声音一段一段，混着对讲机里的杂音。沈时雨坐在化妆凳上没动，手心里还攥着那支耳返，像攥着一件刚失而复得的东西；他把耳返凑到耳边又放下，反复了两次，确认里面真的没有声音了，才慢慢松开手指。他没去挤人群，也没躲回角落，只是坐在灯下，等呼吸一点点落回原位。矮柜上那杯留给鼓手的温水已经凉了。他对着镜子站起来，把外套脱了又穿上，动作很慢，像要把台上那个自己，重新叠好收进口袋。"},
    {t:"choice", prompt:"回后台的路上，你想——", options:[
      {x:"走过去，把他额前汗湿的碎发拨开。", heart:{沈时雨:2}, cb:"他僵了半秒，然后很慢地、很配合地低下头，让你把那撮头发拨到一边，呼吸落在你手背上，热的。"},
      {x:"什么也不说，把水递过去。", heart:{沈时雨:1,温以恒:1}, cb:"他接过去，喉结滚了两下才把水咽下去，瓶盖被他拧得很紧，像怕漏掉什么。"}
    ]},
    {t:"d", who:"温以恒", x:"他终于敢自己站在那束光里了。小队长，谢谢你。", fx:"smile"},
    {t:"verdict", x:"从仰望，到并肩。\n那一拍，他终于留给光。\n我不再问可以吗。\n因为你说过，他很好。\n印章落下，夜风很轻。"},
    {t:"end"}
  ]
});


// ===== ch40.js =====
// 第四十章 陆清越线《小小宇宙》 —— 剧本写手
window.STORY.push({
  id: "ch40",
  title: "陆清越线 · 小小宇宙",
  phase: "结局",
  week: null,
  nodes: [
    {t:"bg", v:"park"},
    {t:"n", x:"周六上午十点，城市西郊那家开了很多年的游乐园。检票口的铁栏杆被摸得发亮，广播里循环着一首走调的迎宾曲，喇叭偶尔滋一声。队伍前排着一对父子，小孩把气球线绕在手指上，绕了三圈还嫌不够。陆清越拽着你的袖子站在那里，金色的头发在阳光下像一小簇跃动的火。他说要带队长哥哥去他的秘密基地，眼睛亮得藏不住秘密，连背包上的小恐龙挂件都跟着一晃一晃，叮叮当当，替他打着拍子。"},
    {t:"n", x:"空气里浮着棉花糖的甜香，混着爆米花机上黄油烤糊的一点点焦味；风把远处过山车的惊叫揉成细碎的背景音，从头顶一层层荡开。检票口旁边有人在卖气球，一束一束地往上飘，绳子绷得笔直。你忽然想起他房间里那面贴满贴纸的墙，和那个他坚信有魔法的玻璃罐——在陆清越的世界里，相信本身，就是一种了不起的超能力。"},
    {t:"d", who:"陆清越", x:"队长哥哥！今天我们要把每一个项目都玩遍！", fx:"laugh"},
    {t:"n", x:"游乐园的喧闹从四面涌来，他的声音却清亮得能从里面浮出来。你低头看他，发现他另一只手还攥着两张皱巴巴的票根，边角被汗浸软了，显然从出门起就死死捏着，怕弄丢这趟只属于你们两个人的行程。检票员撕走半张时，他盯着那张废纸看了两秒，才舍得挪脚；走过闸机他立刻回头看了一眼，确认你真的跟在身后，才又蹦跳着往前走。"},
    {t:"phone", who:"温以恒", msgs:[
      {f:"them", x:"小队长，清越攒了一个月的零花钱买门票，别让他太疯。", time:"10:02"},
      {f:"me",   x:"放心，我看着他。"},
      {f:"them", x:"辛苦啦。给他买根棉花糖。", time:"10:03"}
    ]},
    {t:"n", x:"你说完放心，他已经在前头小跑着回头招手，金发在风里扬起，跑两步又停下来等你，鞋底在水泥地上蹭出很轻的声响。经过旋转茶杯的时候他放慢了一下，明显想去，又看看时间，自己摇摇头说先去做正事——他把今天排得满满当当，写在手心里，字被汗糊了一半。温以恒的叮嘱从手机里落进风里，软得像他本人的脾气——永远在替别人兜底，连管束都带着桂花糕的甜。"},
    {t:"n", x:"第一站是旋转木马。他挑了一匹白得发亮的，非要你坐旁边那匹，说这样转起来的时候队长哥哥一直都在他的视线里。木马起起伏伏，音乐盒的调子老旧，铜管里有一处轻微的走音，一圈一圈地绕，风从耳边过去，带着一点油漆和木头的味道。转到第三圈他忽然指着你笑，说队长哥哥的头发被风吹乱了；下来时他坚持把打靶赢来的小星星贴纸，贴在你手背正中央，按了两下才松手，说这是今天的第一件魔法。人潮涌过来的时候，他忽然跑回来，伸手虚虚挡在你外侧，学着他见过的样子把你护在内侧，自己却被人撞了一个趔趄，站稳了还笑。"},
    {t:"n", x:"他又拉着你冲过小火车和碰碰车，忽然在长椅前刹住脚，神秘兮兮地从背包里掏出一个铁皮盒子，盒面贴满了星星贴纸，锁扣上挂着一枚小小的、被盘得发亮的四叶草钥匙扣。盒角有一处磕瘪的印子，像被谁抱着摔过，又被小心地按了回去。"},
    {t:"d", who:"陆清越", x:"队长哥哥，我有一个秘密基地！这里面都是我的魔法物件！", fx:"laugh"},
    {t:"n", x:"盒子打开，里面躺着星星石、四叶草、一枚旧徽章，还有一张皱巴巴的糖纸——他说那是时雨哥第一次笑的那天留下的。每一件都像被妥帖地供着，连灰都舍不得落；盒子内衬是他自己剪的绒布，边缘剪得歪歪扭扭，还留着铅笔画的线，最上面那层绒布换过两次，因为旧的被他每天打开摸得起了球。这是这个小太阳，用整个童心的认真，在收藏的一年。"},
    {t:"d", who:"陆清越", x:"它们都是真的有魔法！因为都见过你夸我的样子！", fx:"smile"},
    {t:"choice", prompt:"你该怎么接他的小宇宙？", options:[
      {x:"那最厉害的魔法是什么？", heart:{陆清越:2}, cb:"陆清越的眼睛亮成两盏小灯，把铁盒整个捧到你面前，如数家珍，像在展示全世界最珍贵的宝藏。"},
      {x:"你舍得都给我？", heart:{陆清越:1,温以恒:1}, cb:"温以恒在远处笑叹，连沈时雨都跟着弯了眼，仿佛早知道这小孩藏不住心事。"}
    ]},
    {t:"n", x:"他席地坐在长椅边，把铁盒搁在你膝上，开始一件件数给你听。星星石是团综那晚在天台捡的，四叶草是散场后在场地缝里找了四十分钟才找到的，旧徽章是第一次签售时一位奶奶塞给他的，糖纸他擦了又擦，还是留着那道折痕。阳光穿过树叶，在他睫毛上跳，也在铁盒的贴纸上跳；每报出一件，他都要抬头确认你有没有在认真听——对他而言，被你看见，就是魔法生效的证明。"},
    {t:"d", who:"陆清越", x:"所以它们都沾了你的光，才变得有魔法！", fx:"smile"},
    {t:"heart", who:"陆清越", delta:1},
    {t:"bg", v:"ferris"},
    {t:"n", x:"摩天轮升到最高处，城市的轮廓在脚下铺成一张星图，远处的河像被揉亮的银线。座舱里有很轻的晃动，玻璃上凝着一层薄薄的雾。他难得安静下来，没有感叹号，没有蹦跳，只是把脸贴在玻璃上，看着那片被你们一点点走亮的夜，呼吸轻轻扑在窗面，晕开一小团白雾。他用指尖在那团白雾里画了个小小的圈，圈里写了两个字，很快又自己擦掉了。铁盒搁在他膝上，两只手一直虚虚按着盒盖，像怕它跟着风飞出去。"},
    {t:"d", who:"陆清越", x:"队长哥哥，以前都是你保护我。", fx:"shy"},
    {t:"d", who:"陆清越", x:"现在换我保护你了。", fx:"blush"},
    {t:"m", x:"我记起他十八岁生日许的愿，据说和让队长骄傲有关；记起他练到睡着还抱着剧本的样子；记起他被骂哭的第二天，还是第一个在练习室喊早上好。原来那个把世界当童话的小孩，早把长大悄悄写进了愿望里。他不是不会伤，只是选择把伤，也变成一颗发光的星星石。"},
    {t:"n", x:"座舱往下降的时候，能看见底下那几个人了：沈时雨在下面使劲挥手，手臂扬得很高，怕你们看不见似的连跳了两下；苏景行举着相机咔嚓不停，每按一次快门就倒退半步，差点踩到别人的脚；温以恒递上来两杯还冒热气的可可，杯壁上凝着细密的水珠，隔着栏杆往上举，袖口被风吹得鼓起来。这一刻，整座游乐园像被收进他的铁皮盒子，成了又一件、有魔法的物件。"},
    {t:"d", who:"苏景行", x:"小太阳，这张要洗出来贴你床头。", fx:"sleepy"},
    {t:"heart", who:"陆清越", delta:2},
    {t:"phone", who:"顾知遥", msgs:[
      {f:"them", x:"队长大人，几点回来。本少爷的奶油蛋糕可等不了太久。", time:"17:20"},
      {f:"me",   x:"在回去了。"},
      {f:"them", x:"哼。顺便把小鬼的书包背上，他玩起来必定又散架。", time:"17:21"}
    ]},
    {t:"n", x:"出园门时日头已经斜了，路灯一盏一盏亮起来，摊子上的糖炒栗子冒着白气，甜里带一点焦。门口的风铃被进出的客人碰得叮当响，一声还没散，另一声又来了。苏景行靠在栏杆上等你们，相机挂在脖子上；顾知遥拎着一只纸袋，说是路过顺手买的，袋子里其实是陆清越念叨了一整周的奶油蛋糕；温以恒把两件外套都搭在臂上，沈时雨手里攥着四张没用完的票根，舍不得扔。林墨轩站在最外圈，手里还是那本谱子，抬头看了一眼天，只说了三个字：起风了。陆清越把那沓票根分了一张给你，说这一张归队长哥哥保管，因为这是你来过的证据，其余的他都要收进铁盒里。"},
    {t:"choice", prompt:"天色暗下来，你想——", options:[
      {x:"“那今天的魔法，我们留一件到明年。”", heart:{陆清越:2}, cb:"他很认真地点头，把盒里那枚四叶草重新别回你的袖口，说这一件不算送，算寄存，明年他要用一整年的新魔法来换。"},
      {x:"“今晚我请你吃最大的那根棉花糖。”", heart:{陆清越:1,温以恒:1}, cb:"他欢呼着跳起来，回头却先跑去跟温以恒报备，说队长哥哥批准了，电话那头的温以恒笑出了声。"}
    ]},
    {t:"n", x:"他把铁盒抱在怀里，走在你们中间，脚步踩在路灯一格一格的光里，影子被拉得忽长忽短，小恐龙挂件一路叮当。他忽然说了一句没有感叹号的话。他说，队长哥哥，我今天把最重要的一件留下来了——是明天。说完他自己先笑起来，鞋带散了也没管，走得比来时稳了半分。前面温以恒回头替他理了理歪掉的外套领子，顾知遥哼了一声，把蛋糕袋子往他怀里塞过去。"},
    {t:"verdict", x:"他把整个小宇宙都递到你手里。\n魔法物件，原来都叫长大。\n队长哥哥，现在换我保护你。\n印章落下，童心很暖。"},
    {t:"end"}
  ]
});


// ===== ch41.js =====
// 第四十一章 江慕白线《完美作品》 —— 剧本写手
window.STORY.push({
  id: "ch41",
  title: "江慕白线 · 完美作品",
  phase: "结局",
  week: null,
  nodes: [
    {t:"bg", v:"backstage"},
    {t:"n", x:"成团一周年演唱会彩排夜，十一点五十。空荡的舞台只剩你与江慕白，远处的分声部歌声像隔着一层水，听不真切。空荡的观众席黑着，像一只屏住呼吸的耳朵。椅背上还搭着谁的白毛巾，扶手上搁着一只没喝完的水杯，杯壁的水痕一路淌到桌面上——白天这里坐过两千人，此刻只剩他一个人站在灯下。他向来如此，把最重的雕琢，留到无人处。"},
    {t:"n", x:"冷气贴着脚踝往上爬，木地板泛着蜡光，一步一个浅淡的印子。设备间偶尔传来一声低低的嗡鸣，像什么人忘了关掉的心跳。空气里有松香与旧木的味道，像一间从不对外开放的琴房。台口的胶带被踩得起毛，那道白线在灯下泛着灰。你走过的地方，蜡面浮起一层很淡的雾，又慢慢合上。"},
    {t:"n", x:"你忽然觉得，这间后台比任何聚光灯下，都更接近他的真心。灯只开了三分之一，光落在台口的胶带上，把那道白线照得很硬。监视屏的待机灯在他的镜片上映成一点很小很小的青，亮着，不动。"},
    {t:"n", x:"他立在灯影边缘，银白的头发比月光更安静，仪态永远完美，像一幅被装裱好的、静止的画。细框眼镜后的灰眸看不出情绪，只有指尖无意识地点着裤线，一下，又一下，泄露了一点罕见的、不肯停下的思量。他西装袖口的扣子少了一颗，是上周彩排时被器材勾掉的，他一直没补，只拿同色的线草草挽了个结。"},
    {t:"d", who:"江慕白", x:"一年了。你比我以为的，走得更好。", fx:"cool"},
    {t:"m", x:"你想起初评级，他说你是璞玉，说值得最严格的雕琢；那时你只当那是导师的场面话，不懂这份严苛背后，藏着的、不肯说出口的期待。"},
    {t:"n", x:"你也想起那个加练的夜，他说我对你最严格，因为你值得，汗水落在地板，他递来的毛巾还带着雪松味。你会走音的第三小节被他反复按下重来，直到你说不出话，他才把水推过来，说明天继续。排练室的钟走到两点，他先起身把顶灯关了一半，说剩下的一半留给你收声。走廊外的自动售货机嗡了一声，掉下一罐汽水，他弯腰取出来放进你手里，说是练完再喝。那时你才懂，他的值得两个字，比任何情话都重，也从不许诺，只兑现。"},
    {t:"n", x:"他翻开随身文件夹，取出一份装订好的文件，推到你面前。纸页压着沉边，封面是他惯用的深蓝布纹，边角一丝不苟。他的指尖在封面上停了一瞬，像落判词前的一次呼吸，连空气都跟着屏住。远处音响师在对最后一路返送，那声音响了半拍，又被他抬手示意按掉；台口的白线因为这一抬手，亮了一下。"},
    {t:"n", x:"你认出封面角落那一列极小的钢笔字，是他的签名体——每一笔都像在量度，不肯多一分，也不肯少一分。纸是他惯用的那种，摸上去有一点细纹；夹页里露出半截书签，是乐团二十年前的旧票根。这份文件的分量，不在纸，在他肯把名字，压在它上面的那份慎重。"},
    {t:"d", who:"江慕白", x:"这是无限期私人制作人合约。署名处，空着。", fx:"neutral"},
    {t:"phone", who:"苏景行", msgs:[
      {f:"them", x:"慕白哥今晚又要拐我们队长？我可盯着呢。", time:"23:55"},
      {f:"me",   x:"在谈正事。"},
      {f:"them", x:"行，正事。记得你还是我们队长。", time:"23:56"}
    ]},
    {t:"n", x:"江慕白没有接话，只是用指节在合约边缘轻点，一下，又一下，像在落一个判词前的停顿。他太懂得施压的节奏，也太懂得，什么时候该把缰绳，交回你手里。台口的返送喇叭里还残着一点电流的沙沙声，他等那一小段噪音走完，才继续开口。"},
    {t:"d", who:"江慕白", x:"我不逼迫你。签，或不签，选择权始终在你。", fx:"neutral"},
    {t:"choice", prompt:"你如何回应这份合约？", options:[
      {x:"我先看看条款，再回答你。", heart:{江慕白:1}, cb:"江慕白唇角微扬，把笔轻轻放在合约旁，退后半步，把空间与余地，一并留给你。"},
      {x:"你愿意等我多久？", heart:{江慕白:2}, cb:"他凝视你，灰眸里映着舞台的残光，低声说，等你愿意的那天——不催，不逼，只等。"}
    ]},
    {t:"n", x:"你低头，合约扉页是他手书的一行字：致我的完美作品。墨迹未褪色，显然写了有些时日，又被他反复看过——纸角摩得很软，比别处薄了半分，右下角还留着一枚极淡的指印。原来他早把这份告白，准备好了，却一直等到你愿意接的那一刻，才肯推出来。"},
    {t:"d", who:"江慕白", x:"你是我雕过最久的那块玉。我不急。", fx:"cool"},
    {t:"heart", who:"江慕白", delta:1},
    {t:"n", x:"远处分声部的试唱停了，走廊上的脚步声一串一串地近。温以恒拎着两件外套站在门边，说收工了，宵夜在锅里温着；陆清越趴在栏杆上数灯管，数到第七根就忘了，又从头数，数到第三次自己先笑出来；顾知遥看一眼腕表，催着谁把返送线收了，顺手把歪掉的一张椅子摆正；沈时雨把一排空水瓶拧好盖，逐个归到回收箱里，摆得像尺子量过；林墨轩还在跟乐队对最后一版和声，手指在谱面上点着拍子，没抬头。谁也没有往里催，走廊里的说话声，不知不觉都轻了半分。"},
    {t:"d", who:"顾知遥", x:"队长大人，走不走？车在门口，别磨蹭。", fx:"cool"},
    {t:"n", x:"彩排的灯一盏盏熄灭，从最后一排座位开始，往台口收。剩下台口那一道，最后才落下来。他送你到门口，风灌进来，带着初秋的凉意，也把走廊尽头那点宵夜的热气一并卷过来，混着一点辛香。他站在光与暗的交界，半边脸被走廊灯勾出轮廓，半边溶进夜色，像一句没说尽的判词，留白处，比落墨处更烫。最后一排座椅在暗里退成一片模糊的黑。"},
    {t:"d", who:"江慕白", x:"无论你选哪条路，我都站在制作人的位置，看着你成星。", fx:"neutral"},
    {t:"n", x:"门外的夜风卷着远处城市的喧嚣扑来，又退去，卷着几片落叶擦过台阶，声音很碎。他没再往前送，只是站在原地，目送你走进那片光里——像每一次彩排结束，他总是最后一个关灯的人，把舞台，留给别人。走廊尽头的保洁阿姨推着车经过，他侧身让路，顺手把地上散着的两页谱子捡起来叠好。你回头时，他的手还虚按在门框上，没动。"},
    {t:"m", x:"我忽然懂了，他的告白从不是占有，而是把选择权，连同整片夜色，一并交还你手。克制，却滚烫。他雕了那么久的玉，最终想要的，从来不是玉属于他，而是玉，终于肯为自己发光。就像他每一次说完重话，都会把水推过来；每一次逼到极限，都会留一句明天继续。"},
    {t:"n", x:"回程的车上，群里还在跳：陆清越发了一张宵夜的照片，汤面糊了半边；温以恒说给队长留了一碗，别嫌凉；苏景行把那张照片转发给江慕白，配了一句老师也来一碗？没有回音。顾知遥在群里补上一句明早别迟到，罚站也要站得好看。车窗外的路灯一盏接一盏地过去，光在他送你的那份文件封面上掠过又走。你把那份深蓝色的文件放在腿上，纸边压着你的手背，凉的，一点也不重。"},
    {t:"choice", prompt:"夜风里，你想——", options:[
      {x:"把合约收进包里，说“我先带回去看”。", heart:{江慕白:1}, cb:"他点头，没有追问，只抬手替你挡开了门框上方垂下来的一段线缆，动作轻得像早就预演过。"},
      {x:"问他，署名处可不可以先空着。", heart:{江慕白:2}, cb:"他看了你两秒，第一次没有给出判词，只说，可以。那两个字落得很轻，像怕惊醒什么。"}
    ]},
    {t:"n", x:"凌晨的楼道比舞台安静得多，安全出口的灯是暗绿的，一路铺到走廊尽头，把每个人的影子压得很扁。你把文件放回包里，拉链拉到一半，又停下来看了一眼封面那列极小的字，指腹在那道压痕上停了停。楼上有人拖椅子，地板响了一声，接着是陆清越压低的惊呼和温以恒一声轻得几乎听不见的嘘。楼梯拐角贴着一张巡演行程表，最后一行被人用红笔划掉，又画了个很小的对勾。"},
    {t:"phone", who:"江慕白", msgs:[
      {f:"them", x:"合约带回去，不用急着翻。", time:"00:12"},
      {f:"me",   x:"好。"},
      {f:"them", x:"明天九点，练声。迟到照罚。", time:"00:13"}
    ]},
    {t:"verdict", x:"致我的完美作品。\n雕玉的人，从不催促玉开花。\n选择权在你，夜色也在你。\n印章落下，滚烫而静。"},
    {t:"end"}
  ]
});


// ===== ch42.js =====
// 第四十二章 真结局《久星移》 —— 剧本写手
window.STORY.push({
  id: "ch42",
  title: "真结局 · 久星移",
  phase: "结局",
  week: null,
  nodes: [
    {t:"bg", v:"stage"},
    {t:"n", x:"一年后。巡演收官夜，场馆的星蓝光海在黑暗里起伏，像一片被收进屋顶的银河。七个名字的应援棒汇成潮汐，一下一下，拍着这座我们走了很久的舞台。这一年里，有人哭过，有人伤过，也有人，悄悄把心意，藏进了同一首歌的留白里。后台走廊上还堆着没拆完的花篮，包装纸被来往的脚步踩出深深的折痕。"},
    {t:"n", x:"热浪裹着汗与花香扑面，脚下的地板仍因上一首歌的震撼微微发颤，返送里还残留着贝斯的余韵，耳膜上像蒙了一层薄薄的嗡。灯光收束，七人并肩站定，呼吸还乱着，却奇异地同步，像一首排练过千遍、却从没被写进谱子的和声——我们从未约好，却总在同一个节拍上。"},
    {t:"n", x:"身后大屏，七个名字并排亮起：林墨轩、温以恒、顾知遥、沈时雨、苏景行、陆清越，和你。每一个笔画都被光描过，像在说，这一路，没有谁，是独自走到这里的。台下前排一块旧灯牌被举得很高，边角卷了毛，字是手写的：从一百颗星到七颗。你认得它，它从选秀第一期就在，一路从体育馆的看台，跟到了今天。大屏的光慢慢淡下去，名字却还亮着，没有一个先暗。"},
    {t:"n", x:"这一年走过十一座城市，行李箱的贴纸一层压着一层，撕过又贴，边角都起了卷。机场的凌晨、临时搭起来的休息室、谁把耳返落在化妆间、谁半夜在走廊煮泡面被经纪人拎回来、哪一站谁唱错了一整段还硬着头皮接下去——那些没被写进任何一支单曲的琐碎，才是把七个名字焊在一起的东西。那只公用的黑包里，常年塞着谁的护腰、谁的润喉糖、谁永远忘带的转接头。"},
    {t:"d", who:"苏景行", x:"小玩家，我们居然真把这条路走完了。", fx:"smile"},
    {t:"d", who:"温以恒", x:"还好吗？", fx:"smile"},
    {t:"n", x:"温以恒的还好吗还是那样轻，像他每日睡前逐一确认大家状态的习惯，一年了，没变过。你看见他眼角多了道浅浅的纹，是熬夜与操心刻下的，却被他笑起来时，揉成了温柔的弧度。他手里还攥着八瓶水的提手，多出来的那瓶，照例给了台口的场务，动作熟得像做了很多年。他说完还好吗，又习惯性地数了一遍人头，数到第七个才把肩放下来。"},
    {t:"heart", who:"温以恒", delta:1},
    {t:"n", x:"你想起成团夜，七双手叠在一起，那声Stellar Drift第一次被七道声音同时念出。那时谁也没料到，这条路会走到有光的地方，更没料到，光里站的，还是这七个人。中间有过想散的时刻：合同、数据、热搜、谁被单独叫去谈过一整夜的话——最后都在这七个人的沉默里，被一件件按回去了。"},
    {t:"d", who:"顾知遥", x:"哼，队长大人还是我的。", fx:"blush"},
    {t:"n", x:"顾知遥说这话时，耳尖又红了，却破天荒地没躲开旁人的目光。他把手臂环过你的肩，宣示领地般，又在这份嚣张里，藏了一点连他自己都没察觉的、全然的安心。他的演出服袖口有一道新缝的针脚，他自己缝的，缝得歪，还不许造型师碰；说完那句，他自己先笑了一声，像终于不必再把话藏着。他说这话时声音比谁都响，像是故意要让后排也听见。"},
    {t:"d", who:"沈时雨", x:"队长哥……谢谢你，让我站到这里。", fx:"shy"},
    {t:"n", x:"沈时雨的声音不再发抖。那个缩在角落、把别人的话往坏处想的小孩，如今敢把目光稳稳落在镜头前——他终于信了，你当年那句你很好，不是安慰，是预言。他说完低头笑了一下，像是自己也觉得这句话等得太久；台下有粉丝举着当年那块手写应援牌，字迹被雨水泡过一遍，他又看了一遍。"},
    {t:"d", who:"陆清越", x:"队长哥哥，我们七个，最厉害！", fx:"laugh"},
    {t:"n", x:"陆清越举着那只小恐龙挂件，像举着一枚勋章。他的魔法物件，今年又多了好几件，每一件，都沾过你夸他的光。他相信的世界，一年了，还是亮堂堂的；后台走廊里他现在敢一个人走，还敢在拐角停一停，认真听有没有谁需要帮忙。他举挂件的手很稳，拇指却把那截挂绳的扣环按了又按，像在确认它真的还在。他说完那句最厉害，自己先愣了一下，随即又笑，像是终于把那句话，配得上地说了出来。"},
    {t:"d", who:"林墨轩", x:"这一程，很标准。", fx:"cool"},
    {t:"n", x:"林墨轩的评价，依旧吝啬得像金子。可你听得出，那句很标准里，藏着他从不外放的、最大的认可——对一个人，也对一整支队伍。他抱着臂，眼底那点光，比任何评语都重。谱夹里夹着一张写满批注的和声纸，他刚才把所有人的名字都标了一遍，连临时替补的乐手都在边上画了个圈。"},
    {t:"d", who:"江慕白", x:"一年的作品，验收合格。", fx:"cool"},
    {t:"n", x:"江慕白站在导师的位置，银发被收尾的灯勾出轮廓。他说的是验收，眼底却是一片不易察觉的、近乎骄傲的软。他雕了最久的那块玉，终于肯为自己发光了——而他始终，站在制作人该站的地方。说完他把手里的流程表折好，塞回大衣内袋，像完成了一年里最后一道工序。"},
    {t:"n", x:"侧台的灯亮着一排小灯珠，工作人员挤在幕布后，经纪人举着手机往上拍，场务把下一场的返送线悄悄收好。有人小跑着递上两排毛巾，温以恒接过来一条条发下去，最后一条留给了角落里的灯光师；陆清越趁乱从口袋里摸出一颗糖，被沈时雨轻轻按住了手腕，两个人对着笑了一下。台下星蓝的浪还在拍，谁也没有急着走下台阶。幕布后有人很小声地说了句辛苦了，声音立刻被人群的动静盖过去，没人听清，也没人需要听清。"},
    {t:"n", x:"七人同时伸手，手叠手，和那夜一样的姿势，只是每个人的掌心都多了岁月的茧，灯光把交叠的指节照得发亮。顾知遥的手在最上面，压得很用力；沈时雨的手在最下面，稳稳托着，没有抖。这一次，没有人抢拍，也没有人退后半步，七道声音，早就在无数个舞台后，长成了同一种节奏。台下的应援声在这一刻低下去，像整座场馆一起屏住了呼吸。你听见身边有人吸了一下鼻子，声音很快被掌声盖过去。"},
    {t:"choice", prompt:"此刻，你最想做什么？", options:[
      {x:"把手，再叠紧一点。", heart:{苏景行:1,温以恒:1,顾知遥:1,沈时雨:1,陆清越:1,林墨轩:1,江慕白:1}, cb:"七只手同时收拢，掌心的汗与温度混在一起，比任何誓言都烫，也比任何告白都久。"},
      {x:"记住这一刻，记住我们。", heart:{苏景行:1,温以恒:1}, cb:"苏景行笑着把这一幕举到眼前，像要拍下来；温以恒轻轻点头，把七个名字，又默念了一遍。"}
    ]},
    {t:"danmaku", items:[
      "七颗星🌟|Stellar Drift永远",
      "星蓝海💙|手叠手我又哭了",
      "drift观察员|七个名字并排",
      "以恒的桂花糕🍡|温哥还好吗",
      "苏苏的小甜饼🍪|首先是我们",
      "小太阳陆陆☀|七个最厉害",
      "江老师的小本本📒|验收合格泪目"
    ]},
    {t:"n", x:"你忽然明白，心动或许各有归处，有人把领带夹藏进你抽屉，有人把那一拍留给你教的位置，有人把整个小宇宙递到你手里，有人把选择权连同夜色一并交还。但先把你们焊在一起的，是我们这两个字——它在每一次返场、每一顿宵夜、每一次深夜的争吵与和解里，被反复地念过，念得比任何一句情话都多。"},
    {t:"m", x:"无论后来花落谁家，此刻七个名字并排，先于爱情，先于分别，是彼此来时的路。有人把心意藏进歌的留白，有人藏进一件不肯承认的礼物，有人藏进一句练习时的叮嘱——它们都被这一年好好地接着，没有一样掉在地上。我们首先是我们——这不被任何一条心动线带走的，是七颗漂流的星，终于在同一片夜空，彼此照亮。"},
    {t:"d", who:"苏景行", x:"首先是我们，记得吗？", fx:"sleepy"},
    {t:"heart", who:"苏景行", delta:1},
    {t:"verdict", x:"七个名字，先并排，再各自远行。\n我们首先是我们。\n星蓝不灭，漂流的星终会落地。\n印章落下，长久而静。"},
    {t:"end"}
  ]
});
